import { prisma } from "@/lib/prisma"
import { PlansManager } from "@/components/admin/PlansManager"

export const metadata = {
  title: "Admin | Plans & Pricing",
}

export default async function AdminPlansPage() {
  const plans = await prisma.plan.findMany({
    orderBy: { price: "asc" }
  })

  const serializedPlans = plans.map(p => ({
    ...p,
    price: p.price.toNumber()
  }))

  return (
    <div>
      <div style={{ marginBottom: "1.5rem", display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
        <div>
          <h1 className="page-title">Plans & Features</h1>
          <p className="page-subtitle">Manage subscription tiers and access features</p>
        </div>
      </div>

      {/* Client component to handle CRUD operations on Plans */}
      <PlansManager initialPlans={serializedPlans as any} />
    </div>
  )
}

import { Suspense } from "react"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { redirect } from "next/navigation"
import { AccountsManager } from "@/components/accounts/AccountsManager"

export const metadata = {
  title: "Accounts",
}

export default async function AccountsPage() {
  const session = await auth()
  if (!session?.user?.id) {
    redirect("/login")
  }

  // Fetch accounts by calling our API internally or just duplicating the Prisma query
  // Since we are in a server component, it's more efficient to just query Prisma directly
  const dbAccounts = await prisma.tradingAccount.findMany({
    where: { userId: session.user.id },
    include: {
      propChallenge: {
        include: { template: true }
      }
    },
    orderBy: { createdAt: 'desc' }
  })

  const accounts = await Promise.all(dbAccounts.map(async acc => {
    const where: any = { accountId: acc.id, status: 'closed' }
    const trades = await prisma.trade.findMany({
      where,
      select: { netPnl: true, netPnlUsd: true, status: true }
    })

    const totalPnl = trades.reduce((sum, t) => sum + Number(t.netPnl || 0), 0)
    const totalPnlUsd = trades.reduce((sum, t) => sum + Number(t.netPnlUsd ?? (t.netPnl || 0)), 0)

    return {
      id: acc.id,
      name: acc.name,
      broker: acc.broker,
      type: acc.propChallenge ? 'prop_firm' : (acc.type === 'backtest' ? 'demo' : (acc.type || 'personal')),
      baseCurrency: acc.baseCurrency,
      fxRateToUsd: acc.fxRateToUsd ? Number(acc.fxRateToUsd) : 1,
      initialBalance: acc.initialBalance ? Number(acc.initialBalance) : 0,
      isDefault: acc.isDefault,
      createdAt: acc.createdAt,
      propChallenge: acc.propChallenge ? {
        id: acc.propChallenge.id,
        status: acc.propChallenge.status,
        phase: acc.propChallenge.phase,
        currentEquity: acc.propChallenge.currentEquity ? Number(acc.propChallenge.currentEquity) : 0,
        firmName: acc.propChallenge.template.firmName,
        programName: acc.propChallenge.template.programName,
        logoUrl: acc.propChallenge.template.logoUrl || null,
      } : null,
      stats: {
        tradesCount: trades.length,
        totalPnl,
        totalPnlUsd,
      }
    }
  }))

  return (
    <div>
      <Suspense fallback={<div className="skeleton" style={{ height: "400px" }} />}>
        <AccountsManager accounts={accounts} />
      </Suspense>
    </div>
  )
}

"use client"

import { useEffect, useState } from "react"
import { Trophy, CheckCircle2, Lock, Medal } from "lucide-react"
import { toast } from "sonner"

type Achievement = {
  id: string
  code: string
  name: string
  description: string
  icon: string
  target: number
  unlocked: boolean
  unlockedAt: string | null
  earned: boolean
  progress: number
}

type AchievementGroup = {
  category: string
  achievements: Achievement[]
}

type AchievementsData = {
  total: number
  unlockedCount: number
  newlyUnlocked: string[]
  groups: AchievementGroup[]
}

export function AchievementsClient() {
  const [data, setData] = useState<AchievementsData | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(false)

  useEffect(() => {
    const fetchAchievements = async () => {
      try {
        const res = await fetch("/api/achievements")
        if (!res.ok) throw new Error("Failed to fetch")
        const json = await res.json()
        setData(json)

        if (json.newlyUnlocked && json.newlyUnlocked.length > 0) {
          json.newlyUnlocked.forEach((code: string) => {
            // Find the achievement to get its name
            for (const group of json.groups) {
              const ach = group.achievements.find((a: any) => a.code === code)
              if (ach) {
                toast.success(`Achievement Unlocked: ${ach.name}! 🏆`, {
                  description: ach.description,
                  duration: 5000,
                })
              }
            }
          })
        }
      } catch (err) {
        console.error(err)
        setError(true)
      } finally {
        setLoading(false)
      }
    }
    fetchAchievements()
  }, [])

  if (loading) {
    return (
      <div className="flex flex-col gap-6">
        <div className="skeleton h-24 w-full rounded-2xl" />
        <div className="skeleton h-64 w-full rounded-2xl" />
      </div>
    )
  }

  if (error || !data) {
    return (
      <div className="p-8 text-center bg-[var(--color-gray-900)] rounded-[var(--radius-card)] border border-[var(--color-gray-800)] text-[var(--color-gray-400)]">
        Failed to load achievements.
      </div>
    )
  }

  const categoryNames: Record<string, string> = {
    trading: "Trading Fundamentals",
    consistency: "Consistency",
    prop: "Prop Firm",
    journal: "Journal & Discipline",
  }

  return (
    <div className="flex flex-col gap-8 pb-10">
      {/* ─── Overview Stats ────────────────────────────────────────────── */}
      <div className="bg-[var(--color-gray-900)] border border-[var(--color-gray-800)] rounded-[var(--radius-card)] p-6">
        <div className="flex flex-wrap gap-6 items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-14 h-14 rounded-full bg-[var(--color-brand-500)]/20 flex items-center justify-center border border-[var(--color-brand-500)]/30">
              <Trophy size={28} className="text-[var(--color-brand-400)]" />
            </div>
            <div>
              <div className="text-3xl font-bold text-[var(--color-gray-100)]">
                {data.unlockedCount} <span className="text-lg text-[var(--color-gray-500)] font-normal">/ {data.total}</span>
              </div>
              <div className="text-sm font-medium text-[var(--color-brand-400)] uppercase tracking-wider mt-1">
                Total Unlocked
              </div>
            </div>
          </div>

          <div className="flex-1 min-w-[200px] max-w-md">
            <div className="flex justify-between text-xs text-[var(--color-gray-400)] mb-2 font-bold uppercase tracking-wider">
              <span>Overall Progress</span>
              <span>{Math.round((data.unlockedCount / data.total) * 100)}%</span>
            </div>
            <div className="h-2.5 bg-[var(--color-gray-800)] rounded-full overflow-hidden border border-[var(--color-gray-700)]">
              <div 
                className="h-full bg-gradient-to-r from-[var(--color-brand-600)] to-[var(--color-brand-400)] rounded-full transition-all duration-1000 ease-out"
                style={{ width: `${(data.unlockedCount / data.total) * 100}%` }}
              />
            </div>
          </div>
        </div>
      </div>

      {/* ─── Categories ────────────────────────────────────────────────── */}
      <div className="flex flex-col gap-10">
        {data.groups.map(group => (
          <div key={group.category}>
            <h2 className="text-xl font-bold text-[var(--color-gray-200)] mb-4 flex items-center gap-2">
              <Medal size={20} className="text-[var(--color-brand-500)]" />
              {categoryNames[group.category] || group.category}
            </h2>

            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
              {group.achievements.map(achievement => {
                const isUnlocked = achievement.unlocked
                const progressPct = achievement.target > 0 
                  ? Math.min(100, Math.round((achievement.progress / achievement.target) * 100))
                  : (isUnlocked ? 100 : 0)

                return (
                  <div 
                    key={achievement.id}
                    className={`relative overflow-hidden flex flex-col p-5 rounded-[var(--radius-card)] border transition-all duration-300 ${
                      isUnlocked 
                        ? "bg-[var(--color-gray-900)] border-[var(--color-brand-500)]/40 hover:border-[var(--color-brand-400)] hover:shadow-[0_4px_20px_rgba(139,92,246,0.1)]" 
                        : "bg-[var(--color-gray-900)]/50 border-[var(--color-gray-800)] opacity-70 grayscale-[0.6]"
                    }`}
                  >
                    {isUnlocked && (
                      <div className="absolute top-0 right-0 w-16 h-16 bg-gradient-to-bl from-[var(--color-brand-500)]/20 to-transparent rounded-bl-3xl opacity-50 pointer-events-none" />
                    )}

                    <div className="flex items-start gap-4">
                      <div className={`w-12 h-12 flex items-center justify-center rounded-xl text-2xl shrink-0 ${
                        isUnlocked 
                          ? "bg-gradient-to-br from-[var(--color-gray-800)] to-[var(--color-gray-900)] border border-[var(--color-brand-500)]/30 shadow-[0_0_15px_rgba(139,92,246,0.2)]" 
                          : "bg-[var(--color-gray-800)] border border-[var(--color-gray-700)]"
                      }`}>
                        {achievement.icon}
                      </div>

                      <div className="flex-1 min-w-0 pt-0.5">
                        <div className="flex items-center justify-between gap-2">
                          <h3 className={`font-bold truncate ${isUnlocked ? "text-[var(--color-gray-100)]" : "text-[var(--color-gray-300)]"}`}>
                            {achievement.name}
                          </h3>
                          {isUnlocked ? (
                            <CheckCircle2 size={16} className="text-[var(--color-success)] shrink-0" />
                          ) : (
                            <Lock size={14} className="text-[var(--color-gray-500)] shrink-0" />
                          )}
                        </div>
                        <p className="text-xs text-[var(--color-gray-400)] mt-1.5 leading-relaxed">
                          {achievement.description}
                        </p>
                      </div>
                    </div>

                    {/* Progress Bar (only show if target > 1, as target=1 is just binary state) */}
                    {achievement.target > 1 && (
                      <div className="mt-5">
                        <div className="flex justify-between items-end mb-1.5">
                          <span className="text-[10px] font-bold uppercase tracking-wider text-[var(--color-gray-500)]">Progress</span>
                          <span className="text-[10px] font-bold text-[var(--color-gray-300)]">
                            {Math.min(achievement.progress, achievement.target)} / {achievement.target}
                          </span>
                        </div>
                        <div className="h-1.5 bg-[var(--color-gray-800)] rounded-full overflow-hidden">
                          <div 
                            className={`h-full rounded-full transition-all duration-700 ${isUnlocked ? 'bg-[var(--color-success)]' : 'bg-[var(--color-brand-500)]'}`}
                            style={{ width: `${progressPct}%` }}
                          />
                        </div>
                      </div>
                    )}

                    {isUnlocked && achievement.unlockedAt && (
                      <div className="mt-4 text-[9px] text-[var(--color-gray-500)] font-medium uppercase tracking-wider">
                        Unlocked on {new Date(achievement.unlockedAt).toLocaleDateString()}
                      </div>
                    )}
                  </div>
                )
              })}
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}

"use client"

import { useEffect } from "react"
import { useRouter } from "next/navigation"
import { AlertTriangle, RefreshCw, ArrowLeft, TrendingUp } from "lucide-react"

export default function BacktestError({
  error,
  reset,
}: {
  error: Error & { digest?: string }
  reset: () => void
}) {
  const router = useRouter()

  useEffect(() => {
    console.error("[Backtest Error]", error)
  }, [error])

  return (
    <div style={{
      display: "flex", flexDirection: "column", alignItems: "center",
      justifyContent: "center", minHeight: "60vh", gap: "1rem",
      textAlign: "center", padding: "2rem"
    }}>
      <div style={{
        width: 48, height: 48, borderRadius: 12,
        background: "rgba(239,68,68,0.1)", border: "1px solid rgba(239,68,68,0.2)",
        display: "flex", alignItems: "center", justifyContent: "center"
      }}>
        <TrendingUp size={24} style={{ color: "var(--color-loss)" }} />
      </div>
      <h2 style={{ fontSize: "1.25rem", fontWeight: 600, margin: 0, color: "var(--color-gray-200)" }}>
        Backtest failed to load
      </h2>
      <p style={{ color: "var(--color-gray-500)", maxWidth: 420, lineHeight: 1.6, fontSize: "0.85rem" }}>
        {error.message || "Could not initialize the backtesting engine."}
      </p>
      <div style={{ display: "flex", gap: "0.75rem", marginTop: "0.5rem" }}>
        <button onClick={() => router.push("/dashboard")} className="btn btn-secondary" style={{ display: "flex", alignItems: "center", gap: 6 }}>
          <ArrowLeft size={14} /> Dashboard
        </button>
        <button onClick={reset} className="btn btn-primary" style={{ display: "flex", alignItems: "center", gap: 6 }}>
          <RefreshCw size={14} /> Retry
        </button>
      </div>
    </div>
  )
}

import { prisma } from "@/lib/prisma"
import { auth } from "@/lib/auth"
import { redirect } from "next/navigation"
import { BillingClient } from "@/components/billing/BillingClient"
import { getActivePlan } from "@/lib/subscriptions"

export const metadata = {
  title: "Billing & Plans | TradeLink",
}

export default async function BillingPage({ searchParams }: { searchParams: Promise<{ feature?: string }> }) {
  const session = await auth()
  if (!session?.user?.id) redirect("/login")

  const { feature } = await searchParams

  const plans = await prisma.plan.findMany({
    where: { isActive: true },
    orderBy: { price: "asc" }
  })

  const currentPlan = await getActivePlan(session.user.id)

  const serializedPlans = plans.map(p => ({
    ...p,
    price: p.price.toNumber()
  }))

  const serializedCurrentPlan = currentPlan ? {
    ...currentPlan,
    price: currentPlan.price.toNumber()
  } : null

  return (
    <div className="main-content" style={{ maxWidth: 1000, margin: "0 auto" }}>
      <div style={{ textAlign: "center", marginBottom: "3rem" }}>
        <h1 className="page-title" style={{ fontSize: "2rem", marginBottom: "0.5rem" }}>
          Upgrade Your Trading Experience
        </h1>
        <p className="page-subtitle" style={{ fontSize: "1rem" }}>
          {feature === "replay" 
            ? "You need an active plan with Replay Access to use the Market Replay simulator." 
            : "Choose the plan that fits your trading goals."}
        </p>
      </div>

      <BillingClient plans={serializedPlans as any} currentPlanId={serializedCurrentPlan?.id} />
    </div>
  )
}

