import { Suspense } from "react"
import { auth } from "@/lib/auth"
import { redirect } from "next/navigation"
import { prisma } from "@/lib/prisma"
import { CalendarView } from "@/components/calendar/CalendarView"
import { CalendarFilter } from "@/components/calendar/CalendarFilter"
import { EconomicCalendarWidget } from "@/components/calendar/EconomicCalendarWidget"
import { resolveAccountScope } from "@/lib/active-account"
import { dayKey } from "@/lib/dates"

export const metadata = {
  title: "P&L Calendar",
}

export default async function CalendarPage({
  searchParams,
}: {
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>
}) {
  const session = await auth()
  if (!session?.user?.id) {
    redirect("/login")
  }

  const searchParamsObj = await searchParams
  const accountIdParam = typeof searchParamsObj?.accountId === "string" ? searchParamsObj.accountId : "all"

  const [user, scope] = await Promise.all([
    prisma.user.findUnique({ where: { id: session.user.id }, select: { timezone: true } }),
    resolveAccountScope(session.user.id, accountIdParam),
  ])
  const timezone = user?.timezone ?? "UTC"

  // Resolve which accountId to pass to the client component for detailing
  const selectedAccountId = accountIdParam === "all"
    ? "all"
    : accountIdParam
      ? (scope.accounts[0]?.id ?? null)
      : null

  let trades: any[] = []
  if (scope.all) {
    trades = await prisma.trade.findMany({
      where: { userId: session.user.id, status: "closed" },
      select: {
        exitAt: true,
        netPnl: true,
      },
    })
  } else if (scope.accounts.length > 0) {
    trades = await prisma.trade.findMany({
      where: { accountId: scope.accounts[0].id, status: "closed" },
      select: {
        exitAt: true,
        netPnl: true,
      },
    })
  }

  // Aggregate P&L and trade counts by day (YYYY-MM-DD in the user's timezone)
  const dailyPnl: Record<string, number> = {}
  const dailyTradeCount: Record<string, number> = {}

  for (const trade of trades) {
    if (!trade.exitAt) continue // Guard: skip open trades
    const dateStr = dayKey(new Date(trade.exitAt), timezone)
    if (dailyPnl[dateStr] === undefined) {
      dailyPnl[dateStr] = 0
      dailyTradeCount[dateStr] = 0
    }
    dailyPnl[dateStr] += Number(trade.netPnl)
    dailyTradeCount[dateStr] += 1
  }

  // Aggregate prop challenge daily snapshots (keyed by UTC calendar day)
  const propSnapshots = await prisma.propChallengeDailySnapshot.findMany({
    where: {
      challenge: { userId: session.user.id },
    },
    select: {
      date: true,
      dailyPnl: true,
      challenge: { select: { id: true, account: { select: { name: true } } } },
    },
  })

  const propDailyPnl = propSnapshots.reduce((acc, s) => {
    const dateStr = dayKey(s.date, "UTC")
    if (!acc[dateStr]) acc[dateStr] = 0
    acc[dateStr] += Number(s.dailyPnl)
    return acc
  }, {} as Record<string, number>)

  // Retrieve accounts for the filter dropdown
  const filterAccounts = await prisma.tradingAccount.findMany({
    where: { userId: session.user.id },
    select: { id: true, name: true, isDefault: true },
    orderBy: { createdAt: "asc" },
  })

  return (
    <div>
      <div className="page-header" style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: "1rem" }}>
        <div>
          <h1 className="page-title">P&L Calendar</h1>
          <p className="page-subtitle">Visualize your daily performance and consistency.</p>
        </div>
        <Suspense fallback={null}>
          <CalendarFilter accounts={filterAccounts} />
        </Suspense>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))", gap: "1.5rem", alignItems: "start" }}>
        <div style={{ gridColumn: "1 / -1" }}>
          <CalendarView dailyPnl={dailyPnl} dailyTradeCount={dailyTradeCount} propDailyPnl={propDailyPnl} accountId={selectedAccountId || undefined} />
        </div>
        <div style={{ gridColumn: "1 / -1" }}>
          <EconomicCalendarWidget limit={8} />
        </div>
      </div>
    </div>
  )
}

import { auth } from "@/lib/auth"
import { redirect } from "next/navigation"
import { prisma } from "@/lib/prisma"
import { ChallengeCompare } from "@/components/prop-firm/ChallengeCompare"

export const metadata = {
  title: "Compare Challenges",
}

export default async function ComparePage() {
  const session = await auth()
  if (!session?.user?.id) {
    redirect("/login")
  }

  const challenges = await prisma.propChallenge.findMany({
    where: { userId: session.user.id },
    include: {
      template: { select: { firmName: true, logoUrl: true } },
      account: { select: { name: true } },
      dailySnapshots: { orderBy: { date: "desc" }, take: 1 },
    },
    orderBy: { createdAt: "asc" },
  })

  const data = challenges.map(c => {
    const initial = Number(c.initialBalance)
    const current = Number(c.currentBalance ?? initial)
    const profitTarget = initial * (Number(c.profitTargetPct) / 100)
    const currentProfitPct = initial > 0 ? ((current - initial) / initial) * 100 : 0
    const targetProgressPct = profitTarget > 0 ? Math.min(100, ((current - initial) / profitTarget) * 100) : 0
    const maxDdRef = initial
    const ddBudget = maxDdRef * (Number(c.maxDDPct) / 100)
    const ddUsedPct = ddBudget > 0 ? ((maxDdRef - current) / ddBudget) * 100 : 0
    const tradingDays = Number(((c.metadata as any)?.tradingDaysCount) ?? 0)
    const daysRemaining = c.deadlineAt
      ? Math.max(0, Math.ceil((c.deadlineAt.getTime() - Date.now()) / 86400000))
      : null
    const lastSnapshot = c.dailySnapshots[0] ?? null

    return {
      id: c.id,
      firmName: c.template.firmName,
      logoUrl: c.template.logoUrl,
      accountName: c.account.name,
      phase: c.phase,
      status: c.status,
      initialBalance: initial,
      currentBalance: current,
      currentProfitPct: Math.round(currentProfitPct * 100) / 100,
      targetProgressPct: Math.round(Math.max(-100, Math.min(100, targetProgressPct)) * 100) / 100,
      maxDDPct: Number(c.maxDDPct),
      ddUsedPct: Math.round(Math.min(100, Math.max(0, ddUsedPct)) * 100) / 100,
      tradingDays,
      minTradingDays: c.minTradingDays,
      maxTradingDays: c.maxTradingDays,
      daysRemaining,
      lastSnapshotDate: lastSnapshot ? lastSnapshot.date.toISOString().slice(0, 10) : null,
      lastDailyPnl: lastSnapshot ? Number(lastSnapshot.dailyPnl) : null,
    }
  })

  return (
    <div>
      <div className="page-header" style={{ marginBottom: "1.5rem" }}>
        <div>
          <h1 className="page-title">Compare Challenges</h1>
          <p className="page-subtitle">Select challenges to compare them side by side.</p>
        </div>
      </div>
      <ChallengeCompare challenges={data} />
    </div>
  )
}

"use client"

import { useEffect } from "react"
import { useRouter } from "next/navigation"
import { AlertTriangle, RefreshCw, ArrowLeft, BarChart3 } from "lucide-react"

export default function DashboardError({
  error,
  reset,
}: {
  error: Error & { digest?: string }
  reset: () => void
}) {
