              {preview.parseErrors.length > 0 && (
                <div style={{ display: "flex", flexDirection: "column", gap: "0.25rem", padding: "0.65rem", borderRadius: "8px", background: "rgba(239,68,68,0.05)", border: "1px solid rgba(239,68,68,0.2)", fontSize: "0.76rem", color: "var(--color-gray-300)" }}>
                  {preview.parseErrors.slice(0, 3).map((err, idx) => (
                    <div key={idx}>Ligne {err.row} : {err.message}</div>
                  ))}
                </div>
              )}

              {preview.previewRows.length > 0 && (
                <div style={{ overflowX: "auto", border: "1px solid var(--color-gray-800)", borderRadius: "8px" }}>
                  <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "0.78rem", textAlign: "left" }}>
                    <thead>
                      <tr style={{ borderBottom: "1px solid var(--color-gray-800)", background: "var(--color-gray-950)", color: "var(--color-gray-500)", textTransform: "uppercase", fontSize: "0.65rem", fontWeight: 700 }}>
                        <th style={{ padding: "0.5rem 0.65rem" }}>Symbole</th>
                        <th style={{ padding: "0.5rem 0.65rem" }}>Sens</th>
                        <th style={{ padding: "0.5rem 0.65rem" }}>Date d&apos;entrée</th>
                        <th style={{ padding: "0.5rem 0.65rem" }}>Taille</th>
                        <th style={{ padding: "0.5rem 0.65rem" }}>Frais</th>
                        <th style={{ padding: "0.5rem 0.65rem" }}>P&L Net</th>
                      </tr>
                    </thead>
                    <tbody>
                      {preview.previewRows.map((r, idx) => (
                        <tr key={idx} style={{ borderBottom: "1px solid var(--color-gray-900)" }}>
                          <td style={{ padding: "0.5rem 0.65rem", fontWeight: 600, color: "var(--color-gray-200)" }}>{r.symbol}</td>
                          <td style={{ padding: "0.5rem 0.65rem" }}>
                            <span style={{
                              fontSize: "0.65rem",
                              fontWeight: 700,
                              padding: "0.1rem 0.35rem",
                              borderRadius: "4px",
                              background: r.side === "LONG" ? "rgba(16,185,129,0.12)" : "rgba(239,68,68,0.12)",
                              color: r.side === "LONG" ? "var(--color-profit)" : "var(--color-loss)",
                            }}>
                              {r.side}
                            </span>
                          </td>
                          <td style={{ padding: "0.5rem 0.65rem", color: "var(--color-gray-500)" }}>
                            {new Date(r.entryAt).toLocaleString("fr-FR", { dateStyle: "short", timeStyle: "short" })}
                          </td>
                          <td style={{ padding: "0.5rem 0.65rem", fontWeight: 500 }}>{Number(r.quantity).toLocaleString()}</td>
                          <td style={{ padding: "0.5rem 0.65rem", color: "var(--color-gray-500)" }}>
                            {r.fees > 0 ? formatCurrency(r.fees, "USD", true, 2) : formatCurrency(0, "USD", true, 2)}
                          </td>
                          <td style={{ padding: "0.5rem 0.65rem", fontWeight: 700, color: r.netPnl >= 0 ? "var(--color-profit)" : "var(--color-loss)" }}>
                            {formatCurrency(r.netPnl, "USD", true, 2)}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  {preview.total > preview.previewRows.length && (
                    <div style={{ fontSize: "0.72rem", color: "var(--color-gray-500)", padding: "0.5rem 0.65rem", borderTop: "1px solid var(--color-gray-800)", background: "var(--color-gray-950)" }}>
                      … et {preview.total - preview.previewRows.length} autres transactions.
                    </div>
                  )}
                </div>
              )}

              <button
                onClick={handleImport}
                disabled={loading || preview.newRows === 0}
                className="btn btn-primary"
                style={{
                  padding: "0.65rem",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: "0.5rem",
                  fontSize: "0.85rem",
                  fontWeight: 600,
                  height: "40px",
                  marginTop: "0.5rem"
                }}
              >
                {loading ? <Loader2 size={15} className="spin" /> : <Download size={15} />}
                {loading ? "Importation…" : `Importer ${preview.newRows} transaction${preview.newRows !== 1 ? "s" : ""}`}
              </button>
            </div>
          ) : (
            <div className="chart-card" style={{ padding: "2.5rem 2rem", background: "var(--color-gray-900)", border: "1px solid var(--color-gray-800)", borderRadius: "12px", height: "100%", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", textAlign: "center", minHeight: "360px" }}>
              <div style={{ width: "64px", height: "64px", borderRadius: "50%", background: "rgba(255,255,255,0.02)", border: "1px solid var(--color-gray-800)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "1.75rem", marginBottom: "1.25rem" }}>
                📊
              </div>
              <h3 style={{ fontSize: "1rem", fontWeight: 700, color: "var(--color-gray-200)", marginBottom: "0.5rem" }}>
                Aperçu en direct
              </h3>
              <p style={{ fontSize: "0.82rem", color: "var(--color-gray-500)", maxWidth: "280px", lineHeight: 1.5 }}>
                Configurez votre courtier et chargez un relevé CSV sur le panneau de gauche pour voir l&apos;aperçu des transactions.
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

import { auth } from "@/lib/auth"
import { redirect } from "next/navigation"
import { prisma } from "@/lib/prisma"
import { formatCurrency } from "@/lib/formatters"
import { JournalForm } from "@/components/journal/JournalForm"
import { TradeRow } from "@/components/trades/TradeRow"
import Link from "next/link"
import { notFound } from "next/navigation"
import { getActiveAccount } from "@/lib/active-account"
import { dayKey, zonedTimeToUtc, nextMidnightInTz } from "@/lib/dates"

export async function generateMetadata({ params }: { params: Promise<{ date: string }> }) {
  const { date } = await params
  return { title: `Journal - ${date}` }
}

export default async function JournalDatePage({ params }: { params: Promise<{ date: string }> }) {
  const session = await auth()
  if (!session?.user?.id) {
    redirect("/login")
  }

  const { date } = await params
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    notFound()
  }

  const user = await prisma.user.findUnique({
    where: { id: session.user.id },
    select: { timezone: true },
  })
  const timezone = user?.timezone ?? "UTC"

  // Fetch the journal entry if it exists
  const journal = await prisma.dailyJournal.findUnique({
    where: {
      userId_date: {
        userId: session.user.id,
        date,
      },
    },
  })

  // Fetch trades for this day (day boundaries in the user's timezone)
  const targetStart = zonedTimeToUtc(new Date(`${date}T00:00:00`), timezone)
  const targetEnd = nextMidnightInTz(targetStart, timezone)

  const account = await getActiveAccount(session.user.id)

  const trades = await prisma.trade.findMany({
    where: {
      userId: session.user.id,
      accountId: account?.id,
      entryAt: {
        gte: targetStart,
        lt: targetEnd,
      },
    },
    orderBy: { entryAt: "asc" },
    include: { screenshots: true },
  })

  // Calculate daily stats
  const totalTrades = trades.length
  const winningTrades = trades.filter(t => Number(t.netPnl) > 0).length
  const dailyPnl = trades.reduce((acc, t) => acc + Number(t.netPnl || 0), 0)
  const winRate = totalTrades > 0 ? (winningTrades / totalTrades) * 100 : 0

  // Date object for navigation (string arithmetic is DST-safe)
  const [ny, nm, nd] = date.split("-").map(Number)
  const prevDateStr = dayKey(new Date(Date.UTC(ny, nm - 1, nd - 1, 0, 0, 0, 0)), "UTC")
  const nextDateStr = dayKey(new Date(Date.UTC(ny, nm - 1, nd + 1, 0, 0, 0, 0)), "UTC")

  // Prop firm daily snapshots for this day (UTC calendar day)
  const dayStartUtc = new Date(Date.UTC(ny, nm - 1, nd, 0, 0, 0, 0))
  const dayEndUtc = new Date(Date.UTC(ny, nm - 1, nd + 1, 0, 0, 0, 0))
  const propSnapshots = await prisma.propChallengeDailySnapshot.findMany({
    where: {
      challenge: { userId: session.user.id },
      date: { gte: dayStartUtc, lt: dayEndUtc },
    },
    include: { challenge: { include: { template: true, account: true } } },
  })

  const displayDate = new Date(`${date}T00:00:00`).toLocaleDateString("en-US", {
    timeZone: timezone,
    weekday: "long",
    year: "numeric",
    month: "long",
    day: "numeric",
  })

  return (
    <div>
      <div className="page-header" style={{ marginBottom: "1rem" }}>
        <div>
          <div style={{ display: "flex", alignItems: "center", gap: "1rem", marginBottom: "0.25rem" }}>
            <Link href="/calendar" className="btn btn-ghost btn-sm" style={{ padding: "0.25rem 0.5rem" }}>
              ← Calendar
            </Link>
            <h1 className="page-title">{displayDate}</h1>
          </div>
        </div>
        <div className="actions" style={{ display: "flex", gap: "0.5rem" }}>
          <Link href={`/journal/${prevDateStr}`} className="btn btn-secondary btn-sm">
            ← Prev Day
          </Link>
          <Link href={`/journal/${nextDateStr}`} className="btn btn-secondary btn-sm">
            Next Day →
          </Link>
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 3fr", gap: "1.5rem", marginBottom: "2rem" }}>
        {/* Daily Stats Summary */}
        <div style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
          <div className="kpi-card">
            <div className="kpi-label">Daily P&L</div>
            <div className={`kpi-value ${dailyPnl > 0 ? "profit" : dailyPnl < 0 ? "loss" : ""}`}>
              {formatCurrency(dailyPnl, "USD", true, 2)}
            </div>
          </div>
          <div className="kpi-card">
            <div className="kpi-label">Win Rate</div>
            <div className="kpi-value">{winRate.toFixed(1)}%</div>
            <div className="kpi-sub">{winningTrades} W / {totalTrades - winningTrades} L</div>
          </div>
          <div className="kpi-card">
            <div className="kpi-label">Total Trades</div>
            <div className="kpi-value">{totalTrades}</div>
          </div>

          {propSnapshots.length > 0 && (
            <div className="chart-card" style={{ padding: "1rem", background: "var(--color-gray-900)", border: "1px solid var(--color-gray-800)" }}>
              <div style={{ fontSize: "0.75rem", textTransform: "uppercase", letterSpacing: "0.05em", color: "var(--color-gray-500)", marginBottom: "0.75rem" }}>
                Prop Firm P&L
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: "0.5rem" }}>
                {propSnapshots.map(s => (
                  <div key={s.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", fontSize: "0.85rem" }}>
                    <span style={{ color: "var(--color-gray-300)" }}>
                      {s.challenge.template.logoUrl ? (
                        <img src={s.challenge.template.logoUrl} alt="" style={{ width: "16px", height: "16px", objectFit: "contain", marginRight: "0.35rem", verticalAlign: "middle", borderRadius: "3px" }} />
                      ) : null}
                      {s.challenge.template.firmName}
                    </span>
                    <span style={{
                      fontWeight: 600,
                      color: Number(s.dailyPnl) > 0 ? "var(--color-profit)" : Number(s.dailyPnl) < 0 ? "var(--color-loss)" : "var(--color-gray-400)",
                    }}>
                      {formatCurrency(Number(s.dailyPnl), "USD", true, 2)}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Journal Form */}
        <div>
          <JournalForm date={date} initialData={journal} />
        </div>
      </div>

      {/* Daily Trades Table */}
      <h3 style={{ fontSize: "1.1rem", fontWeight: 600, color: "var(--color-gray-200)", marginBottom: "1rem" }}>
        Trades on {displayDate}
      </h3>
      <div className="table-wrapper">
        <table className="data-table">
          <thead>
            <tr>
              <th>Entry Time</th>
              <th>Symbol</th>
              <th>Instrument</th>
              <th>Side</th>
              <th>Qty</th>
              <th>Entry Price</th>
              <th>Exit Price</th>
              <th style={{ textAlign: "right" }}>Net P&L</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {trades.length === 0 ? (
              <tr>
                <td colSpan={9} style={{ textAlign: "center", padding: "3rem" }}>
                  <div className="empty-state">
                    <p>No trades executed on this day.</p>
                  </div>
                </td>
              </tr>
            ) : (
              trades.map((t) => {
                const serializedTrade = {
                  ...t,
                  quantity: t.quantity ? Number(t.quantity) : 0,
                  entryPrice: t.entryPrice ? Number(t.entryPrice) : 0,
                  exitPrice: t.exitPrice ? Number(t.exitPrice) : null,
                  grossPnl: t.grossPnl ? Number(t.grossPnl) : null,
                  fees: t.fees ? Number(t.fees) : 0,
                  netPnl: t.netPnl ? Number(t.netPnl) : null,
                  netPnlUsd: t.netPnlUsd ? Number(t.netPnlUsd) : null,
                  stopLoss: t.stopLoss ? Number(t.stopLoss) : null,
                  riskAmount: t.riskAmount ? Number(t.riskAmount) : null,
                }
                return <TradeRow key={t.id} trade={serializedTrade} />
              })
            )}
          </tbody>
        </table>
      </div>
    </div>
  )
}

import { AppShell } from "@/components/layout/AppShell"
import { auth } from "@/lib/auth"
import { getActivePlan } from "@/lib/subscriptions"
import { prisma } from "@/lib/prisma"
import { redirect } from "next/navigation"

export default async function AppLayout({ children }: { children: React.ReactNode }) {
  const session = await auth()
  let features = {}
  let backtestAccess = false

  if (session?.user?.id) {
    const user = await prisma.user.findUnique({
      where: { id: session.user.id },
      select: { onboarded: true }
    })

    if (user && !user.onboarded) {
      redirect("/onboarding")
    }

    const plan = await getActivePlan(session.user.id)
    const userRole = (session.user as any).role
    const isAdmin = userRole === "ADMIN" || userRole === "SUPER_ADMIN"

    const baseFeatures = plan?.features as Record<string, boolean> | undefined || {}
    features = isAdmin 
      ? { replayAccess: true, propFirmAccess: true, advancedStats: true, backtestAccess: true } 
      : baseFeatures
    backtestAccess = isAdmin ? true : !!plan?.backtestAccess
  }

  return <AppShell initialFeatures={features} initialBacktestAccess={backtestAccess}>{children}</AppShell>
}

