import { NextResponse } from "next/server"
import { requireAdmin, logAdminAction } from "@/lib/admin-auth"
import { prisma } from "@/lib/prisma"
import { z } from "zod"

const impersonateSchema = z.object({
  action: z.literal("impersonate"),
  reason: z.string().max(500).optional(),
})

export async function GET(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const session = await requireAdmin()
  const { id } = await params

  const user = await prisma.user.findUnique({
    where: { id },
    select: {
      id: true,
      email: true,
      name: true,
      role: true,
      status: true,
      createdAt: true,
      lastLoginAt: true,
      deletedAt: true,
      _count: {
        select: {
          accounts: true,
          backtestSessions: true,
          dailyJournals: true,
        },
      },
      accounts: {
        select: { id: true, name: true, broker: true, type: true },
      },
      adminActionLogs: {
        where: { targetUserId: id },
        include: { admin: { select: { email: true, name: true } } },
        orderBy: { createdAt: "desc" },
        take: 20,
      },
    },
  })

  if (!user) {
    return NextResponse.json({ error: "User not found" }, { status: 404 })
  }

  return NextResponse.json({ user })
}

export async function POST(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const session = await requireAdmin()
  const { id } = await params
  const body = await request.json()
  const parsed = impersonateSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: "Invalid input", details: parsed.error.flatten().fieldErrors }, { status: 400 })
  }

  if (parsed.data.action !== "impersonate") {
    return NextResponse.json({ error: "Invalid action" }, { status: 400 })
  }

  // Only SUPER_ADMIN can impersonate
  if (session.user.role !== "SUPER_ADMIN") {
    return NextResponse.json({ error: "Only SUPER_ADMIN can impersonate" }, { status: 403 })
  }

  const targetUser = await prisma.user.findUnique({ where: { id } })
  if (!targetUser) {
    return NextResponse.json({ error: "User not found" }, { status: 404 })
  }

  // Log impersonation
  await logAdminAction({
    adminId: session.user.id,
    targetUserId: id,
    action: "IMPERSONATION_STARTED",
    reason: parsed.data.reason,
    metadata: { targetEmail: targetUser.email },
  })

  // Create impersonation token (30 min expiry)
  const expires = new Date(Date.now() + 30 * 60 * 1000)

  // Set impersonation cookie
  const response = NextResponse.json({
    success: true,
    impersonate: {
      userId: id,
      email: targetUser.email,
      expires: expires.toISOString(),
    },
  })

  // Set a cookie that the middleware can read
  response.cookies.set("admin_impersonate", JSON.stringify({
    userId: id,
    adminId: session.user.id,
    expires: expires.toISOString(),
  }), {
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: "lax",
    maxAge: 30 * 60, // 30 minutes
    path: "/",
  })

  return response
}

import { NextResponse } from "next/server"
import { requireAdmin, logAdminAction } from "@/lib/admin-auth"
import { prisma } from "@/lib/prisma"
import { z } from "zod"

const PATCHSchema = z.object({
  userId: z.string(),
  action: z.enum(["change_role", "suspend", "activate", "ban", "delete"]),
  reason: z.string().optional(),
  role: z.enum(["USER", "ADMIN", "SUPER_ADMIN"]).optional(),
})

export async function GET(request: Request) {
  const session = await requireAdmin()
  const { searchParams } = new URL(request.url)

  const page = parseInt(searchParams.get("page") || "1")
  const pageSize = parseInt(searchParams.get("pageSize") || "20")
  const search = searchParams.get("search") || ""
  const role = searchParams.get("role") || ""
  const status = searchParams.get("status") || ""
  const sortBy = searchParams.get("sortBy") || "createdAt"
  const sortOrder = searchParams.get("sortOrder") || "desc"

  const where: Record<string, unknown> = { deletedAt: null }

  if (search) {
    where.OR = [
      { email: { contains: search, mode: "insensitive" } },
      { name: { contains: search, mode: "insensitive" } },
    ]
  }

  if (role) where.role = role
  if (status) where.status = status

  const [users, total] = await Promise.all([
    prisma.user.findMany({
      where,
      select: {
        id: true,
        email: true,
        name: true,
        role: true,
        status: true,
        createdAt: true,
        lastLoginAt: true,
        _count: { select: { accounts: true } },
      },
      orderBy: { [sortBy]: sortOrder },
      skip: (page - 1) * pageSize,
      take: pageSize,
    }),
    prisma.user.count({ where }),
  ])

  return NextResponse.json({ users, total, page, pageSize })
}

export async function PATCH(request: Request) {
  const session = await requireAdmin()
  const body = await request.json()
  const parsed = PATCHSchema.safeParse(body)

  if (!parsed.success) {
    return NextResponse.json({ error: "Invalid payload" }, { status: 400 })
  }

  const { userId, action, reason, role } = parsed.data

  // Cannot modify yourself (except role change to self)
  if (userId === session.user.id && action !== "change_role") {
    return NextResponse.json({ error: "Cannot modify your own account" }, { status: 400 })
  }

  // Fetch target user
  const targetUser = await prisma.user.findUnique({ where: { id: userId } })
  if (!targetUser) {
    return NextResponse.json({ error: "User not found" }, { status: 404 })
  }

  // Check if target is SUPER_ADMIN and current user is not SUPER_ADMIN
  if (targetUser.role === "SUPER_ADMIN" && session.user.role !== "SUPER_ADMIN") {
    return NextResponse.json({ error: "Cannot modify SUPER_ADMIN" }, { status: 403 })
  }

  let updateData: Record<string, unknown> = {}
  let logAction = ""

  switch (action) {
    case "change_role":
      if (!role) {
        return NextResponse.json({ error: "Role is required" }, { status: 400 })
      }
      // ADMIN cannot promote to SUPER_ADMIN
      if (role === "SUPER_ADMIN" && session.user.role !== "SUPER_ADMIN") {
        return NextResponse.json({ error: "Only SUPER_ADMIN can promote to SUPER_ADMIN" }, { status: 403 })
      }
      updateData = { role }
      logAction = "ROLE_CHANGED"
      break

    case "suspend":
      updateData = { status: "SUSPENDED" }
      logAction = "USER_SUSPENDED"
      break

    case "activate":
      updateData = { status: "ACTIVE" }
      logAction = "USER_ACTIVATED"
      break

    case "ban":
      updateData = { status: "BANNED" }
      logAction = "USER_BANNED"
      break

    case "delete":
      updateData = { deletedAt: new Date() }
      logAction = "USER_DELETED"
      break
  }

  await prisma.user.update({ where: { id: userId }, data: updateData })

  await logAdminAction({
    adminId: session.user.id,
    targetUserId: userId,
    action: logAction,
    reason,
    metadata: { previousRole: targetUser.role, newRole: role },
  })

  return NextResponse.json({ success: true })
}

import { NextResponse } from "next/server"
import { prisma } from "@/lib/prisma"
import bcrypt from "bcryptjs"
import { z } from "zod"
import { rateLimit } from "@/lib/rate-limit"

const registerSchema = z.object({
  name: z.string().min(2),
  email: z.string().email(),
  password: z.string().min(8),
})

export async function POST(request: Request) {
  try {
    // Rate limit: 5 attempts per minute per IP
    const ip = request.headers.get("x-forwarded-for") || "unknown"
    const { success } = rateLimit(`register:${ip}`, { limit: 5, windowMs: 60000 })
    if (!success) {
      return NextResponse.json({ error: "Too many requests. Please try again later." }, { status: 429 })
    }

    const body = await request.json()
    const { name, email, password } = registerSchema.parse(body)

    // Check if user already exists
    const existingUser = await prisma.user.findUnique({
      where: { email },
    })

    if (existingUser) {
      return NextResponse.json({ error: "User already exists with this email." }, { status: 400 })
    }

    // Hash password
    const passwordHash = await bcrypt.hash(password, 10)

    // Create user and a default trading account in a transaction
    const user = await prisma.$transaction(async (tx: any) => {
      const newUser = await tx.user.create({
        data: {
          name,
          email,
          passwordHash,
        },
      })

      await tx.tradingAccount.create({
        data: {
          userId: newUser.id,
          name: "Main Account",
          baseCurrency: "USD",
          initialBalance: 10000,
          isDefault: true,
        },
      })

      return newUser
    })

    // Send Welcome Email asynchronously (don't block the response)
    import("@/lib/email").then(({ sendEmail }) => {
      import("@/emails/WelcomeEmail").then(({ WelcomeEmail }) => {
        sendEmail({
          to: user.email,
          subject: "Welcome to TradeLink 🚀",
          react: WelcomeEmail({ userName: user.name || "Trader" }),
        }).catch(console.error)
      })
    }).catch(console.error)

    return NextResponse.json({ id: user.id, email: user.email, name: user.name })
  } catch (error: unknown) {
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 })
  }
}

import { NextResponse } from "next/server"
import { z } from "zod"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { ensureBacktestAccount } from "@/lib/backtest"
import { classifySymbol } from "@/lib/market/symbols"
import { MARKET_TIMEFRAMES } from "@/lib/market/types"

const tradeSchema = z.object({
  side: z.enum(["long", "short"]),
  symbol: z.string().trim().toUpperCase().min(1),
  entryPrice: z.number().positive(),
  exitPrice: z.number().positive(),
  entryAt: z.number().int().positive(),
  exitAt: z.number().int().positive(),
  stopLoss: z.number().positive().optional(),
  takeProfit: z.number().positive().optional(),
  quantity: z.number().positive(),
  riskAmount: z.number().optional(),
  netPnl: z.number(),
  screenshotUrl: z.string().optional(),
  notes: z.string().optional(),
})

const bodySchema = z.object({
  symbol: z.string().trim().toUpperCase().min(1),
  timeframe: z.enum(MARKET_TIMEFRAMES),
  from: z.number().int().positive(),
  to: z.number().int().positive(),
  strategyName: z.string().optional(),
  initialBalance: z.number().positive().default(10000),
  trades: z.array(tradeSchema).max(1000),
})

export async function GET() {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const sessions = await prisma.backtestSession.findMany({
      where: { userId: session.user.id },
      orderBy: { createdAt: "desc" },
      take: 50,
      include: {
        trades: {
          select: {
            id: true,
            symbol: true,
            side: true,
            entryPrice: true,
            exitPrice: true,
            stopLoss: true,
            quantity: true,
            entryAt: true,
            exitAt: true,
            netPnl: true,
          },
          orderBy: { entryAt: "asc" },
        },
      },
    })

    return NextResponse.json(
      sessions.map((s) => ({
        id: s.id,
        symbol: s.symbol,
        timeframe: s.timeframe,
        from: s.from,
        to: s.to,
        strategyName: s.strategyName,
        initialBalance: Number(s.initialBalance),
        closedPnl: s.closedPnl ? Number(s.closedPnl) : null,
        winRate: s.winRate ? Number(s.winRate) : null,
        tradesCount: s.tradesCount,
        createdAt: s.createdAt,
        trades: s.trades.map((t) => ({
          id: t.id,
          symbol: t.symbol,
          side: t.side,
          entryPrice: Number(t.entryPrice),
          exitPrice: Number(t.exitPrice ?? t.entryPrice),
          stopLoss: t.stopLoss ? Number(t.stopLoss) : null,
          quantity: Number(t.quantity),
          entryAt: t.entryAt,
          exitAt: t.exitAt,
          netPnl: Number(t.netPnl ?? 0),
        })),
      })),
    )
  } catch (error) {
    const message = "Internal Server Error"
    console.error("Backtest sessions list error:", message)
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

export async function POST(request: Request) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const parsed = bodySchema.safeParse(await request.json())
    if (!parsed.success) {
      return NextResponse.json(
        { error: parsed.error.issues.map((i) => i.message).join(", ") },
        { status: 400 },
      )
    }

    const { symbol, timeframe, from, to, strategyName, initialBalance, trades } = parsed.data
    const userId = session.user.id
    const account = await ensureBacktestAccount(userId)

    const pnls = trades.map((t) => t.netPnl)
    const closedPnl = pnls.reduce((s, p) => s + p, 0)
    const wins = pnls.filter((p) => p > 0).length
    const winRate = trades.length ? Math.round((wins / trades.length) * 10000) / 100 : null

    const backtestSession = await prisma.backtestSession.create({
      data: {
        userId,
        symbol,
        timeframe,
        from: new Date(from * 1000),
        to: new Date(to * 1000),
        strategyName: strategyName || null,
        initialBalance,
        tradesCount: trades.length,
        closedPnl,
        winRate,
        trades: {
          create: trades.map((t) => ({
            userId,
            accountId: account.id,
            symbol: t.symbol,
            instrumentType: classifySymbol(t.symbol),
            side: t.side === "long" ? "LONG" : "SHORT",
            quantity: t.quantity,
            entryPrice: t.entryPrice,
            exitPrice: t.exitPrice,
            entryAt: new Date(t.entryAt * 1000),
            exitAt: new Date(t.exitAt * 1000),
            stopLoss: t.stopLoss ?? null,
            grossPnl: t.netPnl,
            netPnl: t.netPnl,
            netPnlUsd: t.netPnl,
            riskAmount: t.riskAmount ?? null,
            notesPost: t.notes ?? null,
            status: "closed",
            source: "backtest",
            importSource: "backtest",
            ...(t.screenshotUrl
              ? {
                  screenshots: {
                    create: {
                      storageUrl: t.screenshotUrl,
                      fileName: t.screenshotUrl.split("/").pop() || "replay.png",
                    },
                  },
                }
              : {}),
          })),
        },
      },
    })

    return NextResponse.json({ success: true, session: backtestSession })
  } catch (error) {
    const message = "Internal Server Error"
    console.error("Backtest session save error:", message)
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

import { NextResponse } from "next/server"
import { z } from "zod"
import { Prisma } from "@prisma/client"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { ensureBacktestAccount } from "@/lib/backtest"
import { classifySymbol } from "@/lib/market/symbols"
import { MARKET_TIMEFRAMES } from "@/lib/market/types"

const tradeSchema = z.object({
  side: z.enum(["long", "short"]),
  symbol: z.string().trim().toUpperCase().min(1),
  entryPrice: z.number().positive(),
  exitPrice: z.number().positive(),
  entryAt: z.number().int().positive(),
  exitAt: z.number().int().positive(),
  stopLoss: z.number().positive().optional(),
  takeProfit: z.number().positive().optional(),
  quantity: z.number().positive(),
  riskAmount: z.number().optional(),
  netPnl: z.number(),
  screenshotUrl: z.string().optional(),
  notes: z.string().optional(),
})

const bodySchema = z.object({
  session: z.object({
    symbol: z.string().trim().toUpperCase().min(1),
    timeframe: z.enum(MARKET_TIMEFRAMES),
    from: z.number().int().positive(),
    to: z.number().int().positive(),
    strategyName: z.string().optional(),
    initialBalance: z.number().positive().default(10000),
  }),
  trade: tradeSchema,
})

export async function POST(request: Request) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const parsed = bodySchema.safeParse(await request.json())
    if (!parsed.success) {
      return NextResponse.json(
        { error: parsed.error.issues.map((i) => i.message).join(", ") },
        { status: 400 },
      )
    }

    const { session: s, trade: t } = parsed.data
    const account = await ensureBacktestAccount(session.user.id)

    // Find (or create) a session matching this replay period so trades from the
    // same replay accumulate into one BacktestSession.
    let backtestSession = await prisma.backtestSession.findFirst({
      where: {
        userId: session.user.id,
        symbol: s.symbol,
        timeframe: s.timeframe,
        from: new Date(s.from * 1000),
        to: new Date(s.to * 1000),
      },
      orderBy: { createdAt: "desc" },
    })

    if (!backtestSession) {
      backtestSession = await prisma.backtestSession.create({
        data: {
          userId: session.user.id,
          symbol: s.symbol,
          timeframe: s.timeframe,
          from: new Date(s.from * 1000),
          to: new Date(s.to * 1000),
          strategyName: s.strategyName || null,
          initialBalance: s.initialBalance,
        },
      })
    }

    const trade = await prisma.trade.create({
      data: {
        userId: session.user.id,
        accountId: account.id,
        backtestSessionId: backtestSession.id,
        symbol: t.symbol,
        instrumentType: classifySymbol(t.symbol),
        side: t.side === "long" ? "LONG" : "SHORT",
        quantity: t.quantity,
        entryPrice: t.entryPrice,
        exitPrice: t.exitPrice,
        entryAt: new Date(t.entryAt * 1000),
        exitAt: new Date(t.exitAt * 1000),
        stopLoss: t.stopLoss ?? null,
        grossPnl: t.netPnl,
        netPnl: t.netPnl,
        netPnlUsd: t.netPnl,
        riskAmount: t.riskAmount ?? null,
        notesPost: t.notes ?? null,
        status: "closed",
        source: "backtest",
        importSource: "backtest",
        screenshots: t.screenshotUrl
          ? {
              create: {
                storageUrl: t.screenshotUrl,
                fileName: t.screenshotUrl.split("/").pop() || "replay.png",
              },
            }
          : undefined,
      },
    })

    // Refresh session aggregates
    // includeBacktest is a sentinel stripped by the Prisma client extension
    const where: Prisma.TradeWhereInput = {
      backtestSessionId: backtestSession.id,
    }
    const trades = await prisma.trade.findMany({ where })
    const pnls = trades.map((x) => Number(x.netPnl || 0))
    const wins = pnls.filter((p) => p > 0).length
    const closedPnl = pnls.reduce((s, p) => s + p, 0)
    await prisma.backtestSession.update({
      where: { id: backtestSession.id },
      data: {
        tradesCount: trades.length,
        closedPnl,
        winRate: trades.length ? Math.round((wins / trades.length) * 10000) / 100 : null,
      },
    })

    // Invalidate behavioral snapshot cache
    await prisma.behavioralSnapshot.deleteMany({
      where: { accountId: account.id },
    })

    return NextResponse.json({ success: true, trade, sessionId: backtestSession.id })
  } catch (error) {
    const message = "Internal Server Error"
    console.error("Backtest trade save error:", message)
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

// API Route — GET /api/behavioral?range=all|90d|30d&accountId=all|<id>
// Analyse comportementale (tous les comptes par défaut)

import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { analyzeBehavior } from "@/lib/behavioral"
import { NextResponse } from "next/server"
import { resolveAccountScope } from "@/lib/active-account"

const RANGES: Record<string, number> = { "30d": 30, "90d": 90, "all": 0 }

export async function GET(request: Request) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const url = new URL(request.url)
    const range = url.searchParams.get("range") || "all"
    const accountIdParam = url.searchParams.get("accountId") || "all"
    const days = RANGES[range] ?? 0

    const scope = await resolveAccountScope(session.user.id, accountIdParam)

    if (scope.accounts.length === 0) {
      return NextResponse.json({ disciplineScore: 100, patterns: [], summary: "No account found." })
    }

    const user = await prisma.user.findUnique({
      where: { id: session.user.id },
      select: { email: true, timezone: true, notificationPrefs: true },
    })
    const timezone = user?.timezone ?? "UTC"

    const tradeWhere: any = scope.all
      ? { userId: session.user.id, status: "closed" }
      : { accountId: scope.accounts[0].id, status: "closed" }

    const historyWhere: any = scope.all
      ? { userId: session.user.id }
      : { accountId: scope.accounts[0].id }

    const since = days > 0 ? new Date(Date.now() - days * 86400000) : undefined

    const [history, trades] = await Promise.all([
      prisma.behavioralSnapshot.findMany({
        where: historyWhere,
        orderBy: { computedAt: "asc" },
        select: { disciplineScore: true, computedAt: true }
      }),
      prisma.trade.findMany({
        where: {
          ...tradeWhere,
          ...(since ? { entryAt: { gte: since } } : {}),
        },
        orderBy: { entryAt: "asc" },
      }),
    ])

    const result = analyzeBehavior(trades, timezone)

    const byId = new Map(trades.map(t => [t.id, t]))
    const typeMeta: Record<string, { label: string; color: string }> = {
      revenge_trading: { label: "Revenge", color: "var(--color-warning)" },
      overtrading: { label: "Overtrading", color: "var(--color-info)" },
      stop_violation: { label: "Stop violation", color: "var(--color-loss)" },
    }
    const recentFlags = result.patterns
      .flatMap(p =>
        (p.affectedTradeIds || [])
          .map(id => byId.get(id))
          .filter((t): t is NonNullable<typeof t> => !!t)
          .map(t => ({
            id: t.id,
            symbol: t.symbol,
            side: t.side,
            netPnl: Number(t.netPnl || 0),
            entryAt: t.entryAt.toISOString(),
            type: p.type,
            label: typeMeta[p.type]?.label || p.type,
            color: typeMeta[p.type]?.color || "var(--color-gray-400)",
          }))
      )
      .sort((a, b) => new Date(b.entryAt).getTime() - new Date(a.entryAt).getTime())
      .slice(0, 8)

      if (range === "all" && trades.length > 0 && !scope.all) {
      const acctId = scope.accounts[0].id
      await prisma.behavioralSnapshot.upsert({
        where: {
          accountId_periodStart_periodEnd: {
            accountId: acctId,
            periodStart: result.period.start,
            periodEnd: result.period.end,
          },
        },
        create: {
          userId: session.user.id,
          accountId: acctId,
          periodStart: result.period.start,
          periodEnd: result.period.end,
          disciplineScore: result.disciplineScore,
          patterns: result.patterns as object,
        },
        update: {
          disciplineScore: result.disciplineScore,
          patterns: result.patterns as object,
          computedAt: new Date(),
        },
      })

      // Risk Alert Email Logic (Cooldown 24h)
      if (result.disciplineScore < 40 && user?.email) {
        const prefs = (user.notificationPrefs as any) || {}
        const lastAlert = prefs.lastRiskAlertAt ? new Date(prefs.lastRiskAlertAt) : new Date(0)
        const now = new Date()

        if (now.getTime() - lastAlert.getTime() > 86400000) {
          // Trigger email asynchronously
          import("@/lib/email").then(({ sendEmail }) => {
            import("@/emails/RiskAlertEmail").then(({ RiskAlertEmail }) => {
              sendEmail({
                to: user.email,
                subject: "⚠️ TradeLink Risk Alert",
                react: RiskAlertEmail({
                  userName: "Trader",
                  alertType: "Low Discipline Score",
                  description: `Your discipline score dropped to ${result.disciplineScore}. You are exhibiting high-risk behavior patterns.`,
                }),
              }).catch(console.error)
            })
          }).catch(console.error)

          // Update last alert time
          await prisma.user.update({
            where: { id: session.user.id },
            data: {
              notificationPrefs: {
                ...prefs,
                lastRiskAlertAt: now.toISOString(),
              },
            },
          })
        }
      }
    }

    return NextResponse.json({ ...result, history, range, recentFlags })
  } catch (error) {
    console.error("[BEHAVIORAL_GET]", error instanceof Error ? error.message : "Unknown error")
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 })
  }
}

function buildSummary(score: number): string {
  if (score >= 85) return "Excellent discipline. Your trading is consistent and rule-based."
  if (score >= 70) return "Good discipline with minor areas to improve."
  if (score >= 50) return "Behavioral patterns detected that are costing you money."
  return "Critical discipline issues detected. Addressing these patterns should be your top priority."
}

import { NextResponse } from "next/server"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { resolveAccountScope } from "@/lib/active-account"
import { dayKey } from "@/lib/dates"

export async function GET(req: Request, { params }: { params: Promise<{ date: string }> }) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const { date } = await params
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      return NextResponse.json({ error: "Invalid date format" }, { status: 400 })
    }

    const { searchParams } = new URL(req.url)
    const accountId = searchParams.get("accountId")

    const [user, scope] = await Promise.all([
      prisma.user.findUnique({ where: { id: session.user.id }, select: { timezone: true } }),
      resolveAccountScope(session.user.id, accountId),
    ])
    const timezone = user?.timezone ?? "UTC"

    const whereClause: any = scope.all
      ? { userId: session.user.id, status: "closed" }
      : scope.accounts.length > 0
        ? { accountId: scope.accounts[0].id, status: "closed" }
        : null

    const trades = whereClause
      ? await prisma.trade.findMany({
          where: whereClause,
          select: {
            id: true,
            symbol: true,
            side: true,
            quantity: true,
            entryAt: true,
            exitAt: true,
            netPnl: true,
            setupTags: true,
            status: true,
          },
        })
      : []

    const dayTrades = trades
      .filter((t) => t.exitAt && dayKey(new Date(t.exitAt), timezone) === date)
      .map((t) => ({
        id: t.id,
        symbol: t.symbol,
        side: t.side,
        quantity: Number(t.quantity || 0),
        entryAt: t.entryAt.toISOString(),
        exitAt: t.exitAt?.toISOString() ?? null,
        netPnl: Number(t.netPnl || 0),
        setupTags: t.setupTags || [],
        status: t.status,
      }))

    const dayPnl = dayTrades.reduce((s, t) => s + t.netPnl, 0)

    const [journal, propSnapshots] = await Promise.all([
      prisma.dailyJournal.findUnique({
        where: { userId_date: { userId: session.user.id, date } },
        select: {
          mood: true,
          sleepHours: true,
          sessionPlan: true,
          endOfDaySummary: true,
          rating: true,
          disciplineChecks: true,
          nightReflection: true,
        },
      }),
      prisma.propChallengeDailySnapshot.findMany({
        where: { date: new Date(date + "T12:00:00Z") },
        select: {
          dailyPnl: true,
          challenge: { select: { account: { select: { name: true } }, template: { select: { firmName: true } } } },
        },
      }),
    ])

    return NextResponse.json({
      date,
      dayPnl: Math.round(dayPnl * 100) / 100,
      trades: dayTrades,
      journal,
      propSnapshots: propSnapshots.map((s) => ({
        firmName: s.challenge.template.firmName,
        accountName: s.challenge.account.name,
        dailyPnl: Number(s.dailyPnl),
      })),
    })
  } catch (error: any) {
    console.error("[CALENDAR_DAY]", error instanceof Error ? error.message : "Unknown error")
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 })
  }
}

import { NextResponse } from "next/server"
import { execSync } from "child_process"
import fs from "fs"
import path from "path"
import os from "os"

const CACHE_FILE = path.join(os.tmpdir(), "forexfactory_calendar_cache.json")
const CACHE_TTL = 3600000 * 2 // 2 hours

const FALLBACK_EVENTS = [
  { title: "CPI m/m", country: "USD", date: new Date(Date.now() + 1000 * 60 * 60 * 2).toISOString(), impact: "High", forecast: "0.2%", previous: "0.2%" },
  { title: "Unemployment Claims", country: "USD", date: new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(), impact: "Medium", forecast: "215K", previous: "212K" },
  { title: "ECB Press Conference", country: "EUR", date: new Date(Date.now() + 1000 * 60 * 60 * 26).toISOString(), impact: "High", forecast: "", previous: "" },
  { title: "NFP (Non-Farm Employment)", country: "USD", date: new Date(Date.now() + 1000 * 60 * 60 * 48).toISOString(), impact: "High", forecast: "180K", previous: "175K" },
]

export async function GET() {
  try {
    // 1. Try to serve from valid cache
    if (fs.existsSync(CACHE_FILE)) {
      const stats = fs.statSync(CACHE_FILE)
      if (Date.now() - stats.mtimeMs < CACHE_TTL) {
        const cachedData = JSON.parse(fs.readFileSync(CACHE_FILE, 'utf-8'))
        return NextResponse.json(cachedData, {
          headers: { 'Cache-Control': 'public, s-maxage=3600, stale-while-revalidate=86400' },
        })
      }
    }
  } catch (e) {
    console.error("Cache read error:", e)
  }

  try {
    // 2. Try to fetch fresh data
    const curlCommand = `curl -s "https://nfs.faireconomy.media/ff_calendar_thisweek.json"`
    const stdout = execSync(curlCommand, { encoding: 'utf-8' })

    let data;
    try {
      data = JSON.parse(stdout)
      // Save valid data to cache
      fs.writeFileSync(CACHE_FILE, JSON.stringify(data), 'utf-8')

      return NextResponse.json(data, {
        headers: { 'Cache-Control': 'public, s-maxage=3600, stale-while-revalidate=86400' },
      })
    } catch (parseError) {
      console.warn("Calendar API rate limited. Serving stale cache or fallback.")
      // 3. Fallback to stale cache if API is rate limited
      if (fs.existsSync(CACHE_FILE)) {
        const staleData = JSON.parse(fs.readFileSync(CACHE_FILE, 'utf-8'))
        return NextResponse.json(staleData)
      }

      // 4. Ultimate fallback to static data (no cache exists)
      return NextResponse.json(FALLBACK_EVENTS)
    }
  } catch (error) {
    // 5. Catch any execution errors (curl failure)
    if (fs.existsSync(CACHE_FILE)) {
      const staleData = JSON.parse(fs.readFileSync(CACHE_FILE, 'utf-8'))
      return NextResponse.json(staleData)
    }
    return NextResponse.json(FALLBACK_EVENTS)
  }
}

import { NextResponse } from "next/server"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"

export async function GET(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }
    const { id } = await params

    const challenge = await prisma.propChallenge.findUnique({
      where: { id },
      include: {
        template: true,
        account: true,
        dailySnapshots: { orderBy: { date: "asc" } },
        events: { orderBy: { createdAt: "asc" } },
        payouts: { orderBy: { requestedAt: "asc" } },
        notes: { orderBy: { createdAt: "asc" } },
      },
    })

    if (!challenge || challenge.userId !== session.user.id) {
      return NextResponse.json({ error: "Challenge not found" }, { status: 404 })
    }

    const url = new URL(request.url)
    const format = url.searchParams.get("format") || "csv"

    if (format === "json") {
      return NextResponse.json(challenge)
    }

    // CSV: summary section + daily snapshots
    const lines: string[] = []
    lines.push("SECTION,KEY,VALUE")
    lines.push(`SUMMARY,firm,${escapeCsv(challenge.template.firmName)}`)
    lines.push(`SUMMARY,account,${escapeCsv(challenge.account.name)}`)
    lines.push(`SUMMARY,phase,${challenge.phase}`)
    lines.push(`SUMMARY,status,${challenge.status}`)
    lines.push(`SUMMARY,initialBalance,${Number(challenge.initialBalance).toFixed(2)}`)
    lines.push(`SUMMARY,currentBalance,${Number(challenge.currentBalance ?? challenge.initialBalance).toFixed(2)}`)
    lines.push(`SUMMARY,profitTargetPct,${challenge.profitTargetPct}`)
    lines.push(`SUMMARY,maxDDPct,${challenge.maxDDPct}`)
    lines.push(`SUMMARY,dailyDDPct,${challenge.dailyDDPct}`)
    lines.push(`SUMMARY,minTradingDays,${challenge.minTradingDays ?? ""}`)
    lines.push(`SUMMARY,maxTradingDays,${challenge.maxTradingDays ?? ""}`)
    lines.push(`SUMMARY,startedAt,${challenge.startedAt.toISOString()}`)
    if (challenge.deadlineAt) lines.push(`SUMMARY,deadlineAt,${challenge.deadlineAt.toISOString()}`)
    if (challenge.breachReason) lines.push(`SUMMARY,breachReason,${challenge.breachReason}`)
    lines.push("")
    lines.push("DAILY,date,startBalance,endBalance,lowestEquity,dailyPnl,tradesCount,dailyDDUsedPct")
    for (const s of challenge.dailySnapshots) {
      lines.push(
        `DAILY,${s.date.toISOString().slice(0, 10)},${Number(s.startBalance).toFixed(2)},${Number(s.endBalance).toFixed(2)},${Number(s.lowestEquity).toFixed(2)},${Number(s.dailyPnl).toFixed(2)},${s.tradesCount},${s.dailyDDUsedPct != null ? Number(s.dailyDDUsedPct).toFixed(2) : ""}`
      )
    }
    lines.push("")
    lines.push("EVENT,createdAt,severity,eventType,message")
    for (const e of challenge.events) {
      lines.push(
        `EVENT,${e.createdAt.toISOString()},${e.severity},${e.eventType},${escapeCsv(e.message ?? "")}`
      )
    }
    if (challenge.payouts.length > 0) {
      lines.push("")
      lines.push("PAYOUT,requestedAt,status,amount")
      for (const p of challenge.payouts) {
        lines.push(`PAYOUT,${p.requestedAt.toISOString()},${p.status},${Number(p.amount).toFixed(2)}`)
      }
    }

    const csv = "\uFEFF" + lines.join("\r\n")
    return new NextResponse(csv, {
      headers: {
        "Content-Type": "text/csv; charset=utf-8",
        "Content-Disposition": `attachment; filename="challenge-${id}.csv"`,
      },
    })
  } catch (error: any) {
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 })
  }
}

function escapeCsv(value: string) {
  if (/[",\r\n]/.test(value)) {
    return `"${value.replace(/"/g, '""')}"`
  }
  return value
}

import { NextResponse } from "next/server"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { z } from "zod"

const updateNoteSchema = z.object({
  content: z.string().min(1).max(5000),
})

async function assertOwnership(noteId: string, userId: string) {
  const note = await prisma.propChallengeNote.findUnique({
    where: { id: noteId },
    include: { challenge: { select: { userId: true } } },
  })
  if (!note || note.challenge.userId !== userId) return null
  return note
}

export async function PATCH(
  request: Request,
  { params }: { params: Promise<{ id: string; noteId: string }> }
) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }
    const { id, noteId } = await params
    const note = await assertOwnership(noteId, session.user.id)
    if (!note) {
      return NextResponse.json({ error: "Note not found" }, { status: 404 })
    }

    const body = await request.json()
    const parsed = updateNoteSchema.safeParse(body)
    if (!parsed.success) {
      return NextResponse.json({ error: "Invalid input", details: parsed.error.flatten().fieldErrors }, { status: 400 })
    }

    const { content } = parsed.data

    const updated = await prisma.propChallengeNote.update({
      where: { id: noteId },
      data: { content },
    })
    return NextResponse.json(updated)
  } catch (error: any) {
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 })
  }
}

export async function DELETE(
  request: Request,
  { params }: { params: Promise<{ id: string; noteId: string }> }
) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }
    const { id, noteId } = await params
    const note = await assertOwnership(noteId, session.user.id)
    if (!note) {
      return NextResponse.json({ error: "Note not found" }, { status: 404 })
    }

    await prisma.propChallengeNote.delete({ where: { id: noteId } })
    return NextResponse.json({ success: true })
  } catch (error: any) {
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 })
  }
}

import { NextResponse } from "next/server"
