import { NextRequest, NextResponse } from "next/server"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { z } from "zod"

interface AdminSession {
  user?: { id?: string; role?: string }
}

const updatePayoutSchema = z.object({
  status: z.enum(["requested", "approved", "paid", "rejected"]).optional(),
  amount: z.union([z.string(), z.number()]).optional(),
})

export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string; payoutId: string }> }
) {
  try {
    const session = await auth() as AdminSession
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const { id, payoutId } = await params
    const body = await request.json()
    const parsed = updatePayoutSchema.safeParse(body)
    if (!parsed.success) {
      return NextResponse.json({ error: "Invalid input", details: parsed.error.flatten().fieldErrors }, { status: 400 })
    }

    const challenge = await prisma.propChallenge.findUnique({ where: { id } })
    if (!challenge || challenge.userId !== session.user.id) {
      return NextResponse.json({ error: "Challenge not found" }, { status: 404 })
    }

    const payout = await prisma.propPayout.findFirst({
      where: { id: payoutId, challengeId: id }
    })
    if (!payout) {
      return NextResponse.json({ error: "Payout not found" }, { status: 404 })
    }

    const data: any = {}
    if (parsed.data.status !== undefined) {
      // Only admins can change payout status
      if (session.user.role !== "ADMIN" && session.user.role !== "SUPER_ADMIN") {
        return NextResponse.json({ error: "Only admins can change payout status" }, { status: 403 })
      }
      data.status = parsed.data.status
    }
    if (parsed.data.amount !== undefined && !isNaN(parseFloat(String(parsed.data.amount)))) data.amount = parseFloat(String(parsed.data.amount))

    const updated = await prisma.propPayout.update({
      where: { id: payoutId },
      data
    })

    return NextResponse.json(updated)
  } catch (error) {
    console.error("Error updating payout:", error instanceof Error ? error.message : "Unknown error")
    return NextResponse.json({ error: "Failed to update payout" }, { status: 500 })
  }
}

export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string; payoutId: string }> }
) {
  try {
    const session = await auth() as AdminSession
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const { id, payoutId } = await params

    const challenge = await prisma.propChallenge.findUnique({ where: { id } })
    if (!challenge || challenge.userId !== session.user.id) {
      return NextResponse.json({ error: "Challenge not found" }, { status: 404 })
    }

    const payout = await prisma.propPayout.findFirst({
      where: { id: payoutId, challengeId: id }
    })
    if (!payout) {
      return NextResponse.json({ error: "Payout not found" }, { status: 404 })
    }

    await prisma.propPayout.delete({ where: { id: payoutId } })
    return NextResponse.json({ success: true })
  } catch (error) {
    console.error("Error deleting payout:", error instanceof Error ? error.message : "Unknown error")
    return NextResponse.json({ error: "Failed to delete payout" }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from "next/server"
import { auth } from "@/lib/auth"
import { evaluateChallenge } from "@/lib/prop-firm.service"
import { prisma } from "@/lib/prisma"
import { revalidatePath } from "next/cache"

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const { id } = await params

    const challenge = await prisma.propChallenge.findUnique({
      where: { id }
    })

    if (!challenge || challenge.userId !== session.user.id) {
      return NextResponse.json({ error: "Challenge not found" }, { status: 404 })
    }

    const updatedChallenge = await evaluateChallenge(id)

    revalidatePath(`/challenges/${id}`)
    revalidatePath(`/challenges`)

    return NextResponse.json(updatedChallenge)
  } catch (error: any) {
    console.error("Error recalculating challenge:", error instanceof Error ? error.message : "Unknown error")
    return NextResponse.json({ error: "Failed to recalculate" }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from "next/server"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { evaluateChallenge } from "@/lib/prop-firm.service"

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }
    const { id } = await params

    const challenge = await prisma.propChallenge.findUnique({
      where: { id },
      include: { account: true },
    })
    if (!challenge || challenge.userId !== session.user.id) {
      return NextResponse.json({ error: "Challenge not found" }, { status: 404 })
    }

    // Initial phase based on the challenge structure
    const metadata = (challenge.metadata as any) || {}
    const steps = String(metadata.steps || "2")
    const initialPhase = steps === "1" ? "funded" : "phase_1"

    // Wipe the challenge's trade history, snapshots and events for a fresh start
    await prisma.trade.deleteMany({ where: { accountId: challenge.accountId } })
    await prisma.propChallengeDailySnapshot.deleteMany({ where: { challengeId: id } })
    await prisma.propChallengeEvent.deleteMany({ where: { challengeId: id } })

    // Reset deadline from maxTradingDays
    const maxTradingDays = challenge.maxTradingDays
    const deadlineAt = maxTradingDays
      ? new Date(Date.now() + maxTradingDays * 86400000)
      : null

    const updated = await prisma.propChallenge.update({
      where: { id },
      data: {
        phase: initialPhase,
        status: "active",
        breachedAt: null,
        breachReason: null,
        currentBalance: null,
        currentEquity: null,
        highestBalance: null,
        highestEquity: null,
        todayStartBalance: null,
        todayResetAt: null,
        startedAt: new Date(),
        deadlineAt,
        metadata: { ...metadata, tradingDaysCount: 0 },
      },
    })

    // Re-evaluate to set baseline live values
    await evaluateChallenge(id)

    return NextResponse.json(updated)
  } catch (error: any) {
    console.error("Error resetting challenge:", error instanceof Error ? error.message : "Unknown error")
    return NextResponse.json({ error: "Failed to reset challenge" }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from "next/server"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { z } from "zod"

interface AlertConfig {
  stopTradingPct?: number
  profitGoalPct?: number
  enableStopTrading?: boolean
  enableProfitGoal?: boolean
}

interface ChallengeMetadata {
  steps?: string
  phase1Target?: number | null
  phase2Target?: number | null
  fundedTarget?: number | null
  payoutSplit?: string | null
  [key: string]: unknown
}

const alertConfigSchema = z.object({
  stopTradingPct: z.union([z.string(), z.number()]).optional(),
  profitGoalPct: z.union([z.string(), z.number()]).optional(),
  enableStopTrading: z.boolean().optional(),
  enableProfitGoal: z.boolean().optional(),
}).optional()

const updateChallengeSchema = z.object({
  profitTargetPct: z.string().optional(),
  maxDDPct: z.string().optional(),
  dailyDDPct: z.string().optional(),
  minTradingDays: z.string().optional(),
  cost: z.union([z.string(), z.number(), z.null()]).optional(),
  alertConfig: alertConfigSchema,
  steps: z.string().optional(),
  phase2Target: z.string().optional(),
  fundedTarget: z.string().optional(),
  payoutSplit: z.string().optional(),
  challengeName: z.string().optional(),
  initialBalance: z.union([z.string(), z.number()]).optional(),
  logoUrl: z.string().url().optional(),
})

export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const { id } = await params
    const body = await request.json()
    const parsed = updateChallengeSchema.safeParse(body)
    if (!parsed.success) {
      return NextResponse.json({ error: "Invalid input", details: parsed.error.flatten().fieldErrors }, { status: 400 })
    }

    const challenge = await prisma.propChallenge.findUnique({
      where: { id },
      include: { account: true },
    })

    if (!challenge || challenge.userId !== session.user.id) {
      return NextResponse.json({ error: "Challenge not found" }, { status: 404 })
    }

    const dataToUpdate: any = {}
    if (parsed.data.profitTargetPct !== undefined) dataToUpdate.profitTargetPct = parseFloat(parsed.data.profitTargetPct)
    if (parsed.data.maxDDPct !== undefined) dataToUpdate.maxDDPct = parseFloat(parsed.data.maxDDPct)
    if (parsed.data.dailyDDPct !== undefined) dataToUpdate.dailyDDPct = parseFloat(parsed.data.dailyDDPct)
    if (parsed.data.minTradingDays !== undefined) dataToUpdate.minTradingDays = parseInt(parsed.data.minTradingDays)
    if (parsed.data.cost !== undefined) dataToUpdate.cost = parsed.data.cost === null || parsed.data.cost === "" ? null : parseFloat(String(parsed.data.cost))

    if (parsed.data.alertConfig !== undefined) {
      const currentAlertConfig = (challenge.alertConfig as AlertConfig) || {}
      dataToUpdate.alertConfig = {
        stopTradingPct: parsed.data.alertConfig.stopTradingPct !== undefined ? Number(parsed.data.alertConfig.stopTradingPct) : (currentAlertConfig.stopTradingPct ?? 85),
        profitGoalPct: parsed.data.alertConfig.profitGoalPct !== undefined ? Number(parsed.data.alertConfig.profitGoalPct) : (currentAlertConfig.profitGoalPct ?? 50),
        enableStopTrading: parsed.data.alertConfig.enableStopTrading !== undefined ? Boolean(parsed.data.alertConfig.enableStopTrading) : (currentAlertConfig.enableStopTrading ?? false),
        enableProfitGoal: parsed.data.alertConfig.enableProfitGoal !== undefined ? Boolean(parsed.data.alertConfig.enableProfitGoal) : (currentAlertConfig.enableProfitGoal ?? false),
      }
    }

    const currentMetadata = (challenge.metadata as ChallengeMetadata) || {}
    const newMetadata = {
      ...currentMetadata,
      steps: parsed.data.steps ?? currentMetadata.steps ?? "2",
      phase1Target: parsed.data.profitTargetPct !== undefined ? parseFloat(parsed.data.profitTargetPct) : (currentMetadata.phase1Target ?? null),
      phase2Target: parsed.data.phase2Target !== undefined ? parseFloat(parsed.data.phase2Target) : (currentMetadata.phase2Target ?? null),
      fundedTarget: parsed.data.fundedTarget !== undefined ? parseFloat(parsed.data.fundedTarget) : (currentMetadata.fundedTarget ?? null),
      payoutSplit: parsed.data.payoutSplit !== undefined ? parsed.data.payoutSplit : (currentMetadata.payoutSplit ?? null),
    }
    dataToUpdate.metadata = newMetadata

    // Update the linked trading account (name / balance)
    if (parsed.data.challengeName !== undefined || parsed.data.initialBalance !== undefined) {
      const accountData: any = {}
      if (parsed.data.challengeName !== undefined) accountData.name = parsed.data.challengeName
      if (parsed.data.initialBalance !== undefined) accountData.initialBalance = parseFloat(String(parsed.data.initialBalance))
      await prisma.tradingAccount.update({
        where: { id: challenge.accountId },
        data: accountData,
      })
    }

    // Save a new firm logo if provided
    if (parsed.data.logoUrl) {
      await prisma.propFirmTemplate.update({
        where: { id: challenge.templateId },
        data: { logoUrl: parsed.data.logoUrl },
      })
    }

    const updated = await prisma.propChallenge.update({
      where: { id },
      data: dataToUpdate,
      include: { template: true, account: true },
    })

    return NextResponse.json(updated)
  } catch (error) {
    console.error("Error updating challenge:", error instanceof Error ? error.message : "Unknown error")
    return NextResponse.json({ error: "Failed to update challenge" }, { status: 500 })
  }
}

export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const { id } = await params

    const challenge = await prisma.propChallenge.findUnique({
      where: { id },
      include: { account: true },
    })

    if (!challenge || challenge.userId !== session.user.id) {
      return NextResponse.json({ error: "Challenge not found" }, { status: 404 })
    }

    // Deleting the account cascades to its trades, the challenge,
    // and the challenge's events/snapshots/payouts (DB-level onDelete: Cascade).
    await prisma.tradingAccount.delete({
      where: { id: challenge.accountId },
    })

    return NextResponse.json({ success: true })
  } catch (error) {
    console.error("Error deleting challenge:", error instanceof Error ? error.message : "Unknown error")
    return NextResponse.json({ error: "Failed to delete challenge" }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from "next/server"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const { id } = await params

    // Get the challenge
    const challenge = await prisma.propChallenge.findUnique({
      where: { id },
      include: { account: true }
    })

    if (!challenge || challenge.userId !== session.user.id) {
      return NextResponse.json({ error: "Challenge not found" }, { status: 404 })
    }

    // Only allow upgrading if status is passed and phase is phase_1
    if (challenge.status !== 'passed' || challenge.phase !== 'phase_1') {
      return NextResponse.json({ error: "Challenge cannot be upgraded" }, { status: 400 })
    }

    const metadata = challenge.metadata as any || {}
    const steps = metadata.steps || '1'

    const phase2Target = metadata.phase2Target ? Number(metadata.phase2Target) : 5
    const fundedTarget = metadata.fundedTarget ? Number(metadata.fundedTarget) : (metadata.phase1Target ? Number(metadata.phase1Target) : 5)

    if (steps === '2') {
      // 2-step challenge: Phase 1 -> Phase 2
      const upgradedChallenge = await prisma.propChallenge.update({
        where: { id: challenge.id },
        data: {
          phase: 'phase_2',
          status: 'active',
          profitTargetPct: phase2Target,
          currentBalance: challenge.initialBalance,
          currentEquity: challenge.initialBalance,
          highestBalance: challenge.initialBalance,
          highestEquity: challenge.initialBalance,
          todayStartBalance: challenge.initialBalance,
          startedAt: new Date(),
          todayResetAt: null,
        }
      })

      await prisma.propChallengeEvent.create({
        data: {
          challengeId: challenge.id,
          eventType: 'phase_passed',
          severity: 'info',
          message: 'Passed Phase 1 and upgraded to Phase 2',
        }
      })

      return NextResponse.json(upgradedChallenge)
    }

    // 1-step or master: Phase 1 -> Funded
    const fundedChallenge = await prisma.propChallenge.update({
      where: { id: challenge.id },
      data: {
        phase: 'funded',
        status: 'active',
        profitTargetPct: fundedTarget,
        currentBalance: challenge.initialBalance,
        currentEquity: challenge.initialBalance,
        highestBalance: challenge.initialBalance,
        highestEquity: challenge.initialBalance,
        todayStartBalance: challenge.initialBalance,
        startedAt: new Date(),
        todayResetAt: null,
      }
    })

    await prisma.propChallengeEvent.create({
      data: {
        challengeId: challenge.id,
        eventType: 'phase_passed',
        severity: 'info',
        message: 'Passed Phase 1 and moved to funded status',
      }
    })

    return NextResponse.json(fundedChallenge)

  } catch (error: any) {
    console.error("Error upgrading challenge:", error instanceof Error ? error.message : "Unknown error")
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 })
  }
}

import { NextResponse } from "next/server"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { evaluateChallenge } from "@/lib/prop-firm.service"

export async function POST() {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const active = await prisma.propChallenge.findMany({
      where: { userId: session.user.id, status: 'active' },
      select: { id: true }
    })

    const results: any[] = []
    for (const c of active) {
      try {
        const updated = await evaluateChallenge(c.id)
        results.push({ id: c.id, status: updated?.status ?? 'unknown' })
      } catch (err) {
        console.error(`evaluate-all error for ${c.id}:`, err instanceof Error ? err.message : "Unknown error")
      }
    }

    return NextResponse.json({ evaluated: results.length, results })
  } catch (error) {
    console.error("Error evaluating challenges:", error instanceof Error ? error.message : "Unknown error")
    return NextResponse.json({ error: "Failed to evaluate challenges" }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from "next/server"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { z } from "zod"

const createChallengeSchema = z.object({
  templateId: z.string().min(1),
  challengeName: z.string().min(1).max(100),
  initialBalance: z.string().or(z.number()),
  steps: z.string().optional(),
  phase2Target: z.string().optional(),
  fundedTarget: z.string().optional(),
  payoutSplit: z.string().optional(),
  logoUrl: z.string().url().optional(),
  cost: z.string().or(z.number()).optional(),
  profitTargetPct: z.string().optional(),
  dailyDDPct: z.string().optional(),
  maxDDPct: z.string().optional(),
  minTradingDays: z.string().optional(),
  maxTradingDays: z.string().optional(),
  enableStopTrading: z.boolean().optional(),
  enableProfitGoal: z.boolean().optional(),
})

export async function POST(request: NextRequest) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const body = await request.json()
    const parsed = createChallengeSchema.safeParse(body)
    if (!parsed.success) {
      return NextResponse.json({ error: "Invalid input", details: parsed.error.flatten().fieldErrors }, { status: 400 })
    }

    const { templateId, challengeName, initialBalance, steps, phase2Target, fundedTarget, payoutSplit, logoUrl, cost } = parsed.data

    // Auto-create a trading account for this challenge
    const balanceDecimal = parseFloat(String(initialBalance))
    const account = await prisma.tradingAccount.create({
      data: {
        userId: session.user.id,
        name: challengeName,
        broker: "Prop Firm",
        type: "prop_firm",
        baseCurrency: "USD",
        initialBalance: balanceDecimal,
        isDefault: false
      }
    })

    // Get template
    const template = await prisma.propFirmTemplate.findUnique({
      where: { id: templateId }
    })

    if (!template) {
      return NextResponse.json({ error: "Template not found" }, { status: 404 })
    }

    // Save the firm logo on the template (shared across all challenges of the firm)
    if (logoUrl) {
      await prisma.propFirmTemplate.update({
        where: { id: template.id },
        data: { logoUrl },
      })
    }

    // Create the challenge
    const isMaster = steps === 'master'
    const phase1Target = parsed.data.profitTargetPct !== undefined ? parseFloat(parsed.data.profitTargetPct) : (template.profitTargetPhase1Pct || 0)
    const initialPhase = isMaster ? 'funded' : 'phase_1'
    const initialTarget = isMaster
      ? (fundedTarget ? parseFloat(fundedTarget) : (template.profitTargetPhase2Pct || 0))
      : phase1Target

    // Default alert config from user preferences
    const user = await prisma.user.findUnique({
      where: { id: session.user.id },
      select: { notificationPrefs: true },
    })
    const prefs = (user?.notificationPrefs as any) || {}
    const alertDefaults = (prefs.defaults as any) || {}
    const alertConfig = {
      stopTradingPct: Number(alertDefaults.stopTradingPct ?? 85),
      profitGoalPct: Number(alertDefaults.profitGoalPct ?? 50),
      enableStopTrading: Boolean(parsed.data.enableStopTrading ?? false),
      enableProfitGoal: Boolean(parsed.data.enableProfitGoal ?? false),
    }

    const maxTradingDays = parsed.data.maxTradingDays !== undefined ? parseInt(parsed.data.maxTradingDays) : (template.maxTradingDays || null)
    const startedAt = new Date()
    const deadlineAt = maxTradingDays ? new Date(startedAt.getTime() + maxTradingDays * 24 * 60 * 60 * 1000) : null

    const challenge = await prisma.propChallenge.create({
      data: {
        userId: session.user.id,
        accountId: account.id,
        templateId: template.id,
        initialBalance: account.initialBalance || 0,
        dailyDDPct: parsed.data.dailyDDPct !== undefined ? parseFloat(parsed.data.dailyDDPct) : (template.dailyDDPct || 0),
        maxDDPct: parsed.data.maxDDPct !== undefined ? parseFloat(parsed.data.maxDDPct) : template.maxDDPct,
        profitTargetPct: initialTarget,
        minTradingDays: parsed.data.minTradingDays !== undefined ? parseInt(parsed.data.minTradingDays) : template.minTradingDays,
        maxTradingDays,
        cost: cost !== undefined ? parseFloat(String(cost)) : null,
        phase: initialPhase,
        status: 'active',
        startedAt,
        deadlineAt,
        currentBalance: account.initialBalance || 0,
        currentEquity: account.initialBalance || 0,
        highestBalance: account.initialBalance || 0,
        highestEquity: account.initialBalance || 0,
        todayStartBalance: account.initialBalance || 0,
        alertConfig,
        metadata: {
          steps: steps || '2',
          phase1Target,
          phase2Target: phase2Target ? parseFloat(phase2Target) : null,
          fundedTarget: fundedTarget ? parseFloat(fundedTarget) : null,
          payoutSplit: payoutSplit || null
        }
      }
    })

    return NextResponse.json(challenge)
  } catch (error: any) {
    console.error("Error creating challenge:", error instanceof Error ? error.message : "Unknown error")
    return NextResponse.json({ error: "Failed to create challenge" }, { status: 500 })
  }
}

