import { NextResponse } from "next/server"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { resolveAccountScope } from "@/lib/active-account"

export async function GET(request: Request) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const { searchParams } = new URL(request.url)
    const accountId = searchParams.get("accountId") || "all"

    if (!accountId || typeof accountId !== "string") {
      return NextResponse.json({ error: "Invalid accountId" }, { status: 400 })
    }

    const scope = await resolveAccountScope(session.user.id, accountId)

    if (!scope.all && scope.accounts.length === 0) {
      return NextResponse.json({ totalTrades: 0, winRate: 0, netPnl: 0, profitFactor: 0, recentTrades: [] })
    }

    const where: any = scope.all
      ? { userId: session.user.id, status: "closed" }
      : { accountId: scope.accounts[0].id, status: "closed" }

    const trades = await prisma.trade.findMany({
      where,
      orderBy: { entryAt: "desc" },
      select: {
        id: true,
        symbol: true,
        side: true,
        entryAt: true,
        netPnl: true,
        instrumentType: true,
      },
    })

    const totalTrades = trades.length
    const winners = trades.filter(t => Number(t.netPnl || 0) > 0)
    const losers = trades.filter(t => Number(t.netPnl || 0) < 0)
    const winRate = totalTrades > 0 ? (winners.length / totalTrades) * 100 : 0

    const grossProfit = winners.reduce((s, t) => s + Number(t.netPnl || 0), 0)
    const grossLoss = Math.abs(losers.reduce((s, t) => s + Number(t.netPnl || 0), 0))
    const profitFactor = grossLoss > 0 ? grossProfit / grossLoss : grossProfit > 0 ? 99 : 0

    const netPnl = trades.reduce((s, t) => s + Number(t.netPnl || 0), 0)

    const recentTrades = trades.slice(0, 5).map(t => ({
      id: t.id,
      symbol: t.symbol,
      side: t.side,
      entryAt: t.entryAt?.toISOString?.() ?? null,
      netPnl: Number(t.netPnl || 0),
      instrumentType: t.instrumentType,
    }))

    return NextResponse.json({
      totalTrades,
      winRate: Math.round(winRate * 10) / 10,
      netPnl: Math.round(netPnl * 100) / 100,
      profitFactor: Math.round(profitFactor * 100) / 100,
      grossProfit: Math.round(grossProfit * 100) / 100,
      grossLoss: Math.round(grossLoss * 100) / 100,
      recentTrades,
    })
  } catch (error) {
    console.error("[OVERVIEW_STATS_GET]", error instanceof Error ? error.message : "Unknown error")
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 })
  }
}

import { NextResponse } from "next/server"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { getActiveAccount } from "@/lib/active-account"
import { dayKey } from "@/lib/dates"
import { z } from "zod"

const backtestSchema = z.object({
  accountId: z.string().optional(),
  startDate: z.string().optional(),
  endDate: z.string().optional(),
  initialBalance: z.number().min(1).default(100000),
  profitTargetPct: z.number().min(0),
  maxDDPct: z.number().min(0).max(100),
  dailyDDPct: z.number().min(0).max(100),
  minTradingDays: z.number().min(0).default(0),
  maxTradingDays: z.number().min(0).nullable().default(null),
  consistencyRulePct: z.number().min(0).default(0),
  drawdownType: z.enum(["static_balance", "trailing_balance", "trailing_equity"]).default("static_balance"),
  dailyResetTimezone: z.string().default("UTC"),
})

export async function POST(request: Request) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const body = await request.json()
    const parsed = backtestSchema.safeParse(body)
    if (!parsed.success) {
      return NextResponse.json({ error: "Invalid input", details: parsed.error.flatten().fieldErrors }, { status: 400 })
    }

    const {
      accountId,
      startDate,
      endDate,
      initialBalance,
      profitTargetPct,
      maxDDPct,
      dailyDDPct,
      minTradingDays,
      maxTradingDays,
      consistencyRulePct,
      drawdownType,
      dailyResetTimezone,
    } = parsed.data

    // Resolve target account
    let account = null
    if (accountId) {
      account = await prisma.tradingAccount.findUnique({
        where: { id: accountId },
        select: { id: true, userId: true, name: true, type: true },
      })
      if (!account || account.userId !== session.user.id) {
        return NextResponse.json({ error: "Account not found" }, { status: 404 })
      }
    } else {
      account = await getActiveAccount(session.user.id)
    }
    if (!account) {
      return NextResponse.json({ error: "No trading account found" }, { status: 404 })
    }

    // Trade window
    const where: any = {
      accountId: account.id,
      status: "closed",
    }
    if (startDate) where.exitAt = { gte: new Date(`${startDate}T00:00:00`) }
    if (endDate) where.exitAt = { ...(where.exitAt || {}), lte: new Date(`${endDate}T23:59:59.999`) }

    const trades = await prisma.trade.findMany({
      where,
      orderBy: { exitAt: "asc" },
    })
    if (trades.length === 0) {
      return NextResponse.json({ error: "No trades found in the selected period" }, { status: 400 })
    }

    // Group trades by day (reset timezone)
    const daysMap = new Map<string, { date: Date; pnl: number; start: number; end: number; lowest: number }>()

    let currentBalance = Number(initialBalance)
    let highestBalance = Number(initialBalance)
    let highestEquity = Number(initialBalance)
    const equityCurve: { date: string; balance: number }[] = []

    for (const trade of trades) {
      const pnl = Number(trade.netPnl || 0)
      if (!trade.exitAt) continue
      const exitAt = trade.exitAt

      // Update highest marks
      if (drawdownType === "trailing_balance") highestBalance = Math.max(highestBalance, currentBalance)
      if (drawdownType === "trailing_equity") highestEquity = Math.max(highestEquity, currentBalance)

      currentBalance += pnl

      const key = dayKey(exitAt, dailyResetTimezone)
      const day = daysMap.get(key) || {
        date: exitAt,
        pnl: 0,
        start: currentBalance - pnl,
        end: currentBalance,
        lowest: currentBalance,
      }
      day.end = currentBalance
      day.lowest = Math.min(day.lowest, currentBalance)
      day.pnl += pnl
      daysMap.set(key, day)

      // Max drawdown check (intraday)
      const maxDdReference =
        drawdownType === "static_balance" ? Number(initialBalance) :
        drawdownType === "trailing_balance" ? highestBalance : highestEquity
      const maxDdThreshold = maxDdReference * (1 - Number(maxDDPct) / 100)
      if (currentBalance <= maxDdThreshold) {
        return NextResponse.json({
          result: "failed",
          reason: "max_dd",
          message: `Max drawdown breached on ${key}`,
          tradingDays: daysMap.size,
          finalBalance: Math.round(currentBalance * 100) / 100,
          equityCurve,
          daysMap: null,
        })
      }
    }

    // Day-level checks
    const sortedDays = [...daysMap.values()].sort((a, b) => a.date.getTime() - b.date.getTime())
    let daysElapsed = 0
    const dailyBreakdown: { date: string; pnl: number; balance: number; cumPnl: number }[] = []
    let cumPnl = 0

    for (const day of sortedDays) {
      const dateKey = dayKey(day.date, dailyResetTimezone)
      const dailyDdThreshold = day.start * (1 - Number(dailyDDPct) / 100)
      if (day.lowest <= dailyDdThreshold) {
        return NextResponse.json({
          result: "failed",
          reason: "daily_dd",
          message: `Daily drawdown breached on ${dateKey}`,
          tradingDays: sortedDays.length,
          finalBalance: Math.round(currentBalance * 100) / 100,
          equityCurve,
          dailyBreakdown,
        })
      }
      cumPnl += day.pnl
      dailyBreakdown.push({
        date: dateKey,
        pnl: Math.round(day.pnl * 100) / 100,
        balance: Math.round(day.end * 100) / 100,
        cumPnl: Math.round(cumPnl * 100) / 100,
      })
      equityCurve.push({ date: dateKey, balance: Math.round(day.end * 100) / 100 })

      // Profit target reached
      const profitTarget = Number(initialBalance) * (Number(profitTargetPct) / 100)
      if (cumPnl >= profitTarget) {
        if (sortedDays.length < Number(minTradingDays)) {
          return NextResponse.json({
            result: "in_progress",
            reason: "min_days",
            message: `Profit target reached on day ${sortedDays.length} but min ${minTradingDays} trading days required.`,
            tradingDays: sortedDays.length,
            finalBalance: Math.round(day.end * 100) / 100,
            equityCurve,
            dailyBreakdown,
          })
        }
        // Consistency
        if (Number(consistencyRulePct) > 0 && cumPnl > 0) {
          let biggestDay = 0
          for (const d of sortedDays) biggestDay = Math.max(biggestDay, d.pnl)
          const biggestPct = (biggestDay / cumPnl) * 100
          if (biggestPct > Number(consistencyRulePct)) {
            return NextResponse.json({
              result: "failed",
              reason: "consistency",
              message: `Consistency rule violated: largest day ${Math.round(biggestPct)}% of profit (max ${consistencyRulePct}%).`,
              tradingDays: sortedDays.length,
              biggestDayPct: Math.round(biggestPct * 100) / 100,
              finalBalance: Math.round(day.end * 100) / 100,
              equityCurve,
              dailyBreakdown,
            })
          }
        }
        return NextResponse.json({
          result: "passed",
          message: `Profit target reached in ${sortedDays.length} trading days (${daysElapsed} calendar days).`,
          tradingDays: sortedDays.length,
          daysElapsed,
          finalBalance: Math.round(day.end * 100) / 100,
          peakProfitPct: Math.round((cumPnl / Number(initialBalance)) * 10000) / 100,
          equityCurve,
          dailyBreakdown,
        })
      }
      daysElapsed = (day.date.getTime() - sortedDays[0].date.getTime()) / 86400000
    }

    // Max trading days limit
    if (maxTradingDays && daysElapsed > Number(maxTradingDays)) {
      return NextResponse.json({
        result: "failed",
        reason: "time_limit",
        message: `Time limit reached: ${Math.floor(daysElapsed)} days used (max ${maxTradingDays}).`,
        tradingDays: sortedDays.length,
        daysElapsed: Math.floor(daysElapsed),
        finalBalance: Math.round(currentBalance * 100) / 100,
        equityCurve,
        dailyBreakdown,
      })
    }

    // In progress
    const maxDdReference = drawdownType === "static_balance" ? Number(initialBalance) : highestBalance
    const ddBudget = maxDdReference * (Number(maxDDPct) / 100)
    const ddUsedPct = ddBudget > 0 ? ((maxDdReference - currentBalance) / ddBudget) * 100 : 0

    return NextResponse.json({
      result: "in_progress",
      message: `Target not reached yet after ${sortedDays.length} trading days.`,
      tradingDays: sortedDays.length,
      daysElapsed: Math.floor(daysElapsed),
      finalBalance: Math.round(currentBalance * 100) / 100,
      currentProfitPct: Math.round((cumPnl / Number(initialBalance)) * 10000) / 100,
      maxDrawdownUsedPct: Math.round(Math.min(100, Math.max(0, ddUsedPct)) * 100) / 100,
      equityCurve,
      dailyBreakdown,
    })
  } catch (error: any) {
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 })
  }
}

import { NextResponse } from "next/server"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"

export async function GET() {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const challenges = await prisma.propChallenge.findMany({
      where: { userId: session.user.id },
      include: {
        template: { select: { firmName: true, logoUrl: true, drawdownType: true } },
        account: { select: { name: true } },
        payouts: { select: { status: true, amount: true } },
        dailySnapshots: { select: { endBalance: true }, orderBy: { date: "asc" } },
      },
    })

    const total = challenges.length
    const active = challenges.filter(c => c.status === "active").length
    const passed = challenges.filter(c => c.status === "passed").length
    const breached = challenges.filter(c => c.status === "breached" || c.status === "failed").length
    const passRate = total > 0 ? (passed / total) * 100 : 0

    // Sum of current P&L ($) across active challenges
    let totalProfit = 0
    for (const c of challenges) {
      if (c.status === "active") {
        totalProfit += Number(c.currentBalance ?? c.initialBalance) - Number(c.initialBalance)
      }
    }

    const payoutsPaid = challenges.reduce((s, c) =>
      s + c.payouts.filter(p => p.status === "paid").reduce((x, p) => x + Number(p.amount), 0), 0)
    const payoutsPending = challenges.reduce((s, c) =>
      s + c.payouts.filter(p => p.status === "requested" || p.status === "approved").reduce((x, p) => x + Number(p.amount), 0), 0)

    // Business case: total cost of challenges vs payouts received
    const totalCost = challenges.reduce((s, c) => s + (c.cost ? Number(c.cost) : 0), 0)
    const roi = totalCost > 0 ? ((payoutsPaid - totalCost) / totalCost) * 100 : null

    const byFirm = new Map<string, { firmName: string; logoUrl: string | null; total: number; passed: number; breached: number; active: number; payoutsPaid: number; payoutsPending: number; cost: number }>()
    for (const c of challenges) {
      const firmName = c.template?.firmName || "Unknown"
      let f = byFirm.get(firmName)
      if (!f) {
        f = { firmName, logoUrl: c.template?.logoUrl || null, total: 0, passed: 0, breached: 0, active: 0, payoutsPaid: 0, payoutsPending: 0, cost: 0 }
        byFirm.set(firmName, f)
      }
      f.total += 1
      if (c.status === "passed") f.passed += 1
      else if (c.status === "breached" || c.status === "failed") f.breached += 1
      else f.active += 1
      f.payoutsPaid += c.payouts.filter(p => p.status === "paid").reduce((x, p) => x + Number(p.amount), 0)
      f.payoutsPending += c.payouts.filter(p => p.status === "requested" || p.status === "approved").reduce((x, p) => x + Number(p.amount), 0)
      f.cost += c.cost ? Number(c.cost) : 0
    }

    const byFirmOut = [...byFirm.values()]
      .map(f => ({
        ...f,
        payoutsPaid: Math.round(f.payoutsPaid * 100) / 100,
        payoutsPending: Math.round(f.payoutsPending * 100) / 100,
        cost: Math.round(f.cost * 100) / 100,
        roi: f.cost > 0 ? Math.round(((f.payoutsPaid - f.cost) / f.cost) * 100 * 10) / 10 : null,
      }))
      .sort((a, b) => b.total - a.total)

    // Progress of each active challenge toward passing its current phase
    const activeChallenges = challenges
      .filter(c => c.status === "active")
      .map(c => {
        const initial = Number(c.initialBalance)
        const current = Number(c.currentBalance ?? initial)
        const profitTargetPct = Number(c.profitTargetPct || 0)
        const maxDDPct = Number(c.maxDDPct || 0)
        const daysTraded = Number((c.metadata as any)?.tradingDaysCount || 0)
        const minDays = Number(c.minTradingDays || 0)

        const profitPct = initial > 0 ? ((current - initial) / initial) * 100 : 0
        const profitReachedPct = profitTargetPct > 0 ? Math.min(100, (profitPct / profitTargetPct) * 100) : 0

        // Peak reference for drawdown (static balance → initial; trailing → highest seen)
        const peak = c.template?.drawdownType === "static_balance"
          ? initial
          : Math.max(initial, current, ...c.dailySnapshots.map(s => Number(s.endBalance)))
        const ddBudget = peak * (maxDDPct / 100)
        const ddUsedPct = ddBudget > 0 ? Math.min(100, Math.max(0, ((peak - current) / ddBudget) * 100)) : 0

        return {
          id: c.id,
          firmName: c.template?.firmName || "Unknown",
          logoUrl: c.template?.logoUrl || null,
          phase: c.phase,
          accountName: c.account?.name || "",
          currentBalance: Math.round(current * 100) / 100,
          profitPct: Math.round(profitPct * 100) / 100,
          profitTargetPct,
          profitReachedPct: Math.round(profitReachedPct * 10) / 10,
          maxDDPct,
          ddUsedPct: Math.round(ddUsedPct * 10) / 10,
          minTradingDays: minDays,
          daysTraded,
        }
      })
      .sort((a, b) => b.ddUsedPct - a.ddUsedPct)

    return NextResponse.json({
      total,
      active,
      passed,
      breached,
      passRate: Math.round(passRate * 10) / 10,
      totalProfit: Math.round(totalProfit * 100) / 100,
      payoutsPaid: Math.round(payoutsPaid * 100) / 100,
      payoutsPending: Math.round(payoutsPending * 100) / 100,
      totalCost: Math.round(totalCost * 100) / 100,
      roi: roi !== null ? Math.round(roi * 10) / 10 : null,
      byFirm: byFirmOut,
      activeChallenges,
    })
  } catch (error: any) {
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 })
  }
}

import { NextResponse } from "next/server"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { dayKey, nextMidnightInTz } from "@/lib/dates"

interface NotificationPrefs {
  eventTypes?: Record<string, boolean>
}

interface AlertConfig {
  stopTradingPct?: number
  profitGoalPct?: number
  enableStopTrading?: boolean
  enableProfitGoal?: boolean
}

type Alert = {
  type: string
  severity: "info" | "warning" | "critical"
  message: string
  challengeId?: string
  challengeName?: string
  value?: string
}

export async function GET() {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const user = await prisma.user.findUnique({
      where: { id: session.user.id },
      select: { notificationPrefs: true, timezone: true },
    })
    const prefs = (user?.notificationPrefs as NotificationPrefs) || {}
    const eventMap = prefs.eventTypes || {}

    const activeChallenges = await prisma.propChallenge.findMany({
      where: { userId: session.user.id, status: "active" },
      include: { template: true },
      orderBy: { startedAt: "asc" },
    })

    const alerts: Alert[] = []

    // Batch fetch all trades for active challenges in one query
    const accountIds = activeChallenges.map(c => c.accountId)
    const allTrades = accountIds.length > 0 ? await prisma.trade.findMany({
      where: { accountId: { in: accountIds }, status: "closed" },
      select: { accountId: true, exitAt: true, netPnl: true },
      orderBy: { exitAt: "asc" },
    }) : []
    const tradesByAccount = new Map<string, typeof allTrades>()
    for (const t of allTrades) {
      const arr = tradesByAccount.get(t.accountId) || []
      arr.push(t)
      tradesByAccount.set(t.accountId, arr)
    }

    // ── Per-challenge risk alerts ─────────────────────────────────────────
    for (const c of activeChallenges) {
      const timezone = c.template.dailyResetTimezone || "UTC"
      const initialBalance = Number(c.initialBalance)
      const profitTargetPct = Number(c.profitTargetPct)
      const maxDDPct = Number(c.maxDDPct)
      const dailyDDPct = Number(c.dailyDDPct)

      const trades = tradesByAccount.get(c.accountId) || []

      let currentBalance = initialBalance
      let highestBalance = initialBalance
      let todayStartBalance = initialBalance
      let todayResetAt = c.todayResetAt || new Date(c.startedAt)

      for (const t of trades) {
        if (!t.exitAt) continue
        const exit = t.exitAt
        if (exit > todayResetAt) {
          todayStartBalance = currentBalance
          todayResetAt = nextMidnightInTz(exit, timezone)
        }
        const pnl = Number(t.netPnl || 0)
        currentBalance += pnl
        if (c.template.drawdownType === "trailing_balance") {
          highestBalance = Math.max(highestBalance, currentBalance)
        }
      }

      const maxDdReference =
        c.template.drawdownType === "static_balance" ? initialBalance :
        c.template.drawdownType === "trailing_balance" ? highestBalance :
        highestBalance

      const ddBudget = maxDdReference * (maxDDPct / 100)
      const ddUsedPct = ddBudget > 0 ? ((maxDdReference - currentBalance) / ddBudget) * 100 : 0
      const dailyUsedPct = todayStartBalance > 0 ? ((todayStartBalance - currentBalance) / todayStartBalance / (dailyDDPct / 100)) * 100 : 0
      const currentProfit = currentBalance - initialBalance
      const targetAmount = initialBalance * (profitTargetPct / 100)
      const profitProgressPct = targetAmount > 0 ? (currentProfit / targetAmount) * 100 : 0
      const daysLeft = c.deadlineAt ? Math.max(0, Math.ceil((c.deadlineAt.getTime() - Date.now()) / 86400000)) : null

      const name = `${c.template.firmName} — ${c.template.programName}`

      if (ddUsedPct >= 90 && eventMap.alert_90pct !== false) {
        alerts.push({ type: "dd_90", severity: "critical", challengeId: c.id, challengeName: name, message: `${Math.round(ddUsedPct)}% of max drawdown used.`, value: `${Math.round(ddUsedPct)}%` })
      } else if (ddUsedPct >= 80 && eventMap.alert_80pct !== false) {
        alerts.push({ type: "dd_80", severity: "warning", challengeId: c.id, challengeName: name, message: `${Math.round(ddUsedPct)}% of max drawdown used.`, value: `${Math.round(ddUsedPct)}%` })
      }

      const stopPct = Number((c.alertConfig as AlertConfig)?.stopTradingPct ?? 85)
      if ((c.alertConfig as AlertConfig)?.enableStopTrading !== false && ddUsedPct >= stopPct && eventMap.stop_trading !== false) {
        alerts.push({ type: "stop_trading", severity: "critical", challengeId: c.id, challengeName: name, message: `Stop-trading threshold reached (${stopPct}% of max DD used). Consider stopping for the day.`, value: `${Math.round(ddUsedPct)}%` })
      }

      if (dailyUsedPct >= 70) {
        alerts.push({ type: "daily_dd", severity: "warning", challengeId: c.id, challengeName: name, message: `${Math.round(dailyUsedPct)}% of today's daily drawdown budget used.`, value: `${Math.round(dailyUsedPct)}%` })
      }

      const goalPct = Number((c.alertConfig as AlertConfig)?.profitGoalPct ?? 50)
      if (profitProgressPct >= goalPct && eventMap.goal_reached !== false) {
        alerts.push({ type: "goal", severity: "info", challengeId: c.id, challengeName: name, message: `${Math.round(profitProgressPct)}% of profit target reached.`, value: `${Math.round(profitProgressPct)}%` })
      }

      if (daysLeft !== null && daysLeft <= 5 && eventMap.deadline_5d !== false) {
        alerts.push({ type: "deadline", severity: daysLeft <= 1 ? "critical" : "warning", challengeId: c.id, challengeName: name, message: `${daysLeft} day${daysLeft === 1 ? "" : "s"} left before deadline.`, value: `${daysLeft}d` })
      }
    }

    // ── Recent stop violations (last 7 days) ──────────────────────────────
    const stopViolations = await prisma.trade.findMany({
      where: {
        userId: session.user.id,
        status: "closed",
        exitAt: { gte: new Date(Date.now() - 7 * 86400000) },
        AND: [{ netPnl: { lt: 0 } }],
      },
      orderBy: { exitAt: "desc" },
      take: 20,
    })

    const avgLoserPct = (() => {
      if (stopViolations.length === 0) return 0
      const sum = stopViolations.reduce((acc, t) => acc + Math.abs(Number(t.netPnl || 0)), 0)
      return sum / stopViolations.length
    })()
    const consecutiveLosingDays = (() => {
      const days = new Set(stopViolations.filter(t => t.exitAt).map(t => dayKey(t.exitAt!, "UTC")))
      let count = 0
      const today = new Date()
      for (let i = 0; i < 7; i++) {
        const d = new Date(today.getTime() - i * 86400000)
        if (days.has(dayKey(d, "UTC"))) count++
        else break
      }
      return count
    })()

    if (consecutiveLosingDays >= 3) {
      alerts.push({ type: "losing_streak", severity: "warning", message: `${consecutiveLosingDays} consecutive losing days this week. Consider stepping back.`, value: `${consecutiveLosingDays}d` })
    }
    if (stopViolations.length >= 10) {
      alerts.push({ type: "many_losses", severity: "warning", message: `${stopViolations.length} losing trades in the last 7 days.`, value: `${stopViolations.length}` })
    }

    // Order: critical first, then warning, then info
    const order = { critical: 0, warning: 1, info: 2 }
    alerts.sort((a, b) => order[a.severity] - order[b.severity])

    return NextResponse.json({ alerts })
  } catch (error: any) {
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 })
  }
}

import { NextResponse } from "next/server"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { z } from "zod"

const riskPrefsSchema = z.object({
  dailyLossLimit: z.union([z.string(), z.number(), z.null()]).optional(),
  maxTradesPerDay: z.union([z.string(), z.number(), z.null()]).optional(),
  maxConsecutiveLosses: z.union([z.string(), z.number(), z.null()]).optional(),
  maxRiskPerTradePct: z.union([z.string(), z.number(), z.null()]).optional(),
})

const DEFAULT_RISK_PREFS = {
  dailyLossLimit: null as number | null, // $
  maxTradesPerDay: null as number | null,
  maxConsecutiveLosses: null as number | null,
  maxRiskPerTradePct: 1 as number, // % of balance
}

export async function GET() {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }
    const user = await prisma.user.findUnique({
      where: { id: session.user.id },
      select: { riskPrefs: true },
    })
    const prefs = (user?.riskPrefs as any) || {}
    return NextResponse.json({
      dailyLossLimit: prefs.dailyLossLimit ?? DEFAULT_RISK_PREFS.dailyLossLimit,
      maxTradesPerDay: prefs.maxTradesPerDay ?? DEFAULT_RISK_PREFS.maxTradesPerDay,
      maxConsecutiveLosses: prefs.maxConsecutiveLosses ?? DEFAULT_RISK_PREFS.maxConsecutiveLosses,
      maxRiskPerTradePct: prefs.maxRiskPerTradePct ?? DEFAULT_RISK_PREFS.maxRiskPerTradePct,
    })
  } catch (error) {
    console.error("Error fetching risk preferences:", error instanceof Error ? error.message : "Unknown error")
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 })
  }
}

export async function PATCH(request: Request) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const body = await request.json()
    const parsed = riskPrefsSchema.safeParse(body)
    if (!parsed.success) {
      return NextResponse.json({ error: "Invalid input", details: parsed.error.flatten().fieldErrors }, { status: 400 })
    }

    const existing = await prisma.user.findUnique({
      where: { id: session.user.id },
      select: { riskPrefs: true },
    })
    const prev = (existing?.riskPrefs as any) || {}

    const merged = {
      dailyLossLimit: parsed.data.dailyLossLimit !== undefined ? (parsed.data.dailyLossLimit === "" || parsed.data.dailyLossLimit === null ? null : Number(parsed.data.dailyLossLimit)) : prev.dailyLossLimit ?? null,
      maxTradesPerDay: parsed.data.maxTradesPerDay !== undefined ? (parsed.data.maxTradesPerDay === "" || parsed.data.maxTradesPerDay === null ? null : Number(parsed.data.maxTradesPerDay)) : prev.maxTradesPerDay ?? null,
      maxConsecutiveLosses: parsed.data.maxConsecutiveLosses !== undefined ? (parsed.data.maxConsecutiveLosses === "" || parsed.data.maxConsecutiveLosses === null ? null : Number(parsed.data.maxConsecutiveLosses)) : prev.maxConsecutiveLosses ?? null,
      maxRiskPerTradePct: parsed.data.maxRiskPerTradePct !== undefined ? (parsed.data.maxRiskPerTradePct === "" || parsed.data.maxRiskPerTradePct === null ? null : Number(parsed.data.maxRiskPerTradePct)) : prev.maxRiskPerTradePct ?? 1,
    }

    await prisma.user.update({
      where: { id: session.user.id },
      data: { riskPrefs: merged },
    })

    return NextResponse.json(merged)
  } catch (error) {
    console.error("Error updating risk preferences:", error instanceof Error ? error.message : "Unknown error")
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 })
  }
}

import { NextResponse } from "next/server"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { resolveAccountScope } from "@/lib/active-account"

export async function GET(request: Request) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const { searchParams } = new URL(request.url)
    const accountId = searchParams.get("accountId")

    const [user, scope] = await Promise.all([
      prisma.user.findUnique({
        where: { id: session.user.id },
        select: { riskPrefs: true, timezone: true },
      }),
      resolveAccountScope(session.user.id, accountId),
    ])

    const prefs = (user?.riskPrefs as any) || {}

    // Today's realized stats
    const dayStart = new Date()
    dayStart.setHours(0, 0, 0, 0)

    const whereClause: any = scope.all
      ? { userId: session.user.id, status: "closed", exitAt: { gte: dayStart } }
      : { accountId: scope.accounts[0]?.id, status: "closed", exitAt: { gte: dayStart } }

    const todayTrades = await prisma.trade.findMany({
      where: whereClause,
      orderBy: { exitAt: "asc" },
      select: { netPnl: true },
    })

    const todayPnl = todayTrades.reduce((s, t) => s + Number(t.netPnl || 0), 0)

    // Consecutive losing trades (across all history)
    let consecutiveLosses = 0
    const recentAll = await prisma.trade.findMany({
      where: scope.all
        ? { userId: session.user.id, status: "closed" }
        : { accountId: scope.accounts[0]?.id, status: "closed" },
      orderBy: { exitAt: "desc" },
      select: { netPnl: true },
      take: 50,
    })
    for (const t of recentAll) {
      if (Number(t.netPnl || 0) < 0) consecutiveLosses++
      else break
    }

    // Week P&L
    const weekStart = new Date()
    weekStart.setHours(0, 0, 0, 0)
    weekStart.setDate(weekStart.getDate() - (weekStart.getDay() === 0 ? 6 : weekStart.getDay() - 1))
    const weekTrades = await prisma.trade.findMany({
      where: {
        ...(scope.all ? { userId: session.user.id } : { accountId: scope.accounts[0]?.id }),
        status: "closed",
        exitAt: { gte: weekStart },
      },
      select: { netPnl: true },
    })
    const weekPnl = weekTrades.reduce((s, t) => s + Number(t.netPnl || 0), 0)

    // Alerts
    const dailyLossLimit = prefs.dailyLossLimit ?? null
    const maxTradesPerDay = prefs.maxTradesPerDay ?? null
    const maxConsecutiveLosses = prefs.maxConsecutiveLosses ?? null

    const alerts: { severity: "critical" | "warning" | "info"; message: string }[] = []

    if (dailyLossLimit !== null && todayPnl <= -Math.abs(dailyLossLimit)) {
      alerts.push({ severity: "critical", message: `Daily loss limit reached (${todayPnl.toFixed(2)} / -${Math.abs(dailyLossLimit)}). Stop trading.` })
    } else if (dailyLossLimit !== null && todayPnl <= -Math.abs(dailyLossLimit) * 0.7) {
      alerts.push({ severity: "warning", message: `Approaching daily loss limit (${Math.round((Math.abs(todayPnl) / Math.abs(dailyLossLimit)) * 100)}%).` })
    }

    if (maxTradesPerDay !== null && todayTrades.length >= maxTradesPerDay) {
      alerts.push({ severity: "warning", message: `Max trades per day reached (${todayTrades.length}/${maxTradesPerDay}).` })
    } else if (maxTradesPerDay !== null && todayTrades.length >= maxTradesPerDay - 1) {
      alerts.push({ severity: "info", message: `One trade left before the daily limit (${todayTrades.length}/${maxTradesPerDay}).` })
    }

    if (maxConsecutiveLosses !== null && consecutiveLosses >= maxConsecutiveLosses) {
      alerts.push({ severity: "critical", message: `${consecutiveLosses} consecutive losses (limit ${maxConsecutiveLosses}). Step back and re-evaluate.` })
    } else if (maxConsecutiveLosses !== null && consecutiveLosses === maxConsecutiveLosses - 1) {
      alerts.push({ severity: "warning", message: `${consecutiveLosses} consecutive losses — one more and you hit your limit.` })
    }

    return NextResponse.json({
      prefs: {
        dailyLossLimit,
        maxTradesPerDay,
        maxConsecutiveLosses,
        maxRiskPerTradePct: prefs.maxRiskPerTradePct ?? 1,
      },
      today: {
        pnl: Math.round(todayPnl * 100) / 100,
        trades: todayTrades.length,
        consecutiveLosses,
      },
      weekPnl: Math.round(weekPnl * 100) / 100,
      baseCurrency: scope.currency,
      alerts,
    })
  } catch (error: any) {
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 })
  }
}

import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { NextResponse } from "next/server"
import { z } from "zod"

const createSetupSchema = z.object({
  name: z.string().min(1).max(100),
  description: z.string().max(500).optional(),
})

export async function GET() {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const setups = await prisma.tradingSetup.findMany({
      where: { userId: session.user.id },
      orderBy: { createdAt: "desc" },
    })

    const trades = await prisma.trade.findMany({
      where: { userId: session.user.id, status: "closed" },
      select: { netPnl: true, netPnlUsd: true, riskAmount: true, setupTags: true, entryAt: true },
      orderBy: { entryAt: "asc" },
    })

    const thirtyDaysAgo = new Date(Date.now() - 30 * 86400000)

    const stats: Record<string, { count: number; wins: number; losses: number; pnl: number; pnlUsd: number; winPnl: number; lossPnl: number; rSum: number; rCount: number; best: number; worst: number; recentCount: number; lastTradeAt: string | null; series: number[] }> = {}

    const ensure = (name: string) => {
      const key = name.toLowerCase()
      if (!stats[key]) {
        stats[key] = {
          count: 0, wins: 0, losses: 0, pnl: 0, pnlUsd: 0, winPnl: 0, lossPnl: 0,
          rSum: 0, rCount: 0, best: -Infinity, worst: Infinity, recentCount: 0,
          lastTradeAt: null, series: [],
        }
      }
      return stats[key]
    }

    for (const t of trades) {
      if (!t.setupTags) continue
      const pnl = Number(t.netPnl || 0)
      const pnlUsd = Number(t.netPnlUsd ?? t.netPnl ?? 0)
      const isWin = pnl > 0
      const isLoss = pnl < 0

      for (const tag of t.setupTags) {
        const s = ensure(tag)
        s.count += 1
        if (isWin) s.wins += 1
        if (isLoss) s.losses += 1
        s.pnl += pnl
        s.pnlUsd += pnlUsd
        if (isWin) s.winPnl += pnl
        if (isLoss) s.lossPnl += Math.abs(pnl)
        if (Number(t.riskAmount) > 0) {
          s.rSum += pnl / Number(t.riskAmount)
          s.rCount += 1
        }
        if (pnl > s.best) s.best = pnl
        if (pnl < s.worst) s.worst = pnl
        if (t.entryAt >= thirtyDaysAgo) s.recentCount += 1
        const ts = t.entryAt.getTime()
        if (!s.lastTradeAt || ts > new Date(s.lastTradeAt).getTime()) s.lastTradeAt = t.entryAt.toISOString()
        s.series.push(pnl)
      }
    }

    const downsample = (arr: number[], max = 40) => {
      if (arr.length <= max) return arr
      const bucket = Math.ceil(arr.length / max)
      const out: number[] = []
      for (let i = 0; i < arr.length; i += bucket) {
        out.push(arr.slice(i, i + bucket).reduce((s, v) => s + v, 0))
      }
      return out
    }

    const enrichedSetups = setups.map((s) => {
      const st = stats[s.name.toLowerCase()] || { count: 0, wins: 0, losses: 0, pnl: 0, pnlUsd: 0, winPnl: 0, lossPnl: 0, rSum: 0, rCount: 0, best: 0, worst: 0, recentCount: 0, lastTradeAt: null, series: [] }

      let cum = 0
      const series = downsample(st.series).map(v => Math.round((cum += v) * 100) / 100)

      return {
        ...s,
        count: st.count,
        winRate: st.count > 0 ? (st.wins / st.count) * 100 : 0,
        netPnl: Math.round(st.pnl * 100) / 100,
        netPnlUsd: Math.round(st.pnlUsd * 100) / 100,
        losses: st.losses,
        profitFactor: st.lossPnl > 0 ? st.winPnl / st.lossPnl : st.winPnl > 0 ? 99 : 0,
        avgWin: st.wins > 0 ? st.winPnl / st.wins : 0,
        avgLoss: st.losses > 0 ? st.lossPnl / st.losses : 0,
        avgR: st.rCount > 0 ? st.rSum / st.rCount : 0,
        best: st.best === -Infinity ? 0 : st.best,
        worst: st.worst === Infinity ? 0 : st.worst,
        recentCount: st.recentCount,
        lastTradeAt: st.lastTradeAt,
        series,
      }
    })

    return NextResponse.json(enrichedSetups)
  } catch (error) {
    console.error("[SETUPS_GET]", error instanceof Error ? error.message : "Unknown error")
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 })
  }
}

export async function POST(req: Request) {
  const session = await auth()
  if (!session?.user?.id) {
