const HEADERS = [
  "entryAt", "exitAt", "symbol", "instrumentType", "side", "quantity",
  "entryPrice", "exitPrice", "stopLoss", "riskAmount", "fees",
  "grossPnl", "netPnl", "netPnlUsd", "setupTags", "emotionTags", "status",
]

function escapeCsv(value: any): string {
  const str = value === null || value === undefined ? "" : String(value)
  if (/[",\n]/.test(str)) return `"${str.replace(/"/g, '""')}"`
  return str
}

export async function GET(request: Request) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const url = new URL(request.url)
    const accountId = url.searchParams.get("accountId") || "all"
    const scope = await resolveAccountScope(session.user.id, accountId)

    if (!scope.all && scope.accounts.length === 0) {
      return new Response("")
    }

    const whereClause: any = scope.all
      ? { userId: session.user.id }
      : { accountId: scope.accounts[0].id }

    const symbol = url.searchParams.get("symbol")
    const side = url.searchParams.get("side")
    const result = url.searchParams.get("result")
    const status = url.searchParams.get("status")
    const date = url.searchParams.get("date")
    const sort = url.searchParams.get("sort")

    if (symbol) whereClause.symbol = { contains: symbol, mode: "insensitive" }
    if (side) whereClause.side = side
    if (status) whereClause.status = status
    if (result) {
      if (result === "win") whereClause.netPnl = { gt: 0 }
      else if (result === "loss") whereClause.netPnl = { lt: 0 }
      else if (result === "be") whereClause.netPnl = { equals: 0 }
    }
    if (date) {
      const now = new Date()
      if (date === "today") whereClause.entryAt = { gte: new Date(now.setHours(0, 0, 0, 0)) }
      else if (date === "7d") { const p = new Date(); p.setDate(p.getDate() - 7); whereClause.entryAt = { gte: p } }
      else if (date === "30d") { const p = new Date(); p.setDate(p.getDate() - 30); whereClause.entryAt = { gte: p } }
      else if (date === "this_month") whereClause.entryAt = { gte: new Date(now.getFullYear(), now.getMonth(), 1) }
    }

    const orderBy: any = {}
    if (sort && sort in HEADERS) orderBy[sort] = "asc"
    else orderBy.entryAt = "desc"

    const format = url.searchParams.get("format")

    const trades = await prisma.trade.findMany({
      where: whereClause,
      orderBy,
      select: {
        entryAt: true, exitAt: true, symbol: true, instrumentType: true, side: true,
        quantity: true, entryPrice: true, exitPrice: true, stopLoss: true, riskAmount: true,
        fees: true, grossPnl: true, netPnl: true, netPnlUsd: true, setupTags: true,
        emotionTags: true, status: true,
      },
    })

    if (format === "json") {
      return NextResponse.json({ trades })
    }

    const rows = trades.map((t) => [
      t.entryAt.toISOString(),
      t.exitAt ? t.exitAt.toISOString() : "",
      t.symbol,
      t.instrumentType || "",
      t.side,
      t.quantity,
      t.entryPrice ?? "",
      t.exitPrice ?? "",
      t.stopLoss ?? "",
      t.riskAmount ?? "",
      t.fees ?? 0,
      t.grossPnl ?? "",
      t.netPnl ?? "",
      t.netPnlUsd ?? "",
      (t.setupTags || []).join("|"),
      (t.emotionTags || []).join("|"),
      t.status,
    ])

    const csv = [HEADERS.join(","), ...rows.map((r) => r.map(escapeCsv).join(","))].join("\n")

    return new Response(csv, {
      headers: {
        "Content-Type": "text/csv; charset=utf-8",
        "Content-Disposition": `attachment; filename="trades-export-${new Date().toISOString().slice(0, 10)}.csv"`,
      },
    })
  } catch (error) {
    console.error("[TRADES_EXPORT_GET]", error instanceof Error ? error.message : "Unknown error")
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 })
  }
}

import { NextResponse } from "next/server"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { evaluateChallenge } from "@/lib/prop-firm.service"
import { z } from "zod"

const rollbackSchema = z.object({
  token: z.object({
    accountId: z.string().min(1),
    before: z.string(),
    challengeId: z.string().optional(),
  }),
})

export async function POST(request: Request) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const body = await request.json()
    const parsed = rollbackSchema.safeParse(body)
    if (!parsed.success) {
      return NextResponse.json({ error: "Invalid input", details: parsed.error.flatten().fieldErrors }, { status: 400 })
    }

    const { token } = parsed.data

    // Ensure the account belongs to the user
    const account = await prisma.tradingAccount.findUnique({
      where: { id: token.accountId },
    })
    if (!account || account.userId !== session.user.id) {
      return NextResponse.json({ error: "Account not found." }, { status: 404 })
    }

    const before = new Date(token.before)

    const result = await prisma.trade.deleteMany({
      where: {
        accountId: token.accountId,
        createdAt: { gt: before },
      },
    })

    // Invalidate behavioral snapshot cache
    await prisma.behavioralSnapshot.deleteMany({
      where: { accountId: token.accountId },
    })

    // Re-evaluate linked challenge after rollback
    let challengeStatus = null
    if (token.challengeId) {
      const evaluated = await evaluateChallenge(token.challengeId)
      challengeStatus = evaluated?.status ?? null
    }

    return NextResponse.json({
      deleted: result.count,
      challengeStatus,
    })
  } catch (error: any) {
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 })
  }
}

import { NextResponse } from "next/server"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { parseCSV } from "@/lib/parsers"
import { parseGenericCSV, type GenericMapping } from "@/lib/parsers/generic.parser"
import { classifySymbol } from "@/lib/market/symbols"
import { getActiveAccount } from "@/lib/active-account"
import { evaluateChallenge } from "@/lib/prop-firm.service"
import { rateLimit } from "@/lib/rate-limit"

const PREVIEW_LIMIT = 10

export async function POST(request: Request) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const rl = rateLimit(`import:${session.user.id}`, { limit: 5, windowMs: 60000 })
    if (!rl.success) {
      return NextResponse.json({ error: "Too many requests. Please wait a minute." }, { status: 429 })
    }

    const formData = await request.formData()
    const file = formData.get("file") as File
    const broker = formData.get("broker") as string
    const accountId = (formData.get("accountId") as string) || null
    const mappingRaw = (formData.get("mapping") as string) || null
    const mode = (formData.get("mode") as string) || "import"

    if (!file || !broker) {
      return NextResponse.json({ error: "File and broker are required." }, { status: 400 })
    }

    const text = await file.text()

    // Retrieve target account: a specific account, or the active account
    let account = null
    let targetChallenge = null

    if (accountId) {
      account = await prisma.tradingAccount.findFirst({
        where: { id: accountId, userId: session.user.id }
      })
      if (!account) {
        return NextResponse.json({ error: "Trading account not found." }, { status: 404 })
      }
      targetChallenge = await prisma.propChallenge.findFirst({
        where: { accountId: account.id }
      })
    } else {
      account = await getActiveAccount(session.user.id)
      if (account) {
        targetChallenge = await prisma.propChallenge.findFirst({
          where: { accountId: account.id }
        })
      }
    }

    if (!account) {
      return NextResponse.json({ error: "No trading account found." }, { status: 404 })
    }

    let parseResult
    if (broker === "generic" && mappingRaw) {
      let mapping: GenericMapping
      try {
        mapping = JSON.parse(mappingRaw)
      } catch {
        return NextResponse.json({ error: "Invalid column mapping." }, { status: 400 })
      }
      parseResult = parseGenericCSV(text, mapping)
    } else {
      parseResult = await parseCSV(text, broker as any)
    }

    if (parseResult.errors.length > 0 && parseResult.trades.length === 0) {
       return NextResponse.json({ error: "Failed to parse CSV file: " + parseResult.errors[0].message }, { status: 400 })
    }

    const parsedTrades = parseResult.trades

    if (parsedTrades.length === 0) {
      return NextResponse.json({ error: "No valid trades found in the CSV." }, { status: 400 })
    }

    const userId = session.user.id as string

    // Fetch default setup
    const defaultSetup = await prisma.tradingSetup.findFirst({
      where: { userId: session.user.id, isDefault: true }
    })
    const defaultSetupTags = defaultSetup ? [defaultSetup.name] : []

    const fxRate = Number(account.fxRateToUsd ?? 1)

    // Map to Prisma schema and calculate missing fields
    const tradesToInsert = parsedTrades.map((t) => {
      const isLong = t.side.toUpperCase() === "LONG"
      let netPnl = t.netPnl

      // Basic P&L calculation if missing
      if (netPnl === undefined) {
        if (t.exitPrice && t.entryPrice) {
          const diff = isLong ? t.exitPrice - t.entryPrice : t.entryPrice - t.exitPrice
          netPnl = (diff * (t.quantity || 1)) - (t.fees || 0)
        } else {
          netPnl = 0
        }
      }

      return {
        userId,
        accountId: account.id,
        symbol: t.symbol,
        instrumentType: t.instrumentType || classifySymbol(t.symbol),
        side: t.side.toUpperCase(),
        entryAt: t.entryAt,
        exitAt: t.exitAt || t.entryAt, // Default to entry if missing
        entryPrice: t.entryPrice ?? 0,
        exitPrice: t.exitPrice ?? 0,
        quantity: t.quantity ?? 0,
        netPnl,
        netPnlUsd: Math.round(Number(netPnl) * fxRate * 10000) / 10000,
        fees: t.fees || 0,
        status: t.status === "open" ? "open" : "closed",
        setupTags: defaultSetupTags,
      }
    })

    // ── PREVIEW MODE ─────────────────────────────────────────────────────────
    if (mode === "preview") {
      // Duplicate detection against existing trades (symbol + entryAt + side)
      const existing = await prisma.trade.findMany({
        where: { accountId: account.id },
        select: { symbol: true, entryAt: true, side: true },
      })
      const seen = new Set(existing.map(e => `${e.symbol}|${e.entryAt.getTime()}|${e.side.toUpperCase()}`))

      const previewRows = tradesToInsert.slice(0, PREVIEW_LIMIT).map((t) => ({
        symbol: t.symbol,
        side: t.side,
        entryAt: t.entryAt.toISOString(),
        exitAt: t.exitAt?.toISOString() || null,
        quantity: Number(t.quantity),
        entryPrice: Number(t.entryPrice),
        exitPrice: Number(t.exitPrice),
        netPnl: Number(t.netPnl),
        fees: Number(t.fees),
        status: t.status,
      }))

      const duplicates = tradesToInsert.filter(t =>
        seen.has(`${t.symbol}|${new Date(t.entryAt).getTime()}|${t.side}`)
      ).length

      return NextResponse.json({
        preview: true,
        total: tradesToInsert.length,
        duplicates,
        newRows: tradesToInsert.length - duplicates,
        previewRows,
        parseErrors: parseResult.errors.slice(0, 5),
      })
    }

    // ── IMPORT MODE ──────────────────────────────────────────────────────────
    const before = new Date()

    const result = await prisma.trade.createMany({
      data: tradesToInsert,
      skipDuplicates: true,
    })

    // Invalidate behavioral snapshot cache
    await prisma.behavioralSnapshot.deleteMany({
      where: { accountId: account.id },
    })

    // If importing into a prop challenge, re-evaluate the challenge immediately
    let challengeStatus = null
    if (targetChallenge && result.count > 0) {
      const evaluated = await evaluateChallenge(targetChallenge.id)
      challengeStatus = evaluated?.status ?? null
    }

    return NextResponse.json({
      count: result.count,
      challengeStatus,
      token: {
        accountId: account.id,
        before: before.toISOString(),
        challengeId: targetChallenge?.id || null,
      },
    })
  } catch (error: unknown) {
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from "next/server"
import { z } from "zod"
import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { DEFAULT_WATCHLIST, sanitizeSymbol, symbolName } from "@/lib/market/symbols"

export interface WatchlistRow {
  id: string
  symbol: string
  name: string
}

const addSchema = z.object({ symbol: z.string().trim().min(2).max(24) })
const delSchema = z.object({ symbol: z.string().trim().min(2).max(24) })

async function rowsFor(userId: string): Promise<WatchlistRow[]> {
  const items = await prisma.watchlistItem.findMany({
    where: { userId },
    orderBy: [{ sortOrder: "asc" }, { createdAt: "asc" }],
  })
  return items.map((i) => ({ id: i.id, symbol: i.symbol, name: i.displayName ?? symbolName(i.symbol) }))
}

async function seedDefaults(userId: string): Promise<void> {
  const count = await prisma.watchlistItem.count({ where: { userId } })
  if (count > 0) return
  await prisma.watchlistItem.createMany({
    data: DEFAULT_WATCHLIST.map((symbol, idx) => ({
      userId,
      symbol,
      displayName: symbolName(symbol),
      sortOrder: idx,
    })),
  })
}

export async function GET() {
  try {
    const session = await auth()
    if (!session?.user?.id) return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    await seedDefaults(session.user.id)
    return NextResponse.json({ items: await rowsFor(session.user.id) })
  } catch (error) {
    const message = "Internal Server Error"
    console.error("Watchlist list error:", message)
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

export async function POST(request: Request) {
  try {
    const session = await auth()
    if (!session?.user?.id) return NextResponse.json({ error: "Unauthorized" }, { status: 401 })

    const parsed = addSchema.safeParse(await request.json())
    if (!parsed.success) return NextResponse.json({ error: "Symbole invalide" }, { status: 400 })

    const symbol = sanitizeSymbol(parsed.data.symbol)
    if (!symbol) return NextResponse.json({ error: "Symbole invalide" }, { status: 400 })

    const count = await prisma.watchlistItem.count({ where: { userId: session.user.id } })
    if (count >= 50) {
      return NextResponse.json({ error: "Watchlist pleine (max 50 symboles)" }, { status: 400 })
    }

    await prisma.watchlistItem.upsert({
      where: { userId_symbol: { userId: session.user.id, symbol } },
      create: { userId: session.user.id, symbol, displayName: symbolName(symbol), sortOrder: count },
      update: {},
    })

    return NextResponse.json({ success: true, items: await rowsFor(session.user.id) })
  } catch (error) {
    const message = "Internal Server Error"
    console.error("Watchlist add error:", message)
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

export async function DELETE(request: NextRequest) {
  try {
    const session = await auth()
    if (!session?.user?.id) return NextResponse.json({ error: "Unauthorized" }, { status: 401 })

    const parsed = delSchema.safeParse(Object.fromEntries(request.nextUrl.searchParams))
    if (!parsed.success) return NextResponse.json({ error: "Symbole invalide" }, { status: 400 })

    const symbol = parsed.data.symbol.trim().toUpperCase()
    await prisma.watchlistItem.deleteMany({ where: { userId: session.user.id, symbol } })

    return NextResponse.json({ success: true, items: await rowsFor(session.user.id) })
  } catch (error) {
    const message = "Internal Server Error"
    console.error("Watchlist delete error:", message)
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

