                    </td>
                    <td style={{ color: "var(--color-gray-400)", fontSize: "0.8rem" }}>
                      {t.exitAt ? new Date(t.exitAt).toLocaleDateString("en-US", { month: "short", day: "numeric" }) : "—"}
