                    <td style={{ color: t.rMultiple != null ? (t.rMultiple >= 0 ? "var(--color-profit)" : "var(--color-loss)") : "var(--color-gray-500)" }}>
                      {t.rMultiple != null ? `${t.rMultiple >= 0 ? "+" : ""}${t.rMultiple.toFixed(2)}R` : "—"}
                    </td>
                    <td style={{ fontSize: "0.78rem", color: "var(--color-gray-400)" }}>{(t.setupTags || []).slice(0, 2).join(", ")}</td>
                    <td style={{ textAlign: "right", fontWeight: 600, color: t.netPnl >= 0 ? "var(--color-profit)" : "var(--color-loss)" }}>
                      {formatCurrency(t.netPnl, ccy, true, 2)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
        <div style={{ marginTop: "0.75rem", textAlign: "right" }}>
          <Link className="btn btn-outline" style={{ fontSize: "0.82rem" }} href={`/trades?accountId=${account.id}`}>
            View all trades →
          </Link>
        </div>
      </div>

      {/* Edit modal */}
      {editing && editForm && (
        <div role="dialog" aria-modal="true" style={{ position: "fixed", inset: 0, zIndex: 200, background: "rgba(0,0,0,0.6)", display: "flex", alignItems: "center", justifyContent: "center", padding: "1rem" }} onClick={() => setEditing(false)}>
          <div className="chart-card" style={{ width: "100%", maxWidth: 440, padding: "1.5rem" }} onClick={e => e.stopPropagation()}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1.25rem" }}>
              <h3 style={{ fontWeight: 700, fontSize: "1.05rem" }}>Edit Account</h3>
              <button onClick={() => setEditing(false)} style={{ background: "transparent", border: "none", color: "var(--color-gray-400)", cursor: "pointer", fontSize: "1.4rem" }}>&times;</button>
            </div>
            <form onSubmit={saveEdit} style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
              <div>
                <label className="label">Account Name</label>
                <input className="input" value={editForm.name} onChange={e => setEditForm({ ...editForm, name: e.target.value })} />
              </div>
              <div>
                <label className="label">Initial Balance</label>
                <input className="input" type="number" value={editForm.initialBalance} onChange={e => setEditForm({ ...editForm, initialBalance: e.target.value })} />
              </div>
              <div>
                <label className="label">FX Rate to USD</label>
                <input className="input" type="number" step="0.0001" value={editForm.fxRateToUsd} onChange={e => setEditForm({ ...editForm, fxRateToUsd: e.target.value })} />
              </div>
              <label style={{ display: "flex", alignItems: "center", gap: "0.5rem", fontSize: "0.85rem", color: "var(--color-gray-300)", cursor: "pointer" }}>
                <input type="checkbox" checked={!!editForm.isDefault} onChange={e => setEditForm({ ...editForm, isDefault: e.target.checked })} />
                Set as default account
              </label>
              <div style={{ display: "flex", justifyContent: "flex-end", gap: "0.5rem", marginTop: "0.5rem" }}>
                <button type="button" className="btn btn-outline" onClick={() => setEditing(false)}>Cancel</button>
                <button type="submit" className="btn btn-primary">Save</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

"use client"

import { useState, useMemo } from "react"
import { useRouter } from "next/navigation"
import { CreateAccountModal } from "./CreateAccountModal"
import { Wallet, Target, Activity, TrendingUp, Pencil, Trash2, ExternalLink } from "lucide-react"
import { formatCurrency } from "@/lib/formatters"
import { toast } from "sonner"

export function AccountsManager({ accounts }: { accounts: any[] }) {
  const router = useRouter()
  const [modalOpen, setModalOpen] = useState(false)
  const [filterType, setFilterType] = useState<string>("all")
  const [editing, setEditing] = useState<any>(null)

  // Global KPIs
  const kpis = useMemo(() => {
    let totalEquity = 0
    let totalPnl = 0
    let totalPnlUsd = 0
    let fundedCapital = 0
    const activeCount = accounts.length

    accounts.forEach(acc => {
      const eq = acc.propChallenge ? acc.propChallenge.currentEquity : acc.initialBalance + acc.stats.totalPnl
      totalEquity += eq
      totalPnl += acc.stats.totalPnl
      totalPnlUsd += acc.stats.totalPnlUsd || 0

      if (acc.type === 'prop_firm' && acc.propChallenge?.status === 'passed') {
        fundedCapital += acc.initialBalance
      }
    })

    return { totalEquity, totalPnl, totalPnlUsd, fundedCapital, activeCount }
  }, [accounts])

  const filteredAccounts = accounts.filter(acc => {
    const type = acc.type || "personal"
    return filterType === "all" || type === filterType
  })

  const getTypeColor = (type: string) => {
    switch (type) {
      case 'prop_firm': return "var(--color-brand-500)"
      case 'demo': return "var(--color-gray-400)"
      default: return "var(--color-profit)"
    }
  }

  const getTypeName = (type: string) => {
    switch (type) {
      case 'prop_firm': return "Prop Firm"
      case 'demo': return "Demo"
      default: return "Personal"
    }
  }

  const openAccount = async (acc: any) => {
    if (acc.propChallenge?.id) {
      router.push(`/challenges/${acc.propChallenge.id}`)
      return
    }
    router.push(`/accounts/${acc.id}`)
  }

  const handleDelete = async (acc: any) => {
    if (!confirm(`Delete account "${acc.name}" and all its trades? This cannot be undone.`)) return
    try {
      const res = await fetch(`/api/accounts/${acc.id}`, { method: "DELETE" })
      if (!res.ok) {
        const data = await res.json().catch(() => null)
        throw new Error(data?.error || "Failed to delete")
      }
      toast.success("Account deleted")
      router.refresh()
    } catch (err: any) {
      toast.error(err.message || "Failed to delete account")
    }
  }

  const handleSaveEdit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!editing) return
    try {
      const res = await fetch(`/api/accounts/${editing.id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: editing.name,
          initialBalance: editing.initialBalance,
          fxRateToUsd: editing.fxRateToUsd,
          isDefault: editing.isDefault,
        }),
      })
      if (!res.ok) throw new Error("Failed to update account")
      toast.success("Account updated")
      setEditing(null)
      router.refresh()
    } catch {
      toast.error("Failed to update account")
    }
  }

  return (
