"use client"

import { useState } from "react"
import { ChevronLeft, ChevronRight, Search, ArrowUpDown } from "lucide-react"

export interface Column<T> {
  key: string
  label: string
  sortable?: boolean
  render?: (item: T) => React.ReactNode
}

interface AdminTableProps<T> {
  columns: Column<T>[]
  data: T[]
  totalItems: number
  pageSize?: number
  currentPage: number
  onPageChange: (page: number) => void
  onSearch?: (query: string) => void
  searchPlaceholder?: string
  sortBy?: string
  sortOrder?: "asc" | "desc"
  onSort?: (key: string) => void
}

export function AdminTable<T extends { id: string }>({
  columns,
  data,
  totalItems,
  pageSize = 20,
  currentPage,
  onPageChange,
  onSearch,
  searchPlaceholder = "Search...",
  sortBy,
  sortOrder,
  onSort,
}: AdminTableProps<T>) {
  const [searchQuery, setSearchQuery] = useState("")
  const totalPages = Math.ceil(totalItems / pageSize)

  const handleSearch = (value: string) => {
    setSearchQuery(value)
    onSearch?.(value)
  }

  return (
    <div>
      {/* Search */}
      {onSearch && (
        <div style={{ marginBottom: 16, position: "relative" }}>
          <Search size={14} style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)", color: "var(--color-gray-500)" }} />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => handleSearch(e.target.value)}
            placeholder={searchPlaceholder}
            style={{
              width: "100%", maxWidth: 320, padding: "0.5rem 0.75rem 0.5rem 2rem",
              borderRadius: 8, border: "1px solid var(--color-gray-700)",
              background: "var(--color-gray-900)", color: "var(--color-gray-200)",
              fontSize: "0.8rem", outline: "none",
            }}
          />
        </div>
      )}

      {/* Table */}
      <div style={{ overflowX: "auto", border: "1px solid var(--color-gray-800)", borderRadius: 8 }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "0.8rem" }}>
          <thead>
            <tr style={{ borderBottom: "1px solid var(--color-gray-800)" }}>
              {columns.map(col => (
                <th
                  key={col.key}
                  onClick={() => col.sortable && onSort?.(col.key)}
                  style={{
                    padding: "0.75rem 1rem", textAlign: "left", fontWeight: 600,
                    color: "var(--color-gray-400)", fontSize: "0.7rem", textTransform: "uppercase",
                    letterSpacing: "0.05em", whiteSpace: "nowrap",
                    cursor: col.sortable ? "pointer" : "default",
                  }}
                >
                  <span style={{ display: "flex", alignItems: "center", gap: 4 }}>
                    {col.label}
                    {col.sortable && (
                      <ArrowUpDown size={12} style={{ opacity: sortBy === col.key ? 1 : 0.4 }} />
                    )}
                  </span>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {data.map(item => (
              <tr key={item.id} style={{ borderBottom: "1px solid var(--color-gray-800)" }}>
                {columns.map(col => (
                  <td key={col.key} style={{ padding: "0.6rem 1rem", color: "var(--color-gray-300)" }}>
                    {col.render ? col.render(item) : String((item as Record<string, unknown>)[col.key] ?? "")}
                  </td>
                ))}
              </tr>
            ))}
            {data.length === 0 && (
              <tr>
                <td colSpan={columns.length} style={{ padding: "2rem", textAlign: "center", color: "var(--color-gray-500)" }}>
                  No data found
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 12, fontSize: "0.75rem", color: "var(--color-gray-400)" }}>
          <span>Showing {((currentPage - 1) * pageSize) + 1}–{Math.min(currentPage * pageSize, totalItems)} of {totalItems}</span>
          <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
            <button
              onClick={() => onPageChange(currentPage - 1)}
              disabled={currentPage === 1}
              style={{ padding: 6, borderRadius: 6, border: "1px solid var(--color-gray-700)", background: "var(--color-gray-900)", color: "var(--color-gray-300)", cursor: currentPage === 1 ? "not-allowed" : "pointer", opacity: currentPage === 1 ? 0.5 : 1 }}
            >
              <ChevronLeft size={14} />
            </button>
            <span style={{ padding: "0 8px" }}>{currentPage} / {totalPages}</span>
            <button
              onClick={() => onPageChange(currentPage + 1)}
              disabled={currentPage === totalPages}
              style={{ padding: 6, borderRadius: 6, border: "1px solid var(--color-gray-700)", background: "var(--color-gray-900)", color: "var(--color-gray-300)", cursor: currentPage === totalPages ? "not-allowed" : "pointer", opacity: currentPage === totalPages ? 0.5 : 1 }}
            >
              <ChevronRight size={14} />
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

"use client"

import { useState } from "react"
import { toast } from "sonner"

export function PlanForm({ plan, onClose, onSave }: { plan?: any, onClose: () => void, onSave: (p: any) => void }) {
  const [loading, setLoading] = useState(false)
  const [formData, setFormData] = useState({
    name: plan?.name || "",
    price: plan?.price || "",
    maxAccounts: plan?.maxAccounts || 1,
    maxTradesPerMonth: plan?.maxTradesPerMonth || "",
    backtestAccess: plan?.backtestAccess || false,
    isActive: plan?.isActive ?? true,
    features: {
      replayAccess: plan?.features?.replayAccess || false,
      propFirmAccess: plan?.features?.propFirmAccess || false,
      advancedStats: plan?.features?.advancedStats || false,
    }
  })

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)
    try {
      const url = plan ? `/api/admin/plans/${plan.id}` : `/api/admin/plans`
      const method = plan ? "PUT" : "POST"

      const res = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...formData,
          price: Number(formData.price),
          maxAccounts: Number(formData.maxAccounts),
          maxTradesPerMonth: formData.maxTradesPerMonth ? Number(formData.maxTradesPerMonth) : null,
        })
      })

      if (!res.ok) throw new Error("Failed to save plan")
      const saved = await res.json()
      toast.success(plan ? "Plan updated" : "Plan created")
      onSave(saved)
    } catch (err: any) {
      toast.error(err.message)
    } finally {
      setLoading(false)
    }
  }

  const toggleFeature = (key: keyof typeof formData.features) => {
    setFormData(prev => ({
      ...prev,
      features: {
        ...prev.features,
        [key]: !prev.features[key]
      }
    }))
  }

  return (
    <div className="card" style={{ padding: "1.5rem", marginBottom: "1.5rem" }}>
      <h3 style={{ fontSize: "1.1rem", fontWeight: 600, color: "var(--color-gray-100)", marginBottom: "1rem" }}>
        {plan ? "Edit Plan" : "Create New Plan"}
      </h3>
      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "1.25rem" }}>

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "1rem" }}>
          <div className="form-group">
            <label className="label">Plan Name (e.g., Standard, Pro, Elite)</label>
            <input 
              type="text" 
              className="input" 
              required
              value={formData.name}
              onChange={e => setFormData({ ...formData, name: e.target.value })}
            />
          </div>
          <div className="form-group">
            <label className="label">Monthly Price ($)</label>
            <input 
              type="number" 
              step="0.01"
              className="input" 
              required
              value={formData.price}
              onChange={e => setFormData({ ...formData, price: e.target.value })}
            />
          </div>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "1rem" }}>
          <div className="form-group">
            <label className="label">Max Accounts</label>
            <input 
              type="number" 
              className="input" 
              required
              value={formData.maxAccounts}
              onChange={e => setFormData({ ...formData, maxAccounts: Number(e.target.value) })}
            />
          </div>
          <div className="form-group">
            <label className="label">Max Trades / Month (Leave blank for unlimited)</label>
            <input 
              type="number" 
              className="input" 
              value={formData.maxTradesPerMonth}
              onChange={e => setFormData({ ...formData, maxTradesPerMonth: e.target.value })}
            />
          </div>
        </div>

        <div>
          <label className="label" style={{ marginBottom: "0.5rem" }}>Access & Features</label>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0.75rem", background: "var(--color-gray-900)", padding: "1rem", borderRadius: "8px", border: "1px solid var(--color-gray-800)" }}>
            <label style={{ display: "flex", alignItems: "center", gap: "0.5rem", color: "var(--color-gray-300)", cursor: "pointer" }}>
              <input 
                type="checkbox" 
                checked={formData.backtestAccess}
                onChange={e => setFormData({ ...formData, backtestAccess: e.target.checked })}
              />
              Backtest Access
            </label>

            <label style={{ display: "flex", alignItems: "center", gap: "0.5rem", color: "var(--color-gray-300)", cursor: "pointer" }}>
              <input 
                type="checkbox" 
                checked={formData.features.replayAccess}
                onChange={() => toggleFeature("replayAccess")}
              />
              Replay Access (Market Replay)
            </label>

            <label style={{ display: "flex", alignItems: "center", gap: "0.5rem", color: "var(--color-gray-300)", cursor: "pointer" }}>
              <input 
                type="checkbox" 
                checked={formData.features.propFirmAccess}
                onChange={() => toggleFeature("propFirmAccess")}
              />
              Prop Firm Manager Access
            </label>

            <label style={{ display: "flex", alignItems: "center", gap: "0.5rem", color: "var(--color-gray-300)", cursor: "pointer" }}>
              <input 
                type="checkbox" 
                checked={formData.features.advancedStats}
                onChange={() => toggleFeature("advancedStats")}
              />
              Advanced Analytics & Reports
            </label>
          </div>
        </div>

        <div style={{ display: "flex", gap: "1rem", marginTop: "0.5rem" }}>
          <label style={{ display: "flex", alignItems: "center", gap: "0.5rem", color: "var(--color-gray-300)", cursor: "pointer" }}>
            <input 
              type="checkbox" 
              checked={formData.isActive}
              onChange={e => setFormData({ ...formData, isActive: e.target.checked })}
            />
            Plan is Active (Available for purchase)
          </label>
        </div>

        <div style={{ display: "flex", justifyContent: "flex-end", gap: "0.75rem", marginTop: "1rem" }}>
          <button type="button" className="btn btn-ghost" onClick={onClose} disabled={loading}>
            Cancel
          </button>
          <button type="submit" className="btn btn-primary" disabled={loading}>
            {loading ? "Saving..." : "Save Plan"}
          </button>
        </div>
      </form>
    </div>
  )
}

"use client"

import { useState } from "react"
import { Plus, Edit2, Trash2, Check, X } from "lucide-react"
import { toast } from "sonner"
import { PlanForm } from "./PlanForm"

export function PlansManager({ initialPlans }: { initialPlans: any[] }) {
  const [plans, setPlans] = useState(initialPlans)
  const [editingPlan, setEditingPlan] = useState<any | null>(null)
  const [isCreating, setIsCreating] = useState(false)

  const refreshPlans = async () => {
    // In a real app we might fetch again or just rely on state updates
    // For now, state updates are handled inline
  }

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this plan?")) return
    try {
      const res = await fetch(`/api/admin/plans/${id}`, { method: "DELETE" })
      if (!res.ok) throw new Error("Failed to delete")
      setPlans(plans.filter(p => p.id !== id))
      toast.success("Plan deleted")
    } catch (e: any) {
      toast.error(e.message)
    }
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "1.5rem" }}>
      <div style={{ display: "flex", justifyContent: "flex-end" }}>
        <button 
          onClick={() => setIsCreating(true)}
          className="btn btn-primary"
        >
          <Plus size={16} /> Create New Plan
        </button>
      </div>

      {(isCreating || editingPlan) && (
        <PlanForm 
          plan={editingPlan}
          onClose={() => {
            setIsCreating(false)
            setEditingPlan(null)
          }}
          onSave={(newPlan) => {
            if (isCreating) {
              setPlans([...plans, newPlan])
            } else {
              setPlans(plans.map(p => p.id === newPlan.id ? newPlan : p))
            }
            setIsCreating(false)
            setEditingPlan(null)
          }}
        />
      )}

      <div className="table-wrapper">
        <table className="data-table comfortable">
          <thead>
            <tr>
              <th>Plan Name</th>
              <th>Price</th>
              <th>Status</th>
              <th>Accounts</th>
              <th>Features</th>
              <th style={{ textAlign: "right" }}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {plans.map((plan) => (
              <tr key={plan.id}>
                <td>
                  <span style={{ fontWeight: 600, color: "var(--color-gray-100)" }}>
                    {plan.name}
                  </span>
                </td>
                <td>
                  <span style={{ fontFamily: "monospace", fontSize: "1rem" }}>
                    ${Number(plan.price).toFixed(2)}
                  </span>
                </td>
                <td>
                  {plan.isActive ? (
                    <span className="badge badge-profit"><Check size={12} /> Active</span>
                  ) : (
                    <span className="badge badge-neutral"><X size={12} /> Inactive</span>
                  )}
                </td>
                <td>
                  <span style={{ color: "var(--color-gray-400)" }}>
                    {plan.maxAccounts} max
                  </span>
                </td>
                <td>
                  <div style={{ display: "flex", gap: "0.25rem", flexWrap: "wrap" }}>
                    {plan.backtestAccess && <span className="badge badge-brand">Backtest</span>}
                    {plan.features?.replayAccess && <span className="badge badge-brand">Replay</span>}
                    {plan.features?.propFirmAccess && <span className="badge badge-brand">PropFirm</span>}
                    {plan.features?.advancedStats && <span className="badge badge-brand">Stats</span>}
                  </div>
                </td>
                <td style={{ textAlign: "right" }}>
                  <div style={{ display: "flex", gap: "0.5rem", justifyContent: "flex-end" }}>
                    <button 
                      onClick={() => setEditingPlan(plan)}
                      className="btn btn-ghost btn-sm"
                    >
                      <Edit2 size={16} />
                    </button>
                    <button 
                      onClick={() => handleDelete(plan.id)}
                      className="btn btn-danger btn-sm"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
            {plans.length === 0 && (
              <tr>
                <td colSpan={6} style={{ textAlign: "center", padding: "2rem", color: "var(--color-gray-500)" }}>
                  No plans created yet.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  )
}

"use client"

import { useState } from "react"
import { AdminTable, Column } from "@/components/admin/AdminTable"
import { Badge } from "@/components/admin/Badge"

export interface Subscription {
  id: string
  status: string
  startDate: Date
  renewalDate: Date | null
  user: { id: string; email: string; name: string | null }
  plan: { id: string; name: string; price: number }
  cryptoTxId: string | null
}

export interface Plan {
  id: string
  name: string
  price: number
}

export function SubscriptionsTable({ initialSubscriptions, plans }: { initialSubscriptions: Subscription[]; plans: Plan[] }) {
  const [subscriptions, setSubscriptions] = useState(initialSubscriptions)
  const [editingUserId, setEditingUserId] = useState<string | null>(null)
  const [selectedPlanId, setSelectedPlanId] = useState("")
  const [isApproving, setIsApproving] = useState<string | null>(null)

  const handleApprove = async (subscriptionId: string) => {
    setIsApproving(subscriptionId)
    try {
      const res = await fetch("/api/admin/subscriptions", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ subscriptionId, status: "ACTIVE" }),
      })
      if (res.ok) {
        window.location.reload()
      }
    } catch {
      setIsApproving(null)
    }
  }

  const handleAssignPlan = async (userId: string) => {
    if (!selectedPlanId) return

    try {
      const res = await fetch("/api/admin/subscriptions", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId, planId: selectedPlanId }),
      })
      if (res.ok) {
        setEditingUserId(null)
        setSelectedPlanId("")
        window.location.reload()
      }
    } catch {
      // silent
    }
  }

  const columns: Column<Subscription>[] = [
    {
      key: "user",
      label: "User",
      render: (sub) => (
        <div>
          <div style={{ fontWeight: 500, color: "var(--color-gray-200)" }}>{sub.user.email}</div>
          {sub.user.name && <div style={{ fontSize: "0.7rem", color: "var(--color-gray-500)" }}>{sub.user.name}</div>}
        </div>
      ),
    },
    {
      key: "plan",
      label: "Plan",
      render: (sub) => editingUserId === sub.user.id ? (
        <div style={{ display: "flex", gap: 4 }}>
          <select
            value={selectedPlanId}
            onChange={(e) => setSelectedPlanId(e.target.value)}
            style={{ padding: "0.3rem 0.5rem", borderRadius: 4, border: "1px solid var(--color-gray-700)", background: "var(--color-gray-900)", color: "var(--color-gray-200)", fontSize: "0.75rem" }}
          >
            <option value="">Select plan</option>
            {plans.map(p => (
              <option key={p.id} value={p.id}>{p.name} — ${p.price}</option>
            ))}
          </select>
          <button onClick={() => handleAssignPlan(sub.user.id)} className="btn btn-primary" style={{ fontSize: "0.65rem", padding: "0.2rem 0.5rem" }}>Save</button>
          <button onClick={() => setEditingUserId(null)} className="btn btn-outline" style={{ fontSize: "0.65rem", padding: "0.2rem 0.5rem" }}>Cancel</button>
        </div>
      ) : (
        <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
          <span>{sub.plan.name}</span>
          <button
            onClick={() => { setEditingUserId(sub.user.id); setSelectedPlanId(sub.plan.id) }}
            style={{ fontSize: "0.65rem", color: "var(--color-brand-500)", background: "transparent", border: "none", cursor: "pointer" }}
          >
            Change
          </button>
        </div>
      ),
    },
    {
      key: "status",
      label: "Status",
      render: (sub) => (
        <Badge variant={sub.status === "ACTIVE" ? "success" : sub.status === "CANCELED" ? "warning" : "default"}>
          {sub.status}
        </Badge>
      ),
    },
    {
      key: "startDate",
      label: "Start Date",
      render: (sub) => new Date(sub.startDate).toLocaleDateString(),
    },
    {
      key: "renewalDate",
      label: "Renewal",
      render: (sub) => sub.renewalDate ? new Date(sub.renewalDate).toLocaleDateString() : "—",
    },
    {
      key: "crypto",
      label: "Crypto Payment",
      render: (sub) => (
        <div style={{ display: "flex", flexDirection: "column", gap: 6, minWidth: 150 }}>
          {sub.cryptoTxId ? (
            <div style={{ fontSize: "0.7rem", color: "var(--color-gray-400)", wordBreak: "break-all" }}>
              <span style={{ fontWeight: 600, color: "var(--color-gray-300)" }}>TxID:</span> {sub.cryptoTxId}
            </div>
          ) : (
            <span style={{ fontSize: "0.75rem", color: "var(--color-gray-500)" }}>No TxID</span>
          )}
          {sub.status === "PENDING" && (
            <button
              onClick={() => handleApprove(sub.id)}
              disabled={isApproving === sub.id}
              className="btn btn-primary"
              style={{ fontSize: "0.7rem", padding: "0.3rem 0.5rem", width: "fit-content" }}
            >
              {isApproving === sub.id ? "Approving..." : "Approve Payment"}
            </button>
          )}
        </div>
      ),
    },
  ]

  return (
    <AdminTable
      columns={columns}
      data={subscriptions}
      totalItems={subscriptions.length}
      currentPage={1}
      onPageChange={() => {}}
    />
  )
}

