  _count: { accounts: number; backtestSessions: number; dailyJournals: number }
  accounts: { id: string; name: string; broker: string | null; type: string }[]
  adminActionLogs: {
    id: string
    action: string
    reason: string | null
    createdAt: Date
    admin: { email: string; name: string | null }
  }[]
}

export function UserDetailClient({ user }: { user: User }) {
  const router = useRouter()
  const [loading, setLoading] = useState(false)
  const [confirmAction, setConfirmAction] = useState<string | null>(null)
  const [reason, setReason] = useState("")

  const handleAction = async (action: string, extra?: Record<string, unknown>) => {
    setLoading(true)
    try {
      if (action === "impersonate") {
        const res = await fetch(`/api/admin/users/${user.id}`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ action, reason, ...extra }),
        })
        if (res.ok) {
          const data = await res.json()
          window.location.href = `/dashboard?impersonate=${data.impersonate.userId}`
        }
      } else {
        const res = await fetch("/api/admin/users", {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ userId: user.id, action, reason, ...extra }),
        })
        if (res.ok) {
          router.refresh()
          setConfirmAction(null)
          setReason("")
        }
      }
    } finally {
      setLoading(false)
    }
  }

  const getActionLabel = () => {
    switch (confirmAction) {
      case "suspend": return "Suspend User"
      case "activate": return "Activate User"
      case "ban": return "Ban User"
      case "delete": return "Delete User"
      case "impersonate": return "Impersonate User"
      default: return ""
    }
  }

  const getActionMessage = () => {
    switch (confirmAction) {
      case "suspend": return `Suspend ${user.email}? They will not be able to log in.`
      case "activate": return `Reactivate ${user.email}? They will be able to log in again.`
      case "ban": return `Ban ${user.email}? This is a severe action. They will be blocked from logging in.`
      case "delete": return `Soft delete ${user.email}? Their data will be preserved but they won't appear in the platform.`
      case "impersonate": return `You will be logged in as ${user.email} for 30 minutes. This action is logged.`
      default: return ""
    }
  }

  return (
    <div>
      <Link href="/admin/users" style={{ display: "inline-flex", alignItems: "center", gap: 6, color: "var(--color-gray-400)", textDecoration: "none", marginBottom: 16, fontSize: "0.8rem" }}>
        <ArrowLeft size={14} /> Back to Users
      </Link>

      {/* Header */}
      <div className="chart-card" style={{ padding: "1.5rem", marginBottom: "1.5rem" }}>
        <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 16, flexWrap: "wrap" }}>
          <div>
            <h1 style={{ fontSize: "1.25rem", fontWeight: 700, color: "var(--color-gray-100)" }}>{user.email}</h1>
            {user.name && <p style={{ fontSize: "0.85rem", color: "var(--color-gray-400)", marginTop: 4 }}>{user.name}</p>}
            <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
              <Badge variant={user.role === "SUPER_ADMIN" ? "warning" : user.role === "ADMIN" ? "info" : "default"}>{user.role}</Badge>
              <Badge variant={user.status === "ACTIVE" ? "success" : user.status === "SUSPENDED" ? "warning" : "danger"}>{user.status}</Badge>
            </div>
          </div>
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
            {user.status === "ACTIVE" ? (
              <button onClick={() => setConfirmAction("suspend")} className="btn btn-outline" style={{ fontSize: "0.75rem", display: "flex", alignItems: "center", gap: 4 }}>
                <UserX size={14} /> Suspend
              </button>
            ) : (
              <button onClick={() => setConfirmAction("activate")} className="btn btn-outline" style={{ fontSize: "0.75rem", display: "flex", alignItems: "center", gap: 4 }}>
                <UserCheck size={14} /> Activate
              </button>
            )}
            <button onClick={() => setConfirmAction("ban")} className="btn btn-outline" style={{ fontSize: "0.75rem", color: "var(--color-loss)", borderColor: "rgba(239,68,68,0.3)", display: "flex", alignItems: "center", gap: 4 }}>
              <AlertTriangle size={14} /> Ban
            </button>
            <button onClick={() => setConfirmAction("impersonate")} className="btn btn-outline" style={{ fontSize: "0.75rem", display: "flex", alignItems: "center", gap: 4 }}>
              <LogIn size={14} /> Impersonate
            </button>
            <button onClick={() => setConfirmAction("delete")} className="btn btn-outline" style={{ fontSize: "0.75rem", color: "var(--color-loss)", borderColor: "rgba(239,68,68,0.3)", display: "flex", alignItems: "center", gap: 4 }}>
              <Trash2 size={14} /> Delete
            </button>
          </div>
        </div>
      </div>

      {/* Stats */}
      <div className="kpi-grid" style={{ marginBottom: "1.5rem" }}>
        {[
          { label: "Accounts", value: user._count.accounts },
          { label: "Backtests", value: user._count.backtestSessions },
          { label: "Journal Entries", value: user._count.dailyJournals },
        ].map(s => (
          <div key={s.label} className="chart-card" style={{ padding: "1rem" }}>
            <p style={{ fontSize: "0.65rem", textTransform: "uppercase", color: "var(--color-gray-500)", fontWeight: 600, letterSpacing: "0.08em" }}>{s.label}</p>
            <p style={{ fontSize: "1.25rem", fontWeight: 700, color: "var(--color-gray-200)", marginTop: 4 }}>{s.value}</p>
          </div>
        ))}
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(400px, 1fr))", gap: "1.5rem" }}>
        {/* Accounts */}
        <div className="chart-card" style={{ padding: "1.25rem" }}>
          <h3 style={{ fontSize: "0.875rem", fontWeight: 600, color: "var(--color-gray-200)", marginBottom: 12 }}>Trading Accounts</h3>
          {user.accounts.length === 0 ? (
            <p style={{ fontSize: "0.8rem", color: "var(--color-gray-500)" }}>No accounts</p>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {user.accounts.map(acc => (
                <div key={acc.id} style={{ padding: "0.5rem 0.75rem", borderRadius: 6, background: "var(--color-gray-950)", border: "1px solid var(--color-gray-800)" }}>
                  <div style={{ fontWeight: 500, color: "var(--color-gray-200)", fontSize: "0.8rem" }}>{acc.name}</div>
                  <div style={{ fontSize: "0.7rem", color: "var(--color-gray-500)" }}>{acc.broker || "—"} · {acc.type}</div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Audit Logs */}
        <div className="chart-card" style={{ padding: "1.25rem" }}>
          <h3 style={{ fontSize: "0.875rem", fontWeight: 600, color: "var(--color-gray-200)", marginBottom: 12 }}>Recent Admin Actions</h3>
          {user.adminActionLogs.length === 0 ? (
            <p style={{ fontSize: "0.8rem", color: "var(--color-gray-500)" }}>No actions logged</p>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {user.adminActionLogs.map(log => (
                <div key={log.id} style={{ padding: "0.5rem 0.75rem", borderRadius: 6, background: "var(--color-gray-950)", border: "1px solid var(--color-gray-800)" }}>
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                    <span style={{ fontWeight: 500, color: "var(--color-gray-200)", fontSize: "0.8rem" }}>{log.action}</span>
                    <span style={{ fontSize: "0.65rem", color: "var(--color-gray-500)" }}>{new Date(log.createdAt).toLocaleDateString()}</span>
                  </div>
                  <div style={{ fontSize: "0.7rem", color: "var(--color-gray-500)" }}>
                    by {log.admin.email} {log.reason && `· ${log.reason}`}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Confirm Dialog */}
      <ConfirmDialog
        open={!!confirmAction}
        title={getActionLabel()}
        message={getActionMessage()}
        confirmLabel={loading ? "Processing..." : "Confirm"}
        variant={confirmAction === "ban" || confirmAction === "delete" ? "danger" : confirmAction === "suspend" ? "warning" : "default"}
        onConfirm={() => confirmAction && handleAction(confirmAction)}
        onCancel={() => { setConfirmAction(null); setReason("") }}
      />

      {/* Reason Input (for suspend/ban) */}
      {confirmAction && (confirmAction === "suspend" || confirmAction === "ban") && (
        <div style={{ position: "fixed", bottom: 80, left: "50%", transform: "translateX(-50%)", zIndex: 101, width: "100%", maxWidth: 400, padding: "0 16px" }}>
          <input
            type="text"
            value={reason}
            onChange={(e) => setReason(e.target.value)}
            placeholder="Reason (optional)"
            style={{ width: "100%", padding: "0.5rem 0.75rem", borderRadius: 8, border: "1px solid var(--color-gray-700)", background: "var(--color-gray-900)", color: "var(--color-gray-200)", fontSize: "0.8rem", outline: "none" }}
          />
        </div>
      )}
    </div>
  )
}

"use client"

import { useState, useCallback } from "react"
import Link from "next/link"
import { AdminTable, Column } from "@/components/admin/AdminTable"
import { Badge } from "@/components/admin/Badge"

interface User {
  id: string
  email: string
  name: string | null
  role: string
  status: string
  createdAt: Date
  lastLoginAt: Date | null
  _count: { accounts: number }
}

export function UsersTable({ initialUsers }: { initialUsers: User[] }) {
  const [users, setUsers] = useState(initialUsers)
  const [search, setSearch] = useState("")
  const [page, setPage] = useState(1)
  const [sortBy, setSortBy] = useState("createdAt")
  const [sortOrder, setSortOrder] = useState<"asc" | "desc">("desc")
  const [roleFilter, setRoleFilter] = useState("")
  const [statusFilter, setStatusFilter] = useState("")
  const [loading, setLoading] = useState(false)

  const fetchUsers = useCallback(async () => {
    setLoading(true)
    const params = new URLSearchParams({
      page: String(page),
      pageSize: "20",
      search,
      sortBy,
      sortOrder,
    })
    if (roleFilter) params.set("role", roleFilter)
    if (statusFilter) params.set("status", statusFilter)

    try {
      const res = await fetch(`/api/admin/users?${params}`)
      const data = await res.json()
      setUsers(data.users)
    } catch {
      // silent
    } finally {
      setLoading(false)
    }
  }, [page, search, sortBy, sortOrder, roleFilter, statusFilter])

  const handleSearch = (value: string) => {
    setSearch(value)
    setPage(1)
    setTimeout(fetchUsers, 300)
  }

  const handleSort = (key: string) => {
    setSortBy(key)
    setSortOrder(prev => prev === "asc" ? "desc" : "asc")
    setTimeout(fetchUsers, 100)
  }

  const columns: Column<User>[] = [
    {
      key: "email",
      label: "User",
      sortable: true,
      render: (user) => (
        <Link href={`/admin/users/${user.id}`} style={{ textDecoration: "none" }}>
          <div>
            <div style={{ fontWeight: 500, color: "var(--color-gray-200)" }}>{user.email}</div>
            {user.name && <div style={{ fontSize: "0.7rem", color: "var(--color-gray-500)" }}>{user.name}</div>}
          </div>
        </Link>
      ),
    },
    {
      key: "role",
      label: "Role",
      sortable: true,
      render: (user) => <Badge variant={user.role === "SUPER_ADMIN" ? "warning" : user.role === "ADMIN" ? "info" : "default"}>{user.role}</Badge>,
    },
    {
      key: "status",
      label: "Status",
      sortable: true,
      render: (user) => <Badge variant={user.status === "ACTIVE" ? "success" : user.status === "SUSPENDED" ? "warning" : "danger"}>{user.status}</Badge>,
    },
    {
      key: "accounts",
      label: "Accounts",
      render: (user) => user._count.accounts,
    },
    {
      key: "createdAt",
      label: "Joined",
      sortable: true,
      render: (user) => new Date(user.createdAt).toLocaleDateString(),
    },
    {
      key: "lastLoginAt",
      label: "Last Login",
      sortable: true,
      render: (user) => user.lastLoginAt ? new Date(user.lastLoginAt).toLocaleDateString() : "—",
    },
  ]

  return (
    <div>
      {/* Filters */}
      <div style={{ display: "flex", gap: 8, marginBottom: 16, flexWrap: "wrap" }}>
        <select
          value={roleFilter}
          onChange={(e) => { setRoleFilter(e.target.value); setPage(1); setTimeout(fetchUsers, 100) }}
          style={{ padding: "0.4rem 0.6rem", borderRadius: 6, border: "1px solid var(--color-gray-700)", background: "var(--color-gray-900)", color: "var(--color-gray-300)", fontSize: "0.8rem" }}
        >
          <option value="">All Roles</option>
          <option value="USER">USER</option>
          <option value="ADMIN">ADMIN</option>
          <option value="SUPER_ADMIN">SUPER_ADMIN</option>
        </select>
        <select
          value={statusFilter}
          onChange={(e) => { setStatusFilter(e.target.value); setPage(1); setTimeout(fetchUsers, 100) }}
          style={{ padding: "0.4rem 0.6rem", borderRadius: 6, border: "1px solid var(--color-gray-700)", background: "var(--color-gray-900)", color: "var(--color-gray-300)", fontSize: "0.8rem" }}
        >
          <option value="">All Status</option>
          <option value="ACTIVE">ACTIVE</option>
          <option value="SUSPENDED">SUSPENDED</option>
          <option value="BANNED">BANNED</option>
        </select>
      </div>

      <AdminTable
        columns={columns}
        data={users}
        totalItems={users.length}
        currentPage={page}
        onPageChange={setPage}
        onSearch={handleSearch}
        searchPlaceholder="Search by email or name..."
        sortBy={sortBy}
        sortOrder={sortOrder}
        onSort={handleSort}
      />
    </div>
  )
}

"use client"

import type { Candle } from "@/lib/market/types"
import { unrealizedPnl } from "@/lib/market/simulator"
import { fmtPrice } from "@/lib/formatters"
import type { SimTrade } from "./types"
import { X } from "lucide-react"
import { formatCurrency } from "@/lib/formatters"

interface Props {
  positions: SimTrade[]
  selectedPositionId: string | null
  currentCandle: Candle | undefined
  symbol: string
  onSelect: (id: string) => void
  onCloseManual: (id: string) => void
  onUpdateLevels: (id: string, levels: { stopLoss: number; takeProfit: number }) => void
  onDeleteTrade: (id: string) => void
  onSaveTrade?: (trade: SimTrade) => void
}

export function PositionsStrip({
  positions,
  selectedPositionId,
  currentCandle,
  symbol,
  onSelect,
  onCloseManual,
  onUpdateLevels,
  onDeleteTrade,
  onSaveTrade,
}: Props) {
  const closedTrades = positions.filter(p => p.exitPrice != null)
  const openPositions = positions.filter(p => p.exitPrice == null)
  const totalPnl = closedTrades.reduce((s, t) => s + (t.netPnl ?? 0), 0)
  const wins = closedTrades.filter(t => (t.netPnl ?? 0) > 0).length
  const winRate = closedTrades.length > 0 ? (wins / closedTrades.length) * 100 : null
  const rVals = closedTrades.map(t => t.rMultiple ?? 0)
  const avgR = rVals.length > 0 ? rVals.reduce((s, r) => s + r, 0) / rVals.length : null
  if (positions.length === 0) {
    return (
      <>
        <div className="tz-replay-positions-header">
          <div className="tz-replay-positions-title">
            Positions <span className="bg-[var(--color-gray-800)] px-2 py-0.5 rounded-full text-xs text-[var(--color-gray-400)]">0</span>
          </div>
        </div>
        <div className="tz-replay-positions-table flex items-center justify-center text-[var(--color-gray-400)] text-[0.85rem]">
          No open positions.
        </div>
      </>
    )
  }

  return (
    <>
      <div className="tz-replay-positions-header">
        <div className="tz-replay-positions-title">
          Positions
          {openPositions.length > 0 && (
            <span className="bg-[var(--color-brand-500)] px-2 py-0.5 rounded-full text-xs text-white">{openPositions.length} open</span>
          )}
          {closedTrades.length > 0 && (
            <span className="bg-[var(--color-gray-800)] px-2 py-0.5 rounded-full text-xs text-[var(--color-gray-400)]">{closedTrades.length} closed</span>
          )}
        </div>
        {closedTrades.length > 0 && (
          <div className="tz-replay-positions-summary">
            <span>P&amp;L: <b className={totalPnl >= 0 ? "text-[var(--color-profit)]" : "text-[var(--color-loss)]"}>{totalPnl >= 0 ? "+" : ""}{totalPnl.toFixed(2)}</b></span>
            {winRate !== null && <span>Win: <b className={winRate >= 50 ? "text-[var(--color-profit)]" : "text-[var(--color-loss)]"}>{winRate.toFixed(0)}%</b></span>}
            {avgR !== null && <span>Avg R: <b className={avgR >= 0 ? "text-[var(--color-profit)]" : "text-[var(--color-loss)]"}>{avgR >= 0 ? "+" : ""}{avgR.toFixed(2)}R</b></span>}
          </div>
        )}
      </div>
      <div className="tz-replay-positions-table">
        <table>
          <thead>
            <tr>
              <th>#</th>
              <th>Symbol</th>
              <th>Direction</th>
              <th>Quantity</th>
              <th>Open time</th>
              <th>Entry</th>
              <th>Stop Loss</th>
              <th>Take Profit</th>
              <th>Unrealized P&L</th>
              <th>Status</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {positions.map((p, i) => {
              const isClosed = p.exitPrice != null
              const pnl = isClosed ? p.netPnl : (currentCandle ? unrealizedPnl(p, currentCandle) : null)
              const isProfit = pnl !== null && pnl >= 0
              const pnlColor = pnl === null ? "" : isProfit ? "tz-replay-td-pnl-up" : "tz-replay-td-pnl-down"
              const active = selectedPositionId === p.id || (selectedPositionId == null && positions[0]?.id === p.id)

              let statusText = "Open"
              if (isClosed) {
                statusText = p.saved ? "Saved" : p.saving ? "Saving..." : "Closed"
              }

              return (
                <tr
                  key={p.id}
                  onClick={() => onSelect(p.id)}
                  className={`cursor-pointer ${active ? "bg-[var(--color-gray-800)]" : "bg-transparent"} ${isClosed ? "opacity-70" : "opacity-100"}`}
                >
                  <td>{i + 1}</td>
                  <td>{symbol}</td>
                  <td className={p.side === "long" ? "tz-replay-td-buy" : "tz-replay-td-sell"}>
                    {p.side === "long" ? "BUY" : "SELL"}
                  </td>
                  <td>{fmtQty(p.quantity)}</td>
                  <td>{new Date(p.entryTime * 1000).toLocaleString(undefined, { month: '2-digit', day: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' })}</td>
                  <td>{fmtPrice(p.entryPrice)}</td>
                  <td>
                    {isClosed ? (
                      <span>{Number.isFinite(p.stopLoss) ? fmtPrice(p.stopLoss) : "—"}</span>
                    ) : (
                      <input
                        type="number"
                        step="any"
                        value={Number.isFinite(p.stopLoss) ? p.stopLoss : ""}
                        onClick={(e) => e.stopPropagation()}
                        onChange={(e) =>
                          onUpdateLevels(p.id, { stopLoss: Number(e.target.value), takeProfit: p.takeProfit })
                        }
                        className="w-[80px] h-[24px] bg-transparent border border-[var(--color-gray-300)] rounded px-1.5 text-xs outline-none text-inherit"
                      />
                    )}
                  </td>
                  <td>
                    {isClosed ? (
                      <span>{Number.isFinite(p.takeProfit) ? fmtPrice(p.takeProfit) : "—"}</span>
                    ) : (
                      <input
                        type="number"
                        step="any"
                        value={Number.isFinite(p.takeProfit) ? p.takeProfit : ""}
                        onClick={(e) => e.stopPropagation()}
                        onChange={(e) =>
                          onUpdateLevels(p.id, { stopLoss: p.stopLoss, takeProfit: Number(e.target.value) })
                        }
                        className="w-[80px] h-[24px] bg-transparent border border-[var(--color-gray-300)] rounded px-1.5 text-xs outline-none text-inherit"
                      />
                    )}
                  </td>
                  <td className={pnlColor}>
                    {pnl === null ? "—" : formatCurrency(pnl, "USD", true)}
                  </td>
                  <td className={isClosed && p.saved ? "text-[var(--color-profit)]" : "text-inherit"}>
                    {isClosed && p.saved ? (
                      <span className="flex items-center gap-1 text-[0.72rem] text-[var(--color-profit)]">
                        ✓ Saved
                      </span>
                    ) : statusText}
                  </td>
                  <td>
                    <div className="flex gap-1 items-center">
                      {isClosed && !p.saved && onSaveTrade && (
                        <button
                          type="button"
                          title="Save to journal"
                          onClick={(e) => {
                            e.stopPropagation()
                            onSaveTrade(p)
                          }}
                          disabled={p.saving}
                          className="bg-[var(--color-gray-800)] border border-[var(--color-gray-700)] text-[var(--color-brand-400)] cursor-pointer rounded px-1.5 py-0.5 text-[0.65rem] font-bold flex items-center gap-1"
                        >
                          {p.saving ? "..." : "Save"}
                        </button>
                      )}
                      <button
                        type="button"
                        title={isClosed ? "Supprimer le trade" : "Fermer la position"}
                        onClick={(e) => {
                          e.stopPropagation()
                          if (isClosed) {
                            onDeleteTrade(p.id)
                          } else {
                            onCloseManual(p.id)
                          }
                        }}
                        className="bg-transparent border-none text-[var(--color-gray-400)] cursor-pointer"
                      >
                        <X size={16} />
                      </button>
                    </div>
                  </td>
                </tr>
              )
            })}
          </tbody>
        </table>
      </div>
    </>
  )
}

function fmt(n: number): string {
  return n.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })
}

function fmtQty(n: number): string {
  return n.toLocaleString("en-US", { maximumFractionDigits: 4 })
}

