  closedTrades: SimTrade[]
  theme: "dark" | "light"
  onUpdateLevels: (id: string, levels: { stopLoss: number; takeProfit: number }) => void
}

const PALETTES = {
  dark: {
    text: "#a1a1aa",
    grid: "#14141a",
    crosshair: "#3f3f46",
    up: "#00c758",
    down: "#ef4444",
    volUp: "rgba(16,185,129,0.35)",
    volDown: "rgba(239,68,68,0.35)",
    brand: "#00c758",
    ema9: "#f59e0b",
    ema20: "#3b82f6",
    ema50: "#a855f7",
    ema200: "#ec4899",
    rsi: "#8b5cf6",
    vwap: "#eab308",
    bb: "#94a3b8",
  },
  light: {
    text: "#52525b",
    grid: "#e8e8ec",
    crosshair: "#c8c8cf",
    up: "#059669",
    down: "#dc2626",
    volUp: "rgba(5,150,105,0.22)",
    volDown: "rgba(220,38,38,0.22)",
    brand: "#16a34a",
    ema9: "#d97706",
    ema20: "#2563eb",
    ema50: "#9333ea",
    ema200: "#db2777",
    rsi: "#7c3aed",
    vwap: "#a16207",
    bb: "#64748b",
  },
}

export const ReplayChart = forwardRef<ReplayChartRef, ReplayChartProps>(function ReplayChart(
  {
    indicatorData,
    indicators,
    positions,
    selectedPositionId,
    closedTrades,
    theme,
    onUpdateLevels,
  },
  ref,
) {
  const selectedTrade =
    selectedPositionId != null
      ? positions.find((p) => p.id === selectedPositionId) ?? null
      : positions[0] ?? null
  const containerRef = useRef<HTMLDivElement>(null)
  const chartRef = useRef<IChartApi | null>(null)
  const candleSeriesRef = useRef<ISeriesApi<"Candlestick"> | null>(null)
  const volumeSeriesRef = useRef<ISeriesApi<"Histogram"> | null>(null)
  const rsiSeriesRef = useRef<ISeriesApi<"Line"> | null>(null)
  const lineSeriesRef = useRef<Map<string, ISeriesApi<"Line">>>(new Map())
  const markersRef = useRef<ISeriesMarkersPluginApi<Time> | null>(null)
  const entryLineRef = useRef<IPriceLine | null>(null)
  const slLineRef = useRef<IPriceLine | null>(null)
  const tpLineRef = useRef<IPriceLine | null>(null)
  const dragRef = useRef<{ mode: "sl" | "tp" } | null>(null)
  const lastSelectedTradeIdRef = useRef<string | null>(null)
  const rafRef = useRef<number | null>(null)
  const candlesCountRef = useRef<number>(0)
  const candlesRef = useRef<Candle[]>([])

  // Drawing Tools States
  const [activeDrawingTool, setActiveDrawingTool] = useState<DrawingToolType>("cursor")
  const activeDrawingToolRef = useRef<DrawingToolType>("cursor")
  const drawingManagerRef = useRef<DrawingManager | null>(null)
  const draftPointsRef = useRef<{ time: Time; price: number }[]>([])
  const drawingDraggingRef = useRef(false)

  const handleClearAllDrawings = () => {
    drawingManagerRef.current?.clearAll()
    draftPointsRef.current = []
  }

  const handleToolChange = (tool: DrawingToolType) => {
    setActiveDrawingTool(tool)
    activeDrawingToolRef.current = tool
    if (tool !== "cursor") {
      chartRef.current?.applyOptions({ handleScroll: false, handleScale: false })
      draftPointsRef.current = []
      drawingManagerRef.current?.setActiveTool(tool as any)
    } else {
      chartRef.current?.applyOptions({
        handleScroll: { mouseWheel: true, pressedMouseMove: true, horzTouchDrag: true, vertTouchDrag: true },
        handleScale: { axisPressedMouseMove: true, mouseWheel: true, pinch: true }
      })
      drawingManagerRef.current?.setActiveTool(null as any)
    }
  }

  // Live refs so callbacks never read stale props
  const activeTradeRef = useRef(selectedTrade)
  const onUpdateLevelsRef = useRef(onUpdateLevels)
  const indicatorsRef = useRef(indicators)
  const indicatorDataRef = useRef(indicatorData)
  const pal = PALETTES[theme]

  useEffect(() => {
    activeTradeRef.current = selectedTrade
    onUpdateLevelsRef.current = onUpdateLevels
    indicatorsRef.current = indicators
    indicatorDataRef.current = indicatorData
  })

  // ── helpers ────────────────────────────────────────────────────────────────
  const updateIndicators = (n: number, candles: Candle[]) => {
    const pal = PALETTES[theme]
    const ind = indicatorsRef.current
    const indData = indicatorDataRef.current
    const lineMap = lineSeriesRef.current

    const specs: { key: keyof IndicatorSeries; enabled: boolean }[] = [
      { key: "ema9", enabled: ind.ema9 },
      { key: "ema20", enabled: ind.ema20 },
      { key: "ema50", enabled: ind.ema50 },
      { key: "ema200", enabled: ind.ema200 },
      { key: "vwap", enabled: ind.vwap },
    ]

    const lineColor = (key: string) =>
      key === "ema9" ? pal.ema9
      : key === "ema20" ? pal.ema20
      : key === "ema50" ? pal.ema50
      : key === "ema200" ? pal.ema200
      : key === "vwap" ? pal.vwap
      : pal.bb

    const ensureLine = (key: string, color: string): ISeriesApi<"Line"> => {
      let s = lineMap.get(key)
      if (!s) {
        s = chartRef.current!.addSeries(LineSeries, {
          color,
          lineWidth: 1,
          priceLineVisible: false,
          lastValueVisible: false,
          crosshairMarkerVisible: false,
        })
        lineMap.set(key, s)
      }
      return s
    }
    const removeLine = (key: string) => {
      const s = lineMap.get(key)
      if (s) {
        chartRef.current?.removeSeries(s)
        lineMap.delete(key)
      }
    }

    for (const { key, enabled } of specs) {
      if (enabled) {
        const s = ensureLine(key, lineColor(key))
        s.applyOptions({ color: lineColor(key) })
        s.setData(
          indData[key].slice(0, n).map((v, i) => ({
            time: candles[i]!.time as Time,
            value: v,
          })),
        )
      } else {
        removeLine(key)
      }
    }

    if (ind.bb) {
      for (const key of ["bbUpper", "bbMiddle", "bbLower"] as const) {
        const s = ensureLine(key, lineColor("bb"))
        s.applyOptions({ color: lineColor("bb") })
        s.setData(
          indData[key].slice(0, n).map((v, i) => ({
            time: candles[i]!.time as Time,
            value: v,
          })),
        )
      }
    } else {
      removeLine("bbUpper")
      removeLine("bbMiddle")
      removeLine("bbLower")
    }

    const rs = rsiSeriesRef.current
    if (rs) {
      if (ind.rsi) {
        chartRef.current?.priceScale("rsi").applyOptions({ visible: true })
        rs.setData(
          indData.rsi.slice(0, n).map((v, i) => ({
            time: candles[i]!.time as Time,
            value: v,
          })),
        )
      } else {
        chartRef.current?.priceScale("rsi").applyOptions({ visible: false })
        rs.setData([])
      }
    }
  }

  // ── init chart (once) ────────────────────────────────────────────────────────
  useEffect(() => {
    const container = containerRef.current
    if (!container) return
    const seriesMap = lineSeriesRef.current

    const pal = PALETTES[theme]
    const chart = createChart(container, {
      autoSize: false,
      layout: {
        background: { type: ColorType.Solid, color: "transparent" },
        textColor: pal.text,
        fontFamily: "inherit",
        fontSize: 11,
      },
      grid: { vertLines: { color: pal.grid }, horzLines: { color: pal.grid } },
      crosshair: {
        mode: CrosshairMode.Normal,
        vertLine: { color: pal.crosshair, width: 1, style: LineStyle.LargeDashed },
        horzLine: { color: pal.crosshair, width: 1, style: LineStyle.LargeDashed },
      },
      rightPriceScale: { borderColor: pal.grid },
      timeScale: { borderColor: pal.grid, rightOffset: 5 },
      handleScroll: { mouseWheel: true, pressedMouseMove: true, horzTouchDrag: true, vertTouchDrag: true },
      handleScale: { axisPressedMouseMove: true, mouseWheel: true, pinch: true },
    })

    const candleSeries = chart.addSeries(CandlestickSeries, {
      upColor: pal.up,
      downColor: pal.down,
      borderVisible: false,
      wickUpColor: pal.up,
      wickDownColor: pal.down,
      priceFormat: { type: "custom", formatter: fmtPrice },
    })

    const volumeSeries = chart.addSeries(HistogramSeries, {
      priceScaleId: "vol",
      priceFormat: { type: "volume" },
      lastValueVisible: false,
      priceLineVisible: false,
    })
    chart.priceScale("vol").applyOptions({ scaleMargins: { top: 0.82, bottom: 0 } })

    const rsiSeries = chart.addSeries(LineSeries, {
      priceScaleId: "rsi",
      color: pal.rsi,
      lineWidth: 2,
      priceLineVisible: false,
      priceFormat: { type: "price", precision: 1, minMove: 0.1 },
    })
    chart.priceScale("rsi").applyOptions({ scaleMargins: { top: 0.8, bottom: 0.05 }, visible: false })

    chartRef.current = chart
    candleSeriesRef.current = candleSeries
    volumeSeriesRef.current = volumeSeries
    rsiSeriesRef.current = rsiSeries
    markersRef.current = createSeriesMarkers(candleSeries, [])

    // ─── Drawing Manager ───────────────────────────────────────────────────────
    const manager = new DrawingManager()
    manager.attach(chart, candleSeries, container)
    drawingManagerRef.current = manager

    chart.subscribeClick((param) => {
      const tool = activeDrawingToolRef.current
      if (tool === "cursor" || !drawingManagerRef.current) return
      if (drawingDraggingRef.current) return

      const point = param.point
      if (!point) return

      let time = param.time as Time
      if (!time) time = chart.timeScale().coordinateToTime(point.x) as Time
      if (!time) return

      const price = candleSeries.coordinateToPrice(point.y)
      if (price === null) return

      const newAnchor = { time, price }
      const currentDraft = [...draftPointsRef.current, newAnchor]

      let required = 2
      if (tool === "HorizontalLine" || tool === "TextAnnotation") required = 1
      if (tool === "ParallelChannel") required = 3

      if (currentDraft.length >= required) {
        const id = crypto.randomUUID()
        let drawing = null
        try {
          switch (tool) {
            case "TrendLine":
              drawing = new TrendLine(id, currentDraft)
              break
            case "HorizontalLine":
              drawing = new HorizontalLine(id, currentDraft)
              break
            case "ParallelChannel":
              drawing = new ParallelChannel(id, currentDraft)
              break
            case "FibRetracement":
              drawing = new FibRetracement(id, currentDraft)
              break
            case "Rectangle":
              drawing = new Rectangle(id, currentDraft)
              break
            case "TextAnnotation":
              drawing = new TextAnnotation(id, currentDraft)
              break
          }
          if (drawing) {
            drawingManagerRef.current.addDrawing(drawing)
          }
        } catch (err: any) {
          console.error(err)
        }
        draftPointsRef.current = []
        handleToolChange("cursor")
      } else {
        draftPointsRef.current = currentDraft
      }
    })

    const ro = new ResizeObserver((entries) => {
      const rect = entries[0]?.contentRect
      if (rect) chart.applyOptions({ width: Math.round(rect.width), height: Math.round(rect.height) })
    })
    ro.observe(container)

    return () => {
      ro.disconnect()
      if (rafRef.current != null) cancelAnimationFrame(rafRef.current)
      chart.remove()
      chartRef.current = null
      candleSeriesRef.current = null
      volumeSeriesRef.current = null
      rsiSeriesRef.current = null
      seriesMap.clear()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // ── theme ────────────────────────────────────────────────────────────────────
  useEffect(() => {
    const chart = chartRef.current
    const pal = PALETTES[theme]
    if (!chart) return
    chart.applyOptions({
      layout: { textColor: pal.text },
      grid: { vertLines: { color: pal.grid }, horzLines: { color: pal.grid } },
      crosshair: {
        vertLine: { color: pal.crosshair },
        horzLine: { color: pal.crosshair },
      },
      rightPriceScale: { borderColor: pal.grid },
      timeScale: { borderColor: pal.grid },
    })
    candleSeriesRef.current?.applyOptions({
      upColor: pal.up,
      downColor: pal.down,
      wickUpColor: pal.up,
      wickDownColor: pal.down,
    })
    rsiSeriesRef.current?.applyOptions({ color: pal.rsi })
    lineSeriesRef.current.forEach((s, key) => {
      const color =
        key === "ema9" ? pal.ema9
        : key === "ema20" ? pal.ema20
        : key === "ema50" ? pal.ema50
        : key === "ema200" ? pal.ema200
        : key === "vwap" ? pal.vwap
        : pal.bb
      s.applyOptions({ color })
    })
  }, [theme])

  // ── imperative data methods ──────────────────────────────────────────────────
  useImperativeHandle(ref, () => ({
    setData: (candles: Candle[]) => {
      const cs = candleSeriesRef.current
      const vs = volumeSeriesRef.current
      const pal = PALETTES[theme]
      candlesCountRef.current = candles.length
      candlesRef.current = candles

      if (cs) {
        cs.setData(
          candles.map((c) => ({
            time: c.time as Time,
            open: c.open,
            high: c.high,
            low: c.low,
            close: c.close,
          })),
        )
      }
      if (vs) {
        if (indicatorsRef.current.volume) {
          vs.setData(
            candles.map((c) => ({
              time: c.time as Time,
              value: c.volume,
              color: c.close >= c.open ? pal.volUp : pal.volDown,
            })),
          )
        } else {
          vs.setData([])
        }
      }
      updateIndicators(candles.length, candles)
      chartRef.current?.timeScale().scrollToRealTime()
    },

    updateTick: (candle: Candle) => {
      const cs = candleSeriesRef.current
      const vs = volumeSeriesRef.current
      const pal = PALETTES[theme]
      const n = candlesCountRef.current

      if (cs) {
        cs.update({ time: candle.time as Time, open: candle.open, high: candle.high, low: candle.low, close: candle.close })
      }
      if (vs && indicatorsRef.current.volume) {
        vs.update({ time: candle.time as Time, value: candle.volume, color: candle.close >= candle.open ? pal.volUp : pal.volDown })
      }
      // Update indicators for this new bar
      const ind = indicatorsRef.current
      const indData = indicatorDataRef.current
      const lineMap = lineSeriesRef.current
      const indSpecs: (keyof IndicatorSeries)[] = ["ema9", "ema20", "ema50", "ema200", "vwap", "bbUpper", "bbMiddle", "bbLower"]
      for (const key of indSpecs) {
        const s = lineMap.get(key)
        if (!s) continue
        const v = indData[key][n]
        if (v != null) s.update({ time: candle.time as Time, value: v })
      }
      if (ind.rsi) {
        const rv = indData.rsi[n]
        if (rv != null) rsiSeriesRef.current?.update({ time: candle.time as Time, value: rv })
      }
      candlesCountRef.current = n + 1
    },

    scrollToEnd: () => {
      chartRef.current?.timeScale().scrollToRealTime()
    },

    takeScreenshot: () => {
      return chartRef.current!.takeScreenshot()
    },
  }))

  // ── indicators-only update (when indicators toggle changes) ──────────────────
  useEffect(() => {
    const n = candlesCountRef.current
    const candles = candlesRef.current
    if (n > 0 && candles.length > 0) {
      updateIndicators(n, candles)
    }
  }, [indicators])

  // ── markers (entries / exits) ────────────────────────────────────────────────
  useEffect(() => {
    const cs = candleSeriesRef.current
    if (!cs) return
    const pal = PALETTES[theme]
    const markers: SeriesMarker<Time>[] = []

    for (const t of closedTrades) {
      if (t.exitTime == null) continue
      const pnl = t.netPnl ?? 0
      markers.push({
        time: t.entryTime as Time,
        position: t.side === "long" ? "belowBar" : "aboveBar",
        color: pal.brand,
        shape: t.side === "long" ? "arrowUp" : "arrowDown",
        text: ` ${t.side.toUpperCase()} ${t.entryPrice.toFixed(2)}`,
      })
      markers.push({
        time: t.exitTime as Time,
        position: t.side === "long" ? "aboveBar" : "belowBar",
        color: pnl >= 0 ? pal.up : pal.down,
        shape: "circle",
        text: ` ${pnl >= 0 ? "+" : ""}${pnl.toFixed(2)}`,
      })
    }
    for (const p of positions) {
      markers.push({
        time: p.entryTime as Time,
        position: p.side === "long" ? "belowBar" : "aboveBar",
        color: pal.brand,
        shape: p.side === "long" ? "arrowUp" : "arrowDown",
        text: ` ${p.side.toUpperCase()} ${p.entryPrice.toFixed(2)}`,
      })
    }
    markers.sort((a, b) => Number(a.time) - Number(b.time))
    markersRef.current?.setMarkers(markers)
  }, [positions, closedTrades, theme])

  // ── SL / TP / entry price lines ──────────────────────────────────────────────
  useEffect(() => {
    const cs = candleSeriesRef.current
    if (!cs) return
    const pal = PALETTES[theme]

    const tradeId = selectedTrade?.id ?? null
    const idChanged = tradeId !== lastSelectedTradeIdRef.current

    if (idChanged) {
      if (entryLineRef.current) {
        cs.removePriceLine(entryLineRef.current)
        entryLineRef.current = null
      }
      if (slLineRef.current) {
        cs.removePriceLine(slLineRef.current)
        slLineRef.current = null
      }
      if (tpLineRef.current) {
        cs.removePriceLine(tpLineRef.current)
        tpLineRef.current = null
      }

      if (selectedTrade) {
        entryLineRef.current = cs.createPriceLine({
          price: selectedTrade.entryPrice,
          color: pal.brand,
          lineWidth: 1,
          lineStyle: LineStyle.Dashed,
          axisLabelVisible: true,
          title: "Entry",
        })
        slLineRef.current = cs.createPriceLine({
          price: selectedTrade.stopLoss,
          color: pal.down,
          lineWidth: 1,
          lineStyle: LineStyle.Solid,
          axisLabelVisible: true,
          title: "SL",
        })
        tpLineRef.current = cs.createPriceLine({
          price: selectedTrade.takeProfit,
          color: pal.up,
          lineWidth: 1,
          lineStyle: LineStyle.Solid,
          axisLabelVisible: true,
          title: "TP",
        })
      }
      lastSelectedTradeIdRef.current = tradeId
    } else if (selectedTrade) {
      if (entryLineRef.current) entryLineRef.current.applyOptions({ price: selectedTrade.entryPrice })
      if (slLineRef.current) slLineRef.current.applyOptions({ price: selectedTrade.stopLoss })
      if (tpLineRef.current) tpLineRef.current.applyOptions({ price: selectedTrade.takeProfit })
    }
  }, [selectedTrade, theme])

  // ── pointer drag on SL/TP lines using capturing phase ────────────────────────
  useEffect(() => {
    const el = containerRef.current
    if (!el) return

    const onPointerDown = (e: PointerEvent) => {
      if (activeDrawingToolRef.current !== "cursor") return

      const chart = chartRef.current
      const act = activeTradeRef.current
      if (!chart || !act || e.button !== 0) return

      const rect = el.getBoundingClientRect()
      const y = e.clientY - rect.top
      const cs = candleSeriesRef.current
      if (!cs) return

      const slPx = cs.priceToCoordinate(act.stopLoss)
      const tpPx = cs.priceToCoordinate(act.takeProfit)

      if (slPx != null && Math.abs(y - slPx) <= 12) {
        dragRef.current = { mode: "sl" }
      } else if (tpPx != null && Math.abs(y - tpPx) <= 12) {
        dragRef.current = { mode: "tp" }
      } else {
        return
      }

      e.stopPropagation()
      e.preventDefault()
      try {
        el.setPointerCapture(e.pointerId)
      } catch {}
    }

    const onPointerMove = (e: PointerEvent) => {
      if (activeDrawingToolRef.current !== "cursor") return

      const d = dragRef.current
      const chart = chartRef.current
      const act = activeTradeRef.current
      if (!chart || !act) return

      const rect = el.getBoundingClientRect()
      const y = e.clientY - rect.top
      const cs = candleSeriesRef.current
      if (!cs) return

      if (d) {
        e.stopPropagation()
        e.preventDefault()
        const price = cs.coordinateToPrice(y)
        if (price == null) return
        if (d.mode === "sl") {
          onUpdateLevelsRef.current(act.id, { stopLoss: price, takeProfit: act.takeProfit })
        } else {
          onUpdateLevelsRef.current(act.id, { stopLoss: act.stopLoss, takeProfit: price })
        }
      } else {
        const slPx = cs.priceToCoordinate(act.stopLoss)
        const tpPx = cs.priceToCoordinate(act.takeProfit)
        const isNearSl = slPx != null && Math.abs(y - slPx) <= 12
        const isNearTp = tpPx != null && Math.abs(y - tpPx) <= 12
        if (isNearSl || isNearTp) {
          el.style.cursor = "ns-resize"
        } else {
          el.style.cursor = "crosshair"
        }
      }
    }

    const onPointerUp = (e: PointerEvent) => {
      if (dragRef.current) {
        e.stopPropagation()
        e.preventDefault()
        dragRef.current = null
        try {
          el.releasePointerCapture(e.pointerId)
        } catch {}
      }
    }

    el.addEventListener("pointerdown", onPointerDown, { capture: true })
    el.addEventListener("pointermove", onPointerMove, { capture: true })
    el.addEventListener("pointerup", onPointerUp, { capture: true })
    el.addEventListener("pointercancel", onPointerUp, { capture: true })

    return () => {
      el.removeEventListener("pointerdown", onPointerDown, { capture: true })
      el.removeEventListener("pointermove", onPointerMove, { capture: true })
      el.removeEventListener("pointerup", onPointerUp, { capture: true })
      el.removeEventListener("pointercancel", onPointerUp, { capture: true })
    }
  }, [])

  return (
    <div
      ref={containerRef}
      className="replay-chart w-full h-full relative bg-transparent"
    >
      <DrawingToolbar
        activeTool={activeDrawingTool}
        onToolChange={handleToolChange}
        onClearAll={handleClearAllDrawings}
      />
    </div>
  )
})

"use client"

import { useEffect } from "react"
import { Play, Pause, ChevronLeft, ChevronRight, SkipForward, Timer } from "lucide-react"
import { formatDateWithTimezone } from "@/lib/formatters"

export interface ReplayControlsProps {
  playing: boolean
  speed: number // candles per tick
  currentIndex: number
  total: number
  currentTime: number | null
  disabled: boolean
  timezone?: string
  onTogglePlay: () => void
  onStep: (dir: -1 | 1) => void
  onSpeed: (speed: number) => void
  onInstant: () => void
  onScrub: (index: number) => void
}

const SPEEDS = [0.5, 1, 2, 5, 10]

function fmtTime(time: number | null): string {
  if (time == null) return "--:--"
  const d = new Date(time * 1000)
  const pad = (n: number) => String(n).padStart(2, "0")
  return `${pad(d.getDate())}/${pad(d.getMonth() + 1)} ${pad(d.getHours())}:${pad(d.getMinutes())}`
}

export function ReplayControls({
  playing,
  speed,
  currentIndex,
  total,
  currentTime,
  disabled,
  timezone = "UTC",
  onTogglePlay,
  onStep,
  onSpeed,
  onInstant,
  onScrub,
}: ReplayControlsProps) {
  // Keyboard shortcuts: Space = play/pause, ←/→ = step, ↑/↓ = speed
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement
      if (
        target.tagName === "INPUT" ||
        target.tagName === "TEXTAREA" ||
        target.tagName === "SELECT" ||
        target.tagName === "BUTTON" ||
        target.isContentEditable
      ) {
        return
      }
      if (disabled) return
      if (e.code === "Space") {
        e.preventDefault()
        onTogglePlay()
      } else if (e.code === "ArrowLeft") {
        e.preventDefault()
        onStep(-1)
      } else if (e.code === "ArrowRight") {
        e.preventDefault()
        onStep(1)
      } else if (e.code === "ArrowUp" || e.code === "ArrowDown") {
        e.preventDefault()
        const idx = SPEEDS.indexOf(speed)
        const next = e.code === "ArrowUp" ? Math.min(idx + 1, SPEEDS.length - 1) : Math.max(idx - 1, 0)
        onSpeed(SPEEDS[Math.max(next, 0)] ?? 1)
      }
    }
    window.addEventListener("keydown", handler)
    return () => window.removeEventListener("keydown", handler)
  }, [disabled, playing, speed, onTogglePlay, onStep, onSpeed])

  const formattedTime = currentTime != null
    ? formatDateWithTimezone(currentTime * 1000, timezone, true)
    : "--:--"

  return (
    <div className="replay-controls" style={{ opacity: disabled ? 0.5 : 1, pointerEvents: disabled ? "none" : "auto" }}>
      <div className="replay-controls-inner">
        <div className="replay-transport">
          <button
            className="replay-btn replay-btn-step"
            onClick={() => onStep(-1)}
            title="Bougie précédente (←)"
            aria-label="Previous candle"
          >
            <ChevronLeft size={16} />
          </button>
          <button
            className={`replay-btn replay-btn-play ${playing ? "playing" : ""}`}
            onClick={onTogglePlay}
            title="Lecture / pause (Espace)"
            aria-label={playing ? "Pause" : "Play"}
          >
            {playing ? <Pause size={18} /> : <Play size={18} />}
          </button>
          <button
            className="replay-btn replay-btn-step"
            onClick={() => onStep(1)}
            title="Bougie suivante (→)"
            aria-label="Next candle"
          >
            <ChevronRight size={16} />
          </button>
          <button
            className="replay-btn replay-btn-step"
            onClick={onInstant}
            title="Dérouler jusqu'à la fin"
            aria-label="Skip to end"
          >
            <SkipForward size={16} />
          </button>
        </div>

        <div className="replay-scrubber">
          <span className="replay-time">{formattedTime}</span>
          <input
            type="range"
            min={0}
            max={Math.max(total - 1, 0)}
            step={1}
            value={currentIndex}
            onChange={(e) => onScrub(Number(e.target.value))}
            className="replay-slider"
            aria-label="Timeline"
          />
          <span className="replay-count">
            {Math.min(currentIndex + 1, total)} / {total}
          </span>
        </div>

        <div className="replay-speeds">
          {SPEEDS.map((s) => (
            <button
              key={s}
              className={`replay-btn replay-btn-speed ${speed === s ? "active" : ""}`}
              onClick={() => onSpeed(s)}
              title={`Vitesse ${s}x`}
            >
              {s}x
            </button>
          ))}
          <span className="replay-timer-hint">
            <Timer size={12} /> Space · ← → · ↑ ↓
          </span>
        </div>
      </div>
    </div>
  )
}

