// ─── Score breakdown bar ──────────────────────────────────────────────────────
function ScoreBreakdownBar({ breakdown }: { breakdown: BehavioralResult["scoreBreakdown"] }) {
  if (!breakdown || breakdown.penalties.length === 0) {
