"use client"

import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from "recharts"
import { dayKey } from "@/lib/dates"

interface Trade {
  exitAt: Date | null
  netPnl: number
}

interface DailyPnlChartProps {
  trades: Trade[]
  currency?: string
  timezone?: string
}

export function DailyPnlChart({ trades, currency = "USD", timezone = "UTC" }: DailyPnlChartProps) {
  // Group trades by date (YYYY-MM-DD in the user's timezone)
  const dailyPnlMap = trades.reduce((acc, trade) => {
    if (!trade.exitAt) return acc
    const dateStr = dayKey(new Date(trade.exitAt), timezone)
    acc[dateStr] = (acc[dateStr] || 0) + trade.netPnl
    return acc
  }, {} as Record<string, number>)

  // Convert to array and sort by date
  const data = Object.entries(dailyPnlMap)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([date, pnl]) => ({
      date,
      // Format label for display e.g. "Aug 12"
      displayDate: new Date(date).toLocaleDateString("en-US", { month: "short", day: "numeric" }),
      pnl
    }))

  if (data.length === 0) {
    return (
      <div className="h-full flex items-center justify-center text-[var(--color-gray-500)]">
        No data yet
      </div>
    )
  }

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat("en-US", { style: "currency", currency, minimumFractionDigits: 0 }).format(val)
  }

  return (
    <ResponsiveContainer width="100%" height="100%">
      <BarChart data={data} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
        <defs>
          <linearGradient id="colorProfit" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="var(--color-profit)" stopOpacity={1} />
            <stop offset="100%" stopColor="var(--color-profit)" stopOpacity={0.4} />
          </linearGradient>
          <linearGradient id="colorLoss" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="var(--color-loss)" stopOpacity={1} />
            <stop offset="100%" stopColor="var(--color-loss)" stopOpacity={0.4} />
          </linearGradient>
        </defs>
        <XAxis 
          dataKey="displayDate" 
          tick={{ fontSize: 11, fill: "var(--color-gray-500)" }}
          axisLine={false}
          tickLine={false}
          dy={10}
        />
        <YAxis 
          tickFormatter={(val) => val >= 1000 || val <= -1000 ? `${(val / 1000).toFixed(1)}k` : val}
          tick={{ fontSize: 11, fill: "var(--color-gray-500)" }}
          axisLine={false}
          tickLine={false}
          dx={-10}
        />
        <Tooltip 
          cursor={{ fill: "var(--color-gray-800)", opacity: 0.2 }}
          contentStyle={{ 
            backgroundColor: "var(--color-gray-900)", 
            border: "1px solid var(--color-gray-800)",
            borderRadius: "8px",
            color: "var(--color-gray-100)",
            boxShadow: "0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06)"
          }}
          itemStyle={{ color: "var(--color-gray-100)", fontWeight: 600 }}
          formatter={(value: any) => [formatCurrency(Number(value)), "P&L"]}
          labelStyle={{ color: "var(--color-gray-400)", marginBottom: "0.5rem", fontWeight: 500, fontSize: "0.8rem" }}
        />
        <Bar dataKey="pnl" radius={[4, 4, 0, 0]}>
          {data.map((entry, index) => (
            <Cell key={`cell-${index}`} fill={entry.pnl >= 0 ? "url(#colorProfit)" : "url(#colorLoss)"} />
          ))}
        </Bar>
      </BarChart>
    </ResponsiveContainer>
  )
}

import { prisma } from "@/lib/prisma"
import { auth } from "@/lib/auth"
import { resolveAccountScope } from "@/lib/active-account"
import { DailyPnlChart } from "./LazyCharts"

export async function DailyPnlChartServer({
  dateRange,
  accountId,
}: {
  dateRange?: { from?: Date; to?: Date }
  accountId?: string | null | "all"
}) {
  const session = await auth()
  if (!session?.user?.id) return null

  const scope = await resolveAccountScope(session.user.id, accountId)

  if (scope.accounts.length === 0) return <DailyPnlChart trades={[]} />

  const user = await prisma.user.findUnique({
    where: { id: session.user.id },
    select: { timezone: true },
  })

  const whereClause: any = scope.all
    ? { userId: session.user.id, status: "closed" }
    : { accountId: scope.accounts[0].id, status: "closed" }
  if (dateRange?.from || dateRange?.to) {
    whereClause.entryAt = {}
    if (dateRange.from) whereClause.entryAt.gte = dateRange.from
    if (dateRange.to) whereClause.entryAt.lte = dateRange.to
  }

  const trades = await prisma.trade.findMany({
    where: whereClause,
    select: { entryAt: true, exitAt: true, netPnl: true },
    orderBy: { entryAt: "asc" }
  })

  const serializedTrades = trades.map(t => ({
    exitAt: t.exitAt ?? t.entryAt,
    netPnl: Number(t.netPnl || 0)
  }))

  return <DailyPnlChart trades={serializedTrades} currency={scope.currency} timezone={user?.timezone ?? "UTC"} />
}

"use client"

import { useRouter, useSearchParams, usePathname } from "next/navigation"
import { useState, useEffect, useTransition } from "react"
import { Wallet, Loader2 } from "lucide-react"

type FilterAccount = {
  id: string
  name: string
  isDefault: boolean
}

export function DashboardFilter({ accounts }: { accounts: FilterAccount[] }) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const [isPending, startTransition] = useTransition()

  const [accountId, setAccountId] = useState(searchParams?.get("accountId") || "all")
  const [period, setPeriod] = useState(searchParams?.get("period") || "all")
  const [showCustom, setShowCustom] = useState(period === "custom")
  const [startDate, setStartDate] = useState(searchParams?.get("from") || "")
  const [endDate, setEndDate] = useState(searchParams?.get("to") || "")

  useEffect(() => {
    const current = searchParams?.get("accountId") || "all"
    if (current !== accountId) setAccountId(current)
  }, [searchParams, accountId])

  const pushParams = (updates: Record<string, string | null>) => {
    const params = new URLSearchParams(searchParams as any)
    for (const [k, v] of Object.entries(updates)) {
      if (v === null) params.delete(k)
      else params.set(k, v)
    }
    startTransition(() => {
      router.push(`${pathname}?${params.toString()}`)
      router.refresh()
    })
  }

  const handleAccountChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const val = e.target.value
    setAccountId(val)
    if (val) pushParams({ accountId: val })
    else pushParams({ accountId: null })
  }

  const handlePeriodChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const val = e.target.value
    setPeriod(val)
    if (val === "custom") {
      setShowCustom(true)
    } else {
      setShowCustom(false)
      pushParams({ period: val, from: null, to: null })
    }
  }

  const handleCustomDateApply = () => {
    pushParams({ period: "custom", from: startDate || null, to: endDate || null })
  }

  return (
    <div className="flex flex-wrap items-center gap-2">
      {showCustom && (
        <div className="flex items-center gap-2 bg-[var(--color-gray-900)] border border-[var(--color-gray-800)] px-2 py-1 rounded-lg">
          <input
            type="date"
            className="input w-[130px] h-8 text-xs px-2"
            value={startDate}
            onChange={e => setStartDate(e.target.value)}
          />
          <span className="text-[var(--color-gray-500)] text-xs">to</span>
          <input
            type="date"
            className="input w-[130px] h-8 text-xs px-2"
            value={endDate}
            onChange={e => setEndDate(e.target.value)}
          />
          <button
            type="button"
            className="btn btn-primary h-8 px-3 text-xs"
            onClick={handleCustomDateApply}
            disabled={isPending}
          >
            Apply
          </button>
        </div>
      )}
      {accounts.length > 1 && (
        <div className="flex items-center gap-1.5 relative">
          <Wallet size={14} className="text-[var(--color-gray-500)] absolute left-3 pointer-events-none" />
          <select
            className="input select w-auto pl-8"
            value={accountId}
            onChange={handleAccountChange}
            disabled={isPending}
          >
            <option value="all">All accounts (consolidated)</option>
            <option value="">Active account</option>
            {accounts.map(a => (
              <option key={a.id} value={a.id}>{a.name}{a.isDefault ? " (default)" : ""}</option>
            ))}
          </select>
        </div>
      )}
      <div className="relative flex items-center">
        <select
          className="input select w-auto"
          value={period}
          onChange={handlePeriodChange}
          disabled={isPending}
        >
          <option value="all">All time</option>
          <option value="7d">Last 7 days</option>
          <option value="30d">Last 30 days</option>
          <option value="90d">Last 90 days</option>
          <option value="ytd">Year to date</option>
          <option value="custom">Custom Date...</option>
        </select>
        {isPending && <Loader2 className="absolute right-[-1.5rem] animate-spin text-[var(--color-gray-500)]" size={16} />}
      </div>
    </div>
  )
}

