  const [rawData, setRawData] = useState<EquityData | null>(null)
  const [loading, setLoading] = useState(true)
  const [timeframe, setTimeframe] = useState("ALL")
  const [viewMode, setViewMode] = useState<ViewMode>("balance")

  useEffect(() => {
    if (equityData && equityData.length > 0) {
      const initial = propInitial ?? equityData[0]?.equity ?? 0
      const current = propCurrent ?? equityData[equityData.length - 1]?.equity ?? 0
      const maxDD = equityData.reduce((m, p) => Math.max(m, p.drawdown ?? 0), 0)
      const curDD = equityData.length > 0 ? (equityData[equityData.length - 1].drawdown ?? 0) : 0
      setRawData({ data: equityData, initialBalance: initial, currentBalance: current, maxDrawdown: maxDD, currentDrawdown: curDD })
      setLoading(false)
      return
    }

    if (snapshots && snapshots.length > 0) {
      let runningHigh = propInitial ?? snapshots[0].endBalance
      const points: EquityPoint[] = snapshots.map(s => {
        const anchor = maxDDLevel ?? (propInitial ?? s.endBalance)
        const dd = anchor > 0 ? ((anchor - s.lowestEquity) / anchor) * 100 : 0
        runningHigh = Math.max(runningHigh, s.endBalance)
        return { date: s.date, equity: s.endBalance, drawdown: Math.max(0, dd) }
      })
      const initial = propInitial ?? points[0]?.equity ?? 0
      const current = propCurrent ?? points[points.length - 1]?.equity ?? 0
      const maxDD = points.reduce((m, p) => Math.max(m, p.drawdown ?? 0), 0)
      const curDD = points.length > 0 ? (points[points.length - 1].drawdown ?? 0) : 0
      setRawData({ data: points, initialBalance: initial, currentBalance: current, maxDrawdown: maxDD, currentDrawdown: curDD })
      setLoading(false)
      return
    }

    setLoading(false)
  }, [equityData, snapshots, propInitial, propCurrent, maxDDLevel])

  const filteredData = useMemo(() => {
    if (!rawData?.data.length) return []
    if (timeframe === "ALL") return rawData.data
    const cutoffs: Record<string, number> = { "1W": 7, "1M": 30, "3M": 90, "6M": 180, "1Y": 365 }
    const days = cutoffs[timeframe] || 30
    const cutoff = new Date(Date.now() - days * 86400000)
    return rawData.data.filter((p) => new Date(p.date) >= cutoff)
  }, [rawData, timeframe])

  const chartData = useMemo(() =>
    filteredData.map((p) => ({
      date: p.date,
      Balance: p.equity,
      Drawdown: p.drawdown ?? 0,
    })),
    [filteredData]
  )

  const initialBalance = rawData?.initialBalance ?? 0
  const currentBalance = rawData?.currentBalance ?? 0
  const maxDrawdown = rawData?.maxDrawdown ?? 0
  const currentDrawdown = rawData?.currentDrawdown ?? 0

  const firstBalance = chartData[0]?.Balance ?? initialBalance
  const lastBalance = chartData[chartData.length - 1]?.Balance ?? currentBalance
  const periodChange = lastBalance - firstBalance
  const periodChangePct = firstBalance !== 0 ? ((periodChange / Math.abs(firstBalance)) * 100) : 0
  const isPositive = periodChange >= 0
  const gradColor = isPositive ? "var(--color-profit)" : "var(--color-loss)"

  const minVal = chartData.length ? Math.min(...chartData.map((d) => d.Balance)) * 0.998 : 0
  const maxVal = chartData.length ? Math.max(...chartData.map((d) => d.Balance)) * 1.002 : 0

  const statItems = [
    { label: "Initial Balance", value: formatCurrency(initialBalance), color: "var(--color-gray-200)" },
    { label: "Current Balance", value: formatCurrency(currentBalance), color: currentBalance >= initialBalance ? "var(--color-profit)" : "var(--color-loss)" },
    { label: "Max Drawdown", value: `-${maxDrawdown.toFixed(2)}%`, color: maxDrawdown > 15 ? "var(--color-loss)" : maxDrawdown > 8 ? "var(--color-warning)" : "var(--color-profit)" },
    { label: "Current DD", value: currentDrawdown > 0 ? `-${currentDrawdown.toFixed(2)}%` : "---", color: currentDrawdown > 5 ? "var(--color-warning)" : "var(--color-profit)" },
  ]

  if (loading) {
    return (
      <div className="chart-card">
        <div className="chart-title">Equity Curve</div>
        <div style={{ display: "flex", flexDirection: "column", gap: "0.75rem", padding: "1rem 1.5rem" }}>
          {[95, 70, 88, 55, 80, 65].map((w, i) => (
            <div key={i} className="skeleton" style={{ height: 8, borderRadius: 4, width: `${w}%` }} />
          ))}
        </div>
      </div>
    )
  }

  if (!rawData || chartData.length === 0) {
    return (
      <div className="chart-card">
        <div className="chart-title">Equity Curve</div>
        <div className="empty-state" style={{ padding: "3rem" }}>
          <p style={{ fontSize: "0.85rem" }}>Import or add trades to see your equity curve.</p>
        </div>
      </div>
    )
  }

  return (
    <div className="chart-card" style={{ padding: "1.25rem", display: "flex", flexDirection: "column", flex: 1 }}>
      {/* Header */}
      <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", marginBottom: "1rem" }}>
        <div>
          <div className="chart-title" style={{ marginBottom: "0.25rem" }}>Equity Curve</div>
          {chartData.length > 0 && (
            <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
              <span style={{ fontFamily: "var(--font-mono)", fontWeight: 700, fontSize: "1.1rem", color: "var(--color-gray-100)" }}>
                {formatCurrency(lastBalance)}
              </span>
              <span style={{
                display: "inline-flex", alignItems: "center", gap: "0.15rem",
                fontSize: "0.7rem", fontWeight: 700, padding: "0.15rem 0.5rem", borderRadius: "10px",
                color: isPositive ? "var(--color-profit)" : "var(--color-loss)",
                background: isPositive ? "rgba(16,185,129,0.12)" : "rgba(239,68,68,0.12)",
              }}>
                {isPositive ? "+" : ""}{periodChangePct.toFixed(2)}%
                <span style={{ marginLeft: "0.25rem", fontWeight: 500, opacity: 0.7 }}>({timeframe})</span>
              </span>
            </div>
          )}
        </div>

        <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
          {/* Toggle mode */}
          <div style={{ display: "flex", background: "var(--color-gray-900)", border: "1px solid var(--color-gray-800)", borderRadius: "10px", padding: "2px", gap: "2px" }}>
            <button
              onClick={() => setViewMode("balance")}
              style={{
                display: "flex", alignItems: "center", gap: "0.25rem",
                padding: "0.25rem 0.5rem", borderRadius: "8px", fontSize: "0.7rem", fontWeight: 600,
                border: "none", cursor: "pointer", transition: "all 0.15s",
                background: viewMode === "balance" ? "rgba(16,185,129,0.15)" : "transparent",
                color: viewMode === "balance" ? "var(--color-profit)" : "var(--color-gray-500)",
              }}
            >
              <Activity size={12} /> Balance
            </button>
            <button
              onClick={() => setViewMode("drawdown")}
              style={{
                display: "flex", alignItems: "center", gap: "0.25rem",
                padding: "0.25rem 0.5rem", borderRadius: "8px", fontSize: "0.7rem", fontWeight: 600,
                border: "none", cursor: "pointer", transition: "all 0.15s",
                background: viewMode === "drawdown" ? "rgba(245,158,11,0.15)" : "transparent",
                color: viewMode === "drawdown" ? "var(--color-warning)" : "var(--color-gray-500)",
              }}
            >
              <BarChart2 size={12} /> Drawdown
            </button>
          </div>

          {/* Timeframes */}
          <div style={{ display: "flex", background: "var(--color-gray-900)", border: "1px solid var(--color-gray-800)", borderRadius: "10px", padding: "2px", gap: "2px" }}>
            {TIMEFRAMES.map((tf) => (
              <button
                key={tf}
                onClick={() => setTimeframe(tf)}
                style={{
                  padding: "0.25rem 0.5rem", borderRadius: "8px", fontSize: "0.7rem", fontWeight: 600,
                  border: "none", cursor: "pointer", transition: "all 0.15s",
                  background: timeframe === tf ? "rgba(16,185,129,0.15)" : "transparent",
                  color: timeframe === tf ? "var(--color-profit)" : "var(--color-gray-500)",
                }}
              >
                {tf}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Stats bar */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: "0.5rem", marginBottom: "1rem" }}>
        {statItems.map((s) => (
          <div key={s.label} style={{ background: "var(--color-gray-900)", border: "1px solid var(--color-gray-800)", borderRadius: "10px", padding: "0.5rem 0.75rem" }}>
            <div style={{ fontSize: "0.6rem", color: "var(--color-gray-500)", marginBottom: "0.15rem" }}>{s.label}</div>
            <div style={{ fontSize: "0.85rem", fontWeight: 700, fontFamily: "var(--font-mono)", color: s.color }}>{s.value}</div>
          </div>
        ))}
      </div>

      {/* Chart */}
      <div style={{ height: 300 }}>
        {viewMode === "balance" ? (
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart data={chartData} margin={{ top: 8, right: 4, left: 0, bottom: 0 }}>
              <defs>
                <linearGradient id="equityGrad" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor={isPositive ? "var(--color-profit)" : "var(--color-loss)"} stopOpacity={0.3} />
                  <stop offset="60%" stopColor={isPositive ? "var(--color-profit)" : "var(--color-loss)"} stopOpacity={0.05} />
                  <stop offset="100%" stopColor={isPositive ? "var(--color-profit)" : "var(--color-loss)"} stopOpacity={0} />
                </linearGradient>
                <filter id="glow">
                  <feGaussianBlur stdDeviation="2" result="coloredBlur" />
                  <feMerge>
                    <feMergeNode in="coloredBlur" />
                    <feMergeNode in="SourceGraphic" />
                  </feMerge>
                </filter>
              </defs>
              <CartesianGrid strokeDasharray="3 3" stroke="var(--color-gray-800)" vertical={false} opacity={0.5} />
              <XAxis
                dataKey="date"
                tick={{ fill: "var(--color-gray-500)", fontSize: 10 }}
                axisLine={false}
                tickLine={false}
                tickFormatter={(d) => d ? `${new Date(d).getMonth() + 1}/${new Date(d).getDate()}` : ""}
                interval="preserveStartEnd"
              />
              <YAxis
                domain={[minVal, maxVal]}
                tick={{ fill: "var(--color-gray-500)", fontSize: 10 }}
                axisLine={false}
                tickLine={false}
                width={55}
                tickFormatter={(v) => `$${v >= 1000 ? `${(v / 1000).toFixed(1)}k` : v}`}
              />
              <Tooltip
                content={<CustomTooltip initialBalance={initialBalance} />}
                cursor={{ stroke: "var(--color-gray-700)", strokeWidth: 1, strokeDasharray: "4 2" }}
              />
              {initialBalance > 0 && (
                <ReferenceLine
                  y={initialBalance}
                  stroke={gradColor}
                  strokeDasharray="5 3"
                  strokeWidth={1}
                  strokeOpacity={0.4}
                />
              )}
              {showMaxDDLine && maxDDLevel && maxDDLevel > 0 && (
                <ReferenceLine
                  y={maxDDLevel}
                  stroke="var(--color-loss)"
                  strokeDasharray="4 3"
                  strokeWidth={1}
                  strokeOpacity={0.5}
                  label={{ value: "Max DD", position: "insideTopRight", fill: "var(--color-loss)", fontSize: 9 }}
                />
              )}
              {showTargetLine && profitTarget && profitTarget > 0 && (
                <ReferenceLine
                  y={profitTarget}
                  stroke="var(--color-profit)"
                  strokeDasharray="4 3"
                  strokeWidth={1}
                  strokeOpacity={0.5}
                  label={{ value: "Target", position: "insideTopRight", fill: "var(--color-profit)", fontSize: 9 }}
                />
              )}
              <Area
                type="monotone"
                dataKey="Balance"
                stroke={gradColor}
                strokeWidth={2.5}
                fill="url(#equityGrad)"
                dot={false}
                activeDot={{ r: 5, fill: gradColor, strokeWidth: 2, stroke: "var(--color-gray-900)" }}
                filter="url(#glow)"
              />
            </ComposedChart>
          </ResponsiveContainer>
        ) : (
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={chartData} margin={{ top: 8, right: 4, left: 0, bottom: 0 }}>
              <defs>
                <linearGradient id="ddGrad" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="var(--color-loss)" stopOpacity={0.4} />
                  <stop offset="100%" stopColor="var(--color-loss)" stopOpacity={0.02} />
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" stroke="var(--color-gray-800)" vertical={false} opacity={0.5} />
              <XAxis
                dataKey="date"
                tick={{ fill: "var(--color-gray-500)", fontSize: 10 }}
                axisLine={false}
                tickLine={false}
                tickFormatter={(d) => d ? `${new Date(d).getMonth() + 1}/${new Date(d).getDate()}` : ""}
                interval="preserveStartEnd"
              />
              <YAxis
                reversed
                tick={{ fill: "var(--color-gray-500)", fontSize: 10 }}
                axisLine={false}
                tickLine={false}
                width={45}
                tickFormatter={(v) => `-${v.toFixed(1)}%`}
              />
              <Tooltip
                content={({ active, payload, label }) => {
                  if (!active || !payload?.length) return null
                  const dd = payload[0]?.value ?? 0
                  return (
                    <div style={{
                      background: "var(--color-gray-900)", border: "1px solid var(--color-gray-800)",
                      borderRadius: "8px", padding: "0.75rem", boxShadow: "0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06)", fontSize: "0.75rem",
                    }}>
                      <div style={{ color: "var(--color-gray-500)", marginBottom: "0.35rem" }}>
                        {label ? new Date(label).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }) : ""}
                      </div>
                      <div style={{ fontWeight: 700, fontFamily: "var(--font-mono)", color: "var(--color-warning)" }}>
                        Drawdown: -{(dd as number).toFixed(2)}%
                      </div>
                    </div>
                  )
                }}
                cursor={{ stroke: "var(--color-gray-700)", strokeWidth: 1, strokeDasharray: "4 2" }}
              />
              <ReferenceLine y={5} stroke="var(--color-warning)" strokeDasharray="4 2" strokeWidth={1} opacity={0.5}
                label={{ value: "5%", position: "insideTopRight", fill: "var(--color-warning)", fontSize: 9 }} />
              <ReferenceLine y={10} stroke="var(--color-loss)" strokeDasharray="4 2" strokeWidth={1} opacity={0.5}
                label={{ value: "10%", position: "insideTopRight", fill: "var(--color-loss)", fontSize: 9 }} />
              {maxDrawdownPct && maxDrawdownPct > 0 && (
                <ReferenceLine y={maxDrawdownPct} stroke="var(--color-loss)" strokeDasharray="2 2" strokeWidth={1.5} opacity={0.7}
                  label={{ value: `Max ${maxDrawdownPct.toFixed(0)}%`, position: "insideTopRight", fill: "var(--color-loss)", fontSize: 9 }} />
              )}
              <Area
                type="monotone"
                dataKey="Drawdown"
                stroke="var(--color-loss)"
                strokeWidth={2}
                fill="url(#ddGrad)"
                dot={false}
                activeDot={{ r: 4, fill: "var(--color-loss)", strokeWidth: 2, stroke: "var(--color-gray-900)" }}
              />
            </AreaChart>
          </ResponsiveContainer>
        )}
      </div>

      {/* Footer legend */}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: "0.75rem", paddingTop: "0.75rem", borderTop: "1px solid var(--color-gray-800)", fontSize: "0.7rem" }}>
        <div style={{ display: "flex", alignItems: "center", gap: "1rem" }}>
          <div style={{ display: "flex", alignItems: "center", gap: "0.35rem" }}>
            <div style={{ width: 16, height: 2, borderRadius: 1, background: gradColor }} />
            <span style={{ color: "var(--color-gray-500)" }}>Balance</span>
          </div>
          {initialBalance > 0 && (
            <div style={{ display: "flex", alignItems: "center", gap: "0.35rem" }}>
              <div style={{ width: 16, borderTop: "2px dashed", borderColor: gradColor, opacity: 0.4 }} />
              <span style={{ color: "var(--color-gray-500)" }}>Initial</span>
            </div>
          )}
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: "0.75rem", color: "var(--color-gray-500)" }}>
          <span style={{ display: "flex", alignItems: "center", gap: "0.25rem" }}>
            <span style={{ width: 6, height: 6, borderRadius: "50%", background: "var(--color-loss)", display: "inline-block" }} />
            {chartData.filter(d => d.Balance < 0).length} L
          </span>
        </div>
      </div>
    </div>
  )
})

export function EquityCurveDashboard() {
  const searchParams = useSearchParams()
  const [data, setData] = useState<EquityData | null>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    const controller = new AbortController()
    const params = new URLSearchParams()
    const period = searchParams.get("period")
    const accountId = searchParams.get("accountId")
    const from = searchParams.get("from")
    const to = searchParams.get("to")
    if (period) params.set("period", period)
    if (accountId) params.set("accountId", accountId)
    if (from) params.set("from", from)
    if (to) params.set("to", to)

    const qs = params.toString()
    fetch(`/api/metrics/equity-curve${qs ? `?${qs}` : ""}`, { signal: controller.signal })
      .then((r) => r.json())
      .then((d) => {
        setData({
          data: d.data || [],
          initialBalance: d.initialBalance || 0,
          currentBalance: d.currentBalance || 0,
          maxDrawdown: d.maxDrawdown || 0,
          currentDrawdown: d.currentDrawdown || 0,
        })
        setLoading(false)
      })
      .catch(() => setLoading(false))
    return () => controller.abort()
  }, [searchParams])

  if (loading) {
    return (
      <div className="chart-card">
        <div className="chart-title">Equity Curve</div>
        <div style={{ display: "flex", flexDirection: "column", gap: "0.75rem", padding: "1rem 1.5rem" }}>
          {[95, 70, 88, 55, 80, 65].map((w, i) => (
            <div key={i} className="skeleton" style={{ height: 8, borderRadius: 4, width: `${w}%` }} />
          ))}
        </div>
      </div>
    )
  }

  if (!data || data.data.length === 0) {
    return (
      <div className="chart-card">
        <div className="chart-title">Equity Curve</div>
        <div className="empty-state" style={{ padding: "3rem" }}>
          <p style={{ fontSize: "0.85rem" }}>Import or add trades to see your equity curve.</p>
        </div>
      </div>
    )
  }

  return <EquityCurveChart equityData={data.data} initialBalance={data.initialBalance} currentBalance={data.currentBalance} />
}

"use client"

import { useEffect, useState } from "react"
import { useSearchParams } from "next/navigation"

type HeatmapCell = { day: number; hour: number; pnl: number }

const DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]

export function HourHeatmap() {
  const [data, setData] = useState<HeatmapCell[]>([])
  const [loading, setLoading] = useState(true)
  const [tooltip, setTooltip] = useState<{ x: number; y: number; text: string } | null>(null)
  const searchParams = useSearchParams()

  useEffect(() => {
    setLoading(true)
    const params = new URLSearchParams()
    const period = searchParams.get("period")
    const accountId = searchParams.get("accountId")
    const from = searchParams.get("from")
    const to = searchParams.get("to")
    if (period) params.set("period", period)
    if (accountId) params.set("accountId", accountId)
    if (from) params.set("from", from)
    if (to) params.set("to", to)

    const qs = params.toString()
    fetch(`/api/metrics/charts${qs ? `?${qs}` : ""}`)
      .then((r) => r.json())
      .then((d) => {
        setData(d.heatmapData || [])
        setLoading(false)
      })
      .catch(() => setLoading(false))
  }, [searchParams])

  if (loading) {
    return (
      <div className="chart-card">
        <div className="chart-title">Performance by Hour & Day</div>
        <div className="skeleton" style={{ height: 200 }} />
      </div>
    )
  }

  if (data.length === 0) {
    return (
      <div className="chart-card">
        <div className="chart-title">Performance by Hour & Day</div>
        <div className="empty-state" style={{ padding: "1.5rem", height: 200 }}>
          <p style={{ fontSize: "0.85rem" }}>Import trades to see your most profitable trading hours.</p>
        </div>
      </div>
    )
  }

  const maxAbs = Math.max(1, ...data.map((d) => Math.abs(d.pnl)))

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", minimumFractionDigits: 0 }).format(val)
  }

  const formatHour = (h: number) => `${String(h).padStart(2, "0")}:00`
  const FULL_DAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]

  return (
    <div className="chart-card">
      <div className="chart-title">Performance by Hour & Day</div>

      <div style={{ display: "flex", flexDirection: "column", marginTop: "1rem", gap: "0.5rem" }}>
        <div style={{ display: "grid", gridTemplateColumns: "30px repeat(24, 1fr)", gap: "4px" }}>

          {/* Grid rows for each day (0 = Mon, 6 = Sun) */}
          {DAYS.map((dayLabel, d) => (
            <div key={d} style={{ display: "contents" }}>

              {/* Y Axis Label */}
              <div style={{ 
                fontSize: "0.65rem", 
                color: "var(--color-gray-500)", 
                display: "flex", 
                alignItems: "center",
                justifyContent: "flex-end",
                paddingRight: "6px",
                height: "100%"
              }}>
                {dayLabel}
              </div>

              {/* 24 Hours */}
              {Array.from({ length: 24 }).map((_, h) => {
                const cell = data.find(c => c.day === d && c.hour === h)
                const pnl = cell?.pnl || 0
                const intensity = pnl === 0 ? 0 : Math.max(0.15, Math.abs(pnl) / maxAbs)
                const isProfit = pnl >= 0

                return (
                  <div 
                    key={`${d}-${h}`} 
                    className="heatmap-cell"
                    style={{ 
                      aspectRatio: "1/1",
                      borderRadius: "3px",
                      background: pnl === 0 
                        ? "var(--color-gray-800)" 
                        : isProfit ? "var(--color-profit)" : "var(--color-loss)",
                      opacity: pnl === 0 ? 1 : intensity,
                      position: "relative",
                      cursor: "pointer",
                      transition: "transform 0.1s, opacity 0.1s"
                    }}
                    onMouseEnter={(e) => {
                      const rect = e.currentTarget.getBoundingClientRect()
                      setTooltip({
                        x: rect.left + rect.width / 2,
                        y: rect.top - 8,
                        text: `${FULL_DAYS[d]} ${formatHour(h)}\n${formatCurrency(pnl)}`
                      })
                      e.currentTarget.style.transform = "scale(1.3)"
                      e.currentTarget.style.zIndex = "10"
                    }}
                    onMouseLeave={(e) => {
                      setTooltip(null)
                      e.currentTarget.style.transform = "scale(1)"
                      e.currentTarget.style.zIndex = "1"
                    }}
                  />
                )
              })}
            </div>
          ))}

        </div>

        {/* X Axis Labels */}
        <div style={{ 
          display: "grid", 
          gridTemplateColumns: "30px repeat(24, 1fr)", 
          gap: "4px",
          color: "var(--color-gray-500)", 
          fontSize: "0.65rem",
          marginTop: "4px"
        }}>
          <div /> {/* offset for Y labels */}
          {Array.from({ length: 24 }).map((_, h) => (
            <div key={h} style={{ textAlign: "center" }}>
              {String(h).padStart(2, "0")}H
            </div>
          ))}
        </div>
      </div>

      {/* Legend */}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "flex-end", gap: "0.5rem", marginTop: "1rem", fontSize: "0.68rem", color: "var(--color-gray-500)" }}>
        <span>No trades</span>
        <div style={{ width: 12, height: 12, borderRadius: 2, background: "var(--color-gray-800)" }} />
        <span>Loss</span>
        <div style={{ width: 12, height: 12, borderRadius: 2, background: "var(--color-loss)", opacity: 0.35 }} />
        <div style={{ width: 12, height: 12, borderRadius: 2, background: "var(--color-loss)" }} />
        <span>Profit</span>
        <div style={{ width: 12, height: 12, borderRadius: 2, background: "var(--color-profit)", opacity: 0.35 }} />
        <div style={{ width: 12, height: 12, borderRadius: 2, background: "var(--color-profit)" }} />
      </div>

      {/* Custom Tooltip */}
      {tooltip && (
        <div 
          className="heatmap-tooltip"
          style={{ 
            left: tooltip.x,
            top: tooltip.y,
            transform: "translate(-50%, -100%)"
          }}
        >
          {tooltip.text.split("\n").map((line, i) => (
            <div key={i} style={{ color: i === 1 ? "var(--color-gray-100)" : "var(--color-gray-400)" }}>
              {line}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

// components/dashboard/KpiGrid.tsx
// KPI Cards — Server Component qui lit les métriques depuis l'API

import { computeMetrics } from "@/lib/metrics"
import { prisma } from "@/lib/prisma"
import { auth } from "@/lib/auth"
import { resolveAccountScope } from "@/lib/active-account"
import { formatCurrency } from "@/lib/formatters"
import type { Trade } from "@prisma/client"
import { getTranslations } from "next-intl/server"

import { Activity, Target, Lightbulb, TrendingUp, AlertTriangle, List } from "lucide-react"

// ... existing code in KpiGrid ...
export async function KpiGrid({
  dateRange,
  accountId,
}: {
  dateRange?: { from?: Date; to?: Date }
  accountId?: string | null | "all"
}) {
  const session = await auth()
  if (!session?.user?.id) return null

  // Récupérer les trades du compte (sélectionné, consolidé, ou par défaut)
  const scope = await resolveAccountScope(session.user.id, accountId)

  const t = await getTranslations("KpiGrid")

  if (scope.accounts.length === 0) {
    return (
      <div style={{ display: "flex", gap: "1rem", flexWrap: "wrap", width: "100%", marginBottom: "1.5rem" }}>
        <EmptyKpiCard label={t("netPnl")} icon={<Activity size={16} />} noDataLabel={t("noData")} />
        <EmptyKpiCard label={t("winRate")} icon={<Target size={16} />} noDataLabel={t("noData")} />
        <EmptyKpiCard label={t("expectancy")} icon={<Lightbulb size={16} />} noDataLabel={t("noData")} />
        <EmptyKpiCard label={t("profitFactor")} icon={<TrendingUp size={16} />} noDataLabel={t("noData")} />
        <EmptyKpiCard label={t("maxDrawdown")} icon={<AlertTriangle size={16} />} noDataLabel={t("noData")} />
        <EmptyKpiCard label={t("totalTrades")} icon={<List size={16} />} noDataLabel={t("noData")} />
      </div>
    )
  }

  const whereClause: any = scope.all
    ? { userId: session.user.id, status: "closed" }
    : { accountId: scope.accounts[0].id, status: "closed" }
  if (dateRange?.from || dateRange?.to) {
    whereClause.entryAt = {}
    if (dateRange.from) whereClause.entryAt.gte = dateRange.from
    if (dateRange.to) whereClause.entryAt.lte = dateRange.to
  }

  const trades = await prisma.trade.findMany({
    where: whereClause,
    select: {
      status: true,
      netPnl: true,
      riskAmount: true,
      entryAt: true,
      exitAt: true,
      setupTags: true,
    },
    orderBy: { entryAt: "desc" },
  })

  const user = await prisma.user.findUnique({
    where: { id: session.user.id },
    select: { timezone: true },
  })

  const metrics = computeMetrics(trades as Trade[], scope.baseBalance, user?.timezone ?? "UTC")
  const currency = scope.currency

  return (
    <div style={{ display: "flex", gap: "1rem", flexWrap: "wrap", width: "100%", marginBottom: "1.5rem" }}>
      <KpiCard
        label={t("netPnl")}
        value={formatCurrency(metrics.netPnl, currency)}
        sub={t("closedTrades", { count: trades.length })}
        type={metrics.netPnl >= 0 ? "profit" : "loss"}
        id="kpi-net-pnl"
        icon={<Activity size={16} />}
        size="large"
      />
      <KpiCard
        label={t("winRate")}
        value={`${(metrics.winRate * 100).toFixed(1)}%`}
        sub={`${metrics.winningTrades}W / ${metrics.losingTrades}L`}
        type={metrics.winRate >= 0.5 ? "profit" : "loss"}
        id="kpi-win-rate"
        icon={<Target size={16} />}
      />
      <KpiCard
        label={t("expectancy")}
        value={formatCurrency(metrics.expectancy, currency)}
        sub={t("perTrade")}
        type={metrics.expectancy >= 0 ? "profit" : "loss"}
        id="kpi-expectancy"
        icon={<Lightbulb size={16} />}
      />
      <KpiCard
        label={t("profitFactor")}
        value={metrics.profitFactor === Infinity ? "∞" : metrics.profitFactor.toFixed(2)}
        sub={t("grossProfit", { amount: formatCurrency(metrics.grossProfit, currency) })}
        type={metrics.profitFactor >= 1 ? "profit" : "loss"}
        id="kpi-profit-factor"
        icon={<TrendingUp size={16} />}
      />
      <KpiCard
        label={t("maxDrawdown")}
        value={`${metrics.maxDrawdownPct.toFixed(1)}%`}
        sub={formatCurrency(metrics.maxDrawdown, currency)}
        type={metrics.maxDrawdownPct > 10 ? "loss" : "neutral"}
        id="kpi-max-drawdown"
        icon={<AlertTriangle size={16} />}
      />
      <KpiCard
        label={t("totalTrades")}
        value={`${trades.length}`}
        sub={`${metrics.winningTrades}W / ${metrics.losingTrades}L`}
        type="neutral"
        id="kpi-total-trades"
        icon={<List size={16} />}
      />
    </div>
  )
}

// ─── KPI Card Component ───────────────────────────────────────────────────────
function KpiCard({
  label, value, sub, type = "neutral", id, icon, size = "normal"
}: {
  label: string
  value: string
  sub?: string
  type?: "profit" | "loss" | "neutral"
  id: string
  icon?: React.ReactNode
  size?: "normal" | "large"
}) {
  const color = type === "profit" ? "var(--color-profit)" : type === "loss" ? "var(--color-loss)" : "var(--color-gray-100)"

  return (
    <div className="chart-card" id={id} style={{ padding: "1.1rem 1.25rem", flex: "1 1 180px", display: "flex", flexDirection: "column", justifyContent: "center", gap: "0.35rem" }}>
      <div style={{ display: "flex", alignItems: "center", gap: "0.35rem", fontSize: "0.75rem", color: "var(--color-gray-500)", textTransform: "uppercase", fontWeight: 700, letterSpacing: "0.05em" }}>
        {icon && <span style={{ opacity: 0.7 }}>{icon}</span>}
        {label}
      </div>
      <div style={{ fontSize: size === "large" ? "1.6rem" : "1.2rem", fontWeight: 700, color, fontVariantNumeric: "tabular-nums" }}>{value}</div>
      {sub && <div style={{ fontSize: "0.75rem", color: "var(--color-gray-500)", fontWeight: 500 }}>{sub}</div>}
    </div>
  )
}

function EmptyKpiCard({ label, icon, noDataLabel = "No data yet" }: { label: string, icon?: React.ReactNode, noDataLabel?: string }) {
  return (
    <div className="chart-card" style={{ padding: "1.1rem 1.25rem", flex: "1 1 180px", display: "flex", flexDirection: "column", justifyContent: "center", gap: "0.35rem" }}>
      <div style={{ display: "flex", alignItems: "center", gap: "0.35rem", fontSize: "0.75rem", color: "var(--color-gray-500)", textTransform: "uppercase", fontWeight: 700, letterSpacing: "0.05em" }}>
        {icon && <span style={{ opacity: 0.7 }}>{icon}</span>}
        {label}
      </div>
      <div style={{ fontSize: "1.2rem", fontWeight: 700, color: "var(--color-gray-700)", fontVariantNumeric: "tabular-nums" }}>—</div>
      <div style={{ fontSize: "0.75rem", color: "var(--color-gray-500)", fontWeight: 500 }}>{noDataLabel}</div>
    </div>
  )
}

