function GaugeChart({ score }: { score: number }) {
  const clampedScore = Math.max(-100, Math.min(100, score))
  const angle = (clampedScore / 100) * 90

  return (
    <div style={{ position: "relative", width: 140, height: 84, margin: "0 auto", display: "flex", alignItems: "flex-end", justifyContent: "center", overflow: "hidden" }}>
      <div style={{ position: "absolute", bottom: 4, fontWeight: 700, fontSize: "1.5rem", letterSpacing: "-0.05em", color: "var(--color-gray-200)", zIndex: 0 }}>
        {score > 0 ? "+" : ""}{score}
      </div>
      <svg viewBox="0 0 200 100" style={{ width: "100%", height: "100%", position: "absolute", bottom: 0, zIndex: 10, pointerEvents: "none" }}>
        <path d="M 20 100 A 80 80 0 0 1 180 100" fill="none" stroke="var(--color-gray-700)" strokeWidth="20" strokeLinecap="round" />
        <defs>
          <linearGradient id="gaugeGrad" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="#EF4444" />
            <stop offset="50%" stopColor="#9CA3AF" />
            <stop offset="100%" stopColor="#00c758" />
          </linearGradient>
          <linearGradient id="needleGrad" x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stopColor="#3B82F6" />
            <stop offset="100%" stopColor="#1D4ED8" />
          </linearGradient>
        </defs>
        <path d="M 20 100 A 80 80 0 0 1 180 100" fill="none" stroke="url(#gaugeGrad)" strokeWidth="20" strokeLinecap="round" strokeDasharray="2 6" />
        <g style={{ transformOrigin: "100px 100px", transform: `rotate(${angle}deg)`, transition: "transform 1s cubic-bezier(0.4, 0, 0.2, 1)" }}>
          <polygon points="96,100 104,100 100,30" fill="url(#needleGrad)" />
        </g>
        <circle cx="100" cy="100" r="6" fill="var(--color-brand-500)" />
      </svg>
    </div>
  )
}

function SymbolCard({ data }: { data: SymbolData }) {
  const signalClass = data.signal === "BUY" ? "badge-profit" : data.signal === "SELL" ? "badge-loss" : "badge-neutral"
  const trendColor = data.trend === "BULLISH" ? "var(--color-profit)" : data.trend === "BEARISH" ? "var(--color-loss)" : "var(--color-gray-400)"
  const changeColor = data.change >= 0 ? "var(--color-profit)" : "var(--color-loss)"

  return (
    <div className="card card-hover" style={{ display: "flex", flexDirection: "column", alignItems: "center", padding: "1.25rem" }}>
      <div style={{ display: "flex", width: "100%", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 12 }}>
        <div>
          <div style={{ fontWeight: 700, fontSize: "1rem", color: "var(--color-gray-200)", letterSpacing: "0.05em", marginBottom: 2 }}>{data.symbol}</div>
          <div style={{ fontSize: "0.65rem", color: "var(--color-gray-500)", textTransform: "uppercase", letterSpacing: "0.08em" }}>{data.name}</div>
        </div>
        <div style={{ textAlign: "right" }}>
          <div style={{ fontSize: "0.95rem", fontWeight: 700, color: "var(--color-gray-200)", fontVariantNumeric: "tabular-nums" }}>{data.price}</div>
          <div style={{ fontSize: "0.7rem", fontWeight: 600, color: changeColor, fontVariantNumeric: "tabular-nums" }}>
            {data.change > 0 ? "+" : ""}{data.change}%
          </div>
        </div>
      </div>

      <div style={{ width: "100%", height: 40, marginBottom: 16 }}>
        <ResponsiveContainer width="100%" height="100%">
          <LineChart data={data.history}>
            <YAxis domain={["dataMin", "dataMax"]} hide />
            <Line 
              type="monotone" 
              dataKey="value" 
              stroke={changeColor} 
              strokeWidth={2} 
              dot={false} 
              isAnimationActive={false}
            />
          </LineChart>
        </ResponsiveContainer>
      </div>

      <span className={`badge ${signalClass}`} style={{ marginBottom: 20, fontSize: "0.6rem", padding: "4px 14px" }}>
        {data.signal}
      </span>

      <GaugeChart score={data.score} />

      <div style={{ display: "flex", width: "100%", justifyContent: "space-between", marginTop: 20, padding: "0 8px", textAlign: "center" }}>
        {(["short", "medium", "long"] as const).map(k => (
          <div key={k} style={{ display: "flex", flexDirection: "column" }}>
            <span style={{ fontSize: "0.6rem", color: "var(--color-gray-500)", textTransform: "uppercase", letterSpacing: "0.08em", marginBottom: 3 }}>{k}</span>
            <span style={{ fontSize: "0.8rem", fontWeight: 700, color: data[k] >= 0 ? "var(--color-profit)" : "var(--color-loss)" }}>
              {data[k] > 0 ? "+" : ""}{data[k]}
            </span>
          </div>
        ))}
      </div>

      <div style={{ width: "100%", height: 1, background: "var(--color-gray-800)", margin: "14px 0" }} />

      <div style={{ fontSize: "0.65rem", fontWeight: 700, letterSpacing: "0.08em", color: "var(--color-gray-500)", textTransform: "uppercase" }}>
        Trend <span style={{ color: trendColor }}>{data.trend}</span>
      </div>
    </div>
  )
}

export function MarketOverview() {
  const [time, setTime] = useState("")
  const [selectedSymbols, setSelectedSymbols] = useState<string[]>(["EURUSD", "GBPJPY", "NAS100", "XAUUSD"])
  const [isModalOpen, setIsModalOpen] = useState(false)
  const [allData, setAllData] = useState<SymbolData[]>(AVAILABLE_SYMBOLS)
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    const saved = localStorage.getItem("market_overview_symbols")
    if (saved) {
      try { setSelectedSymbols(JSON.parse(saved)) } catch {}
    }
  }, [])

  useEffect(() => {
    setTime(new Date().toLocaleTimeString("en-US", { hour12: false }))
    const interval = setInterval(() => setTime(new Date().toLocaleTimeString("en-US", { hour12: false })), 1000)
    return () => clearInterval(interval)
  }, [])

  const fetchRealData = async () => {
    try {
      setLoading(true)
      // Yahoo finance symbols corresponding to the hardcoded list
      const yahooSymbols = ["EURUSD=X", "GBPJPY=X", "^NDX", "GC=F", "BTC-USD", "^DJI", "ETH-USD", "JPY=X"]
      const res = await fetch(`/api/market-quotes?symbols=${encodeURIComponent(yahooSymbols.join(","))}`)
      if (!res.ok) throw new Error("Failed to fetch")
      const result = await res.json()
      const quotes = result.quotes || []

      const updatedData = AVAILABLE_SYMBOLS.map((item, i) => {
        const quote = quotes[i]
        if (!quote) return item

        const price = quote.last ? (quote.last > 1000 ? quote.last.toFixed(1) : quote.last.toFixed(4)) : item.price
        const change = quote.changePct !== null ? Number(quote.changePct.toFixed(2)) : item.change

        const trend = change > 0.5 ? "BULLISH" : change < -0.5 ? "BEARISH" : "NEUTRAL"
        const signal = change > 0.5 ? "BUY" : change < -0.5 ? "SELL" : "NEUTRAL"

        const baseScore = Math.max(-100, Math.min(100, change * 40))
        const score = Number(baseScore.toFixed(1))
        const short = Math.max(-100, Math.min(100, Math.round(score + (Math.random() * 40 - 20))))
        const medium = Math.max(-100, Math.min(100, Math.round(score * 0.8 + (Math.random() * 30 - 15))))
        const long = Math.max(-100, Math.min(100, Math.round(score * 0.5 + (Math.random() * 20 - 10))))

        return {
          ...item,
          price: String(price),
          change: change,
          trend: trend as any,
          signal: signal as any,
          score,
          short,
          medium,
          long,
        }
      })
      setAllData(updatedData)
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchRealData()
    const interval = setInterval(fetchRealData, 60000)
    return () => clearInterval(interval)
  }, [])

  const saveSymbols = (symbols: string[]) => {
    setSelectedSymbols(symbols)
    localStorage.setItem("market_overview_symbols", JSON.stringify(symbols))
  }

  const displayedSymbols = allData.filter(s => selectedSymbols.includes(s.symbol))

  return (
    <div style={{ padding: "1.25rem" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16, flexWrap: "wrap", gap: 12 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <span style={{ fontSize: "1rem" }}>&#128202;</span>
          <h2 style={{ fontSize: "1rem", fontWeight: 600, color: "var(--color-gray-200)" }}>Market Overview</h2>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <button onClick={() => setIsModalOpen(true)} style={{ padding: 6, borderRadius: 8, background: "transparent", border: "none", color: "var(--color-gray-400)", cursor: "pointer" }}>
            <Settings size={14} />
          </button>
          <button onClick={fetchRealData} disabled={loading} style={{ padding: 6, borderRadius: 8, background: "transparent", border: "none", color: "var(--color-gray-400)", cursor: "pointer" }}>
            <RefreshCcw size={14} className={loading ? "animate-spin" : ""} />
          </button>
        </div>
      </div>

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
        <p style={{ fontSize: "0.75rem", color: "var(--color-gray-500)" }}>Last update <span style={{ fontFamily: "var(--font-mono)" }}>{time}</span></p>
        <p style={{ fontSize: "0.75rem", fontWeight: 600, color: "var(--color-profit)" }}>{displayedSymbols.length} symbols</p>
      </div>

      {displayedSymbols.length === 0 ? (
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: "2rem", border: "1px dashed var(--color-gray-700)", borderRadius: 8 }}>
          <p style={{ color: "var(--color-gray-400)", marginBottom: 12, fontSize: "0.85rem" }}>No assets configured</p>
          <button onClick={() => setIsModalOpen(true)} className="btn btn-primary" style={{ fontSize: "0.75rem" }}>
            Configure Assets
          </button>
        </div>
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: "1rem" }}>
          {displayedSymbols.map(item => (
            <SymbolCard key={item.symbol} data={item} />
          ))}
        </div>
      )}

      {isModalOpen && (
        <div style={{ position: "fixed", inset: 0, zIndex: 50, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }}>
          <div onClick={() => setIsModalOpen(false)} style={{ position: "absolute", inset: 0, background: "rgba(0,0,0,0.5)" }} />
          <div className="chart-card" style={{ position: "relative", width: "100%", maxWidth: 440, padding: "1.5rem", zIndex: 10 }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <Settings size={16} style={{ color: "var(--color-brand-500)" }} />
                <h3 style={{ fontSize: "1rem", fontWeight: 600, color: "var(--color-gray-200)" }}>Configure Symbols</h3>
              </div>
              <button onClick={() => setIsModalOpen(false)} style={{ padding: 4, borderRadius: 6, background: "transparent", border: "none", color: "var(--color-gray-400)", cursor: "pointer" }}>
                <X size={16} />
              </button>
            </div>

            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, maxHeight: 240, overflowY: "auto", marginBottom: 16 }}>
              {allData.map(sym => {
                const isChecked = selectedSymbols.includes(sym.symbol)
                return (
                  <button key={sym.symbol} onClick={() => saveSymbols(isChecked ? selectedSymbols.filter(s => s !== sym.symbol) : [...selectedSymbols, sym.symbol])}
                    style={{
                      display: "flex", alignItems: "center", justifyContent: "space-between", padding: 10,
                      borderRadius: 8, border: `1px solid ${isChecked ? "var(--color-brand-500)" : "var(--color-gray-700)"}`,
                      background: isChecked ? "var(--color-profit-muted)" : "var(--color-gray-950)",
                      color: isChecked ? "var(--color-gray-200)" : "var(--color-gray-400)", cursor: "pointer", textAlign: "left",
                    }}>
                    <div>
                      <div style={{ fontSize: "0.8rem", fontWeight: 600 }}>{sym.symbol}</div>
                      <div style={{ fontSize: "0.6rem", opacity: 0.7 }}>{sym.name}</div>
                    </div>
                    <div style={{
                      width: 18, height: 18, borderRadius: 4, border: `1px solid ${isChecked ? "var(--color-brand-500)" : "var(--color-gray-600)"}`,
                      background: isChecked ? "var(--color-brand-500)" : "transparent",
                      display: "flex", alignItems: "center", justifyContent: "center",
                    }}>
                      {isChecked && <Check size={12} style={{ color: "white", strokeWidth: 3 }} />}
                    </div>
                  </button>
                )
              })}
            </div>

            <div style={{ display: "flex", gap: 8, justifyContent: "flex-end", borderTop: "1px solid var(--color-gray-800)", paddingTop: 12 }}>
              <button onClick={() => saveSymbols(AVAILABLE_SYMBOLS.map(s => s.symbol))} className="btn btn-outline" style={{ fontSize: "0.7rem", padding: "4px 10px" }}>Select All</button>
              <button onClick={() => saveSymbols([])} className="btn btn-outline" style={{ fontSize: "0.7rem", padding: "4px 10px" }}>Clear All</button>
              <div style={{ flex: 1 }} />
              <button onClick={() => setIsModalOpen(false)} className="btn btn-primary" style={{ fontSize: "0.8rem" }}>Done</button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

"use client"

import { useState, useEffect } from "react"
import { ChevronLeft, ChevronRight } from "lucide-react"
import { useRouter } from "next/navigation"
import { useTheme } from "@/components/ThemeProvider"
import { formatCurrency } from "@/lib/formatters"
import { useTranslations, useLocale } from "next-intl"

export function MiniCalendar({ dailyPnl, dailyTradeCount = {} }: { dailyPnl: Record<string, number>; dailyTradeCount?: Record<string, number> }) {
  const [currentDate, setCurrentDate] = useState(() => new Date())
  const [mounted, setMounted] = useState(false)
  const router = useRouter()
  const { resolvedTheme } = useTheme()
  const t = useTranslations("MiniCalendar")
  const locale = useLocale()

  useEffect(() => {
    setMounted(true)
  }, [])

  const isDark = mounted && resolvedTheme === "dark"

  if (!mounted) {
    return <div style={{ padding: "0.5rem", minHeight: "350px", background: "transparent" }} />
  }

  const year = currentDate.getFullYear()
  const month = currentDate.getMonth()

  const firstDay = new Date(year, month, 1)
  const lastDay = new Date(year, month + 1, 0)
  const daysInMonth = lastDay.getDate()
  const startDow = firstDay.getDay()

  const monthName = new Intl.DateTimeFormat(locale, { month: "long" }).format(firstDay)

  // Get short weekday names dynamically
  const dayNames = Array.from({ length: 7 }, (_, i) => {
    // Jan 1 2023 was a Sunday. So Jan 1 2023 + i days gives the correct weekday order starting from Sunday.
    const d = new Date(2023, 0, 1 + i)
    return new Intl.DateTimeFormat(locale, { weekday: "short" }).format(d)
  })

  const todayStr = (() => {
    const d = new Date()
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`
  })()

  const cells: ({ key: string; day: number; pnl: number; trades: number; isToday: boolean } | null)[] = []
  for (let i = 0; i < startDow; i++) cells.push(null)
  for (let d = 1; d <= daysInMonth; d++) {
    const key = `${year}-${String(month + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`
    cells.push({ key, day: d, pnl: dailyPnl[key] ?? 0, trades: dailyTradeCount[key] ?? 0, isToday: key === todayStr })
  }

  const monthPnl = cells.reduce((sum, c) => c ? sum + c.pnl : sum, 0)
  const greenDays = cells.filter(c => c && c.pnl > 0).length
  const redDays = cells.filter(c => c && c.pnl < 0).length
  const tradingDays = cells.filter(c => c && c.pnl !== 0).length

  const colors = isDark
    ? {
        profitBg: "rgba(16,185,129,0.12)",
        profitBorder: "rgba(16,185,129,0.3)",
        profitText: "var(--color-profit)",
        lossBg: "rgba(239,68,68,0.12)",
        lossBorder: "rgba(239,68,68,0.3)",
        lossText: "var(--color-loss)",
      }
    : {
        profitBg: "rgba(16,185,129,0.1)",
        profitBorder: "rgba(16,185,129,0.25)",
        profitText: "#065f46",
        lossBg: "rgba(239,68,68,0.1)",
        lossBorder: "rgba(239,68,68,0.25)",
        lossText: "#991b1b",
      }

  return (
    <div style={{ padding: "0.5rem" }}>
      {/* Header */}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: "1rem" }}>
        <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
          <button
            onClick={() => setCurrentDate(new Date(year, month - 1, 1))}
            className="btn btn-secondary"
            style={{ padding: "0.35rem 0.6rem", display: "flex", alignItems: "center" }}
          >
            <ChevronLeft size={14} />
          </button>
          <span style={{ fontSize: "1rem", fontWeight: 700, color: "var(--color-gray-100)", minWidth: 140, textAlign: "center", textTransform: "capitalize" }}>
            {monthName} {year}
          </span>
          <button
            onClick={() => setCurrentDate(new Date(year, month + 1, 1))}
            className="btn btn-secondary"
            style={{ padding: "0.35rem 0.6rem", display: "flex", alignItems: "center" }}
          >
            <ChevronRight size={14} />
          </button>
        </div>

        {/* Legend */}
        <div style={{ display: "flex", alignItems: "center", gap: "0.75rem", fontSize: "0.65rem", color: "var(--color-gray-500)" }}>
          <span style={{ display: "flex", alignItems: "center", gap: "0.25rem" }}>
            <span style={{ width: 10, height: 10, borderRadius: 2, background: colors.profitBg, border: `1px solid ${colors.profitBorder}`, display: "inline-block" }} /> {t("profit")}
          </span>
          <span style={{ display: "flex", alignItems: "center", gap: "0.25rem" }}>
            <span style={{ width: 10, height: 10, borderRadius: 2, background: colors.lossBg, border: `1px solid ${colors.lossBorder}`, display: "inline-block" }} /> {t("loss")}
          </span>
          <span style={{ display: "flex", alignItems: "center", gap: "0.25rem" }}>
            <span style={{ width: 10, height: 10, borderRadius: 2, background: "var(--color-gray-200)", border: "1px solid var(--color-gray-300)", display: "inline-block" }} /> {t("noTrades")}
          </span>
          <span style={{ display: "flex", alignItems: "center", gap: "0.25rem" }}>
            <span style={{ width: 10, height: 10, borderRadius: 2, border: "2px solid var(--color-brand-500)", display: "inline-block" }} /> {t("today")}
          </span>
        </div>
      </div>

      {/* Day headers */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: "0.4rem", marginBottom: "0.4rem" }}>
        {dayNames.map((d, i) => (
          <div key={i} style={{ textAlign: "center", fontSize: "0.7rem", fontWeight: 600, color: "var(--color-gray-500)", padding: "0.4rem 0", textTransform: "capitalize" }}>
            {d}
          </div>
        ))}
      </div>

      {/* Grid */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: "0.4rem" }}>
        {cells.map((cell, i) => {
          if (!cell) return <div key={`e${i}`} />
          const hasTrades = cell.pnl !== 0
          let bgColor = "var(--color-gray-900)"
          let borderColor = "var(--color-gray-800)"
          let textColor = "var(--color-gray-500)"

          if (cell.pnl > 0) {
            bgColor = colors.profitBg
            borderColor = colors.profitBorder
            textColor = colors.profitText
          } else if (cell.pnl < 0) {
            bgColor = colors.lossBg
            borderColor = colors.lossBorder
            textColor = colors.lossText
          }

          return (
            <div
              key={cell.key}
              onClick={() => router.push(`/calendar`)}
              className="calendar-cell"
              style={{
                background: bgColor,
                border: cell.isToday ? "2px solid var(--color-brand-500)" : `1px solid ${borderColor}`,
                borderRadius: "6px",
                minHeight: "72px",
                padding: "0.5rem 0.6rem",
                display: "flex",
                flexDirection: "column",
                justifyContent: "space-between",
              }}
            >
              <span style={{ fontSize: "0.8rem", fontWeight: 600, color: cell.isToday ? "var(--color-brand-400)" : "var(--color-gray-500)", textAlign: "right" }}>
                {cell.day}
              </span>
              {hasTrades ? (
                <>
                  <span style={{ fontSize: "0.78rem", fontWeight: 700, color: textColor, textAlign: "center", textShadow: isDark ? "0 1px 6px rgba(0,0,0,0.4)" : "none" }}>
                    {formatCurrency(cell.pnl, "USD", true, 2)}
                  </span>
                  <span style={{ fontSize: "0.65rem", color: textColor, opacity: 0.7, textAlign: "center" }}>
                    {t("tradesCount", { count: cell.trades })}
                  </span>
                </>
              ) : (
                <span style={{ fontSize: "0.7rem", color: "var(--color-gray-400)", textAlign: "center" }}>—</span>
              )}
            </div>
          )
        })}
      </div>

      {/* Summary */}
      {tradingDays > 0 && (
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: "0.75rem", padding: "0.5rem 0.75rem", background: "var(--color-gray-900)", borderRadius: "var(--radius-card)", border: "1px solid var(--color-gray-800)", fontSize: "0.7rem" }}>
          <span style={{ color: "var(--color-profit)", fontWeight: 600 }}>{greenDays} {t("greenDays")}</span>
          <span style={{ color: "var(--color-gray-500)" }}>{tradingDays} {t("tradingDays")}</span>
          <span style={{ color: monthPnl >= 0 ? "var(--color-profit)" : "var(--color-loss)", fontWeight: 700, fontSize: "0.8rem" }}>
            {formatCurrency(monthPnl, "USD", true, 2)}
          </span>
          <span style={{ color: "var(--color-gray-500)" }}>{Math.round((greenDays / Math.max(tradingDays, 1)) * 100)}{t("winDays")}</span>
          <span style={{ color: "var(--color-loss)", fontWeight: 600 }}>{redDays} {t("redDays")}</span>
        </div>
      )}
    </div>
  )
}

"use client"

import { useRouter } from "next/navigation"

export function PropChallengesOverview({ challenges }: { challenges: any[] }) {
  const router = useRouter()
  const now = Date.now()

  if (challenges.length === 0) return null

  return (
    <div className="chart-card" style={{ marginBottom: "1rem" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1rem" }}>
        <div className="chart-title" style={{ margin: 0 }}>Prop Challenges</div>
        <button
          onClick={() => router.push("/challenges")}
          className="btn btn-outline"
          style={{ padding: "0.35rem 0.75rem", fontSize: "0.8rem" }}
        >
          View all
        </button>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))", gap: "0.75rem" }}>
        {challenges.map(c => {
          const maxDdRef = c.template.drawdownType === 'static_balance' ? Number(c.initialBalance) :
                           c.template.drawdownType === 'trailing_balance' ? Number(c.highestBalance) :
                           Number(c.highestEquity)
          const maxDdThreshold = maxDdRef * (1 - Number(c.maxDDPct) / 100)
          const maxDdAllowed = maxDdRef - maxDdThreshold
          const maxDdUsed = Math.max(0, maxDdRef - Number(c.currentEquity))
          const ddPct = maxDdAllowed > 0 ? Math.min((maxDdUsed / maxDdAllowed) * 100, 100) : 0

          const profitTarget = Number(c.initialBalance) * (Number(c.profitTargetPct) / 100)
          const currentProfit = Number(c.currentEquity) - Number(c.initialBalance)
          const profitPct = profitTarget > 0 ? Math.min(Math.max((currentProfit / profitTarget) * 100, 0), 100) : 0
          const profitSign = currentProfit >= 0 ? "+" : ""

          const minDays = Number(c.minTradingDays || 0)
          const daysDone = Math.min(Number(c.tradingDaysCount || 0), Math.max(minDays, 1))
          const daysPct = minDays > 0 ? Math.min((daysDone / minDays) * 100, 100) : 100

          let deadlineLabel: string | null = null
          let deadlineTone = "var(--color-gray-500)"
          if (c.deadlineAt) {
            const rem = Math.ceil((new Date(c.deadlineAt).getTime() - now) / 86400000)
            if (c.status === "active") {
              deadlineLabel = rem <= 0 ? "Due today" : `${rem}d left`
              deadlineTone = rem <= 1 ? "var(--color-loss)" : rem <= 5 ? "var(--color-warning)" : "var(--color-gray-500)"
            }
          }

          const latestEvent = Array.isArray(c.events) && c.events.length > 0 ? c.events[0] : null

          return (
            <div
              key={c.id}
              onClick={() => router.push(`/challenges/${c.id}`)}
              style={{
                background: "var(--color-gray-900)", border: "1px solid var(--color-gray-800)",
                borderRadius: "var(--radius-card)", padding: "1rem", cursor: "pointer",
                transition: "border-color 0.2s ease",
                display: "flex", flexDirection: "column", gap: "0.6rem",
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: "0.5rem" }}>
                <div style={{ display: "flex", alignItems: "center", gap: "0.5rem", minWidth: 0 }}>
                  {c.template?.logoUrl && (
                    <div style={{
                      width: "28px", height: "28px", borderRadius: "6px", flexShrink: 0,
                      background: "var(--color-gray-800)", border: "1px solid var(--color-gray-700)",
                      display: "flex", alignItems: "center", justifyContent: "center", overflow: "hidden",
                    }}>
                      {/* eslint-disable-next-line @next/next/no-img-element */}
                      <img src={c.template.logoUrl} alt={c.template.firmName} style={{ maxWidth: "100%", maxHeight: "100%", objectFit: "contain" }} />
                    </div>
                  )}
                  <div style={{ minWidth: 0 }}>
                    <div style={{ fontSize: "0.9rem", fontWeight: 600, color: "var(--color-gray-100)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                      {c.account.name}
                    </div>
                    <div style={{ fontSize: "0.7rem", color: "var(--color-gray-500)" }}>
                      {c.phase === 'phase_1' ? "Phase 1" : c.phase === 'phase_2' ? "Phase 2" : "Funded"}
                      {c.template.firmName ? ` · ${c.template.firmName}` : ""}
                    </div>
                  </div>
                </div>
                <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: "0.25rem", flexShrink: 0 }}>
                  <span className={`badge ${c.status === 'active' || c.status === 'passed' ? 'badge-profit' : 'badge-loss'}`} style={{ fontSize: "0.6rem" }}>
                    {c.status.toUpperCase()}
                  </span>
                  {deadlineLabel && (
                    <span style={{ fontSize: "0.62rem", fontWeight: 600, color: deadlineTone }}>{deadlineLabel}</span>
                  )}
                </div>
              </div>

              <div>
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: "0.68rem", color: "var(--color-gray-400)", marginBottom: "0.25rem" }}>
                  <span>Profit Target</span>
                  <span style={{ color: currentProfit >= 0 ? "var(--color-profit)" : "var(--color-loss)" }}>
                    {profitSign}{currentProfit.toLocaleString("en-US", { maximumFractionDigits: 0 })} · {Math.round(profitPct)}%
                  </span>
                </div>
                <div className="progress-bar" style={{ marginBottom: "0.25rem" }}>
                  <div className="progress-bar-fill" style={{ width: `${profitPct}%`, background: currentProfit >= 0 ? "var(--color-profit)" : "var(--color-loss)" }} />
                </div>
              </div>

              <div>
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: "0.68rem", color: "var(--color-gray-400)", marginBottom: "0.25rem" }}>
                  <span>Drawdown Used</span>
                  <span style={{ color: ddPct >= 80 ? "var(--color-warning)" : "var(--color-gray-300)" }}>{Math.round(ddPct)}%</span>
                </div>
                <div className="progress-bar" style={{ marginBottom: "0.25rem" }}>
                  <div className="progress-bar-fill" style={{ width: `${ddPct}%`, background: ddPct >= 80 ? "var(--color-warning)" : "var(--color-brand-500)" }} />
                </div>
              </div>

              {minDays > 0 && (
                <div>
                  <div style={{ display: "flex", justifyContent: "space-between", fontSize: "0.68rem", color: "var(--color-gray-400)", marginBottom: "0.25rem" }}>
                    <span>Min Trading Days</span>
                    <span style={{ color: "var(--color-gray-300)" }}>{c.tradingDaysCount ?? 0}/{minDays}</span>
                  </div>
                  <div className="progress-bar" style={{ marginBottom: "0.25rem" }}>
                    <div className="progress-bar-fill" style={{ width: `${daysPct}%`, background: "var(--color-gray-400)" }} />
                  </div>
                </div>
              )}

              {latestEvent && (
                <div style={{ fontSize: "0.68rem", color: latestEvent.severity === 'critical' ? "var(--color-loss)" : latestEvent.severity === 'warning' ? "var(--color-warning)" : "var(--color-gray-400)" }}>
                  {latestEvent.message || latestEvent.eventType.replace(/_/g, " ")}
                </div>
              )}
            </div>
          )
        })}
      </div>
    </div>
  )
}

import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { resolveAccountScope } from "@/lib/active-account"
import { formatCurrency, formatDateWithTimezone } from "@/lib/formatters"
import { cookies } from "next/headers"
import Link from "next/link"

export async function RecentTradesTable({
  dateRange,
  accountId,
}: {
  dateRange?: { from?: Date; to?: Date }
  accountId?: string | null | "all"
}) {
  const session = await auth()
  if (!session?.user?.id) return null

  const user = await prisma.user.findUnique({ where: { id: session.user.id } })
  const scope = await resolveAccountScope(session.user.id, accountId)

  const cookieStore = await cookies()
  const density = cookieStore.get("ui_density")?.value === "compact" ? "compact" : "comfortable"

  if (scope.accounts.length === 0) return <EmptyTable />

  const whereClause: any = scope.all
    ? { userId: session.user.id, status: "closed" }
    : { accountId: scope.accounts[0].id, status: "closed" }
  if (dateRange?.from || dateRange?.to) {
    whereClause.entryAt = {}
    if (dateRange.from) whereClause.entryAt.gte = dateRange.from
    if (dateRange.to) whereClause.entryAt.lte = dateRange.to
  }

  const trades = await prisma.trade.findMany({
    where: whereClause,
    orderBy: { entryAt: "desc" },
    take: 5
  })

  if (trades.length === 0) return <EmptyTable />
  const currency = scope.currency

  return (
    <div className="table-wrapper">
      <table className={`data-table ${density}`}>
        <thead>
          <tr>
            <th>Date</th>
            <th>Symbol</th>
            <th>Side</th>
            <th>Entry</th>
            <th>Exit</th>
            <th style={{ textAlign: "right" }}>P&L</th>
          </tr>
        </thead>
        <tbody>
          {trades.map((t: any) => (
            <tr key={t.id}>
              <td>
                <Link href={`/trades?id=${t.id}`} style={{ textDecoration: "none", color: "inherit" }}>
                  <div style={{ fontWeight: 500, color: "var(--color-gray-200)" }}>
                    {formatDateWithTimezone(t.exitAt ?? t.entryAt, user?.timezone)}
                  </div>
                  <div style={{ fontSize: "0.7rem", color: "var(--color-gray-500)" }}>
                    {new Date(t.exitAt ?? t.entryAt).toLocaleTimeString([], { timeZone: user?.timezone, hour: '2-digit', minute: '2-digit' })}
                  </div>
                </Link>
              </td>
              <td>
                <Link href={`/trades?id=${t.id}`} style={{ textDecoration: "none", color: "inherit" }}>
                  <span style={{ fontWeight: 600 }}>{t.symbol}</span>
                  <span style={{ marginLeft: "0.5rem", fontSize: "0.7rem", color: "var(--color-gray-500)" }}>
                    {t.instrumentType}
                  </span>
                </Link>
              </td>
              <td>
                <Link href={`/trades?id=${t.id}`} style={{ textDecoration: "none", color: "inherit" }}>
                  <span className={`badge ${t.side === 'LONG' ? 'badge-profit' : 'badge-loss'}`}>
                    {t.side}
                  </span>
                </Link>
              </td>
              <td><Link href={`/trades?id=${t.id}`} style={{ textDecoration: "none", color: "inherit" }}>{formatCurrency(Number(t.entryPrice), currency, false, 2)}</Link></td>
              <td><Link href={`/trades?id=${t.id}`} style={{ textDecoration: "none", color: "inherit" }}>{t.exitPrice ? formatCurrency(Number(t.exitPrice), currency, false, 2) : "—"}</Link></td>
              <td style={{ textAlign: "right" }}>
                <Link href={`/trades?id=${t.id}`} style={{ textDecoration: "none", color: "inherit" }}>
                  <span style={{ 
                    fontWeight: 600, 
                    color: Number(t.netPnl) > 0 ? "var(--color-profit)" : Number(t.netPnl) < 0 ? "var(--color-loss)" : "inherit" 
                  }}>
                    {formatCurrency(Number(t.netPnl), currency, true, 2)}
                  </span>
                </Link>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

function EmptyTable() {
  return (
    <div className="empty-state" style={{ padding: "3rem" }}>
      <p>No recent trades found.</p>
    </div>
  )
}

"use client"

import { useEffect, useState } from "react"
import { useSearchParams } from "next/navigation"
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from "recharts"

export function SetupBarChart() {
  const [data, setData] = useState<{name: string, pnl: number, count: number, winRate: number}[]>([])
  const [loading, setLoading] = useState(true)
  const searchParams = useSearchParams()

  useEffect(() => {
    setLoading(true)
    const controller = new AbortController()
    const params = new URLSearchParams()
    const period = searchParams.get("period")
    const accountId = searchParams.get("accountId")
    const from = searchParams.get("from")
    const to = searchParams.get("to")
    if (period) params.set("period", period)
    if (accountId) params.set("accountId", accountId)
    if (from) params.set("from", from)
    if (to) params.set("to", to)

    const qs = params.toString()
    fetch(`/api/metrics/charts${qs ? `?${qs}` : ""}`, { signal: controller.signal })
      .then((r) => r.json())
      .then((d) => {
        setData(d.setupData || [])
        setLoading(false)
      })
      .catch(() => setLoading(false))
    return () => controller.abort()
  }, [searchParams])

  return (
    <div className="chart-card" style={{ display: "flex", flexDirection: "column", height: "100%" }}>
      <div className="chart-title">Performance by Setup</div>

      {loading ? (
        <div className="skeleton" style={{ flex: 1 }} />
      ) : data.length === 0 ? (
        <div className="empty-state" style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center" }}>
          <p style={{ fontSize: "0.85rem" }}>Tag your trades to see this chart.</p>
        </div>
      ) : (
        <div style={{ flex: 1, minHeight: 0 }}>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={data} margin={{ top: 10, right: 10, left: -20, bottom: 0 }} barSize={32} barGap={8}>
              <defs>
                <linearGradient id="setupProfit" x1="0" y1="0" x2="0" y2="1">
