import { ShareCard } from "@/components/prop-firm/ShareCard"
import { ExportPdfButton } from "@/components/prop-firm/ExportPdfButton"
import { CreateChallengeDrawer } from "@/components/prop-firm/CreateChallengeDrawer"

export function ChallengeDetailPage({
  challenge,
  templates,
  accounts,
}: {
  challenge: any
  templates: any[]
  accounts: any[]
}) {
  const router = useRouter()
  const [syncing, setSyncing] = useState(false)
  const [editing, setEditing] = useState(false)
  const [deleting, setDeleting] = useState(false)
  const [resetting, setResetting] = useState(false)

  const isPassed = challenge.status === 'passed'

  const handleSync = async () => {
    setSyncing(true)
    try {
      const res = await fetch(`/api/challenges/${challenge.id}/recalculate`, { method: "POST" })
      if (!res.ok) throw new Error("Failed to sync")
      router.refresh()
      toast.success("Challenge re-evaluated")
    } catch (err) {
      toast.error("Failed to sync challenge")
    } finally {
      setSyncing(false)
    }
  }

  const handleUpgrade = async () => {
    try {
      const res = await fetch(`/api/challenges/${challenge.id}/upgrade`, { method: "POST" })
      if (!res.ok) throw new Error("Failed to upgrade")
      router.refresh()
      toast.success(isPassed ? "Upgraded to next phase" : "Challenge upgraded")
    } catch (err) {
      toast.error("Failed to upgrade phase")
    }
  }

  const handleSubmit = async (data: any) => {
    const res = await fetch(`/api/challenges/${challenge.id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ...data, id: challenge.id }),
    })
    if (!res.ok) {
      const errData = await res.json()
      throw new Error(errData.error || "Failed to update challenge")
    }
    router.refresh()
  }

  const handleDelete = async () => {
    if (!confirm(`Delete challenge "${challenge.account.name}" and its trading account? This cannot be undone.`)) return
    setDeleting(true)
    try {
      const res = await fetch(`/api/challenges/${challenge.id}`, { method: "DELETE" })
      if (!res.ok) throw new Error("Failed to delete")
      toast.success("Challenge deleted")
      router.push("/challenges")
    } catch (err) {
      toast.error("Failed to delete challenge")
      setDeleting(false)
    }
  }

  const handleExport = async () => {
    try {
      const res = await fetch(`/api/challenges/${challenge.id}/export?format=csv`)
      if (!res.ok) throw new Error("Failed to export")
      const blob = await res.blob()
      const url = URL.createObjectURL(blob)
      const a = document.createElement("a")
      a.href = url
      a.download = `challenge-${challenge.account.name.replace(/[^a-z0-9]+/gi, "-")}.csv`
      a.click()
      URL.revokeObjectURL(url)
      toast.success("Challenge exported")
    } catch {
      toast.error("Failed to export challenge")
    }
  }

  const handleReset = async () => {
    if (!confirm(
      `Reset challenge "${challenge.account.name}" back to ${challenge.metadata?.steps === '1' ? 'funded' : 'phase 1'}?\n\n` +
      `This will DELETE all trades, daily snapshots and events on this challenge and restart the timer. This cannot be undone.`
    )) return
    setResetting(true)
    try {
      const res = await fetch(`/api/challenges/${challenge.id}/reset`, { method: "POST" })
      if (!res.ok) throw new Error("Failed to reset")
      toast.success("Challenge reset")
      router.refresh()
    } catch {
      toast.error("Failed to reset challenge")
    } finally {
      setResetting(false)
    }
  }

  const shareData = {
    challengeId: challenge.id,
    firmName: challenge.template?.firmName || "Prop Firm",
    programName: challenge.template?.programName || "",
    logoUrl: challenge.template?.logoUrl || null,
    accountName: challenge.account.name,
    phase: challenge.phase,
    status: challenge.status,
    initialBalance: Number(challenge.initialBalance),
    currentBalance: Number(challenge.currentBalance || challenge.initialBalance),
    currentProfitPct: Number(challenge.initialBalance) > 0
      ? ((Number(challenge.currentBalance || challenge.initialBalance) - Number(challenge.initialBalance)) / Number(challenge.initialBalance)) * 100
      : 0,
    profitTargetPct: Number(challenge.profitTargetPct),
    targetProgressPct: Number(challenge.profitTargetPct) > 0
      ? ((Number(challenge.currentBalance || challenge.initialBalance) - Number(challenge.initialBalance)) / (Number(challenge.initialBalance) * Number(challenge.profitTargetPct) / 100)) * 100
      : 0,
    maxDDPct: Number(challenge.maxDDPct),
    ddUsedPct: Number(challenge.maxDDPct) > 0
      ? ((Number(challenge.initialBalance) - Number(challenge.currentBalance || challenge.initialBalance)) / (Number(challenge.initialBalance) * Number(challenge.maxDDPct) / 100)) * 100
      : 0,
    tradingDays: Number(challenge.metadata?.tradingDaysCount || 0),
    minTradingDays: challenge.minTradingDays,
    daysRemaining: challenge.deadlineAt
      ? Math.max(0, Math.ceil((new Date(challenge.deadlineAt).getTime() - Date.now()) / 86400000))
      : null,
  }

  return (
    <>
      <div style={{ 
        padding: "1.25rem 1.5rem", borderRadius: "8px", marginBottom: "2rem", 
        display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: "1.5rem", 
        background: "var(--color-gray-900)", border: "1px solid var(--color-gray-800)"
      }}>

        <div style={{ display: "flex", alignItems: "center", gap: "1.25rem" }}>
          <button
            onClick={() => router.push("/challenges")}
            className="btn btn-outline"
            style={{ padding: "0.5rem 0.75rem", fontSize: "0.85rem", color: "var(--color-gray-300)" }}
            title="Back to Challenges"
          >
            &larr; Back
          </button>
          {challenge.template?.logoUrl && (
            <div style={{
              width: "44px", height: "44px", borderRadius: "6px",
              background: "var(--color-gray-800)", border: "1px solid var(--color-gray-700)",
              display: "flex", alignItems: "center", justifyContent: "center", overflow: "hidden"
            }}>
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img src={challenge.template.logoUrl} alt={`${challenge.template.firmName} logo`} style={{ maxWidth: "80%", maxHeight: "80%", objectFit: "contain" }} />
            </div>
          )}
          <div>
            <h1 style={{ fontSize: "1.5rem", fontWeight: 700, color: "var(--color-gray-100)" }}>{challenge.account.name}</h1>
            <div style={{ fontSize: "0.85rem", color: "var(--color-gray-400)", fontWeight: 500, display: "flex", alignItems: "center", gap: "0.5rem" }}>
              <span>{challenge.template.firmName}</span>
              <span style={{ color: "var(--color-gray-600)" }}>&bull;</span>
              <span>{challenge.template.programName}</span>
            </div>
          </div>
        </div>

        <div style={{ display: "flex", gap: "0.5rem", flexWrap: "wrap" }}>
          {isPassed && challenge.phase === 'phase_1' && (
            <button onClick={handleUpgrade} className="btn btn-primary" style={{ padding: "0.5rem 1rem", fontSize: "0.85rem" }}>
              {challenge.metadata?.steps === '2' ? "Start Phase 2" : "Get Funded"}
            </button>
          )}
          <button onClick={handleSync} disabled={syncing} className="btn btn-outline" style={{ padding: "0.5rem 1rem", fontSize: "0.85rem" }}>
            {syncing ? "Syncing..." : "Sync Engine"}
          </button>
          <button onClick={handleExport} className="btn btn-outline" style={{ padding: "0.5rem 1rem", fontSize: "0.85rem" }}>
            Export CSV
          </button>
          <ExportPdfButton challengeId={challenge.id} accountName={challenge.account.name} />
          <ShareCard data={shareData} />
          <button onClick={() => setEditing(true)} className="btn btn-outline" style={{ padding: "0.5rem 1rem", fontSize: "0.85rem" }}>
            Edit
          </button>
          {(challenge.status === 'breached' || challenge.status === 'failed') && (
            <button
              onClick={handleReset}
              disabled={resetting}
              className="btn btn-outline"
              style={{ padding: "0.5rem 1rem", fontSize: "0.85rem", color: "var(--color-brand-500)" }}
            >
              {resetting ? "Resetting..." : "Reset"}
            </button>
          )}
          <button
            onClick={handleDelete}
            disabled={deleting}
            className="btn btn-outline"
            style={{ padding: "0.5rem 1rem", fontSize: "0.85rem", color: "var(--color-loss)" }}
          >
            {deleting ? "Deleting..." : "Delete"}
          </button>
        </div>
      </div>

      <ChallengeDetailView challenge={challenge} />

      <div style={{ display: "flex", flexDirection: "column", gap: "1.5rem", marginTop: "1.5rem" }}>
        <AlertSettings challengeId={challenge.id} initialConfig={challenge.alertConfig} />

        {challenge.phase === 'funded' && <PayoutsSection challengeId={challenge.id} />}

        <NotesSection challengeId={challenge.id} />
      </div>

      <CreateChallengeDrawer
        isOpen={editing}
        onClose={() => setEditing(false)}
        accounts={accounts}
        templates={templates}
        challenge={challenge}
        onSubmit={handleSubmit}
      />
    </>
  )
}

"use client"

import { useState } from "react"
import { jsPDF } from "jspdf"
import { autoTable } from "jspdf-autotable"
import { toast } from "sonner"

export function ExportPdfButton({ challengeId, accountName }: { challengeId: string; accountName: string }) {
  const [busy, setBusy] = useState(false)

  const exportPdf = async () => {
    setBusy(true)
    try {
      const res = await fetch(`/api/challenges/${challengeId}/export?format=json`)
      if (!res.ok) throw new Error("Failed to load data")
      const c = await res.json()

      const doc = new jsPDF({ orientation: "landscape", unit: "pt", format: "a4" })
      const W = doc.internal.pageSize.getWidth()

      // Header
      doc.setFillColor(15, 17, 23)
      doc.rect(0, 0, W, 70, "F")
      doc.setTextColor(255, 255, 255)
      doc.setFont("helvetica", "bold")
      doc.setFontSize(18)
      doc.text(`${c.template?.firmName || "Prop Firm"} — Challenge Report`, 40, 32)
      doc.setFont("helvetica", "normal")
      doc.setFontSize(10)
      doc.setTextColor(200, 200, 210)
      doc.text(`${c.account?.name || ""} · ${c.phase.replace("_", " ")} · ${c.status}`, 40, 50)

      doc.setTextColor(30, 30, 40)
      let y = 90

      // Summary
      doc.setFontSize(13)
      doc.setFont("helvetica", "bold")
      doc.text("Summary", 40, y)
      y += 8
      const summaryRows = [
        ["Firm", c.template?.firmName || "—", "Status", c.status],
        ["Account", c.account?.name || "—", "Phase", c.phase.replace("_", " ")],
        ["Initial balance", `$${Number(c.initialBalance).toLocaleString("en-US")}`, "Current balance", `$${Number(c.currentBalance ?? c.initialBalance).toLocaleString("en-US")}`],
        ["Profit target", `${Number(c.profitTargetPct)}%`, "Max drawdown", `${Number(c.maxDDPct)}%`],
        ["Daily drawdown", `${Number(c.dailyDDPct)}%`, "Trading days", `${Number(c.metadata?.tradingDaysCount || 0)} / ${c.minTradingDays || 0}`],
        ["Started", new Date(c.startedAt).toLocaleDateString("en-US"), "Deadline", c.deadlineAt ? new Date(c.deadlineAt).toLocaleDateString("en-US") : "No limit"],
      ]
      autoTable(doc, {
        startY: y,
        head: [["Key", "Value", "Key", "Value"]],
        body: summaryRows,
        theme: "striped",
        styles: { fontSize: 8.5, cellPadding: 5 },
        headStyles: { fillColor: [80, 70, 229], textColor: 255 },
        columnStyles: { 0: { cellWidth: 120 }, 1: { cellWidth: 220 }, 2: { cellWidth: 120 }, 3: { cellWidth: 220 } },
      })

      y = (doc as any).lastAutoTable.finalY + 22

      // Daily breakdown
      doc.setFontSize(13)
      doc.setFont("helvetica", "bold")
      doc.text("Daily Breakdown", 40, y)
      y += 8
      const snapRows = (c.dailySnapshots || []).map((s: any) => [
        s.date.slice(0, 10),
        `$${Number(s.startBalance).toLocaleString("en-US", { minimumFractionDigits: 2 })}`,
        `$${Number(s.endBalance).toLocaleString("en-US", { minimumFractionDigits: 2 })}`,
        `${Number(s.dailyPnl) >= 0 ? "+" : ""}$${Number(s.dailyPnl).toLocaleString("en-US", { minimumFractionDigits: 2 })}`,
        String(s.tradesCount),
        s.dailyDDUsedPct != null ? `${Math.round(Number(s.dailyDDUsedPct))}%` : "—",
      ])
      autoTable(doc, {
        startY: y,
        head: [["Date", "Start", "End", "P&L", "Trades", "DD used"]],
        body: snapRows,
        theme: "striped",
        styles: { fontSize: 8.5, cellPadding: 4 },
        headStyles: { fillColor: [80, 70, 229], textColor: 255 },
        columnStyles: {
          0: { cellWidth: 90 },
          1: { cellWidth: 120, halign: "right" },
          2: { cellWidth: 120, halign: "right" },
          3: { cellWidth: 130, halign: "right" },
          4: { cellWidth: 70, halign: "right" },
          5: { cellWidth: 80, halign: "right" },
        },
      })

      y = (doc as any).lastAutoTable.finalY + 22

      // Events
      if ((c.events || []).length > 0) {
        doc.setFontSize(13)
        doc.setFont("helvetica", "bold")
        doc.text("Events", 40, y)
        y += 8
        const eventRows = c.events.map((e: any) => [
          new Date(e.createdAt).toLocaleString("en-US", { dateStyle: "short", timeStyle: "short" }),
          e.eventType.replace(/_/g, " "),
          e.severity,
          e.message || "",
        ])
        autoTable(doc, {
          startY: y,
          head: [["Date", "Type", "Severity", "Message"]],
          body: eventRows,
          theme: "striped",
          styles: { fontSize: 8, cellPadding: 4 },
          headStyles: { fillColor: [80, 70, 229], textColor: 255 },
          columnStyles: { 0: { cellWidth: 140 }, 1: { cellWidth: 130 }, 2: { cellWidth: 80 }, 3: { cellWidth: 400 } },
        })
      }

      doc.save(`${accountName.replace(/[^a-z0-9]+/gi, "-")}-report.pdf`)
      toast.success("PDF report downloaded")
    } catch {
      toast.error("Failed to generate PDF")
    } finally {
      setBusy(false)
    }
  }

  return (
    <button onClick={exportPdf} disabled={busy} className="btn btn-outline" style={{ padding: "0.5rem 1rem", fontSize: "0.85rem" }}>
      {busy ? "Generating…" : "Export PDF"}
    </button>
  )
}

"use client"

import { useCallback, useEffect, useState } from "react"
import { toast } from "sonner"

type Note = {
  id: string
  content: string
  createdAt: string
  updatedAt: string
}

export function NotesSection({ challengeId }: { challengeId: string }) {
  const [notes, setNotes] = useState<Note[]>([])
  const [content, setContent] = useState("")
  const [loading, setLoading] = useState(true)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [editContent, setEditContent] = useState("")
  const [saving, setSaving] = useState(false)

  const load = useCallback(async () => {
    try {
      const res = await fetch(`/api/challenges/${challengeId}/notes`)
      if (!res.ok) return
      setNotes(await res.json())
    } catch {
      // silent
    } finally {
      setLoading(false)
    }
  }, [challengeId])

  useEffect(() => {
    load()
  }, [load])

  const add = async () => {
    if (!content.trim()) return
    setSaving(true)
    try {
      const res = await fetch(`/api/challenges/${challengeId}/notes`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ content: content.trim() }),
      })
      if (!res.ok) throw new Error("Failed")
      setContent("")
      await load()
      toast.success("Note added")
    } catch {
      toast.error("Failed to add note")
    } finally {
      setSaving(false)
    }
  }

  const update = async (id: string) => {
    if (!editContent.trim()) return
    setSaving(true)
    try {
      const res = await fetch(`/api/challenges/${challengeId}/notes/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ content: editContent.trim() }),
      })
      if (!res.ok) throw new Error("Failed")
      setEditingId(null)
      await load()
      toast.success("Note updated")
    } catch {
      toast.error("Failed to update note")
    } finally {
      setSaving(false)
    }
  }

  const remove = async (id: string) => {
    if (!confirm("Delete this note?")) return
    try {
      await fetch(`/api/challenges/${challengeId}/notes/${id}`, { method: "DELETE" })
      await load()
    } catch {
      toast.error("Failed to delete note")
    }
  }

  const formatDate = (iso: string) =>
    new Date(iso).toLocaleString("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" })

  return (
    <div style={{ background: "var(--color-gray-900)", padding: "1.5rem", borderRadius: "8px", border: "1px solid var(--color-gray-800)", display: "flex", flexDirection: "column" }}>
      <h3 style={{ fontSize: "0.95rem", fontWeight: 600, marginBottom: "1.25rem", color: "var(--color-gray-100)", borderBottom: "1px solid var(--color-gray-800)", paddingBottom: "0.75rem", flexShrink: 0 }}>Journal Notes</h3>

      <div style={{ display: "flex", gap: "0.5rem", marginBottom: "1rem" }}>
        <input
          className="input"
          value={content}
          onChange={e => setContent(e.target.value)}
          placeholder="Add a note about this challenge… (strategy, plan, lessons)"
          style={{ background: "var(--color-gray-950)", border: "1px solid var(--color-gray-800)", color: "var(--color-gray-100)" }}
          onKeyDown={e => { if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) add() }}
        />
        <button className="btn btn-primary" onClick={add} disabled={saving || !content.trim()} style={{ padding: "0.5rem 1rem", whiteSpace: "nowrap" }}>
          Add
        </button>
      </div>

      {loading && <div style={{ color: "var(--color-gray-500)", fontSize: "0.8rem", padding: "1rem", textAlign: "center" }}>Loading notes…</div>}

      {!loading && notes.length === 0 && (
        <div style={{ color: "var(--color-gray-500)", fontSize: "0.8rem", padding: "1rem", textAlign: "center" }}>
          No notes yet. Capture your thoughts about each phase.
        </div>
      )}

      <div style={{ display: "flex", flexDirection: "column", gap: "0.5rem" }}>
        {notes.map(n => (
          <div key={n.id} style={{ background: "var(--color-gray-950)", border: "1px solid var(--color-gray-800)", borderRadius: "8px", padding: "1rem" }}>
            {editingId === n.id ? (
              <>
                <textarea
                  className="input"
                  value={editContent}
                  onChange={e => setEditContent(e.target.value)}
                  rows={3}
                  style={{ background: "var(--color-gray-900)", border: "1px solid var(--color-gray-700)" }}
                  autoFocus
                />
                <div style={{ display: "flex", gap: "0.5rem", marginTop: "0.5rem", justifyContent: "flex-end" }}>
                  <button className="btn btn-outline" onClick={() => setEditingId(null)} style={{ padding: "0.3rem 0.8rem", fontSize: "0.8rem" }}>Cancel</button>
                  <button className="btn btn-primary" onClick={() => update(n.id)} disabled={saving} style={{ padding: "0.3rem 0.8rem", fontSize: "0.8rem" }}>Save</button>
                </div>
              </>
            ) : (
              <>
                <div style={{ fontSize: "0.88rem", color: "var(--color-gray-200)", whiteSpace: "pre-wrap" }}>{n.content}</div>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: "0.5rem" }}>
                  <span style={{ fontSize: "0.68rem", color: "var(--color-gray-500)" }}>{formatDate(n.createdAt)}</span>
                  <div style={{ display: "flex", gap: "0.5rem" }}>
                    <button
                      onClick={() => { setEditingId(n.id); setEditContent(n.content) }}
                      style={{ fontSize: "0.72rem", color: "var(--color-brand-500)", background: "transparent", border: "none", cursor: "pointer" }}
                    >
                      Edit
                    </button>
                    <button
                      onClick={() => remove(n.id)}
                      style={{ fontSize: "0.72rem", color: "var(--color-loss)", background: "transparent", border: "none", cursor: "pointer" }}
                    >
                      Delete
                    </button>
                  </div>
                </div>
              </>
            )}
          </div>
        ))}
      </div>
    </div>
  )
}

"use client"

import { useEffect, useState } from "react"
import { toast } from "sonner"

const EVENT_LABELS: Record<string, string> = {
  breached: "Challenge breached / failed",
  target_hit: "Profit target reached",
  alert_80pct: "Drawdown alert at 80%",
  alert_90pct: "Drawdown alert at 90%",
  min_days_not_met: "Min trading days not met",
  stop_trading: "Stop-trading alert",
  goal_reached: "Profit goal reached",
  deadline_5d: "Deadline in 5 days",
  deadline_1d: "Deadline in 1 day",
}

export function NotificationPreferences() {
  const [eventTypes, setEventTypes] = useState<Record<string, boolean>>({})
  const [defaults, setDefaults] = useState({ stopTradingPct: 85, profitGoalPct: 50 })
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [browserEnabled, setBrowserEnabled] = useState(false)
  const [permission, setPermission] = useState<NotificationPermission | "unsupported">("unsupported")

  useEffect(() => {
    setBrowserEnabled(localStorage.getItem("tradelink_browser_notifications") === "1")
    setPermission("Notification" in window ? Notification.permission : "unsupported")
  }, [])

  const toggleBrowser = async (enabled: boolean) => {
    if (enabled) {
      if (!("Notification" in window)) {
        toast.error("Browser notifications are not supported here")
        return
      }
      const p = await Notification.requestPermission()
      setPermission(p)
      if (p === "granted") {
        localStorage.setItem("tradelink_browser_notifications", "1")
        setBrowserEnabled(true)
        toast.success("Browser notifications enabled")
      } else {
        toast.error("Permission denied by the browser")
      }
    } else {
      localStorage.removeItem("tradelink_browser_notifications")
      setBrowserEnabled(false)
    }
  }

  useEffect(() => {
    fetch("/api/notifications/preferences")
      .then(r => r.json())
      .then(d => {
        setEventTypes(d.eventTypes || {})
        setDefaults(d.defaults || {})
      })
      .catch(() => {})
      .finally(() => setLoading(false))
  }, [])

  const save = async () => {
    setSaving(true)
    try {
      const res = await fetch("/api/notifications/preferences", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ eventTypes, defaults }),
      })
      if (!res.ok) throw new Error("Failed")
      toast.success("Notification preferences saved")
    } catch {
      toast.error("Failed to save preferences")
    } finally {
      setSaving(false)
    }
  }

  return (
    <div className="chart-card" style={{ padding: "1.5rem" }}>
      <h2 style={{ fontSize: "1.1rem", fontWeight: 700, marginBottom: "0.25rem" }}>Notification Preferences</h2>
      <p style={{ fontSize: "0.85rem", color: "var(--color-gray-500)", marginBottom: "1.25rem" }}>
        Choose which prop-firm events show up in your notification center.
      </p>

      {loading && <div style={{ color: "var(--color-gray-500)", fontSize: "0.85rem" }}>Loading…</div>}

      {!loading && (
        <div style={{ display: "flex", flexDirection: "column", gap: "0.5rem" }}>
          {Object.keys(EVENT_LABELS).map(key => (
            <label key={key} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "0.5rem 0", cursor: "pointer", borderBottom: "1px solid var(--color-gray-800)" }}>
              <span style={{ fontSize: "0.88rem", color: "var(--color-gray-200)" }}>{EVENT_LABELS[key]}</span>
              <input
                type="checkbox"
                checked={Boolean(eventTypes[key])}
                onChange={e => setEventTypes(p => ({ ...p, [key]: e.target.checked }))}
                style={{ width: 17, height: 17, accentColor: "var(--color-brand-500)" }}
              />
            </label>
          ))}

          <div style={{ marginTop: "0.75rem", display: "flex", gap: "1.5rem", flexWrap: "wrap" }}>
            <div className="form-group" style={{ minWidth: 160 }}>
              <label className="label">Default stop-trading threshold (%)</label>
              <input
                type="number"
                min={1}
                max={100}
                className="input"
                value={defaults.stopTradingPct}
                onChange={e => setDefaults(d => ({ ...d, stopTradingPct: Number(e.target.value) }))}
              />
            </div>
            <div className="form-group" style={{ minWidth: 160 }}>
              <label className="label">Default profit goal (%)</label>
              <input
                type="number"
                min={1}
                max={100}
                className="input"
                value={defaults.profitGoalPct}
                onChange={e => setDefaults(d => ({ ...d, profitGoalPct: Number(e.target.value) }))}
              />
            </div>
          </div>
          <div style={{ fontSize: "0.75rem", color: "var(--color-gray-500)", marginTop: "0.25rem" }}>
            These defaults prefill the Alert Settings when you create a new challenge.
          </div>

          <div style={{ marginTop: "1rem", paddingTop: "1rem", borderTop: "1px solid var(--color-gray-800)" }}>
            <label style={{ display: "flex", justifyContent: "space-between", alignItems: "center", cursor: "pointer", gap: "1rem" }}>
              <div>
                <div style={{ fontWeight: 600, fontSize: "0.88rem", color: "var(--color-gray-200)" }}>Browser notifications</div>
                <div style={{ fontSize: "0.75rem", color: "var(--color-gray-500)" }}>
                  Receive desktop/push-style alerts when a new prop-firm event happens.
                  {permission === "denied" && " Permission was denied in your browser — allow it in the site settings."}
                  {permission === "default" && " You'll be asked for permission when you enable this."}
                </div>
              </div>
              <input
                type="checkbox"
                checked={browserEnabled}
                onChange={e => toggleBrowser(e.target.checked)}
                style={{ width: 17, height: 17, accentColor: "var(--color-brand-500)", flexShrink: 0 }}
              />
            </label>
          </div>

          <div style={{ marginTop: "1rem", display: "flex", justifyContent: "flex-end" }}>
            <button className="btn btn-primary" onClick={save} disabled={saving}>
              {saving ? "Saving…" : "Save preferences"}
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

"use client"

import React, { useState, useEffect } from "react"
import { toast } from "sonner"
import { Wallet, CheckCircle2, Clock, Plus } from "lucide-react"

const PAYOUT_STATUS: Record<string, { label: string; color: string }> = {
  requested: { label: "Requested", color: "var(--color-warning)" },
  approved: { label: "Approved", color: "var(--color-brand-500)" },
  paid: { label: "Paid", color: "var(--color-profit)" },
  rejected: { label: "Rejected", color: "var(--color-loss)" },
}

function formatDate(iso: string): string {
  try {
    return new Date(iso).toLocaleString("en-US", {
      year: "numeric",
      month: "short",
      day: "numeric",
    })
  } catch {
    return iso
  }
}

export function PayoutsManager() {
  const [payouts, setPayouts] = useState<any[]>([])
  const [totals, setTotals] = useState({ paid: 0, approved: 0, requested: 0, pending: 0 })
  const [fundedChallenges, setFundedChallenges] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [modalOpen, setModalOpen] = useState(false)

  // Register form
  const [challengeId, setChallengeId] = useState("")
  const [amount, setAmount] = useState("")
  const [date, setDate] = useState("")

  useEffect(() => {
    setDate(new Date().toISOString().slice(0, 10))
  }, [])
  const [note, setNote] = useState("")
  const [saving, setSaving] = useState(false)

  const refresh = async () => {
    try {
      const res = await fetch("/api/prop-firms/payouts")
      if (res.ok) {
        const data = await res.json()
        setPayouts(data.payouts || [])
        setTotals(data.totals || { paid: 0, approved: 0, requested: 0, pending: 0 })
        setFundedChallenges(data.fundedChallenges || [])
      }
    } catch {
      // ignore
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    refresh()
  }, [])

  const registerPayout = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!challengeId) {
      toast.error("Select a funded account")
      return
    }
    if (!amount || isNaN(parseFloat(amount))) {
      toast.error("Enter a valid amount")
      return
    }
    setSaving(true)
    try {
      const res = await fetch(`/api/challenges/${challengeId}/payouts`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          amount: parseFloat(amount),
          requestedAt: date ? `${date}T12:00:00Z` : undefined,
          note,
        }),
      })
      const data = await res.json().catch(() => null)
      if (!res.ok) throw new Error(data?.error || "Failed to register payout")
      toast.success("Payout registered")
      setChallengeId("")
      setAmount("")
      setNote("")
      setModalOpen(false)
      await refresh()
    } catch (err: any) {
      toast.error(err.message || "Failed to register payout")
    } finally {
      setSaving(false)
    }
  }

  const updateStatus = async (p: any, status: string) => {
    if (status === p.status) return
    try {
      const res = await fetch(`/api/challenges/${p.challengeId}/payouts/${p.id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status }),
      })
      if (!res.ok) throw new Error("Failed to update payout")
      toast.success(`Payout marked ${status}`)
      await refresh()
    } catch {
      toast.error("Failed to update payout")
    }
  }

  const deletePayout = async (p: any) => {
    if (!confirm("Delete this payout?")) return
    try {
      const res = await fetch(`/api/challenges/${p.challengeId}/payouts/${p.id}`, { method: "DELETE" })
      if (!res.ok) throw new Error("Failed to delete payout")
      toast.success("Payout removed")
      await refresh()
    } catch {
      toast.error("Failed to delete payout")
    }
  }

  const fmt = (v: number) => `$${v.toLocaleString("en-US", { minimumFractionDigits: 2 })}`

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "1.75rem" }}>
      {/* Header */}
      <div className="page-header">
        <div>
          <h1 className="page-title">Payouts</h1>
          <p className="page-subtitle">Withdrawals are only available on funded accounts.</p>
        </div>
        <button className="btn btn-primary" onClick={() => setModalOpen(true)}>
          <Plus size={16} /> Register Payout
        </button>
      </div>

      {/* Summary cards */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: "1rem" }}>
        <div className="kpi-card" style={{ display: "flex", flexDirection: "column", gap: "0.5rem" }}>
          <div style={{ display: "flex", alignItems: "center", gap: "0.5rem", color: "var(--color-gray-400)", fontSize: "0.75rem", textTransform: "uppercase", fontWeight: 600 }}>
            <CheckCircle2 size={14} /> Total Paid
          </div>
          <div style={{ fontSize: "1.6rem", fontWeight: 700, color: "var(--color-profit)" }}>{fmt(totals.paid)}</div>
          <div style={{ fontSize: "0.72rem", color: "var(--color-gray-500)" }}>
            {payouts.filter(p => p.status === 'paid').length} payout{payouts.filter(p => p.status === 'paid').length > 1 ? "s" : ""} paid
          </div>
        </div>
        <div className="kpi-card" style={{ display: "flex", flexDirection: "column", gap: "0.5rem" }}>
          <div style={{ display: "flex", alignItems: "center", gap: "0.5rem", color: "var(--color-gray-400)", fontSize: "0.75rem", textTransform: "uppercase", fontWeight: 600 }}>
            <Clock size={14} /> Pending
          </div>
          <div style={{ fontSize: "1.6rem", fontWeight: 700, color: "var(--color-warning)" }}>{fmt(totals.pending)}</div>
          <div style={{ fontSize: "0.72rem", color: "var(--color-gray-500)" }}>
            {payouts.filter(p => p.status === 'requested' || p.status === 'approved').length} awaiting payment
          </div>
        </div>
        <div className="kpi-card" style={{ display: "flex", flexDirection: "column", gap: "0.5rem" }}>
          <div style={{ display: "flex", alignItems: "center", gap: "0.5rem", color: "var(--color-gray-400)", fontSize: "0.75rem", textTransform: "uppercase", fontWeight: 600 }}>
            <Wallet size={14} /> Approved
          </div>
          <div style={{ fontSize: "1.6rem", fontWeight: 700, color: "var(--color-brand-500)" }}>{fmt(totals.approved)}</div>
          <div style={{ fontSize: "0.72rem", color: "var(--color-gray-500)" }}>
            {payouts.filter(p => p.status === 'approved').length} approved
          </div>
        </div>
        <div className="kpi-card" style={{ display: "flex", flexDirection: "column", gap: "0.5rem" }}>
          <div style={{ display: "flex", alignItems: "center", gap: "0.5rem", color: "var(--color-gray-400)", fontSize: "0.75rem", textTransform: "uppercase", fontWeight: 600 }}>
            <Wallet size={14} /> Funded accounts
          </div>
          <div style={{ fontSize: "1.6rem", fontWeight: 700, color: "var(--color-text)" }}>{fundedChallenges.length}</div>
          <div style={{ fontSize: "0.72rem", color: "var(--color-gray-500)" }}>
            eligible for payouts
          </div>
        </div>
      </div>

      {/* Register modal */}
      {modalOpen && (
        <div style={{
          position: "fixed", inset: 0, zIndex: 200,
          background: "rgba(0,0,0,0.6)", display: "flex", alignItems: "center", justifyContent: "center", padding: "1rem",
        }} onClick={() => setModalOpen(false)}>
          <div className="chart-card" style={{ width: "100%", maxWidth: 460, padding: "1.5rem" }} onClick={e => e.stopPropagation()}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1.25rem" }}>
              <h3 style={{ fontWeight: 700, fontSize: "1.05rem" }}>Register Payout</h3>
              <button onClick={() => setModalOpen(false)} style={{ background: "transparent", border: "none", color: "var(--color-gray-400)", cursor: "pointer", fontSize: "1.4rem" }}>&times;</button>
            </div>

            {fundedChallenges.length === 0 ? (
              <div style={{ padding: "1rem 0", fontSize: "0.85rem", color: "var(--color-gray-500)" }}>
                No funded accounts yet. Funded accounts are only eligible once a challenge reaches the funded phase.
              </div>
            ) : (
              <form onSubmit={registerPayout} style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
                <div>
                  <label className="label">Funded account</label>
                  <select className="input" value={challengeId} onChange={e => setChallengeId(e.target.value)}>
                    <option value="">Select a funded account…</option>
                    {fundedChallenges.map(c => (
                      <option key={c.id} value={c.id}>
                        {c.firmName} — {c.accountName} — equity {fmt(c.currentEquity)}
                      </option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="label">Amount (USD)</label>
                  <input className="input" type="number" value={amount} onChange={e => setAmount(e.target.value)} placeholder="0.00" />
                </div>
                <div>
                  <label className="label">Date</label>
                  <input className="input" type="date" value={date} onChange={e => setDate(e.target.value)} />
                </div>
                <div>
                  <label className="label">Note (optional)</label>
                  <input className="input" type="text" value={note} onChange={e => setNote(e.target.value)} placeholder="e.g. monthly withdrawal" />
                </div>
                <div style={{ display: "flex", justifyContent: "flex-end", gap: "0.5rem", marginTop: "0.5rem" }}>
                  <button type="button" className="btn btn-outline" onClick={() => setModalOpen(false)}>Cancel</button>
                  <button type="submit" className="btn btn-primary" disabled={saving}>
                    {saving ? "..." : "Register"}
                  </button>
                </div>
              </form>
            )}
          </div>
        </div>
      )}

      {/* Payouts table */}
      <div>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "0.75rem" }}>
          <h3 style={{ fontSize: "1.05rem", fontWeight: 700, color: "var(--color-gray-100)" }}>All payouts</h3>
          <span style={{ fontSize: "0.78rem", color: "var(--color-gray-500)" }}>
            {payouts.length} total
          </span>
        </div>

        {loading ? (
          <div className="skeleton" style={{ height: 120 }} />
        ) : payouts.length === 0 ? (
          <div className="chart-card" style={{ padding: "2.5rem", textAlign: "center" }}>
            <div style={{ fontSize: "1.8rem", marginBottom: "0.5rem" }}>💸</div>
            <div style={{ fontWeight: 700, color: "var(--color-gray-200)" }}>No payouts yet</div>
            <div style={{ fontSize: "0.85rem", color: "var(--color-gray-500)", marginTop: "0.35rem" }}>
              Register your first payout from a funded account above.
            </div>
          </div>
        ) : (
          <div style={{ overflowX: "auto", borderRadius: "12px", border: "1px solid var(--color-gray-800)" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "0.8rem" }}>
              <thead>
                <tr style={{ background: "var(--color-gray-900)", color: "var(--color-gray-400)", textAlign: "left" }}>
                  <th style={{ padding: "0.6rem 0.75rem" }}>Firm</th>
                  <th style={{ padding: "0.6rem 0.75rem" }}>Account</th>
                  <th style={{ padding: "0.6rem 0.75rem", textAlign: "right" }}>Amount</th>
                  <th style={{ padding: "0.6rem 0.75rem" }}>Date</th>
                  <th style={{ padding: "0.6rem 0.75rem" }}>Note</th>
                  <th style={{ padding: "0.6rem 0.75rem" }}>Status</th>
                  <th style={{ padding: "0.6rem 0.75rem" }}></th>
                </tr>
              </thead>
              <tbody>
                {payouts.map(p => {
                  const st = PAYOUT_STATUS[p.status] || { label: p.status, color: "var(--color-gray-400)" }
                  return (
                    <tr key={p.id} style={{ borderTop: "1px solid var(--color-gray-800)", color: "var(--color-gray-300)" }}>
                      <td style={{ padding: "0.5rem 0.75rem", whiteSpace: "nowrap" }}>
                        <span style={{ display: "inline-flex", alignItems: "center", gap: "0.4rem" }}>
                          {p.logoUrl && (
                            <span style={{ width: 18, height: 18, borderRadius: 4, overflow: "hidden", background: "var(--color-gray-800)", display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                              {/* eslint-disable-next-line @next/next/no-img-element */}
                              <img src={p.logoUrl} alt={p.firmName} style={{ maxWidth: "100%", maxHeight: "100%", objectFit: "contain" }} />
                            </span>
                          )}
                          <span style={{ fontWeight: 600, color: "var(--color-gray-100)" }}>{p.firmName}</span>
                        </span>
                      </td>
                      <td style={{ padding: "0.5rem 0.75rem", whiteSpace: "nowrap" }}>{p.accountName}</td>
                      <td style={{ padding: "0.5rem 0.75rem", textAlign: "right", fontWeight: 600, color: "var(--color-gray-100)", whiteSpace: "nowrap" }}>{fmt(p.amount)}</td>
                      <td style={{ padding: "0.5rem 0.75rem", whiteSpace: "nowrap", color: "var(--color-gray-400)" }}>{formatDate(p.requestedAt)}</td>
                      <td style={{ padding: "0.5rem 0.75rem", color: "var(--color-gray-400)", maxWidth: 220 }}>
                        <span style={{ display: "block", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }} title={p.note || ""}>{p.note || "—"}</span>
                      </td>
                      <td style={{ padding: "0.5rem 0.75rem", whiteSpace: "nowrap" }}>
                        <select
                          className="input"
                          value={p.status}
                          onChange={e => updateStatus(p, e.target.value)}
                          style={{ padding: "0.3rem 1.8rem 0.3rem 0.6rem", fontSize: "0.75rem", width: "auto", color: st.color }}
                        >
                          {Object.entries(PAYOUT_STATUS).map(([key, s]) => (
                            <option key={key} value={key} style={{ color: "var(--color-gray-100)" }}>
                              {s.label}
                            </option>
                          ))}
                        </select>
                      </td>
                      <td style={{ padding: "0.5rem 0.75rem", textAlign: "right", whiteSpace: "nowrap" }}>
                        <button
                          onClick={() => deletePayout(p)}
                          className="btn btn-outline"
                          style={{ padding: "0.25rem 0.5rem", fontSize: "0.7rem", color: "var(--color-loss)" }}
                        >
                          &times;
                        </button>
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  )
}

"use client"

import React, { useState, useEffect } from "react"
import { toast } from "sonner"

const PAYOUT_STATUS: Record<string, { label: string; color: string }> = {
  requested: { label: "Requested", color: "var(--color-warning)" },
  approved: { label: "Approved", color: "var(--color-brand-500)" },
  paid: { label: "Paid", color: "var(--color-profit)" },
  rejected: { label: "Rejected", color: "var(--color-loss)" },
}

function formatDate(iso: string): string {
  try {
    return new Date(iso).toLocaleString("en-US", {
      year: "numeric",
      month: "short",
      day: "numeric",
    })
  } catch {
    return iso
  }
}

export function PayoutsSection({ challengeId }: { challengeId: string }) {
  const [payouts, setPayouts] = useState<any[]>([])
  const [payoutAmount, setPayoutAmount] = useState("")
  const [payoutDate, setPayoutDate] = useState("")

  useEffect(() => {
    setPayoutDate(new Date().toISOString().slice(0, 10))
  }, [])
  const [payoutNote, setPayoutNote] = useState("")
  const [savingPayout, setSavingPayout] = useState(false)

  const refresh = async () => {
    try {
      const res = await fetch(`/api/challenges/${challengeId}/payouts`)
      if (res.ok) setPayouts(await res.json())
    } catch {
      // ignore
    }
  }

  useEffect(() => {
    refresh()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [challengeId])

  const requestPayout = async () => {
    if (!payoutAmount || isNaN(parseFloat(payoutAmount))) {
      toast.error("Enter a valid amount")
      return
    }
    setSavingPayout(true)
    try {
      const res = await fetch(`/api/challenges/${challengeId}/payouts`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          amount: parseFloat(payoutAmount),
          requestedAt: payoutDate ? `${payoutDate}T12:00:00Z` : undefined,
          note: payoutNote,
        }),
      })
      if (!res.ok) throw new Error("Failed to request payout")
      setPayoutAmount("")
      setPayoutNote("")
      await refresh()
      toast.success("Payout requested")
    } catch (err) {
      toast.error("Failed to request payout")
    } finally {
      setSavingPayout(false)
    }
  }

  const updatePayoutStatus = async (payoutId: string, status: string) => {
    try {
      const res = await fetch(`/api/challenges/${challengeId}/payouts/${payoutId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status }),
      })
      if (!res.ok) throw new Error("Failed to update payout")
      await refresh()
    } catch (err) {
      toast.error("Failed to update payout")
    }
  }

  const deletePayout = async (payoutId: string) => {
    try {
      const res = await fetch(`/api/challenges/${challengeId}/payouts/${payoutId}`, {
        method: "DELETE",
      })
      if (!res.ok) throw new Error("Failed to delete payout")
      setPayouts(payouts.filter(p => p.id !== payoutId))
      toast.success("Payout removed")
    } catch (err) {
      toast.error("Failed to delete payout")
    }
  }

  const totalPaid = payouts.filter(p => p.status === 'paid').reduce((sum, p) => sum + Number(p.amount), 0)

  return (
    <div style={{ marginTop: "2rem" }}>
      <h3 style={{ fontSize: "1.05rem", fontWeight: 600, marginBottom: "0.5rem", color: "var(--color-gray-100)" }}>Payouts</h3>
      <div style={{ fontSize: "0.85rem", color: "var(--color-gray-400)", marginBottom: "1rem" }}>
        Total paid: <span style={{ color: "var(--color-profit)", fontWeight: 600 }}>${totalPaid.toLocaleString("en-US", { minimumFractionDigits: 2 })}</span>
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: "0.5rem", marginBottom: "1rem" }}>
        <div style={{ display: "flex", gap: "0.5rem" }}>
          <input
            type="number"
            className="input"
            value={payoutAmount}
            onChange={e => setPayoutAmount(e.target.value)}
            placeholder="Amount (USD)"
            style={{ flex: 1 }}
          />
          <input
            type="date"
            className="input"
            value={payoutDate}
            onChange={e => setPayoutDate(e.target.value)}
            style={{ width: 170 }}
          />
          <button onClick={requestPayout} disabled={savingPayout} className="btn btn-primary" style={{ padding: "0.5rem 1rem", fontSize: "0.85rem" }}>
            {savingPayout ? "..." : "Request"}
          </button>
        </div>
        <input
          type="text"
          className="input"
          value={payoutNote}
          onChange={e => setPayoutNote(e.target.value)}
          placeholder="Note (optional)"
        />
      </div>

      {payouts.length === 0 ? (
        <div style={{ color: "var(--color-gray-500)", fontSize: "0.85rem", padding: "1rem 0" }}>
          No payouts yet. Funded accounts can request withdrawals here.
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "0.6rem" }}>
          {payouts.map(p => {
            const st = PAYOUT_STATUS[p.status] || { label: p.status, color: "var(--color-gray-400)" }
            return (
              <div key={p.id} style={{
                background: "var(--color-gray-900)", border: "1px solid var(--color-gray-800)",
                borderRadius: "10px", padding: "0.75rem 1rem",
                display: "flex", alignItems: "center", gap: "0.75rem",
              }}>
                <div style={{ flex: 1 }}>
                  <div style={{ fontWeight: 600, color: "var(--color-gray-100)" }}>${Number(p.amount).toLocaleString("en-US", { minimumFractionDigits: 2 })}</div>
                  <div style={{ fontSize: "0.7rem", color: "var(--color-gray-500)" }}>{formatDate(p.requestedAt)}</div>
                  {p.note && (
                    <div style={{ fontSize: "0.75rem", color: "var(--color-gray-400)", marginTop: "0.2rem" }}>{p.note}</div>
                  )}
                </div>
                <span className="badge" style={{ background: `${st.color}22`, color: st.color, border: `1px solid ${st.color}40` }}>
                  {st.label.toUpperCase()}
                </span>
                {p.status !== 'paid' && (
                  <div style={{ display: "flex", gap: "0.3rem" }}>
                    {p.status === 'requested' && (
                      <button
                        onClick={() => updatePayoutStatus(p.id, p.status)}
                        className="btn btn-outline"
                        style={{ padding: "0.3rem 0.6rem", fontSize: "0.75rem" }}
                      >
                        Approve
                      </button>
                    )}
                    {p.status === 'approved' && (
                      <button
                        onClick={() => updatePayoutStatus(p.id, p.status)}
                        className="btn btn-outline"
                        style={{ padding: "0.3rem 0.6rem", fontSize: "0.75rem" }}
                      >
                        Mark Paid
                      </button>
                    )}
                    <button
                      onClick={() => updatePayoutStatus(p.id, 'rejected')}
                      className="btn btn-outline"
                      style={{ padding: "0.3rem 0.6rem", fontSize: "0.75rem", color: "var(--color-loss)" }}
                    >
                      Reject
                    </button>
                  </div>
                )}
                {p.status === 'rejected' && (
                  <button
                    onClick={() => updatePayoutStatus(p.id, 'requested')}
                    className="btn btn-outline"
                    style={{ padding: "0.3rem 0.6rem", fontSize: "0.75rem" }}
                  >
                    Reopen
                  </button>
                )}
                <button
                  onClick={() => deletePayout(p.id)}
                  className="btn btn-outline"
                  style={{ padding: "0.3rem 0.6rem", fontSize: "0.75rem", color: "var(--color-loss)" }}
                >
                  &times;
                </button>
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}

"use client"

import React, { useState, useEffect } from "react"

interface GaugeProps {
  label: string
  used: number
  total: number
  isBreached: boolean
  formatCurrency?: boolean
  reverseColors?: boolean
}

function NeedleGauge({ label, used, total, isBreached, formatCurrency = true, reverseColors = false }: GaugeProps) {
  const [mounted, setMounted] = useState(false)
  useEffect(() => { setMounted(true) }, [])

  const pctRaw = total > 0 ? (used / total) * 100 : 0
  const pct = Math.min(Math.max(pctRaw, 0), 100) || 0

  const formattedUsed = formatCurrency ? `$${Math.max(0, used).toLocaleString("en-US", {minimumFractionDigits: 2})}` : Math.max(0, used).toString()
  const formattedTotal = formatCurrency ? `$${total.toLocaleString("en-US", {minimumFractionDigits: 2})}` : total.toString()

  const angle = mounted ? ((pct / 100) * 180) - 90 : -90

  // Calculate graduations
  const ticks = [0, 25, 50, 75, 100].map((val) => {
    const angleDeg = 180 - (val / 100) * 180
    const rad = angleDeg * (Math.PI / 180)

    // Ticks on the inner edge of the arc
    const r1 = 68
    const r2 = 58

    const x1 = 100 + r1 * Math.cos(rad)
    const y1 = 100 - r1 * Math.sin(rad)
    const x2 = 100 + r2 * Math.cos(rad)
    const y2 = 100 - r2 * Math.sin(rad)

    // Text positioning further inside
    const textR = 42
    const textX = 100 + textR * Math.cos(rad)
    const textY = 100 - textR * Math.sin(rad) + (val === 0 || val === 100 ? -2 : 4)

    return { val, x1, y1, x2, y2, textX, textY }
  })

  const gradientId = reverseColors ? `profit-grad-${label.replace(/\s+/g, '')}` : `dd-grad-${label.replace(/\s+/g, '')}`;

  return (
    <div className="bg-[var(--color-gray-950)] p-5 rounded-lg border border-[var(--color-gray-800)] flex flex-col items-center">
      <div className="text-xs text-[var(--color-gray-400)] uppercase font-semibold tracking-wider mb-2 text-center">{label}</div>

      <div className="w-full max-w-[180px] relative mt-4">
        <svg viewBox="0 0 200 100" className="w-full h-auto overflow-visible">
          <defs>
            <linearGradient id={`dd-grad-${label.replace(/\s+/g, '')}`} x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="#00c758" />
              <stop offset="60%" stopColor="#f59e0b" />
              <stop offset="100%" stopColor="#ef4444" />
            </linearGradient>
            <linearGradient id={`profit-grad-${label.replace(/\s+/g, '')}`} x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="#6b7280" />
              <stop offset="50%" stopColor="#3b82f6" />
              <stop offset="100%" stopColor="#00c758" />
            </linearGradient>
            <linearGradient id="needleGradient" x1="0%" y1="0%" x2="0%" y2="100%">
              <stop offset="0%" stopColor="var(--color-gray-100)" />
              <stop offset="100%" stopColor="var(--color-gray-400)" />
            </linearGradient>
          </defs>

          <path
            d="M 20 100 A 80 80 0 0 1 180 100"
            fill="none"
            stroke={`url(#${gradientId})`}
            strokeWidth="16"
            strokeLinecap="round"
          />

          {/* Graduations */}
          {ticks.map((tick) => (
            <g key={tick.val}>
              <line
                x1={tick.x1}
                y1={tick.y1}
                x2={tick.x2}
                y2={tick.y2}
                stroke="var(--color-gray-600)"
                strokeWidth="2"
                strokeLinecap="round"
              />
              <text
                x={tick.textX}
                y={tick.textY}
                fill="var(--color-gray-500)"
                className="text-[10px] font-semibold"
                textAnchor="middle"
                dominantBaseline="middle"
              >
                {tick.val}
              </text>
            </g>
          ))}

          {/* Needle */}
          <g style={{ transformOrigin: '100px 100px', transform: `rotate(${angle}deg)`, transition: 'transform 1s cubic-bezier(0.34, 1.56, 0.64, 1)' }}>
            <polygon
              points="96,100 104,100 100,30"
              fill="url(#needleGradient)"
            />
            <polygon
              points="96,100 104,100 100,30"
              fill="var(--color-gray-100)"
              opacity="0.5"
              filter="blur(4px)"
            />
          </g>

          <circle cx="100" cy="100" r="6" fill="var(--color-gray-200)" />
          <circle cx="100" cy="100" r="2" fill="var(--color-gray-950)" />
        </svg>

        <div className="absolute -bottom-6 inset-x-0 text-center">
          <div className="text-xl font-bold text-[var(--color-gray-100)] leading-none">{pct.toFixed(1)}<span className="text-[0.85rem] text-[var(--color-gray-500)] ml-0.5">%</span></div>
        </div>
      </div>

      <div className="mt-10 flex justify-between w-full border-t border-[var(--color-gray-800)] pt-3">
        <div className="flex flex-col">
          <span className="text-[0.6rem] text-[var(--color-gray-500)] uppercase font-semibold">Used</span>
          <span className="text-[0.85rem] font-semibold text-[var(--color-gray-100)]">{formattedUsed}</span>
        </div>
        <div className="flex flex-col text-right">
          <span className="text-[0.6rem] text-[var(--color-gray-500)] uppercase font-semibold">Limit</span>
          <span className="text-[0.85rem] font-semibold text-[var(--color-gray-400)]">{formattedTotal}</span>
        </div>
      </div>
    </div>
  )
}

export function PropFirmGauges({ challenge }: { challenge: any }) {
  if (!challenge) return null

  const maxDdReference = 
    challenge.template.drawdownType === 'static_balance' ? Number(challenge.initialBalance) :
    challenge.template.drawdownType === 'trailing_balance' ? Number(challenge.highestBalance) :
    Number(challenge.highestEquity)

  const maxDdThreshold = maxDdReference * (1 - Number(challenge.maxDDPct) / 100)
  const maxDdAllowed = maxDdReference - maxDdThreshold
  const maxDdUsed = maxDdReference - Number(challenge.currentEquity)

  const dailyDdThreshold = Number(challenge.todayStartBalance) * (1 - Number(challenge.dailyDDPct) / 100)
  const dailyDdAllowed = Number(challenge.todayStartBalance) - dailyDdThreshold
  const dailyDdUsed = Number(challenge.todayStartBalance) - Number(challenge.currentEquity)

  const profitTarget = Number(challenge.initialBalance) * (Number(challenge.profitTargetPct) / 100)
  const currentProfit = Number(challenge.currentBalance) - Number(challenge.initialBalance)

  return (
    <div className="bg-[var(--color-gray-900)] p-6 rounded-lg border border-[var(--color-gray-800)] h-full flex flex-col">
      <h3 className="text-[0.95rem] font-semibold mb-5 text-[var(--color-gray-100)] border-b border-[var(--color-gray-800)] pb-3 shrink-0">Objectives & Limits</h3>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-2 xl:grid-cols-2 gap-4 flex-1">
        <NeedleGauge 
          label="Daily Drawdown" 
          used={Math.max(0, dailyDdUsed)} 
          total={dailyDdAllowed} 
          isBreached={dailyDdUsed >= dailyDdAllowed} 
        />

        <NeedleGauge 
          label="Max Drawdown" 
          used={Math.max(0, maxDdUsed)} 
          total={maxDdAllowed} 
          isBreached={maxDdUsed >= maxDdAllowed} 
        />

        <NeedleGauge 
          label="Profit Target" 
          used={Math.max(0, currentProfit)} 
          total={profitTarget} 
          isBreached={false}
          reverseColors={true}
        />

        {challenge.minTradingDays ? (
           <NeedleGauge 
             label="Min Trading Days" 
             used={Number(challenge.metadata?.tradingDaysCount || 0)} 
             total={challenge.minTradingDays} 
             isBreached={false} 
             formatCurrency={false}
             reverseColors={true}
           />
        ) : (
           <NeedleGauge 
             label="Trading Days" 
             used={Number(challenge.metadata?.tradingDaysCount || 0)} 
             total={Math.max(1, Number(challenge.metadata?.tradingDaysCount || 0))} 
             isBreached={false} 
             formatCurrency={false}
             reverseColors={true}
           />
        )}
      </div>
    </div>
  )
}

"use client"

import { useCallback, useEffect, useState } from "react"
import { toast } from "sonner"

type CardData = {
  challengeId: string
  firmName: string
  programName: string
  logoUrl: string | null
  accountName: string
  phase: string
  status: string
  initialBalance: number
  currentBalance: number
  currentProfitPct: number
  profitTargetPct: number
  targetProgressPct: number
  maxDDPct: number
  ddUsedPct: number
  tradingDays: number
  minTradingDays: number | null
  daysRemaining: number | null
}

export function ShareCard({ data }: { data: CardData }) {
  const [open, setOpen] = useState(false)
  const [loadingLink, setLoadingLink] = useState(false)
  const [publicUrl, setPublicUrl] = useState<string | null>(null)
  const [logoDataUrl, setLogoDataUrl] = useState<string | null>(null)
  const [preview, setPreview] = useState<string | null>(null)

  // Load logo as a data URL so the SVG stays self-contained for export
  useEffect(() => {
    if (!data.logoUrl) { setLogoDataUrl(null); return }
    let cancelled = false
    fetch(data.logoUrl)
      .then(r => r.blob())
      .then(b => new Promise<string>((res, rej) => {
        const fr = new FileReader()
        fr.onload = () => res(String(fr.result))
        fr.onerror = rej
        fr.readAsDataURL(b)
      }))
      .then(url => { if (!cancelled) setLogoDataUrl(url) })
      .catch(() => { if (!cancelled) setLogoDataUrl(null) })
    return () => { cancelled = true }
  }, [data.logoUrl])

  const buildSvg = useCallback((logo: string | null, scale = 1) => {
    const W = 640, H = 400
    const w = W * scale, h = H * scale
    const statusColor = data.status === "passed" ? "#00c758" : data.status === "breached" || data.status === "failed" ? "#ef4444" : "#8b5cf6"
    const profit = data.currentBalance - data.initialBalance
    const profitColor = profit >= 0 ? "#00c758" : "#ef4444"
    const targetPct = Math.min(100, Math.max(0, data.targetProgressPct))
    const ddPct = Math.min(100, Math.max(0, data.ddUsedPct))
    const ddColor = ddPct >= 80 ? "#ef4444" : ddPct >= 60 ? "#f59e0b" : "#00c758"

    const bar = (x: number, y: number, width: number, pct: number, color: string, label: string, valueLabel: string) => `
      <text x="${x}" y="${y}" font-size="${11 * scale}" fill="#9ca3af" font-family="system-ui, sans-serif">${label}</text>
      <text x="${x + width}" y="${y}" font-size="${11 * scale}" fill="#e5e7eb" font-family="system-ui, sans-serif" text-anchor="end" font-weight="600">${valueLabel}</text>
      <rect x="${x}" y="${y + 6 * scale}" width="${width}" height="${6 * scale}" rx="${3 * scale}" fill="#1f2937"/>
      <rect x="${x}" y="${y + 6 * scale}" width="${Math.min(width, width * pct / 100)}" height="${6 * scale}" rx="${3 * scale}" fill="${color}"/>
    `

    const logoTag = logo
      ? `<image href="${logo}" x="${24 * scale}" y="${24 * scale}" width="${40 * scale}" height="${40 * scale}" preserveAspectRatio="xMidYMid meet"/>`
      : ""

    return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${W} ${H}">
  <defs>
    <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stop-color="#111827"/>
      <stop offset="100%" stop-color="#1f2937"/>
    </linearGradient>
  </defs>
  <rect width="${W}" height="${H}" rx="20" fill="url(#bg)"/>
  <rect x="0" y="${H - 6}" width="${W}" height="6" fill="${statusColor}"/>

  ${logoTag}
  <text x="${logo ? 80 : 24}${scale}" y="${36 * scale}" font-size="${20 * scale}" font-weight="700" fill="#f9fafb" font-family="system-ui, sans-serif">${escapeXml(data.firmName)}</text>
  <text x="${logo ? 80 : 24}${scale}" y="${56 * scale}" font-size="${12 * scale}" fill="#9ca3af" font-family="system-ui, sans-serif">${escapeXml(data.programName)} · ${escapeXml(data.accountName)}</text>

  <rect x="${W - 150 * scale}" y="${22 * scale}" width="${126 * scale}" height="${30 * scale}" rx="${8 * scale}" fill="${statusColor}" opacity="0.15"/>
  <text x="${W - 87 * scale}" y="${42 * scale}" font-size="${13 * scale}" font-weight="700" fill="${statusColor}" text-anchor="middle" font-family="system-ui, sans-serif">${escapeXml(data.status.toUpperCase())}</text>

  <text x="${24 * scale}" y="${110 * scale}" font-size="${13 * scale}" fill="#9ca3af" font-family="system-ui, sans-serif">PROGRESS</text>
  <text x="${W - 24 * scale}" y="${110 * scale}" font-size="${26 * scale}" font-weight="700" fill="${profitColor}" text-anchor="end" font-family="system-ui, sans-serif">${data.currentProfitPct >= 0 ? "+" : ""}${data.currentProfitPct.toFixed(1)}%</text>

  ${bar(24, 140, W - 48, targetPct, "#8b5cf6", `Profit Target (${data.profitTargetPct}%)`, `${targetPct.toFixed(0)}%`)}
  ${bar(24, 185, W - 48, ddPct, ddColor, `Max Drawdown (${data.maxDDPct}%)`, `${ddPct.toFixed(1)}% used`)}

  <text x="${24 * scale}" y="${255 * scale}" font-size="${11 * scale}" fill="#9ca3af" font-family="system-ui, sans-serif">BALANCE</text>
  <text x="${24 * scale}" y="${280 * scale}" font-size="${24 * scale}" font-weight="700" fill="#f9fafb" font-family="system-ui, sans-serif">$${data.currentBalance.toLocaleString("en-US", { maximumFractionDigits: 0 })}</text>

  <text x="${W / 2 * scale}" y="${255 * scale}" font-size="${11 * scale}" fill="#9ca3af" text-anchor="middle" font-family="system-ui, sans-serif">PHASE</text>
  <text x="${W / 2 * scale}" y="${280 * scale}" font-size="${24 * scale}" font-weight="700" fill="#f9fafb" text-anchor="middle" font-family="system-ui, sans-serif">${escapeXml(data.phase.replace('_', ' ').toUpperCase())}</text>

  <text x="${W - 24 * scale}" y="${255 * scale}" font-size="${11 * scale}" fill="#9ca3af" text-anchor="end" font-family="system-ui, sans-serif">TRADING DAYS</text>
  <text x="${W - 24 * scale}" y="${280 * scale}" font-size="${24 * scale}" font-weight="700" fill="#f9fafb" text-anchor="end" font-family="system-ui, sans-serif">${data.tradingDays}${data.minTradingDays ? `/${data.minTradingDays}` : ""}</text>

  <text x="${24 * scale}" y="${330 * scale}" font-size="${11 * scale}" fill="#6b7280" font-family="system-ui, sans-serif">
    Generated with TradeLink${data.daysRemaining !== null ? ` · ${data.daysRemaining} day(s) left on deadline` : ""}
  </text>
</svg>`
  }, [data])

  const generate = useCallback(async () => {
    const svg = buildSvg(logoDataUrl)
    const blob = new Blob([svg], { type: "image/svg+xml;charset=utf-8" })
    const url = URL.createObjectURL(blob)
    setPreview(url)
  }, [buildSvg, logoDataUrl])

  useEffect(() => {
    if (open) generate()
  }, [open, generate])

  const downloadPng = async () => {
    const scale = 2
    const svg = buildSvg(logoDataUrl, scale)
    const blob = new Blob([svg], { type: "image/svg+xml;charset=utf-8" })
    const url = URL.createObjectURL(blob)
    try {
      const img = new Image()
      await new Promise<void>((resolve, reject) => {
        img.onload = () => resolve()
        img.onerror = () => reject(new Error("load failed"))
        img.src = url
      })
      const canvas = document.createElement("canvas")
      canvas.width = 640 * scale
      canvas.height = 400 * scale
      const ctx = canvas.getContext("2d")!
      ctx.drawImage(img, 0, 0)
      const pngUrl = canvas.toDataURL("image/png")
      const a = document.createElement("a")
      a.href = pngUrl
      a.download = `${data.firmName.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-challenge.png`
      a.click()
      toast.success("Progress card downloaded")
    } catch {
      toast.error("Could not generate PNG")
    } finally {
      URL.revokeObjectURL(url)
    }
  }

  const downloadSvg = () => {
    const svg = buildSvg(logoDataUrl)
    const blob = new Blob([svg], { type: "image/svg+xml;charset=utf-8" })
    const url = URL.createObjectURL(blob)
    const a = document.createElement("a")
    a.href = url
    a.download = `${data.firmName.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-challenge.svg`
    a.click()
    URL.revokeObjectURL(url)
    toast.success("Progress card downloaded (SVG)")
  }

  const handleGetLink = async () => {
    if (publicUrl) {
      navigator.clipboard.writeText(window.location.origin + publicUrl)
      toast.success("Link copied to clipboard!")
      return
    }

    setLoadingLink(true)
    try {
      const res = await fetch("/api/share", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ entityType: "challenge", entityId: data.challengeId })
      })
      if (!res.ok) throw new Error("Failed to generate link")
      const json = await res.json()
      setPublicUrl(json.url)
      navigator.clipboard.writeText(window.location.origin + json.url)
      toast.success("Public link copied to clipboard!")
    } catch {
      toast.error("Failed to generate share link")
    } finally {
      setLoadingLink(false)
    }
  }

  return (
    <>
      <button className="btn btn-outline" onClick={() => setOpen(true)} style={{ padding: "0.5rem 1rem", fontSize: "0.85rem" }}>
        Share
      </button>

      {open && (
        <div style={{
          position: "fixed", inset: 0, background: "rgba(0,0,0,0.6)", zIndex: 200,
          display: "flex", alignItems: "center", justifyContent: "center", padding: "1.5rem",
        }} onClick={() => setOpen(false)}>
          <div
            className="chart-card"
            style={{ padding: "1.5rem", maxWidth: 680, width: "100%" }}
            onClick={e => e.stopPropagation()}
          >
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1rem" }}>
              <div style={{ fontWeight: 700 }}>Share progress card</div>
              <button onClick={() => setOpen(false)} style={{ background: "transparent", border: "none", color: "var(--color-gray-400)", cursor: "pointer", fontSize: "1.2rem" }}>×</button>
            </div>

            {preview && (
              // eslint-disable-next-line @next/next/no-img-element
              <img src={preview} alt="Progress card preview" style={{ width: "100%", borderRadius: "12px", marginBottom: "1rem" }} />
            )}

            {publicUrl && (
              <div style={{ marginBottom: "1rem", padding: "0.75rem", background: "rgba(0,199,88,0.1)", border: "1px solid rgba(0,199,88,0.2)", borderRadius: "8px", color: "var(--color-profit)", fontSize: "0.85rem", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{window.location.origin + publicUrl}</span>
                <button onClick={() => {
                  navigator.clipboard.writeText(window.location.origin + publicUrl)
                  toast.success("Copied!")
                }} style={{ background: "none", border: "none", color: "inherit", cursor: "pointer", fontWeight: "bold" }}>Copy</button>
              </div>
            )}

            <div style={{ display: "flex", gap: "0.5rem", justifyContent: "space-between" }}>
              <button className="btn btn-primary" onClick={handleGetLink} disabled={loadingLink} style={{ padding: "0.5rem 1rem", fontSize: "0.85rem" }}>
                {loadingLink ? "Generating..." : publicUrl ? "Copy Public Link" : "Get Public Link"}
              </button>
              <div style={{ display: "flex", gap: "0.5rem" }}>
                <button className="btn btn-outline" onClick={downloadSvg} style={{ padding: "0.5rem 1rem", fontSize: "0.85rem" }}>
                  Download SVG
                </button>
                <button className="btn btn-outline" onClick={downloadPng} style={{ padding: "0.5rem 1rem", fontSize: "0.85rem", background: "rgba(255,255,255,0.05)" }}>
                  Download PNG
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  )
}

function escapeXml(s: string) {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;")
}

"use client"

import React, { useState, useEffect } from "react"
import { toast } from "sonner"

const DRAWDOWN_TYPES = ["static_balance", "trailing_balance", "trailing_equity"]

interface Template {
  id: string
  firmName: string
  programName: string
  drawdownType: string
  dailyDDPct: number | null
  maxDDPct: number | null
