const MONTH_NAMES = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
]

function currentMonth(): string {
  const d = new Date()
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`
}

function monthLabel(month: string): string {
  const [y, m] = month.split("-").map(Number)
  return `${MONTH_NAMES[m - 1]} ${y}`
}

function fmtMoney(v: number, sign = false): string {
  const s = v.toLocaleString("en-US", { minimumFractionDigits: 2 })
  return `${sign && v > 0 ? "+" : ""}$${s}`
}

const P_STATUS: Record<string, { label: string; color: string }> = {
  requested: { label: "Requested", color: "var(--color-warning)" },
  approved: { label: "Approved", color: "var(--color-brand-500)" },
  paid: { label: "Paid", color: "var(--color-profit)" },
  rejected: { label: "Rejected", color: "var(--color-loss)" },
}

const PDF_SECTIONS = [
  { key: "summary", label: "Summary" },
  { key: "daily", label: "Daily P&L" },
  { key: "setups", label: "Top setups" },
  { key: "symbols", label: "Top Symbols" },
  { key: "hours", label: "Hourly Performance" },
  { key: "dow", label: "Day of Week" },
  { key: "payouts", label: "Payouts" },
] as const

type PdfSection = (typeof PDF_SECTIONS)[number]["key"]

export function MonthlyReport() {
  const [month, setMonth] = useState(currentMonth)
  const [data, setData] = useState<MonthlyReportData | null>(null)
  const [loading, setLoading] = useState(true)
  const [pdfSections, setPdfSections] = useState<PdfSection[]>(PDF_SECTIONS.map(s => s.key))
  const [showPdfOptions, setShowPdfOptions] = useState(false)

  const load = useCallback(async (m: string) => {
    setLoading(true)
    try {
      const res = await fetch(`/api/reports/monthly?month=${m}`)
      if (!res.ok) throw new Error("Failed to load")
      setData(await res.json())
    } catch {
      toast.error("Failed to load report")
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    load(month)
  }, [month, load])

  const exportCsv = () => {
    if (!data) return
    const rows = [
      ["date", "pnl", "pnl_usd", "trades"],
      ...data.daily.filter((d: DailyItem) => d.trades > 0).map((d: DailyItem) => [d.date, d.pnl, d.pnlUsd, d.trades]),
    ]
    const csv = rows.map(r => r.join(",")).join("\n")
    const blob = new Blob([csv], { type: "text/csv" })
    const url = URL.createObjectURL(blob)
    const a = document.createElement("a")
    a.href = url
    a.download = `report-${month}.csv`
    a.click()
    URL.revokeObjectURL(url)
  }

  const exportPdf = () => {
    if (!data) return
    const doc = new jsPDF({ orientation: "landscape", unit: "pt", format: "a4" })
    const W = doc.internal.pageSize.getWidth()
    const incl = (k: PdfSection) => pdfSections.includes(k)

    doc.setFillColor(15, 17, 23)
    doc.rect(0, 0, W, 70, "F")
    doc.setTextColor(255, 255, 255)
    doc.setFont("helvetica", "bold")
    doc.setFontSize(18)
    doc.text(`TradeLink — Monthly Report`, 40, 32)
    doc.setFont("helvetica", "normal")
    doc.setFontSize(10)
    doc.setTextColor(200, 200, 210)
    doc.text(monthLabel(month), 40, 50)

    doc.setTextColor(30, 30, 40)
    let y = 90
    const t = data.trades

    if (incl("summary")) {
      doc.setFontSize(13)
      doc.setFont("helvetica", "bold")
      doc.text("Performance Summary", 40, y)
      y += 8
      autoTable(doc, {
        startY: y,
        head: [["Metric", "Value", "Metric", "Value"]],
        body: [
          ["Net P&L", fmtMoney(t.totalPnl, true), "P&L (USD)", fmtMoney(t.totalPnlUsd, true)],
          ["Trades", String(t.total), "Win rate", `${t.winRate.toFixed(1)}%`],
          ["Wins / Losses", `${t.wins} / ${t.losses}`, "Profit factor", t.profitFactor === 99 ? "∞" : t.profitFactor.toFixed(2)],
          ["Expectancy", fmtMoney(t.expectancy, true), "Avg R", t.avgR.toFixed(2)],
          ["Avg win", fmtMoney(t.avgWin, true), "Avg loss", fmtMoney(t.avgLoss, true)],
          ["Best trade", fmtMoney(t.best, true), "Worst trade", fmtMoney(t.worst, true)],
          ["Trading days", String(t.tradingDays), "Avg trades / day", t.avgTradesPerDay.toFixed(1)],
        ],
        theme: "striped",
        styles: { fontSize: 8.5, cellPadding: 5 },
        headStyles: { fillColor: [80, 70, 229], textColor: 255 },
        columnStyles: { 0: { cellWidth: 130 }, 1: { cellWidth: 210 }, 2: { cellWidth: 130 }, 3: { cellWidth: 210 } },
      })

      y = (doc as unknown as JspdfWithAutoTable).lastAutoTable.finalY + 22
    }

    if (incl("daily")) {
      doc.setFontSize(13)
      doc.setFont("helvetica", "bold")
      doc.text("Daily P&L", 40, y)
      y += 8
      const dayRows = data.daily
        .filter((d: DailyItem) => d.trades > 0)
        .map((d: DailyItem) => [
          d.date,
          `${d.pnl >= 0 ? "+" : ""}$${d.pnl.toLocaleString("en-US", { minimumFractionDigits: 2 })}`,
          `${d.cumPnl >= 0 ? "+" : ""}$${d.cumPnl.toLocaleString("en-US", { minimumFractionDigits: 2 })}`,
          String(d.trades),
        ])
      autoTable(doc, {
        startY: y,
        head: [["Date", "P&L", "Cumulative", "Trades"]],
        body: dayRows,
        theme: "striped",
        styles: { fontSize: 8.5, cellPadding: 4 },
        headStyles: { fillColor: [80, 70, 229], textColor: 255 },
        columnStyles: { 0: { cellWidth: 90 }, 1: { cellWidth: 150, halign: "right" }, 2: { cellWidth: 150, halign: "right" }, 3: { cellWidth: 70, halign: "right" } },
      })

      y = (doc as unknown as JspdfWithAutoTable).lastAutoTable.finalY + 22
    }

    if (incl("setups") && data.setups.length > 0) {
      doc.setFontSize(13)
      doc.setFont("helvetica", "bold")
      doc.text("Top Setups", 40, y)
      y += 8
      autoTable(doc, {
        startY: y,
        head: [["Setup", "Trades", "Wins", "Win rate", "P&L"]],
        body: data.setups.map((s: SetupItem) => [s.name, String(s.count), String(s.wins), s.count > 0 ? `${((s.wins / s.count) * 100).toFixed(0)}%` : "—", fmtMoney(s.pnl, true)]),
        theme: "striped",
        styles: { fontSize: 8.5, cellPadding: 4 },
        headStyles: { fillColor: [80, 70, 229], textColor: 255 },
        columnStyles: { 0: { cellWidth: 200 }, 1: { cellWidth: 70, halign: "right" }, 2: { cellWidth: 70, halign: "right" }, 3: { cellWidth: 70, halign: "right" }, 4: { cellWidth: 110, halign: "right" } },
      })
      y = (doc as unknown as JspdfWithAutoTable).lastAutoTable.finalY + 22
    }

    if (incl("symbols") && data.symbols.length > 0) {
      doc.setFontSize(13)
      doc.setFont("helvetica", "bold")
      doc.text("Top Symbols", 40, y)
      y += 8
      autoTable(doc, {
        startY: y,
        head: [["Symbol", "Trades", "P&L"]],
        body: data.symbols.map((s: SymbolItem) => [s.symbol, String(s.count), fmtMoney(s.pnl, true)]),
        theme: "striped",
        styles: { fontSize: 8.5, cellPadding: 4 },
        headStyles: { fillColor: [80, 70, 229], textColor: 255 },
        columnStyles: { 0: { cellWidth: 140 }, 1: { cellWidth: 90, halign: "right" }, 2: { cellWidth: 130, halign: "right" } },
      })
      y = (doc as unknown as JspdfWithAutoTable).lastAutoTable.finalY + 22
    }

    if (incl("hours") && data.hours.length > 0) {
      doc.setFontSize(13)
      doc.setFont("helvetica", "bold")
      doc.text("Performance by Hour", 40, y)
      y += 8
      autoTable(doc, {
        startY: y,
        head: [["Hour", "Trades", "Wins", "P&L"]],
        body: data.hours.map((h: HourItem) => [`${h.hour}:00`, String(h.count), String(h.wins), fmtMoney(h.pnl, true)]),
        theme: "striped",
        styles: { fontSize: 8.5, cellPadding: 4 },
        headStyles: { fillColor: [80, 70, 229], textColor: 255 },
        columnStyles: { 0: { cellWidth: 90 }, 1: { cellWidth: 90, halign: "right" }, 2: { cellWidth: 90, halign: "right" }, 3: { cellWidth: 130, halign: "right" } },
      })
      y = (doc as unknown as JspdfWithAutoTable).lastAutoTable.finalY + 22
    }

    if (incl("dow") && data.dow.length > 0) {
      doc.setFontSize(13)
      doc.setFont("helvetica", "bold")
      doc.text("Performance by Day", 40, y)
      y += 8
      autoTable(doc, {
        startY: y,
        head: [["Day", "Trades", "Wins", "P&L"]],
        body: data.dow.map((d: DowItem) => [d.name, String(d.count), String(d.wins), fmtMoney(d.pnl, true)]),
        theme: "striped",
        styles: { fontSize: 8.5, cellPadding: 4 },
        headStyles: { fillColor: [80, 70, 229], textColor: 255 },
        columnStyles: { 0: { cellWidth: 110 }, 1: { cellWidth: 90, halign: "right" }, 2: { cellWidth: 90, halign: "right" }, 3: { cellWidth: 130, halign: "right" } },
      })
      y = (doc as unknown as JspdfWithAutoTable).lastAutoTable.finalY + 22
    }

    if (incl("payouts") && data.payouts.length > 0) {
      doc.setFontSize(13)
      doc.setFont("helvetica", "bold")
      doc.text("Payouts", 40, y)
      y += 8
      autoTable(doc, {
        startY: y,
        head: [["Firm", "Account", "Amount", "Status", "Date"]],
        body: data.payouts.map((p: PayoutItem) => [
          p.firmName,
          p.accountName,
          fmtMoney(p.amount),
          p.status,
          new Date(p.requestedAt).toLocaleDateString("en-US"),
        ]),
        theme: "striped",
        styles: { fontSize: 8.5, cellPadding: 4 },
        headStyles: { fillColor: [80, 70, 229], textColor: 255 },
        columnStyles: { 0: { cellWidth: 160 }, 1: { cellWidth: 160 }, 2: { cellWidth: 110, halign: "right" }, 3: { cellWidth: 90 }, 4: { cellWidth: 90 } },
      })
    }

    doc.save(`tradelink-report-${month}.pdf`)
    toast.success("PDF report downloaded")
  }

  const togglePdfSection = (k: PdfSection) => {
    setPdfSections(prev => (prev.includes(k) ? prev.filter(x => x !== k) : [...prev, k]))
  }

  const t = data?.trades as TradeSummary
  const daily = data?.daily || []
  const dayShort = daily.map(d => ({
    ...d,
    label: d.date.slice(5),
  }))

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "1.75rem" }}>
      {/* Header */}
      <div className="page-header">
        <div>
          <h1 className="page-title">Monthly Report</h1>
          <p className="page-subtitle">Performance summary for a single month.</p>
        </div>
        <div style={{ display: "flex", gap: "0.5rem", alignItems: "center", flexWrap: "wrap" }}>
          <input
            type="month"
            className="input"
            value={month}
            onChange={e => e.target.value && setMonth(e.target.value)}
            style={{ width: 170 }}
          />
          <button className="btn btn-outline" onClick={exportCsv} disabled={!data}>
            <Download size={15} /> CSV
          </button>
          <div style={{ position: "relative" }}>
            <button className="btn btn-outline" onClick={() => setShowPdfOptions(v => !v)} disabled={!data}>
              <FileText size={15} /> PDF
            </button>
            {showPdfOptions && (
              <div
                style={{
                  position: "absolute", right: 0, top: "calc(100% + 6px)", zIndex: 40,
                  background: "var(--color-gray-900)", border: "1px solid var(--color-gray-700)",
                  borderRadius: "10px", padding: "0.75rem", minWidth: 180, boxShadow: "0 10px 30px rgba(0,0,0,0.4)",
                }}
              >
                <div style={{ fontSize: "0.7rem", fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.04em", color: "var(--color-gray-500)", marginBottom: "0.5rem" }}>
                  Include in PDF
                </div>
                <div style={{ display: "flex", flexDirection: "column", gap: "0.35rem" }}>
                  {PDF_SECTIONS.map(s => (
                    <label key={s.key} style={{ display: "flex", alignItems: "center", gap: "0.5rem", fontSize: "0.82rem", color: "var(--color-gray-300)", cursor: "pointer" }}>
                      <input
                        type="checkbox"
                        checked={pdfSections.includes(s.key)}
                        onChange={() => togglePdfSection(s.key)}
                        style={{ accentColor: "var(--color-brand-500)" }}
                      />
                      {s.label}
                    </label>
                  ))}
                </div>
                <button
                  className="btn btn-primary"
                  style={{ marginTop: "0.6rem", width: "100%" }}
                  onClick={() => { setShowPdfOptions(false); exportPdf() }}
                  disabled={pdfSections.length === 0}
                >
                  <FileText size={14} /> Download
                </button>
              </div>
            )}
          </div>
        </div>
      </div>

      {loading ? (
        <div className="skeleton" style={{ height: 300 }} />
      ) : !data ? (
        <div className="empty-state">Unable to load report.</div>
      ) : (
        <motion.div 
          variants={containerVariants}
          initial="hidden"
          animate="visible"
          style={{ display: "flex", flexDirection: "column", gap: "1.75rem" }}
        >
          {/* Month title */}
          <motion.div variants={itemVariants} style={{ fontSize: "1.05rem", fontWeight: 700, color: "var(--color-gray-100)" }}>
            {monthLabel(month)}
            <span style={{ fontSize: "0.85rem", fontWeight: 400, color: "var(--color-gray-500)", marginLeft: "0.75rem" }}>
              {t.total} trades · {t.tradingDays} trading days
            </span>
          </motion.div>

          {/* KPIs */}
          <motion.div variants={itemVariants} style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: "1rem" }}>
            <div className="kpi-card" style={{ display: "flex", flexDirection: "column", gap: "0.4rem" }}>
              <div className="kpi-label">Net P&L</div>
              <div className="kpi-value" style={{ color: t.totalPnl >= 0 ? "var(--color-profit)" : "var(--color-loss)" }}>
                {fmtMoney(t.totalPnl, true)}
              </div>
              <div className="kpi-sub">in USD: {fmtMoney(t.totalPnlUsd, true)}</div>
            </div>
            <div className="kpi-card" style={{ display: "flex", flexDirection: "column", gap: "0.4rem" }}>
              <div className="kpi-label">Win rate</div>
              <div className="kpi-value">{t.winRate.toFixed(1)}%</div>
              <div className="kpi-sub">{t.wins}W / {t.losses}L / {t.breakeven} BE</div>
            </div>
            <div className="kpi-card" style={{ display: "flex", flexDirection: "column", gap: "0.4rem" }}>
              <div className="kpi-label">Profit factor</div>
              <div className="kpi-value" style={{ color: t.profitFactor >= 2 ? "var(--color-profit)" : t.profitFactor >= 1 ? "var(--color-warning)" : "var(--color-loss)" }}>
                {t.profitFactor === 99 ? "∞" : t.profitFactor.toFixed(2)}
              </div>
              <div className="kpi-sub">avg R: {t.avgR.toFixed(2)}</div>
            </div>
            <div className="kpi-card" style={{ display: "flex", flexDirection: "column", gap: "0.4rem" }}>
              <div className="kpi-label">Expectancy / trade</div>
              <div className="kpi-value" style={{ color: t.expectancy >= 0 ? "var(--color-profit)" : "var(--color-loss)" }}>
                {fmtMoney(t.expectancy, true)}
              </div>
              <div className="kpi-sub">avg win {fmtMoney(t.avgWin, true)} · avg loss {fmtMoney(t.avgLoss, true)}</div>
            </div>
            <div className="kpi-card" style={{ display: "flex", flexDirection: "column", gap: "0.4rem" }}>
              <div className="kpi-label">Best / Worst</div>
              <div className="kpi-value" style={{ fontSize: "1.1rem", color: t.best >= 0 ? "var(--color-profit)" : "var(--color-gray-100)" }}>
                {fmtMoney(t.best, true)}
              </div>
              <div className="kpi-sub" style={{ color: t.worst <= 0 ? "var(--color-loss)" : "var(--color-gray-500)" }}>
                {fmtMoney(t.worst, true)}
              </div>
            </div>
          </motion.div>

          {/* Daily chart */}
          <motion.div variants={itemVariants} className="chart-card">
            <div className="chart-title">Daily P&L and cumulative</div>
            <ResponsiveContainer width="100%" height={260}>
              <ComposedChart data={dayShort} margin={{ top: 4, right: 8, bottom: 0, left: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="var(--color-gray-800)" vertical={false} />
                <XAxis dataKey="label" tick={{ fontSize: 9, fill: "var(--color-gray-500)" }} interval="preserveStartEnd" minTickGap={24} />
                <YAxis yAxisId="pnl" tick={{ fontSize: 10, fill: "var(--color-gray-500)" }} width={60} />
                <YAxis yAxisId="cum" orientation="right" tick={{ fontSize: 10, fill: "var(--color-gray-500)" }} width={60} />
                <Tooltip
                  contentStyle={{ background: "var(--color-gray-900)", border: "1px solid var(--color-gray-700)", borderRadius: "8px", fontSize: "0.8rem" }}
                  labelStyle={{ color: "var(--color-gray-300)" }}
                  formatter={(value, name) => [
                    fmtMoney(Number(value), true),
                    name === "cumPnl" ? "Cumulative" : "Daily P&L",
                  ]}
                />
                <ReferenceLine yAxisId="pnl" y={0} stroke="var(--color-gray-600)" />
                <Bar yAxisId="pnl" dataKey="pnl" radius={[3, 3, 0, 0]}>
                  {dayShort.map((d, i) => (
                    <Cell key={i} fill={d.pnl >= 0 ? "var(--color-profit)" : "var(--color-loss)"} />
                  ))}
                </Bar>
                <Line yAxisId="cum" type="monotone" dataKey="cumPnl" stroke="var(--color-brand-500)" strokeWidth={2} dot={false} />
              </ComposedChart>
            </ResponsiveContainer>
          </motion.div>

          {/* Setups + Symbols */}
          <motion.div variants={itemVariants} style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(320px, 1fr))", gap: "1.5rem" }}>
            <div className="chart-card">
              <div className="chart-title">Top Setups</div>
              {data.setups.length === 0 ? (
                <div style={{ color: "var(--color-gray-500)", fontSize: "0.85rem" }}>No setups this month.</div>
              ) : (
                <div style={{ display: "flex", flexDirection: "column", gap: "0.6rem" }}>
                  {data.setups.slice(0, 8).map((s: SetupItem) => (
                    <div key={s.name} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: "0.5rem" }}>
                      <span style={{ fontSize: "0.85rem", color: "var(--color-gray-300)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                        {s.name}
                        <span style={{ color: "var(--color-gray-500)", marginLeft: "0.35rem", fontSize: "0.75rem" }}>
                          {s.count} · {s.wins}W
                        </span>
                      </span>
                      <span style={{ fontSize: "0.85rem", fontWeight: 600, color: s.pnl >= 0 ? "var(--color-profit)" : "var(--color-loss)", whiteSpace: "nowrap" }}>
                        {fmtMoney(s.pnl, true)}
                      </span>
                    </div>
                  ))}
                </div>
              )}
            </div>
            <div className="chart-card">
              <div className="chart-title">Top Symbols</div>
              {data.symbols.length === 0 ? (
                <div style={{ color: "var(--color-gray-500)", fontSize: "0.85rem" }}>No symbols this month.</div>
              ) : (
                <div style={{ display: "flex", flexDirection: "column", gap: "0.6rem" }}>
                  {data.symbols.slice(0, 8).map((s: SymbolItem) => (
                    <div key={s.symbol} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: "0.5rem" }}>
                      <span style={{ fontSize: "0.85rem", color: "var(--color-gray-300)", whiteSpace: "nowrap" }}>
                        {s.symbol}
                        <span style={{ color: "var(--color-gray-500)", marginLeft: "0.35rem", fontSize: "0.75rem" }}>{s.count} trades</span>
                      </span>
                      <span style={{ fontSize: "0.85rem", fontWeight: 600, color: s.pnl >= 0 ? "var(--color-profit)" : "var(--color-loss)", whiteSpace: "nowrap" }}>
                        {fmtMoney(s.pnl, true)}
                      </span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </motion.div>

          {/* Hours + Days of week */}
          <motion.div variants={itemVariants} style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(320px, 1fr))", gap: "1.5rem" }}>
            <div className="chart-card">
              <div className="chart-title">Performance by hour</div>
              {data.hours.length === 0 ? (
                <div style={{ color: "var(--color-gray-500)", fontSize: "0.85rem" }}>No trades this month.</div>
              ) : (
                <ResponsiveContainer width="100%" height={200}>
                  <BarChart data={data.hours} margin={{ top: 4, right: 8, bottom: 0, left: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke="var(--color-gray-800)" vertical={false} />
                    <XAxis dataKey="hour" tick={{ fontSize: 9, fill: "var(--color-gray-500)" }} tickFormatter={(v: number) => `${v}:00`} />
                    <YAxis tick={{ fontSize: 10, fill: "var(--color-gray-500)" }} width={52} />
                    <Tooltip
                      contentStyle={{ background: "var(--color-gray-900)", border: "1px solid var(--color-gray-700)", borderRadius: "8px", fontSize: "0.8rem" }}
                      labelStyle={{ color: "var(--color-gray-300)" }}
                      labelFormatter={(v) => `${v}:00`}
                      formatter={(value, name) => [fmtMoney(Number(value), true), name === "wins" ? "Wins" : "P&L"]}
                    />
                    <Bar dataKey="pnl" radius={[3, 3, 0, 0]}>
                      {data.hours.map((h: HourItem, i: number) => (
                        <Cell key={i} fill={h.pnl >= 0 ? "var(--color-profit)" : "var(--color-loss)"} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              )}
            </div>
            <div className="chart-card">
              <div className="chart-title">Performance by day of week</div>
              {data.dow.length === 0 ? (
                <div style={{ color: "var(--color-gray-500)", fontSize: "0.85rem" }}>No trades this month.</div>
              ) : (
                <div style={{ display: "flex", flexDirection: "column", gap: "0.6rem" }}>
                  {data.dow.map((d: DowItem) => (
                    <div key={d.dow} style={{ display: "flex", alignItems: "center", gap: "0.75rem" }}>
                      <span style={{ width: 90, fontSize: "0.85rem", color: "var(--color-gray-300)", flexShrink: 0 }}>{d.name}</span>
                      <div style={{ flex: 1, height: 16, background: "var(--color-gray-800)", borderRadius: 4, overflow: "hidden", position: "relative" }}>
                        <div
                          style={{
                            height: "100%", borderRadius: 4,
                            width: `${Math.max(2, Math.min(100, (Math.abs(d.pnl) / Math.max(...data.dow.map((x: DowItem) => Math.abs(x.pnl)))) * 100))}%`,
                            background: d.pnl >= 0 ? "var(--color-profit)" : "var(--color-loss)",
                            opacity: 0.85,
                          }}
                        />
                      </div>
                      <span style={{ width: 90, fontSize: "0.82rem", fontWeight: 600, textAlign: "right", color: d.pnl >= 0 ? "var(--color-profit)" : "var(--color-loss)", flexShrink: 0 }}>
                        {fmtMoney(d.pnl, true)}
                      </span>
                      <span style={{ width: 46, fontSize: "0.75rem", color: "var(--color-gray-500)", textAlign: "right", flexShrink: 0 }}>{d.count} tr</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </motion.div>

          {/* Challenges + Payouts */}
          <motion.div variants={itemVariants} style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(320px, 1fr))", gap: "1.5rem" }}>
            <div className="chart-card">
              <div className="chart-title">Challenges</div>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0.75rem" }}>
                <div>
                  <div className="kpi-label">Started</div>
                  <div style={{ fontSize: "1.3rem", fontWeight: 700, color: "var(--color-gray-100)" }}>{data.challenges.startedCount}</div>
                  {data.challenges.startedCost > 0 && (
                    <div style={{ fontSize: "0.7rem", color: "var(--color-gray-500)" }}>cost {fmtMoney(data.challenges.startedCost)}</div>
                  )}
                </div>
                <div>
                  <div className="kpi-label">Passed</div>
                  <div style={{ fontSize: "1.3rem", fontWeight: 700, color: "var(--color-profit)" }}>{data.challenges.passed}</div>
                </div>
                <div>
                  <div className="kpi-label">Breached</div>
                  <div style={{ fontSize: "1.3rem", fontWeight: 700, color: "var(--color-loss)" }}>{data.challenges.breached}</div>
                </div>
                <div>
                  <div className="kpi-label">Still active</div>
                  <div style={{ fontSize: "1.3rem", fontWeight: 700, color: "var(--color-brand-500)" }}>{data.challenges.active}</div>
                </div>
              </div>
            </div>
            <div className="chart-card">
              <div className="chart-title">Payouts</div>
              {data.payouts.length === 0 ? (
                <div style={{ color: "var(--color-gray-500)", fontSize: "0.85rem" }}>No payouts this month.</div>
              ) : (
                <div style={{ display: "flex", flexDirection: "column", gap: "0.6rem" }}>
                  <div style={{ display: "flex", gap: "1.25rem", marginBottom: "0.25rem" }}>
                    <div>
                      <div className="kpi-label">Total</div>
                      <div style={{ fontSize: "1.15rem", fontWeight: 700, color: "var(--color-gray-100)" }}>{fmtMoney(data.payoutsTotals.amount)}</div>
                    </div>
                    <div>
                      <div className="kpi-label">Paid</div>
                      <div style={{ fontSize: "1.15rem", fontWeight: 700, color: "var(--color-profit)" }}>{fmtMoney(data.payoutsTotals.paidAmount)}</div>
                    </div>
                  </div>
                  {data.payouts.slice(0, 6).map((p: PayoutItem, i: number) => {
                    const st = P_STATUS[p.status] || { label: p.status, color: "var(--color-gray-400)" }
                    return (
                      <div key={i} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: "0.5rem", fontSize: "0.82rem" }}>
                        <span style={{ display: "inline-flex", alignItems: "center", gap: "0.4rem", color: "var(--color-gray-300)", minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                          {p.logoUrl && (
                            <span style={{ width: 16, height: 16, borderRadius: 3, overflow: "hidden", background: "var(--color-gray-800)", display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                              {/* eslint-disable-next-line @next/next/no-img-element */}
                              <img src={p.logoUrl} alt="" style={{ maxWidth: "100%", maxHeight: "100%", objectFit: "contain" }} />
                            </span>
                          )}
                          {p.firmName} — {p.accountName}
                        </span>
                        <span style={{ display: "inline-flex", alignItems: "center", gap: "0.5rem", flexShrink: 0 }}>
                          <span style={{ fontWeight: 600, color: "var(--color-gray-100)" }}>{fmtMoney(p.amount)}</span>
                          <span className="badge" style={{ background: `${st.color}22`, color: st.color, border: `1px solid ${st.color}40` }}>
                            {st.label}
                          </span>
                        </span>
                      </div>
                    )
                  })}
                </div>
              )}
            </div>
          </motion.div>
        </motion.div>
      )}
    </div>
  )
}

"use client"

import { useState, useEffect, useMemo } from "react"
import { Calculator, ShieldAlert, Settings2, AlertTriangle, Info, Save } from "lucide-react"
import { toast } from "sonner"

type RiskStatus = {
  prefs: { dailyLossLimit: number | null; maxTradesPerDay: number | null; maxConsecutiveLosses: number | null; maxRiskPerTradePct: number | null }
  today: { pnl: number; trades: number; consecutiveLosses: number }
  weekPnl: number
  baseCurrency: string
  alerts: { severity: "critical" | "warning" | "info"; message: string }[]
}

export function RiskManager() {
  const [accounts, setAccounts] = useState<any[]>([])
  const [status, setStatus] = useState<RiskStatus | null>(null)

  // Calculator inputs
  const [calcAccount, setCalcAccount] = useState("")
  const [calcBalance, setCalcBalance] = useState("100000")
  const [riskPct, setRiskPct] = useState("1")
  const [entryPrice, setEntryPrice] = useState("")
  const [stopPrice, setStopPrice] = useState("")

  // Limits form
  const [dailyLossLimit, setDailyLossLimit] = useState("")
  const [maxTradesPerDay, setMaxTradesPerDay] = useState("")
  const [maxConsecutiveLosses, setMaxConsecutiveLosses] = useState("")
  const [maxRiskPerTradePct, setMaxRiskPerTradePct] = useState("1")
  const [saving, setSaving] = useState(false)

  useEffect(() => {
    fetch("/api/accounts")
      .then(r => r.json())
      .then(d => {
        if (d.accounts) {
          setAccounts(d.accounts)
          const active = d.accounts.find((a: any) => a.isActive) || d.accounts[0]
          if (active) {
            setCalcAccount(active.id)
            setCalcBalance(String(Number(active.initialBalance ?? 0) || 100000))
          }
        }
      })
      .catch(() => {})

    fetch(`/api/risk/status${window.location.search}`)
      .then(r => r.json())
      .then(d => {
        setStatus(d)
        setDailyLossLimit(d.prefs.dailyLossLimit != null ? String(d.prefs.dailyLossLimit) : "")
        setMaxTradesPerDay(d.prefs.maxTradesPerDay != null ? String(d.prefs.maxTradesPerDay) : "")
        setMaxConsecutiveLosses(d.prefs.maxConsecutiveLosses != null ? String(d.prefs.maxConsecutiveLosses) : "")
        setMaxRiskPerTradePct(d.prefs.maxRiskPerTradePct != null ? String(d.prefs.maxRiskPerTradePct) : "1")
      })
      .catch(() => {})
  }, [])

  const handleAccountChange = (id: string) => {
    setCalcAccount(id)
    const acc = accounts.find(a => a.id === id)
    if (acc) setCalcBalance(String(Number(acc.initialBalance ?? 0) || 100000))
  }

  const calc = useMemo(() => {
    const bal = Number(calcBalance) || 0
    const risk = (Number(riskPct) || 0) / 100
    const riskAmount = bal * risk
    const entry = Number(entryPrice)
    const stop = Number(stopPrice)
    let size: number | null = null
    let stopDist = 0
    let maxRiskPct = 0
    let maxRiskAmount = 0
    if (entry > 0 && stop > 0) {
      stopDist = Math.abs(entry - stop)
      size = stopDist > 0 ? riskAmount / stopDist : null
    }
    const riskLimitPct = status?.prefs.maxRiskPerTradePct ?? 1
    if (bal > 0 && riskLimitPct > 0) {
      maxRiskAmount = bal * (riskLimitPct / 100)
      maxRiskPct = maxRiskAmount > 0 ? (riskAmount / maxRiskAmount) * 100 : 0
    }
    return { riskAmount, size, stopDist, maxRiskAmount, maxRiskPct, bal }
  }, [calcBalance, riskPct, entryPrice, stopPrice, status])

  const savePrefs = async () => {
    setSaving(true)
    try {
      const res = await fetch("/api/risk/prefs", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          dailyLossLimit: dailyLossLimit,
          maxTradesPerDay: maxTradesPerDay,
          maxConsecutiveLosses: maxConsecutiveLosses,
          maxRiskPerTradePct: maxRiskPerTradePct,
        }),
      })
      if (!res.ok) throw new Error("Failed to save")
      toast.success("Risk limits saved")
      const s = await fetch(`/api/risk/status${window.location.search}`).then(r => r.json())
      setStatus(s)
    } catch {
      toast.error("Failed to save risk limits")
    } finally {
      setSaving(false)
    }
  }

  const currency = status?.baseCurrency || "USD"
  const fmt = (v: number, sign = false) =>
    `${sign && v > 0 ? "+" : ""}${v.toLocaleString("en-US", { style: "currency", currency, minimumFractionDigits: 2 })}`

  const dailyUsedPct = status?.prefs.dailyLossLimit && status.prefs.dailyLossLimit !== 0
    ? Math.min(100, (Math.max(0, status.today.pnl) / Math.abs(status.prefs.dailyLossLimit)) * 0) || Math.min(100, (Math.abs(Math.min(0, status.today.pnl)) / Math.abs(status.prefs.dailyLossLimit)) * 100)
    : 0

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "1.5rem" }}>

      {/* Alerts */}
      {status && status.alerts.length > 0 && (
        <div style={{ display: "flex", flexDirection: "column", gap: "0.6rem" }}>
          {status.alerts.map((a, i) => (
            <div
              key={i}
              style={{
                display: "flex", alignItems: "flex-start", gap: "0.6rem", padding: "0.75rem 1rem", borderRadius: "8px",
                background: a.severity === "critical" ? "rgba(239,68,68,0.08)" : a.severity === "warning" ? "rgba(245,158,11,0.08)" : "rgba(59,130,246,0.08)",
                border: `1px solid ${a.severity === "critical" ? "rgba(239,68,68,0.35)" : a.severity === "warning" ? "rgba(245,158,11,0.35)" : "rgba(59,130,246,0.35)"}`,
                fontSize: "0.85rem", color: "var(--color-gray-200)",
              }}
            >
              {a.severity === "critical" ? <ShieldAlert size={16} style={{ color: "var(--color-loss)", marginTop: 1 }} />
                : a.severity === "warning" ? <AlertTriangle size={16} style={{ color: "var(--color-warning)", marginTop: 1 }} />
                : <Info size={16} style={{ color: "var(--color-info)", marginTop: 1 }} />}
              <span>{a.message}</span>
            </div>
          ))}
        </div>
      )}

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(600px, 1fr))", gap: "1.5rem", alignItems: "start" }}>

        {/* ── Live risk status ── */}
        <div className="chart-card" style={{ padding: "1.5rem" }}>
          <div style={{ display: "flex", alignItems: "center", gap: "0.5rem", marginBottom: "1rem" }}>
            <ShieldAlert size={16} style={{ color: "var(--color-brand-500)" }} />
            <h2 style={{ fontSize: "1.05rem", fontWeight: 700, color: "var(--color-gray-100)" }}>Live Risk Status</h2>
          </div>

          {!status ? (
            <div className="skeleton" style={{ height: 120 }} />
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: "1.25rem" }}>
              {/* Daily loss limit */}
              <div>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "0.35rem" }}>
                  <span style={{ fontSize: "0.78rem", fontWeight: 600, color: "var(--color-gray-400)" }}>Daily loss budget</span>
                  <span style={{ fontSize: "0.78rem", fontWeight: 700, color: status.prefs.dailyLossLimit != null ? (Math.abs(status.today.pnl) / Math.abs(status.prefs.dailyLossLimit) > 0.7 ? "var(--color-loss)" : "var(--color-gray-200)") : "var(--color-gray-600)" }}>
                    {status.today.pnl <= 0 ? Math.abs(status.today.pnl).toFixed(0) : 0} / {status.prefs.dailyLossLimit != null ? Math.abs(status.prefs.dailyLossLimit) : "∞"} {currency}
                  </span>
                </div>
                <div style={{ background: "var(--color-gray-800)", borderRadius: 6, height: 8, overflow: "hidden" }}>
                  <div style={{
                    height: "100%", width: `${dailyUsedPct}%`, borderRadius: 6, transition: "width 400ms ease",
                    background: dailyUsedPct >= 100 ? "var(--color-loss)" : dailyUsedPct >= 70 ? "var(--color-warning)" : "var(--color-profit)",
                  }} />
                </div>
                {status.prefs.dailyLossLimit != null && (
                  <div style={{ fontSize: "0.7rem", color: "var(--color-gray-500)", marginTop: "0.25rem" }}>
                    {status.today.pnl > 0 ? "No losses today yet." : `${Math.round(dailyUsedPct)}% of your daily loss budget used.`}
                  </div>
                )}
              </div>

              {/* Trades today */}
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: "0.75rem" }}>
                <MiniStat label="Trades today" value={`${status.today.trades}`} sub={status.prefs.maxTradesPerDay != null ? `limit ${status.prefs.maxTradesPerDay}` : "no limit"} />
                <MiniStat label="P&L today" value={fmt(status.today.pnl, true)} color={status.today.pnl > 0 ? "var(--color-profit)" : status.today.pnl < 0 ? "var(--color-loss)" : "var(--color-gray-200)"} />
                <MiniStat label="Week P&L" value={fmt(status.weekPnl, true)} color={status.weekPnl > 0 ? "var(--color-profit)" : status.weekPnl < 0 ? "var(--color-loss)" : "var(--color-gray-200)"} />
              </div>

              {/* Consecutive losses */}
              <div style={{ display: "flex", alignItems: "center", gap: "0.75rem", padding: "0.75rem", borderRadius: "8px", background: "var(--color-gray-900)", border: "1px solid var(--color-gray-800)" }}>
                <div style={{ fontSize: "1.6rem", fontWeight: 800, color: status.today.consecutiveLosses >= 3 ? "var(--color-loss)" : status.today.consecutiveLosses >= 2 ? "var(--color-warning)" : "var(--color-gray-300)" }}>
                  {status.today.consecutiveLosses}
                </div>
                <div>
                  <div style={{ fontSize: "0.72rem", fontWeight: 700, color: "var(--color-gray-400)" }}>Consecutive losses</div>
                  <div style={{ fontSize: "0.7rem", color: "var(--color-gray-500)" }}>
                    {status.prefs.maxConsecutiveLosses != null ? `limit ${status.prefs.maxConsecutiveLosses}` : "no limit set"}
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* ── Risk limits settings ── */}
        <div className="chart-card" style={{ padding: "1.5rem" }}>
          <div style={{ display: "flex", alignItems: "center", gap: "0.5rem", marginBottom: "1rem" }}>
            <Settings2 size={16} style={{ color: "var(--color-brand-500)" }} />
            <h2 style={{ fontSize: "1.05rem", fontWeight: 700, color: "var(--color-gray-100)" }}>Daily Risk Limits</h2>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0.9rem" }}>
            <div className="form-group">
              <label className="label">Daily loss limit ({currency})</label>
              <input className="input" type="number" value={dailyLossLimit} onChange={e => setDailyLossLimit(e.target.value)} placeholder="e.g. 500" />
            </div>
            <div className="form-group">
              <label className="label">Max trades / day</label>
              <input className="input" type="number" value={maxTradesPerDay} onChange={e => setMaxTradesPerDay(e.target.value)} placeholder="e.g. 5" />
            </div>
            <div className="form-group">
              <label className="label">Max consecutive losses</label>
              <input className="input" type="number" value={maxConsecutiveLosses} onChange={e => setMaxConsecutiveLosses(e.target.value)} placeholder="e.g. 3" />
            </div>
            <div className="form-group">
              <label className="label">Max risk / trade (%)</label>
              <input className="input" type="number" step="0.1" min="0.1" max="5" value={maxRiskPerTradePct} onChange={e => setMaxRiskPerTradePct(e.target.value)} placeholder="e.g. 1" />
            </div>
          </div>
          <div style={{ display: "flex", justifyContent: "flex-end", marginTop: "1rem" }}>
            <button className="btn btn-primary" onClick={savePrefs} disabled={saving} style={{ display: "flex", alignItems: "center", gap: "0.4rem" }}>
              <Save size={15} /> {saving ? "Saving…" : "Save limits"}
            </button>
          </div>
        </div>
      </div>

      {/* ── Position size calculator ── */}
      <div className="chart-card" style={{ padding: "1.5rem" }}>
        <div style={{ display: "flex", alignItems: "center", gap: "0.5rem", marginBottom: "1.25rem" }}>
          <Calculator size={16} style={{ color: "var(--color-brand-500)" }} />
          <h2 style={{ fontSize: "1.05rem", fontWeight: 700, color: "var(--color-gray-100)" }}>Position Size Calculator</h2>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(170px, 1fr))", gap: "0.9rem", marginBottom: "1.5rem" }}>
          <div className="form-group">
            <label className="label">Account</label>
            <select className="input select" value={calcAccount} onChange={e => handleAccountChange(e.target.value)}>
              <option value="" disabled>Select account</option>
              {accounts.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
            </select>
          </div>
          <div className="form-group">
            <label className="label">Balance ({currency})</label>
            <input className="input" type="number" value={calcBalance} onChange={e => setCalcBalance(e.target.value)} />
          </div>
          <div className="form-group">
            <label className="label">Risk per trade (%)</label>
            <input className="input" type="number" step="0.1" min="0.1" max="5" value={riskPct} onChange={e => setRiskPct(e.target.value)} />
          </div>
          <div className="form-group">
            <label className="label">Entry price</label>
            <input className="input" type="number" value={entryPrice} onChange={e => setEntryPrice(e.target.value)} placeholder="e.g. 100" />
          </div>
          <div className="form-group">
            <label className="label">Stop loss price</label>
            <input className="input" type="number" value={stopPrice} onChange={e => setStopPrice(e.target.value)} placeholder="e.g. 99" />
          </div>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(150px, 1fr))", gap: "0.75rem" }}>
          <ResultStat label="Risk amount" value={fmt(calc.riskAmount)} color={calc.maxRiskAmount > 0 && calc.riskAmount > calc.maxRiskAmount ? "var(--color-loss)" : "var(--color-gray-100)"} />
          <ResultStat label="Position size" value={calc.size != null ? calc.size.toFixed(4) : "—"} sub={calc.stopDist > 0 ? `stop distance ${calc.stopDist.toFixed(2)}` : "enter entry & stop"} />
          {status?.prefs.maxRiskPerTradePct != null && (
            <>
              <ResultStat label="Max risk allowed" value={fmt(calc.maxRiskAmount)} color="var(--color-info)" />
              <ResultStat label="Risk usage" value={`${calc.maxRiskPct.toFixed(0)}%`} color={calc.maxRiskPct > 100 ? "var(--color-loss)" : calc.maxRiskPct >= 80 ? "var(--color-warning)" : "var(--color-profit)"} />
            </>
          )}
        </div>
      </div>
    </div>
  )
}

function MiniStat({ label, value, sub, color }: { label: string; value: string; sub?: string; color?: string }) {
  return (
    <div style={{ padding: "0.75rem", borderRadius: "8px", background: "var(--color-gray-900)", border: "1px solid var(--color-gray-800)" }}>
      <div style={{ fontSize: "0.65rem", textTransform: "uppercase", letterSpacing: "0.04em", fontWeight: 700, color: "var(--color-gray-500)", marginBottom: "0.3rem" }}>{label}</div>
      <div style={{ fontSize: "1.05rem", fontWeight: 700, color: color || "var(--color-gray-100)" }}>{value}</div>
      {sub && <div style={{ fontSize: "0.7rem", color: "var(--color-gray-600)" }}>{sub}</div>}
    </div>
  )
}

function ResultStat({ label, value, sub, color }: { label: string; value: string; sub?: string; color?: string }) {
  return (
    <div style={{ padding: "0.9rem", borderRadius: "10px", background: "var(--color-gray-900)", border: "1px solid var(--color-gray-800)" }}>
      <div style={{ fontSize: "0.68rem", textTransform: "uppercase", letterSpacing: "0.05em", fontWeight: 700, color: "var(--color-gray-500)", marginBottom: "0.35rem" }}>{label}</div>
      <div style={{ fontSize: "1.3rem", fontWeight: 800, color: color || "var(--color-gray-100)", fontVariantNumeric: "tabular-nums" }}>{value}</div>
      {sub && <div style={{ fontSize: "0.72rem", color: "var(--color-gray-600)", marginTop: "0.15rem" }}>{sub}</div>}
    </div>
  )
}

"use client"

import { useState, useMemo } from "react"
import { toast } from "sonner"
import { X, Plus, BookOpen, PenTool, Check } from "lucide-react"
import { SETUP_TEMPLATES, SetupTemplate } from "@/lib/setups-templates"

type CreateSetupModalProps = {
  onCreated: () => void
}

export function CreateSetupModal({ onCreated }: CreateSetupModalProps) {
  const [isOpen, setIsOpen] = useState(false)
  const [mode, setMode] = useState<"template" | "custom">("template")
  const [loading, setLoading] = useState(false)

  // Custom mode state
  const [name, setName] = useState("")
  const [description, setDescription] = useState("")

  // Template mode state
  const [selectedTemplate, setSelectedTemplate] = useState<SetupTemplate | null>(null)

  const categories = useMemo(() => Array.from(new Set(SETUP_TEMPLATES.map(t => t.category))), [])

  const handleSubmit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault()

    const finalName = mode === "custom" ? name : selectedTemplate?.name
    const finalDesc = mode === "custom" ? description : selectedTemplate?.description

    if (!finalName) return

    setLoading(true)
    try {
      const res = await fetch("/api/setups", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: finalName, description: finalDesc }),
      })

      const data = await res.json()

      if (!res.ok) throw new Error(data.error || "Failed to create setup")

      toast.success(`Setup "${finalName}" added`)
      onCreated()
      setIsOpen(false)
      // reset
      setName("")
      setDescription("")
      setSelectedTemplate(null)
    } catch (err: any) {
      toast.error(err.message)
    } finally {
      setLoading(false)
    }
  }

  return (
    <>
      <button className="btn btn-primary" onClick={() => setIsOpen(true)} style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
        <Plus size={16} /> New Setup
      </button>

      {isOpen && (
        <div style={{
          position: "fixed", inset: 0, zIndex: 100,
          background: "rgba(0,0,0,0.7)", backdropFilter: "blur(4px)",
          display: "flex", alignItems: "center", justifyContent: "center"
        }}>
          <div className="chart-card" style={{ width: 550, maxWidth: "90vw", padding: "0", display: "flex", flexDirection: "column", maxHeight: "85vh" }}>

            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "1.25rem 1.5rem", borderBottom: "1px solid var(--color-gray-800)" }}>
              <h2 style={{ margin: 0, fontSize: "1.2rem", fontWeight: 700 }}>Add a Setup</h2>
              <button onClick={() => setIsOpen(false)} style={{ background: "transparent", border: "none", color: "var(--color-gray-400)", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}>
                <X size={20} />
              </button>
            </div>

            <div style={{ display: "flex", padding: "1rem 1.5rem", gap: "0.5rem", borderBottom: "1px solid var(--color-gray-800)", background: "var(--color-gray-950)" }}>
              <button 
                onClick={() => setMode("template")}
                style={{ 
                  flex: 1, padding: "0.6rem", display: "flex", alignItems: "center", justifyContent: "center", gap: "0.5rem", borderRadius: "8px", border: "none", cursor: "pointer",
                  fontSize: "0.85rem", fontWeight: 600, transition: "all 0.2s",
                  background: mode === "template" ? "var(--color-brand-600)" : "transparent",
                  color: mode === "template" ? "white" : "var(--color-gray-400)"
                }}
              >
                <BookOpen size={16} /> From Templates
              </button>
              <button 
                onClick={() => setMode("custom")}
                style={{ 
                  flex: 1, padding: "0.6rem", display: "flex", alignItems: "center", justifyContent: "center", gap: "0.5rem", borderRadius: "8px", border: "none", cursor: "pointer",
                  fontSize: "0.85rem", fontWeight: 600, transition: "all 0.2s",
                  background: mode === "custom" ? "var(--color-gray-700)" : "transparent",
                  color: mode === "custom" ? "white" : "var(--color-gray-400)"
                }}
              >
                <PenTool size={16} /> Custom Setup
              </button>
            </div>

            <div style={{ padding: "1.5rem", overflowY: "auto", flex: 1 }}>
              {mode === "template" ? (
                <div style={{ display: "flex", flexDirection: "column", gap: "1.5rem" }}>
                  {categories.map(cat => (
                    <div key={cat}>
                      <h3 style={{ fontSize: "0.8rem", color: "var(--color-gray-400)", textTransform: "uppercase", letterSpacing: "0.05em", marginBottom: "0.75rem" }}>{cat}</h3>
                      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0.75rem" }}>
                        {SETUP_TEMPLATES.filter(t => t.category === cat).map(t => (
                          <div 
                            key={t.name}
                            onClick={() => setSelectedTemplate(t)}
                            style={{ 
                              padding: "0.85rem", borderRadius: "8px", cursor: "pointer", transition: "all 0.2s",
                              border: selectedTemplate?.name === t.name ? "1px solid var(--color-brand-500)" : "1px solid var(--color-gray-800)",
                              background: selectedTemplate?.name === t.name ? "rgba(59, 130, 246, 0.05)" : "var(--color-gray-900)",
                              display: "flex", flexDirection: "column", gap: "0.35rem", position: "relative"
                            }}
                          >
                            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                              <span style={{ fontSize: "0.85rem", fontWeight: 600, color: "var(--color-gray-200)" }}>{t.name}</span>
                              {selectedTemplate?.name === t.name && <Check size={14} style={{ color: "var(--color-brand-500)" }} />}
                            </div>
                            <span style={{ fontSize: "0.75rem", color: "var(--color-gray-500)", lineHeight: 1.4 }}>{t.description}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <form id="custom-setup-form" onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "1.25rem" }}>
                  <div className="form-group" style={{ margin: 0 }}>
                    <label className="label">Setup Name *</label>
                    <input 
                      autoFocus
                      required
                      placeholder="e.g. A+ Breakout"
                      value={name} 
                      onChange={(e) => setName(e.target.value)} 
                      className="input" 
                    />
                  </div>

                  <div className="form-group" style={{ margin: 0 }}>
                    <label className="label">Description (optional)</label>
                    <textarea 
                      placeholder="Rules, confluence factors..."
                      value={description} 
                      onChange={(e) => setDescription(e.target.value)} 
                      className="input" 
                      rows={4}
                      style={{ resize: "none" }}
                    />
                  </div>
                </form>
              )}
            </div>

            <div style={{ display: "flex", justifyContent: "flex-end", gap: "0.75rem", padding: "1.25rem 1.5rem", borderTop: "1px solid var(--color-gray-800)", background: "var(--color-gray-950)", borderBottomLeftRadius: "12px", borderBottomRightRadius: "12px" }}>
              <button type="button" className="btn btn-outline" onClick={() => setIsOpen(false)}>Cancel</button>

              {mode === "template" ? (
                <button type="button" className="btn btn-primary" disabled={loading || !selectedTemplate} onClick={() => handleSubmit()}>
                  {loading ? "Adding..." : "Add Template"}
                </button>
              ) : (
                <button type="submit" form="custom-setup-form" className="btn btn-primary" disabled={loading || !name}>
                  {loading ? "Creating..." : "Create Setup"}
                </button>
              )}
            </div>

          </div>
        </div>
      )}
    </>
  )
}

"use client"

import { useEffect, useState, useMemo } from "react"
import { CreateSetupModal } from "./CreateSetupModal"
import { SetupDetailPanel } from "./SetupDetailPanel"
import { toast } from "sonner"
import { formatCurrency } from "@/lib/formatters"
import { Check, Trash2, Target, TrendingUp, Pencil, X, Save, ArrowDownWideNarrow, Search, Eye } from "lucide-react"

type Setup = {
  id: string
  name: string
  description: string | null
  isDefault: boolean
  count: number
  winRate: number
  netPnl: number
  netPnlUsd: number
  losses: number
  profitFactor: number
  avgWin: number
  avgLoss: number
  avgR: number
  best: number
  worst: number
  recentCount: number
  lastTradeAt: string | null
  series: number[]
}

type SortKey = "pnl" | "winrate" | "trades" | "name"

const SORT_OPTIONS: { key: SortKey; label: string }[] = [
  { key: "pnl", label: "Best P&L" },
  { key: "winrate", label: "Win rate" },
  { key: "trades", label: "Most trades" },
  { key: "name", label: "Name" },
]

function fmt(v: number, sign = false): string {
  const s = v.toLocaleString("en-US", { minimumFractionDigits: 2 })
  return `${sign && v > 0 ? "+" : ""}$${s}`
}

function Sparkline({ series, positive }: { series: number[]; positive: boolean }) {
  if (series.length < 2) {
    return <div style={{ height: 36 }} />
  }
  const min = Math.min(...series)
  const max = Math.max(...series)
  const range = max - min || 1
  const w = 100
  const h = 36
  const pts = series
    .map((v, i) => `${((i / (series.length - 1)) * w).toFixed(1)},${(h - ((v - min) / range) * (h - 4) - 2).toFixed(1)}`)
    .join(" ")
  const last = series[series.length - 1]
  const color = positive ? "var(--color-profit)" : "var(--color-loss)"
  return (
    <svg width="100%" height={h} viewBox={`0 0 ${w} ${h}`} preserveAspectRatio="none" style={{ display: "block" }}>
      <polyline
        points={pts}
        fill="none"
        stroke={color}
        strokeWidth={1.75}
        vectorEffect="non-scaling-stroke"
        opacity={last >= series[0] ? 1 : 0.85}
      />
    </svg>
  )
}

export function SetupsManager() {
  const [setups, setSetups] = useState<Setup[]>([])
  const [loading, setLoading] = useState(true)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [editName, setEditName] = useState("")
  const [editDescription, setEditDescription] = useState("")
  const [saving, setSaving] = useState(false)
  const [sortKey, setSortKey] = useState<SortKey>("pnl")
  const [query, setQuery] = useState("")
  const [detailId, setDetailId] = useState<string | null>(null)

  const loadSetups = async () => {
    setLoading(true)
    try {
      const res = await fetch("/api/setups")
      const data = await res.json()
      setSetups(data)
    } catch (err) {
      toast.error("Failed to load setups")
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadSetups()
  }, [])

  const sorted = useMemo(() => {
    let arr = [...setups]
    if (query.trim()) {
      const q = query.trim().toLowerCase()
      arr = arr.filter(s => s.name.toLowerCase().includes(q) || (s.description || "").toLowerCase().includes(q))
    }
    switch (sortKey) {
      case "name": return arr.sort((a, b) => a.name.localeCompare(b.name))
      case "winrate": return arr.sort((a, b) => (b.count > 0 ? b.winRate : -1) - (a.count > 0 ? a.winRate : -1))
      case "trades": return arr.sort((a, b) => b.count - a.count)
      default: return arr.sort((a, b) => b.netPnl - a.netPnl)
    }
  }, [setups, sortKey, query])

  const totals = useMemo(() => {
    const withTrades = setups.filter(s => s.count > 0)
    const totalPnl = setups.reduce((sum, s) => sum + s.netPnl, 0)
    const totalTrades = setups.reduce((sum, s) => sum + s.count, 0)
    const best = [...setups].sort((a, b) => b.netPnl - a.netPnl)[0]
    const bestWinRate = withTrades.length > 0 ? [...withTrades].sort((a, b) => b.winRate - a.winRate)[0] : null
    const profitable = setups.filter(s => s.netPnl > 0).length
    return { totalPnl, totalTrades, best, bestWinRate, profitable, total: setups.length, withTrades }
  }, [setups])

  const startEdit = (setup: Setup) => {
    setEditingId(setup.id)
    setEditName(setup.name)
    setEditDescription(setup.description || "")
  }

  const cancelEdit = () => {
    setEditingId(null)
    setEditName("")
    setEditDescription("")
  }

  const saveEdit = async (id: string) => {
    if (!editName.trim()) return
    setSaving(true)
    try {
      const res = await fetch(`/api/setups/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: editName.trim(), description: editDescription.trim() }),
      })
      if (!res.ok) {
        const d = await res.json()
        throw new Error(d.error || "Failed to save")
      }
      toast.success("Setup updated")
      cancelEdit()
      loadSetups()
    } catch (err: any) {
      toast.error(err.message)
    } finally {
      setSaving(false)
    }
  }

  const setAsDefault = async (id: string, name: string) => {
    try {
      const res = await fetch(`/api/setups/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ isDefault: true }),
      })
      if (!res.ok) throw new Error("Failed to set default")
      toast.success(`${name} is now your default setup`)
      loadSetups()
    } catch (err: any) {
      toast.error(err.message)
    }
  }

  const deleteSetup = async (id: string, name: string) => {
    if (!confirm(`Are you sure you want to delete the setup "${name}"? This won't delete the tags on your existing trades.`)) return
    try {
      const res = await fetch(`/api/setups/${id}`, { method: "DELETE" })
      if (!res.ok) throw new Error("Failed to delete setup")
      toast.success(`Setup deleted`)
      loadSetups()
    } catch (err: any) {
      toast.error(err.message)
    }
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "2rem" }}>
      <div className="page-header" style={{ marginBottom: 0 }}>
        <div>
          <h1 className="page-title">Trading Setups</h1>
          <p className="page-subtitle">Manage your strategies, define rules, and track performance.</p>
        </div>
        <div className="actions">
          <CreateSetupModal onCreated={loadSetups} />
        </div>
      </div>

      {/* Global KPIs */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(190px, 1fr))", gap: "1rem" }}>
        <div className="card-hover" style={{ display: "flex", flexDirection: "column", gap: "0.75rem", padding: "1.5rem", borderRadius: "12px", background: "var(--color-gray-900)", border: "1px solid var(--color-gray-800)" }}>
          <div style={{ fontSize: "0.75rem", textTransform: "uppercase", fontWeight: 700, letterSpacing: "0.05em", color: "var(--color-gray-500)" }}>Combined P&L</div>
          <div style={{ fontSize: "2rem", fontWeight: 800, fontFamily: "var(--font-mono)", letterSpacing: "-0.02em", color: totals.totalPnl > 0 ? "var(--color-profit)" : totals.totalPnl < 0 ? "var(--color-loss)" : "var(--color-gray-100)" }}>
            {fmt(totals.totalPnl, true)}
          </div>
          <div style={{ fontSize: "0.75rem", fontWeight: 600, color: "var(--color-gray-500)" }}>{totals.totalTrades} tagged trades</div>
        </div>
        <div className="card-hover" style={{ display: "flex", flexDirection: "column", gap: "0.75rem", padding: "1.5rem", borderRadius: "12px", background: "var(--color-gray-900)", border: "1px solid var(--color-gray-800)" }}>
