            </>
          )}
        </div>
      </div>
    </>
  )
}

"use client"

import { useRouter, useSearchParams, usePathname } from "next/navigation"
import { formatCurrency, formatDateWithTimezone } from "@/lib/formatters"
import { motion } from "framer-motion"

type TradeRowProps = {
  trade: any
  timezone?: string
  baseCurrency?: string
  visibleColumns?: Record<string, boolean>
  selected?: boolean
  index?: number
  onSelect?: () => void
}

export function TradeRow({ trade, timezone = "UTC", baseCurrency = "USD", visibleColumns, selected, index = 0, onSelect }: TradeRowProps) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()

  const show = (key: string) => visibleColumns ? visibleColumns[key] !== false : true

  const handleRowClick = () => {
    const params = new URLSearchParams(searchParams.toString())
    params.set("tradeId", trade.id)
    router.push(`${pathname}?${params.toString()}`)
  }

  const handleSelectClick = (e: React.MouseEvent) => {
    e.stopPropagation()
    onSelect?.()
  }

  const pnl = Number(trade.netPnl || 0)

  return (
    <motion.tr
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.2, delay: Math.min(index * 0.05, 0.5) }}
      className="recent-trade-item"
      onClick={handleRowClick}
      style={{ cursor: "pointer", ...(selected ? { background: "rgba(139,92,246,0.08)" } : {}) }}
      onMouseEnter={(e) => { if (!selected) e.currentTarget.style.backgroundColor = "var(--color-gray-900)" }}
      onMouseLeave={(e) => { if (!selected) e.currentTarget.style.backgroundColor = "transparent" }}
    >
      {visibleColumns && (
        <td style={{ width: "36px" }} onClick={handleSelectClick}>
          <input
            type="checkbox"
            checked={selected}
            onChange={() => onSelect?.()}
            onClick={(e) => e.stopPropagation()}
            style={{ accentColor: "var(--color-brand-500)", cursor: "pointer" }}
          />
        </td>
      )}
      {show("entryAt") && (
        <td>
          <div suppressHydrationWarning style={{ fontWeight: 500, color: "var(--color-gray-200)", whiteSpace: "nowrap" }}>
            {formatDateWithTimezone(trade.entryAt, timezone)}
          </div>
          <div suppressHydrationWarning style={{ fontSize: "0.85rem", color: "var(--color-gray-500)" }}>
            {new Date(trade.entryAt).toLocaleTimeString([], { timeZone: timezone, hour: "2-digit", minute: "2-digit" })}
          </div>
        </td>
      )}
      {show("symbol") && (
        <td>
          <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
            <span style={{ fontWeight: 600 }}>{trade.symbol}</span>
            {trade.screenshots && trade.screenshots.length > 0 && (
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ color: "var(--color-brand-500)" }}>
                <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M17 8l-5-5-5 5M12 3v12" strokeLinecap="round" strokeLinejoin="round"/>
              </svg>
            )}
          </div>
        </td>
      )}
      {show("instrumentType") && (
        <td>
          <span style={{ fontSize: "0.85rem", color: "var(--color-gray-500)" }}>{trade.instrumentType}</span>
        </td>
      )}
      {show("side") && (
        <td>
          <span className={`badge ${trade.side === "LONG" ? "badge-profit" : "badge-loss"}`}>{trade.side}</span>
        </td>
      )}
      {show("quantity") && <td>{Number(trade.quantity).toString()}</td>}
      {show("entryPrice") && <td>{formatCurrency(Number(trade.entryPrice), baseCurrency, false, 2)}</td>}
      {show("exitPrice") && <td>{trade.exitPrice ? formatCurrency(Number(trade.exitPrice), baseCurrency, false, 2) : "—"}</td>}
      {show("stopLoss") && <td>{trade.stopLoss ? formatCurrency(Number(trade.stopLoss), baseCurrency, false, 2) : "—"}</td>}
      {show("riskAmount") && <td>{trade.riskAmount ? formatCurrency(Number(trade.riskAmount), baseCurrency, true, 0) : "—"}</td>}
      {show("fees") && <td>{Number(trade.fees) > 0 ? formatCurrency(Number(trade.fees), baseCurrency, true, 2) : "—"}</td>}
      {show("setupTags") && (
        <td>
          {trade.setupTags && trade.setupTags.length > 0 ? (
            <span className="badge badge-neutral" style={{ fontSize: "0.72rem" }}>
              {trade.setupTags[0]}
              {trade.setupTags.length > 1 && <span style={{ opacity: 0.6 }}> +{trade.setupTags.length - 1}</span>}
            </span>
          ) : (
            <span style={{ color: "var(--color-gray-600)" }}>—</span>
          )}
        </td>
      )}
      {show("emotionTags") && (
        <td>
          {trade.emotionTags && trade.emotionTags.length > 0 ? (
            <span style={{ fontSize: "0.75rem", color: "var(--color-gray-400)" }}>{trade.emotionTags.join(", ")}</span>
          ) : (
            <span style={{ color: "var(--color-gray-600)" }}>—</span>
          )}
        </td>
      )}
      {show("netPnl") && (
        <td style={{ textAlign: "right" }}>
          <span className={`badge ${pnl > 0 ? "badge-profit" : pnl < 0 ? "badge-loss" : "badge-neutral"}`} style={{ fontWeight: 700, fontSize: "0.8rem" }}>
            {formatCurrency(pnl, baseCurrency, true, 2)}
          </span>
        </td>
      )}
      {show("status") && (
        <td>
          <span className="badge badge-neutral" style={{ fontSize: "0.7rem", textTransform: "uppercase" }}>{trade.status}</span>
        </td>
      )}
    </motion.tr>
  )
}

"use client"

import { useEffect, useState } from "react"
import { useSearchParams } from "next/navigation"
import { AreaChart, Area, ResponsiveContainer, Tooltip, ReferenceLine } from "recharts"
import { TrendingUp, TrendingDown } from "lucide-react"

export function TradesEquityMini() {
  const searchParams = useSearchParams()
  const [data, setData] = useState<{ equity: number; date: string }[]>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    setLoading(true)
    const params = new URLSearchParams()
    const accountId = searchParams?.get("accountId")
    const from = searchParams?.get("from")
    const to = searchParams?.get("to")
    if (accountId) params.set("accountId", accountId)
    if (from) params.set("from", from)
    if (to) params.set("to", to)

    const qs = params.toString()
    fetch(`/api/metrics/equity-curve${qs ? `?${qs}` : ""}`)
      .then((r) => r.json())
      .then((d) => {
        setData((d.data || []).map((p: any) => ({ equity: p.equity, date: p.date })))
        setLoading(false)
      })
      .catch(() => setLoading(false))
  }, [searchParams])

  if (loading) return <div className="skeleton" style={{ height: 80, borderRadius: "var(--radius-card)" }} />
  if (data.length < 2) return null

  const first = data[0].equity
  const last = data[data.length - 1].equity
  const change = last - first
  const changePct = first !== 0 ? ((change / Math.abs(first)) * 100) : 0
  const isPositive = change >= 0
  const minVal = Math.min(...data.map(d => d.equity)) * 0.999
  const maxVal = Math.max(...data.map(d => d.equity)) * 1.001

  return (
    <div style={{
      display: "flex", alignItems: "center", gap: "1.5rem",
      background: "var(--color-gray-900)", border: "1px solid var(--color-gray-800)",
      borderRadius: "var(--radius-card)", padding: "0.75rem 1.25rem",
      marginBottom: "1rem",
    }}>
      <div style={{ flex: 1, height: 50, minWidth: 0 }}>
        <ResponsiveContainer width="100%" height="100%">
          <AreaChart data={data} margin={{ top: 2, right: 0, left: 0, bottom: 0 }}>
            <defs>
              <linearGradient id="miniEqGrad" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor={isPositive ? "var(--color-profit)" : "var(--color-loss)"} stopOpacity={0.25} />
                <stop offset="100%" stopColor={isPositive ? "var(--color-profit)" : "var(--color-loss)"} stopOpacity={0} />
              </linearGradient>
            </defs>
            <ReferenceLine y={first} stroke="var(--color-gray-700)" strokeDasharray="3 3" strokeWidth={1} />
            <Tooltip
              content={({ active, payload }) => {
                if (!active || !payload?.length) return null
                return (
                  <div style={{
                    background: "var(--color-gray-900)", border: "1px solid var(--color-gray-700)",
                    borderRadius: 8, padding: "0.4rem 0.6rem", fontSize: "0.7rem",
                  }}>
                    <span style={{ fontFamily: "var(--font-mono)", fontWeight: 700, color: "var(--color-gray-100)" }}>
                      ${Number(payload[0].value).toLocaleString("en-US", { minimumFractionDigits: 2 })}
                    </span>
                  </div>
                )
              }}
            />
            <Area
              type="monotone"
              dataKey="equity"
              stroke={isPositive ? "var(--color-profit)" : "var(--color-loss)"}
              strokeWidth={1.5}
              fill="url(#miniEqGrad)"
              dot={false}
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>

      <div style={{ flexShrink: 0, textAlign: "right" }}>
        <div style={{ display: "flex", alignItems: "center", gap: "0.35rem", justifyContent: "flex-end" }}>
          {isPositive ? <TrendingUp size={14} color="var(--color-profit)" /> : <TrendingDown size={14} color="var(--color-loss)" />}
          <span style={{ fontFamily: "var(--font-mono)", fontWeight: 700, fontSize: "0.95rem", color: isPositive ? "var(--color-profit)" : "var(--color-loss)" }}>
            {isPositive ? "+" : ""}{changePct.toFixed(2)}%
          </span>
        </div>
        <div style={{ fontFamily: "var(--font-mono)", fontSize: "0.7rem", color: "var(--color-gray-500)", marginTop: "0.1rem" }}>
          {data.length} points
        </div>
      </div>
    </div>
  )
}

"use client"

import { useRouter, useSearchParams, usePathname } from "next/navigation"
import { useState } from "react"
import { Search, SlidersHorizontal, X } from "lucide-react"
import { useTranslations } from "next-intl"

type Account = { id: string; name: string; isDefault: boolean }

export function TradesFilter({ accounts = [] }: { accounts?: Account[] }) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const t = useTranslations("TradesFilter")

  const [accountId, setAccountId] = useState(searchParams?.get("accountId") || "")
  const [symbol, setSymbol] = useState(searchParams?.get("symbol") || "")
  const [side, setSide] = useState(searchParams?.get("side") || "")
  const [result, setResult] = useState(searchParams?.get("result") || "")
  const [date, setDate] = useState(searchParams?.get("date") || "")
  const [instrument, setInstrument] = useState(searchParams?.get("instrument") || "")
  const [setup, setSetup] = useState(searchParams?.get("setup") || "")
  const [session, setSession] = useState(searchParams?.get("session") || "")

  const handleApply = (e: React.FormEvent) => {
    e.preventDefault()
    const params = new URLSearchParams(searchParams as any)

    if (accountId) params.set("accountId", accountId)
    else params.delete("accountId")

    if (symbol) params.set("symbol", symbol)
    else params.delete("symbol")

    if (side) params.set("side", side)
    else params.delete("side")

    if (result) params.set("result", result)
    else params.delete("result")

    if (date) params.set("date", date)
    else params.delete("date")

    if (instrument) params.set("instrument", instrument)
    else params.delete("instrument")

    if (setup) params.set("setup", setup)
    else params.delete("setup")

    if (session) params.set("session", session)
    else params.delete("session")

    // Reset to page 1 when filtering
    params.set("page", "1")

    router.push(`${pathname}?${params.toString()}`)
    router.refresh()
  }

  const handleClear = () => {
    setAccountId("")
    setSymbol("")
    setSide("")
    setResult("")
    setDate("")
    setInstrument("")
    setSetup("")
    setSession("")
    router.push(pathname || "/trades")
    router.refresh()
  }

  const hasActiveFilters = accountId || symbol || side || result || date || instrument || setup || session

  return (
    <form onSubmit={handleApply} className="flex flex-col gap-4 mb-6 bg-[var(--color-gray-900)] p-5 rounded-[var(--radius-card)] border border-[var(--color-gray-800)]">

      <div className="flex flex-wrap gap-4 items-end">
      {accounts.length > 1 && (
        <div className="flex-1 min-w-[170px] m-0">
          <label className="label text-xs uppercase tracking-wider text-[var(--color-gray-500)] mb-2 font-bold">
            {t("account")}
          </label>
          <select 
            value={accountId} 
            onChange={(e) => setAccountId(e.target.value)} 
            className="input select"
          >
            <option value="">{t("allAccounts")}</option>
            {accounts.map((a) => (
              <option key={a.id} value={a.id}>{a.name}{a.isDefault ? ` (${t("default")})` : ""}</option>
            ))}
          </select>
        </div>
      )}

      <div className="flex-1 min-w-[200px] m-0">
        <label className="label text-xs uppercase tracking-wider text-[var(--color-gray-500)] mb-2 font-bold">
          {t("symbol")}
        </label>
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[var(--color-gray-500)]" size={16} />
          <input 
            value={symbol} 
            onChange={(e) => setSymbol(e.target.value)} 
            placeholder={t("symbolPlaceholder")}
            className="input pl-9"
          />
        </div>
      </div>

      <div className="flex-1 min-w-[150px] m-0">
        <label className="label text-xs uppercase tracking-wider text-[var(--color-gray-500)] mb-2 font-bold">
          {t("tradeSide")}
        </label>
        <select 
          value={side} 
          onChange={(e) => setSide(e.target.value)} 
          className="input select"
        >
          <option value="">{t("allSides")}</option>
          <option value="LONG">{t("long")}</option>
          <option value="SHORT">{t("short")}</option>
        </select>
      </div>

      <div className="flex-1 min-w-[150px] m-0">
        <label className="label text-xs uppercase tracking-wider text-[var(--color-gray-500)] mb-2 font-bold">
          {t("result")}
        </label>
        <select 
          value={result} 
          onChange={(e) => setResult(e.target.value)} 
          className="input select"
        >
          <option value="">{t("allResults")}</option>
          <option value="win">{t("winningTrades")}</option>
          <option value="loss">{t("losingTrades")}</option>
          <option value="be">{t("breakEven")}</option>
        </select>
      </div>

      <div className="flex-1 min-w-[150px] m-0">
        <label className="label text-xs uppercase tracking-wider text-[var(--color-gray-500)] mb-2 font-bold">
          {t("timeframe")}
        </label>
        <select 
          value={date} 
          onChange={(e) => setDate(e.target.value)} 
          className="input select"
        >
          <option value="">{t("allTime")}</option>
          <option value="today">{t("today")}</option>
          <option value="7d">{t("last7Days")}</option>
          <option value="30d">{t("last30Days")}</option>
          <option value="this_month">{t("thisMonth")}</option>
        </select>
      </div>

      <div className="flex-1 min-w-[150px] m-0">
        <label className="label text-xs uppercase tracking-wider text-[var(--color-gray-500)] mb-2 font-bold">
          {t("instrument")}
        </label>
        <select 
          value={instrument} 
          onChange={(e) => setInstrument(e.target.value)} 
          className="input select"
        >
          <option value="">{t("allTypes")}</option>
          <option value="forex">{t("forex")}</option>
          <option value="crypto">{t("crypto")}</option>
          <option value="indices">{t("indices")}</option>
          <option value="commodities">{t("commodities")}</option>
          <option value="stock">{t("stocks")}</option>
        </select>
      </div>

      <div className="flex-1 min-w-[150px] m-0">
        <label className="label text-xs uppercase tracking-wider text-[var(--color-gray-500)] mb-2 font-bold">
          {t("setupTag")}
        </label>
        <input 
          value={setup} 
          onChange={(e) => setSetup(e.target.value)} 
          placeholder={t("setupTagPlaceholder")}
          className="input"
        />
      </div>

      <div className="flex-1 min-w-[150px] m-0">
        <label className="label text-xs uppercase tracking-wider text-[var(--color-gray-500)] mb-2 font-bold">
          {t("session")}
        </label>
        <select 
          value={session} 
          onChange={(e) => setSession(e.target.value)} 
          className="input select"
        >
          <option value="">{t("allSessions")}</option>
          <option value="london">{t("london")}</option>
          <option value="ny_open">{t("newYork")}</option>
          <option value="asia">{t("asia")}</option>
          <option value="overlap">{t("overlap")}</option>
        </select>
      </div>

      </div>

      <div className="flex gap-3 pt-2 mt-2 border-t border-[var(--color-gray-800)]">
        <button type="submit" className="btn btn-primary px-6 h-[42px] flex items-center gap-2">
          <SlidersHorizontal size={16} /> {t("filter")}
        </button>
        {hasActiveFilters && (
          <button type="button" onClick={handleClear} className="btn btn-outline px-4 h-[42px] flex items-center gap-2 text-[var(--color-gray-400)]">
            <X size={16} /> {t("clear")}
          </button>
        )}
      </div>
    </form>
  )
}

