// components/trades/TradesTable.tsx
// Client — colonnes configurables, sélection multiple, tri, totaux, pagination
"use client"

import { useMemo, useState, useEffect, useRef } from "react"
import { useRouter, useSearchParams, usePathname } from "next/navigation"
import { toast } from "sonner"
import { Columns3, Trash2, CheckCheck, ArrowUpDown, ArrowUp, ArrowDown, X, Download, FileText } from "lucide-react"
import { formatCurrency } from "@/lib/formatters"
import { TradeRow } from "@/components/trades/TradeRow"
import jsPDF from "jspdf"
import autoTable from "jspdf-autotable"
import { useTranslations, useLocale } from "next-intl"

export const TRADE_COLUMNS = [
  { key: "entryAt", label: "Entry Time", default: true, sortable: true },
  { key: "symbol", label: "Symbol", default: true, sortable: true },
  { key: "instrumentType", label: "Instrument", default: true, sortable: false },
  { key: "side", label: "Side", default: true, sortable: true },
  { key: "quantity", label: "Qty", default: true, sortable: true },
  { key: "entryPrice", label: "Entry Price", default: true, sortable: true },
  { key: "exitPrice", label: "Exit Price", default: true, sortable: true },
  { key: "stopLoss", label: "Stop Loss", default: false, sortable: false },
  { key: "riskAmount", label: "Risk $", default: false, sortable: false },
  { key: "fees", label: "Fees", default: false, sortable: false },
  { key: "setupTags", label: "Setup", default: true, sortable: false },
  { key: "emotionTags", label: "Emotions", default: false, sortable: false },
  { key: "netPnl", label: "Net P&L", default: true, sortable: true },
  { key: "status", label: "Status", default: true, sortable: false },
] as const

type ColumnKey = (typeof TRADE_COLUMNS)[number]["key"]

type Props = {
  trades: any[]
  totals: { count: number; netPnl: number; wins: number; losses: number }
  density: string
  timezone?: string
  baseCurrency?: string
  sortKey: string
  sortDir: string
  currentPage: number
  totalPages: number
  totalTrades: number
  itemsPerPage: number
}

export function TradesTable({
  trades,
  totals,
  density,
  timezone,
  baseCurrency = "USD",
  sortKey,
  sortDir,
  currentPage,
  totalPages,
  totalTrades,
  itemsPerPage,
}: Props) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const t = useTranslations("TradesTable")
  const locale = useLocale()

  const [visible, setVisible] = useState<Record<string, boolean>>(() => {
    return TRADE_COLUMNS.reduce((acc: any, c) => ({ ...acc, [c.key]: c.default }), {})
  })
  const [selected, setSelected] = useState<Set<string>>(new Set())
  const [columnsOpen, setColumnsOpen] = useState(false)
  const [bulkOpen, setBulkOpen] = useState(false)
  const [busy, setBusy] = useState(false)
  const columnsRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const stored = localStorage.getItem("trades_columns")
    if (stored) {
      try {
        const parsed = JSON.parse(stored)
        setVisible(prev => {
          const next = { ...prev }
          for (const key of Object.keys(parsed)) {
            if (key in next) next[key] = parsed[key]
          }
          return next
        })
      } catch {
        // ignore
      }
    }
  }, [])

  useEffect(() => {
    try {
      localStorage.setItem("trades_columns", JSON.stringify(visible))
    } catch {
      // ignore
    }
  }, [visible])

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (columnsRef.current && !columnsRef.current.contains(e.target as Node)) setColumnsOpen(false)
    }
    document.addEventListener("mousedown", handler)
    return () => document.removeEventListener("mousedown", handler)
  }, [])

  const selectedIds = useMemo(() => Array.from(selected), [selected])

  const toggleColumn = (key: string) => {
    setVisible((prev) => ({ ...prev, [key]: !prev[key] }))
  }

  const toggleSelect = (id: string) => {
    setSelected((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  const toggleSelectAll = () => {
    setSelected((prev) => {
      if (prev.size === trades.length && trades.length > 0) return new Set()
      return new Set(trades.map((t) => t.id))
    })
  }

  const handleSort = (key: string) => {
    const params = new URLSearchParams(searchParams.toString())
    if (params.get("sort") === key) {
      params.set("dir", params.get("dir") === "asc" ? "desc" : "asc")
    } else {
      params.set("sort", key)
      params.set("dir", key === "entryAt" ? "desc" : "asc")
    }
    params.set("page", "1")
    router.push(`${pathname}?${params.toString()}`)
    router.refresh()
  }

  const runBulk = async (action: "delete" | "open" | "close") => {
    if (selectedIds.length === 0) return
    if (action === "delete" && !confirm(t("messages.deleteConfirm", { count: selectedIds.length }))) return
    setBusy(true)
    try {
      const res = await fetch("/api/trades/bulk", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ids: selectedIds, action }),
      })
      const data = await res.json()
      if (!res.ok) throw new Error(data.error || "Failed")
      toast.success(t("messages.updatedTrades", { count: data.count }))
      setSelected(new Set())
      router.refresh()
    } catch (err: any) {
      toast.error(err.message || t("messages.actionFailed"))
    } finally {
      setBusy(false)
      setBulkOpen(false)
    }
  }

  const exportCsv = async () => {
    const params = new URLSearchParams(searchParams.toString())
    params.delete("page")
    params.delete("tradeId")
    try {
      const res = await fetch(`/api/trades/export?${params.toString()}`)
      if (!res.ok) throw new Error("Export failed")
      const blob = await res.blob()
      const url = URL.createObjectURL(blob)
      const a = document.createElement("a")
      a.href = url
      a.download = "trades-export.csv"
      a.click()
      URL.revokeObjectURL(url)
      toast.success(t("messages.exportedCsv"))
    } catch {
      toast.error(t("messages.exportFailed"))
    }
  }

  const exportPdf = async () => {
    const params = new URLSearchParams(searchParams.toString())
    params.delete("page")
    params.delete("tradeId")
    params.set("format", "json")
    try {
      const res = await fetch(`/api/trades/export?${params.toString()}`)
      if (!res.ok) throw new Error("Export failed")
      const { trades: exportTrades } = await res.json()

      const doc = new jsPDF({ orientation: "landscape", unit: "pt", format: "a4" })

      doc.setFontSize(18)
      doc.text(t("report.tradesReport"), 40, 40)

      doc.setFontSize(10)
      doc.setTextColor(100)
      doc.text(t("report.generatedOn", { date: new Date().toLocaleDateString(locale) }), 40, 55)

      const totalPnl = exportTrades.reduce((sum: number, t: any) => sum + Number(t.netPnl || 0), 0)
      const winRate = exportTrades.length > 0 
        ? ((exportTrades.filter((t: any) => Number(t.netPnl || 0) > 0).length / exportTrades.length) * 100).toFixed(1) 
        : 0

      doc.setFontSize(12)
      doc.setTextColor(totalPnl >= 0 ? 0 : 200, totalPnl >= 0 ? 150 : 0, 0)
      doc.text(`${t("report.totalPnl")}${totalPnl >= 0 ? '+' : ''}${formatCurrency(totalPnl, baseCurrency)} | ${t("report.winRate")}${winRate}% | ${t("report.trades")}${exportTrades.length}`, 40, 80)

      autoTable(doc, {
        startY: 100,
        head: [["Date", "Symbol", "Side", "Qty", "Entry", "Exit", "P&L", "Status"]],
        body: exportTrades.map((t: any) => [
          new Date(t.entryAt).toLocaleString(),
          t.symbol,
          t.side,
          t.quantity,
          t.entryPrice || "-",
          t.exitPrice || "-",
          Number(t.netPnl || 0).toFixed(2),
          t.status
        ]),
        theme: 'grid',
        headStyles: { fillColor: [15, 23, 42] },
        styles: { fontSize: 8 },
        alternateRowStyles: { fillColor: [248, 250, 252] },
      })

      doc.save(`trades-export-${new Date().toISOString().slice(0, 10)}.pdf`)
      toast.success(t("messages.exportedPdf"))
    } catch (err) {
      console.error(err)
      toast.error(t("messages.exportFailed"))
    }
  }

  const visibleColumns = TRADE_COLUMNS.filter((c) => visible[c.key])
  const pageNetPnl = trades.reduce((s, t) => s + Number(t.netPnl || 0), 0)
  const skip = (currentPage - 1) * itemsPerPage

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "0.75rem" }}>
      {/* Toolbar */}
      <div style={{ display: "flex", alignItems: "center", gap: "0.75rem", flexWrap: "wrap" }}>
        {/* Selection */}
        {selectedIds.length > 0 ? (
          <div style={{ display: "flex", alignItems: "center", gap: "0.5rem", padding: "0.35rem 0.6rem", borderRadius: "8px", background: "rgba(139,92,246,0.12)", border: "1px solid rgba(139,92,246,0.3)" }}>
            <span style={{ fontSize: "0.85rem", fontWeight: 600, color: "var(--color-brand-300)" }}>
              {t("selection.selected", { count: selectedIds.length })}
            </span>
            <button onClick={() => setSelected(new Set())} title={t("actions.clearSelection")} style={{ display: "flex", alignItems: "center", background: "none", border: "none", cursor: "pointer", color: "var(--color-gray-400)" }}>
              <X size={14} />
            </button>
            <div style={{ display: "flex", gap: "0.35rem", position: "relative" }}>
              <button className="btn btn-ghost btn-sm" onClick={() => setBulkOpen((o) => !o)} disabled={busy} style={{ fontSize: "0.78rem" }}>
                {t("actions.bulkActions")}
              </button>
              {bulkOpen && (
                <div style={{ position: "absolute", top: "calc(100% + 4px)", right: 0, zIndex: 20, minWidth: "180px", background: "var(--color-gray-900)", border: "1px solid var(--color-gray-700)", borderRadius: "8px", padding: "0.35rem", boxShadow: "0 8px 24px rgba(0,0,0,0.4)", display: "flex", flexDirection: "column", gap: "0.15rem" }}>
                  <button className="btn btn-ghost btn-sm" onClick={() => runBulk("open")} disabled={busy} style={{ justifyContent: "flex-start", gap: "0.4rem" }}>
                    <CheckCheck size={14} /> {t("actions.markOpen")}
                  </button>
                  <button className="btn btn-ghost btn-sm" onClick={() => runBulk("close")} disabled={busy} style={{ justifyContent: "flex-start", gap: "0.4rem" }}>
                    <CheckCheck size={14} /> {t("actions.markClosed")}
                  </button>
                  <button className="btn btn-ghost btn-sm" onClick={() => runBulk("delete")} disabled={busy} style={{ justifyContent: "flex-start", gap: "0.4rem", color: "var(--color-loss)" }}>
                    <Trash2 size={14} /> {t("actions.delete")}
                  </button>
                </div>
              )}
            </div>
          </div>
        ) : (
          <span style={{ fontSize: "0.85rem", color: "var(--color-gray-500)" }}>
            {t("selection.matchingFilters", { count: totals.count })}
          </span>
        )}

        <div style={{ marginLeft: "auto", display: "flex", gap: "0.5rem" }}>
          <button
            className="btn btn-outline btn-sm"
            onClick={exportCsv}
            style={{ display: "flex", alignItems: "center", gap: "0.4rem" }}
            title={t("actions.exportCsv")}
          >
            <Download size={14} /> {t("actions.exportCsv")}
          </button>
          <button
            className="btn btn-outline btn-sm"
            onClick={exportPdf}
            style={{ display: "flex", alignItems: "center", gap: "0.4rem" }}
            title={t("actions.exportPdf")}
          >
            <FileText size={14} /> {t("actions.exportPdf")}
          </button>
          {/* Column visibility */}
          <div style={{ position: "relative" }} ref={columnsRef}>
            <button
              className="btn btn-outline btn-sm"
              onClick={() => setColumnsOpen((o) => !o)}
              style={{ display: "flex", alignItems: "center", gap: "0.4rem" }}
            >
              <Columns3 size={14} /> {t("actions.columns")}
            </button>
            {columnsOpen && (
              <div style={{ position: "absolute", top: "calc(100% + 4px)", right: 0, zIndex: 20, minWidth: "200px", maxHeight: "320px", overflowY: "auto", background: "var(--color-gray-900)", border: "1px solid var(--color-gray-700)", borderRadius: "8px", padding: "0.5rem", boxShadow: "0 8px 24px rgba(0,0,0,0.4)" }}>
                {TRADE_COLUMNS.map((c) => (
                  <label key={c.key} style={{ display: "flex", alignItems: "center", gap: "0.5rem", padding: "0.3rem 0.4rem", fontSize: "0.82rem", cursor: "pointer", color: "var(--color-gray-200)" }}>
                    <input
                      type="checkbox"
                      checked={!!visible[c.key]}
                      onChange={() => toggleColumn(c.key)}
                      style={{ accentColor: "var(--color-brand-500)" }}
                    />
                    {t(`columns.${c.key}`)}
                  </label>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Table */}
      <div className="table-wrapper">
        <table className={`data-table ${density}`}>
          <thead>
            <tr>
              <th style={{ width: "36px" }}>
                <input
                  type="checkbox"
                  checked={trades.length > 0 && selected.size === trades.length}
                  onChange={toggleSelectAll}
                  style={{ accentColor: "var(--color-brand-500)", cursor: "pointer" }}
                  title="Select all on page"
                />
              </th>
              {visibleColumns.map((c) => (
                <th
                  key={c.key}
                  onClick={c.sortable ? () => handleSort(c.key) : undefined}
                  style={{
                    cursor: c.sortable ? "pointer" : "default",
                    userSelect: "none",
                    textAlign: c.key === "netPnl" ? "right" : "left",
                  }}
                >
                  <span style={{ display: "inline-flex", alignItems: "center", gap: "0.25rem" }}>
                    {t(`columns.${c.key}`)}
                    {c.sortable && (sortKey === c.key ? (
                      sortDir === "asc" ? <ArrowUp size={12} /> : <ArrowDown size={12} />
                    ) : (
                      <ArrowUpDown size={12} style={{ opacity: 0.35 }} />
                    ))}
                  </span>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {trades.length === 0 ? (
              <tr>
                <td colSpan={visibleColumns.length + 1} style={{ textAlign: "center", padding: "3rem" }}>
                  <div className="empty-state">
                    <p>{t("empty.noTrades")}</p>
                  </div>
                </td>
              </tr>
            ) : (
              trades.map((t, i) => (
                <TradeRow
                  key={t.id}
                  trade={t}
                  index={i}
                  timezone={timezone}
                  baseCurrency={baseCurrency}
                  visibleColumns={visible}
                  selected={selected.has(t.id)}
                  onSelect={() => toggleSelect(t.id)}
                />
              ))
            )}
          </tbody>
          <tfoot>
            <tr style={{ background: "var(--color-gray-900)" }}>
              <td colSpan={visibleColumns.length + 1} style={{ textAlign: "right", paddingRight: "1rem" }}>
                <span style={{ fontSize: "0.8rem", color: "var(--color-gray-500)", marginRight: "0.5rem" }}>{t("tableFoot.pageTotal")}</span>
                <span style={{ fontWeight: 700, fontSize: "0.85rem", color: pageNetPnl >= 0 ? "var(--color-profit)" : "var(--color-loss)" }}>
                  {formatCurrency(pageNetPnl, baseCurrency, true, 2)}
                </span>
              </td>
            </tr>
          </tfoot>
        </table>
      </div>

      {/* Totals strip */}
      <div style={{ display: "flex", flexWrap: "wrap", gap: "1.25rem", padding: "0.75rem 1rem", background: "var(--color-gray-900)", borderRadius: "var(--radius-card)", border: "1px solid var(--color-gray-800)", fontSize: "0.8rem" }}>
        <div>
          <span style={{ color: "var(--color-gray-500)" }}>{t("summary.filteredNetPnl")}</span>
          <strong style={{ color: totals.netPnl >= 0 ? "var(--color-profit)" : "var(--color-loss)" }}>
            {formatCurrency(totals.netPnl, baseCurrency, true, 2)}
          </strong>
        </div>
        <div>
          <span style={{ color: "var(--color-gray-500)" }}>{t("summary.winRate")}</span>
          <strong style={{ color: "var(--color-gray-200)" }}>
            {totals.count > 0 ? ((totals.wins / totals.count) * 100).toFixed(1) : "0"}%
          </strong>
          <span style={{ color: "var(--color-gray-600)" }}> ({totals.wins}W / {totals.losses}L)</span>
        </div>
        <div>
          <span style={{ color: "var(--color-gray-500)" }}>{t("summary.avgPnl")}</span>
          <strong style={{ color: totals.count > 0 && totals.netPnl >= 0 ? "var(--color-profit)" : totals.count > 0 ? "var(--color-loss)" : "inherit" }}>
            {totals.count > 0 ? formatCurrency(totals.netPnl / totals.count, baseCurrency, true, 2) : "—"}
          </strong>
        </div>
        {selectedIds.length > 0 && (
          <div>
            <span style={{ color: "var(--color-gray-500)" }}>{t("summary.selectedPnl")}</span>
            <strong style={{ color: "var(--color-gray-200)" }}>
              {formatCurrency(
                trades.filter((t) => selected.has(t.id)).reduce((s, t) => s + Number(t.netPnl || 0), 0),
                baseCurrency,
                true,
                2
              )}
            </strong>
          </div>
        )}
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "0.5rem" }}>
          <div style={{ fontSize: "0.85rem", color: "var(--color-gray-400)" }}>
            {t("pagination.showing", { start: skip + 1, end: Math.min(skip + itemsPerPage, totalTrades), total: totalTrades })}
          </div>
          <div style={{ display: "flex", gap: "0.5rem" }}>
            {currentPage > 1 ? (
              <LinkBtn href={pageHref(currentPage - 1, searchParams, pathname)}>{t("pagination.previous")}</LinkBtn>
            ) : (
              <button className="btn btn-secondary" disabled style={{ opacity: 0.5, cursor: "not-allowed" }}>
                {t("pagination.previous")}
              </button>
            )}
            <div style={{ padding: "0.5rem 1rem", fontSize: "0.85rem", color: "var(--color-gray-200)" }}>
              {t("pagination.pageOf", { current: currentPage, total: totalPages })}
            </div>
            {currentPage < totalPages ? (
              <LinkBtn href={pageHref(currentPage + 1, searchParams, pathname)}>{t("pagination.next")}</LinkBtn>
            ) : (
              <button className="btn btn-secondary" disabled style={{ opacity: 0.5, cursor: "not-allowed" }}>
                {t("pagination.next")}
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  )
}

function LinkBtn({ href, children }: { href: string; children: React.ReactNode }) {
  return (
    <a href={href} className="btn btn-secondary" style={{ textDecoration: "none", display: "inline-block", padding: "0.5rem 1rem" }}>
      {children}
    </a>
  )
}

function pageHref(page: number, searchParams: URLSearchParams, pathname: string) {
  const params = new URLSearchParams(searchParams.toString())
  params.set("page", String(page))
  return `${pathname}?${params.toString()}`
}

import { auth } from "@/lib/auth"
import { prisma } from "@/lib/prisma"
import { redirect } from "next/navigation"

export type AdminSession = {
  user: {
    id: string
    email: string
    name: string | null
    role: string
    status: string
  }
}

/**
 * Require admin role. Redirects to / if not authorized.
 * Also checks for suspended/banned status.
 */
export async function requireAdmin(): Promise<AdminSession> {
  const session = await auth()

  if (!session?.user?.id) {
    redirect("/login")
  }

  // Check status
  const status = (session.user as Record<string, unknown>).status as string
  if (status === "SUSPENDED" || status === "BANNED") {
    redirect("/login?error=account_disabled")
  }

  // Check role
  const role = (session.user as Record<string, unknown>).role as string
  if (role !== "ADMIN" && role !== "SUPER_ADMIN") {
    redirect("/?error=unauthorized")
  }

  return session as unknown as AdminSession
}

/**
 * Check if current user is SUPER_ADMIN
 */
export async function requireSuperAdmin(): Promise<AdminSession> {
  const session = await requireAdmin()

  if (session.user.role !== "SUPER_ADMIN") {
    redirect("/?error=unauthorized")
  }

  return session
}

/**
 * Log an admin action to the audit trail
 */
export async function logAdminAction(params: {
  adminId: string
  targetUserId?: string
  action: string
  reason?: string
  metadata?: Record<string, unknown>
}) {
  return prisma.adminActionLog.create({
    data: {
      adminId: params.adminId,
      targetUserId: params.targetUserId || null,
      action: params.action,
      reason: params.reason || null,
      metadata: (params.metadata as any) || undefined,
    },
  })
}

/**
 * Formats a numeric value into a currency string based on the given baseCurrency.
 */
export function formatCurrency(amount: number, currency: string = "USD", includeSign: boolean = false, fractionDigits: number = 2): string {
  const abs = Math.abs(amount)
  const sign = includeSign && amount > 0 ? "+" : amount < 0 ? "-" : ""

  const formatted = new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: currency,
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: fractionDigits,
  }).format(abs)

  return `${sign}${formatted}`
}

/**
 * Formats a price number with appropriate decimal places.
 * Strips trailing zeros, respects natural wicks (e.g. XAU/USD).
 */
export function fmtPrice(v: number): string {
  if (v == null || isNaN(v)) return "—"
  const a = Math.abs(v)
  if (a >= 1000) return v.toLocaleString("en-US", { maximumFractionDigits: 2 })
  if (a >= 1) return v.toFixed(2)
  if (a >= 0.01) return v.toFixed(4)
  return v.toFixed(6)
}

/**
 * Formats a Date object into a readable string based on the user's timezone.
 */
export function formatDateWithTimezone(date: Date | string | number, timezone: string = "UTC", includeTime: boolean = false): string {
  const options: Intl.DateTimeFormatOptions = {
    timeZone: timezone,
    year: "numeric",
    month: "short",
    day: "numeric",
  }

  if (includeTime) {
    options.hour = "2-digit"
    options.minute = "2-digit"
  }

  try {
    return new Intl.DateTimeFormat("en-US", options).format(new Date(date))
  } catch (e) {
    // Fallback if timezone is invalid
    return new Intl.DateTimeFormat("en-US", { ...options, timeZone: "UTC" }).format(new Date(date))
  }
}

// lib/parsers/binance.parser.ts
// Binance Spot/Futures — Trade History CSV parser

import type { ParsedTrade } from "./ib.parser"
import type { ParseResult } from "./index"

export function binanceParser(csvText: string): ParseResult {
  const errors: { row: number; message: string }[] = []
  const trades: ParsedTrade[] = []

  const lines = csvText.trim().split("\n").filter(Boolean)
  if (lines.length < 2) {
    return { broker: "binance", trades: [], errors: [{ row: 0, message: "Empty file" }], totalRows: 0 }
  }

  const headers = lines[0].split(",").map((h) => h.replace(/"/g, "").trim())
  const col = (name: string) => headers.findIndex((h) => h.toLowerCase().includes(name.toLowerCase()))

  // Binance format: Date(UTC), Pair, Side, Order Price, Order Amount, Filled, Total, Fee, status
  const idxDate   = col("Date")
  const idxPair   = col("Pair")
  const idxSide   = col("Side")
  const idxPrice  = col("Price") !== -1 ? col("Price") : col("Order Price")
  const idxFilled = col("Filled")
  const idxTotal  = col("Total")
  const idxFee    = col("Fee")
  const idxStatus = col("Status")
  const idxOrderId = col("Order ID")

  let totalRows = 0

  for (let i = 1; i < lines.length; i++) {
    const cols = lines[i].split(",").map((c) => c.replace(/"/g, "").trim())
    totalRows++

    try {
      // Skip cancelled orders
      if (idxStatus !== -1 && cols[idxStatus]?.toLowerCase() === "cancelled") continue

      const dateStr  = cols[idxDate]
      const pair     = cols[idxPair]
      const sideStr  = cols[idxSide]?.toLowerCase()
      const priceStr = cols[idxPrice]
      const filledStr = cols[idxFilled]
      const feeStr   = cols[idxFee] ?? "0"

      if (!dateStr || !pair || !sideStr || !priceStr || !filledStr) {
        errors.push({ row: i + 1, message: `Missing required fields on row ${i + 1}` })
        continue
      }

      const price  = parseFloat(priceStr)
      const filled = parseFloat(filledStr)
      const fee    = Math.abs(parseBinanceFee(feeStr))

      if (isNaN(price) || isNaN(filled) || price <= 0) {
        errors.push({ row: i + 1, message: `Invalid price/quantity on row ${i + 1}` })
        continue
      }

      const entryAt = new Date(dateStr)
      if (isNaN(entryAt.getTime())) {
        errors.push({ row: i + 1, message: `Invalid date on row ${i + 1}: ${dateStr}` })
        continue
      }

      // Binance pair: BTCUSDT → symbol = BTC/USDT
      const symbol = formatBinancePair(pair)
      const side: "long" | "short" = sideStr === "buy" ? "long" : "short"

      trades.push({
        externalId: idxOrderId !== -1 ? cols[idxOrderId] : undefined,
        symbol,
        instrumentType: "crypto",
        side,
        quantity: filled,
        entryPrice: price,
        entryAt,
        fees: fee,
        session: "ny_open", // Binance 24/7 — pas de session
        importSource: "csv",
      })
    } catch (err) {
      errors.push({ row: i + 1, message: `Parse error on row ${i + 1}: ${String(err)}` })
    }
  }

  return { broker: "binance", trades, errors, totalRows }
}

function parseBinanceFee(feeStr: string): number {
  // Format: "0.00042 BNB" ou "0.00042"
  const match = feeStr.match(/[\d.]+/)
  return match ? parseFloat(match[0]) : 0
}

function formatBinancePair(pair: string): string {
  // BTCUSDT → BTC/USDT, ETHBTC → ETH/BTC
  const quoteCurrencies = ["USDT", "BUSD", "BTC", "ETH", "BNB", "USD"]
  for (const quote of quoteCurrencies) {
    if (pair.endsWith(quote)) {
      const base = pair.slice(0, -quote.length)
      return `${base}/${quote}`
    }
  }
  return pair
}

// lib/parsers/ib.parser.ts
// Interactive Brokers — Activity Statement CSV parser
// Format : Trades section avec colonnes fixes

import type { ParseResult } from "./index"

// Colonnes attendues dans l'Activity Statement IB
// const REQUIRED_COLS = ["Symbol", "Date/Time", "Quantity", "T. Price", "Comm/Fee", "Realized P&L"]

export interface ParsedTrade {
  externalId?: string
  symbol: string
  instrumentType?: string
  side: "long" | "short" | "LONG" | "SHORT"
  quantity: number
  entryPrice?: number
  exitPrice?: number
  entryAt: Date
  exitAt?: Date
  grossPnl?: number
  fees: number
  netPnl?: number
  session?: string
  status?: "open" | "closed"
  importSource: "csv"
}

export function ibParser(csvText: string): ParseResult {
  const errors: { row: number; message: string }[] = []
  const trades: ParsedTrade[] = []

  const lines = csvText.split("\n").map((l) => l.trim()).filter(Boolean)
  if (lines.length === 0) {
    return { broker: "interactive_brokers", trades: [], errors: [{ row: 0, message: "Empty file" }], totalRows: 0 }
  }

  // Trouver l'en-tête de la section Trades
  // Format IB: "Trades,Header,DataDiscriminator,Asset Category,Currency,Symbol,Date/Time,..."
  let headerIndex = -1
  let headers: string[] = []

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    if (line.startsWith("Trades,Header,") || line.includes("Date/Time") && line.includes("T. Price")) {
      headers = parseCSVLine(line)
      headerIndex = i
      break
    }
  }

  if (headerIndex === -1) {
    // Essai avec format simple (export "Trades" only)
    headers = parseCSVLine(lines[0])
    headerIndex = 0
  }

  // Indices des colonnes clés
  const col = (name: string) => headers.findIndex((h) => h.includes(name))

  const idxSymbol    = col("Symbol")
  const idxDateTime  = col("Date/Time")
  const idxQty       = col("Quantity")
  const idxPrice     = col("T. Price")
  const idxFees      = col("Comm/Fee")
  const idxPnl       = col("Realized P&L")
  const idxAsset     = col("Asset Category")
  const idxCurrency  = col("Currency")
  const idxTradeId   = col("Trade ID")

  if (idxSymbol === -1 || idxDateTime === -1 || idxQty === -1 || idxPrice === -1) {
    return {
      broker: "interactive_brokers",
      trades: [],
      errors: [{ row: 0, message: `Missing required columns. Found: ${headers.join(", ")}` }],
      totalRows: 0,
    }
  }

  let totalRows = 0

  for (let i = headerIndex + 1; i < lines.length; i++) {
    const line = lines[i]
    // Ignorer les lignes de sous-totaux, totaux et autres sections
    if (!line.startsWith("Trades,Data,") && !isDataLine(line, headers)) continue

    const cols = parseCSVLine(line)
    totalRows++

    try {
      const symbol   = cols[idxSymbol]?.trim()
      const dateStr  = cols[idxDateTime]?.trim()
      const qtyStr   = cols[idxQty]?.trim()
      const priceStr = cols[idxPrice]?.trim()
      const feesStr  = cols[idxFees]?.trim() ?? "0"
      const pnlStr   = cols[idxPnl]?.trim()
      const asset    = cols[idxAsset]?.trim()?.toLowerCase() ?? ""

      if (!symbol || !dateStr || !priceStr || !qtyStr) {
        errors.push({ row: i + 1, message: `Missing required fields on row ${i + 1}` })
        continue
      }

      const qty   = parseFloat(qtyStr.replace(",", ""))
      const price = parseFloat(priceStr.replace(",", ""))
      const fees  = Math.abs(parseFloat(feesStr.replace(",", "") || "0"))
      const pnl   = pnlStr ? parseFloat(pnlStr.replace(",", "")) : undefined

      if (isNaN(qty) || isNaN(price)) {
        errors.push({ row: i + 1, message: `Invalid numeric values on row ${i + 1}` })
        continue
      }

      // IB format date: "2024-01-15, 09:30:00" or "2024-01-15;09:30:00"
      const entryAt = parseIBDate(dateStr)
      if (!entryAt) {
        errors.push({ row: i + 1, message: `Invalid date format: ${dateStr} on row ${i + 1}` })
        continue
      }

      const instrumentType = mapAssetType(asset)
      const side: "long" | "short" = qty > 0 ? "long" : "short"

      const trade: ParsedTrade = {
        externalId: idxTradeId !== -1 ? cols[idxTradeId]?.trim() : undefined,
        symbol,
        instrumentType,
        side,
        quantity: Math.abs(qty),
        entryPrice: price,
        entryAt,
        fees,
        grossPnl: pnl,
        netPnl: pnl !== undefined ? pnl - fees : undefined,
        session: detectSession(entryAt),
        importSource: "csv",
      }

      trades.push(trade)
    } catch (err) {
      errors.push({ row: i + 1, message: `Parse error on row ${i + 1}: ${String(err)}` })
    }
  }

  return { broker: "interactive_brokers", trades, errors, totalRows }
}

// ─── Helpers ──────────────────────────────────────────────────────────────────
function parseCSVLine(line: string): string[] {
  const result: string[] = []
  let current = ""
  let inQuotes = false

  for (const char of line) {
    if (char === '"') {
      inQuotes = !inQuotes
    } else if (char === "," && !inQuotes) {
      result.push(current.trim())
      current = ""
    } else {
      current += char
    }
  }
  result.push(current.trim())
  return result
}

function isDataLine(line: string, headers: string[]): boolean {
  // Heuristique : la ligne a autant de colonnes que le header et commence par "Trades" ou est une ligne de données
  const cols = line.split(",")
  return cols.length >= Math.max(5, headers.length - 3)
}

function parseIBDate(dateStr: string): Date | null {
  // Formats: "2024-01-15, 09:30:00" / "2024-01-15;09:30:00" / "20240115  09:30:00"
  const cleaned = dateStr.replace(";", " ").replace(",", "").trim()
  const d = new Date(cleaned)
  return isNaN(d.getTime()) ? null : d
}

function mapAssetType(asset: string): string {
  if (asset.includes("stock") || asset.includes("equity")) return "stock"
  if (asset.includes("forex") || asset.includes("cash")) return "forex"
  if (asset.includes("future")) return "futures"
  if (asset.includes("option")) return "options"
  if (asset.includes("crypto")) return "crypto"
  return "stock" // défaut pour IB
}

function detectSession(date: Date): string {
  const hour = date.getUTCHours()
  if (hour >= 13 && hour < 21) return "ny_open"      // 9am–5pm EST
  if (hour >= 7 && hour < 16) return "london"        // 7am–4pm UTC
  if (hour >= 0 && hour < 8) return "asia"
  return "pre_market"
}

// lib/parsers/metatrader.parser.ts
// MetaTrader 4 & 5 (MT4/MT5) statement CSV parser
// Supports standard column names from MT4/MT5 exported reports (Ticket, Open Time, Type, Size, Item, Profit, etc.)

import type { ParseResult, ParsedTrade } from "./index"
import { classifySymbol } from "@/lib/market/symbols"

function parseRow(line: string): string[] {
  const out: string[] = []
  let cur = ""
  let inQuotes = false
  for (let i = 0; i < line.length; i++) {
    const ch = line[i]
    if (inQuotes) {
      if (ch === '"') {
        if (line[i + 1] === '"') {
          cur += '"'
          i++
        } else {
          inQuotes = false
        }
      } else {
        cur += ch
      }
    } else if (ch === '"') {
      inQuotes = true
    } else if (ch === ",") {
      out.push(cur.trim())
      cur = ""
    } else {
      cur += ch
    }
  }
  out.push(cur.trim())
  return out
}

function parseNumber(value: string): number | undefined {
  if (value === undefined || value === null || value === "") return undefined
  const cleaned = value.replace(/[$,\s]/g, "")
  const n = parseFloat(cleaned)
  return isNaN(n) ? undefined : n
}

function parseDate(value: string): Date | null {
  if (!value) return null
  const d = new Date(value)
  if (!isNaN(d.getTime())) return d

  // Handle format: DD.MM.YYYY HH:MM:SS
  const m = value.match(/^(\d{2})[.\-\/](\d{2})[.\-\/](\d{4})(?:\s+(\d{2}):(\d{2}):(\d{2}))?/)
  if (m) {
    const [, dd, mm, yyyy, hr, min, sec] = m
    const dt = new Date(
      parseInt(yyyy, 10),
      parseInt(mm, 10) - 1,
      parseInt(dd, 10),
      hr ? parseInt(hr, 10) : 0,
      min ? parseInt(min, 10) : 0,
      sec ? parseInt(sec, 10) : 0
    )
    return isNaN(dt.getTime()) ? null : dt
  }
  return null
}

export function metatraderParser(csvText: string): ParseResult {
  const errors: { row: number; message: string }[] = []
  const trades: ParsedTrade[] = []

  const lines = csvText.trim().split(/\r?\n/)
  if (lines.length < 2) {
    return {
      broker: "generic",
      trades: [],
      errors: [{ row: 0, message: "File is empty or has no data rows." }],
      totalRows: 0,
    }
  }

  // Find header row (usually contains Ticket, Type, Size, Item/Symbol, Profit, etc.)
  let headerIndex = -1
  let headers: string[] = []

  for (let i = 0; i < lines.length; i++) {
    const row = parseRow(lines[i])
    const rowJoined = row.join(" ").toLowerCase()
    if (rowJoined.includes("ticket") && (rowJoined.includes("open time") || rowJoined.includes("close time"))) {
      headers = row
      headerIndex = i
      break
    }
  }

  if (headerIndex === -1) {
    // Fallback: try first line as headers
    headers = parseRow(lines[0])
    headerIndex = 0
  }

  const colIdx = (keywords: string[]) => {
    return headers.findIndex((h) => {
      const val = h.toLowerCase().trim()
      return keywords.some((k) => val === k || val.includes(k))
    })
  }

  const idxTicket = colIdx(["ticket", "position id", "deal id", "order"])
  const idxOpenTime = colIdx(["open time", "time open", "open_time"])
  const idxCloseTime = colIdx(["close time", "time close", "close_time", "exit time", "exit_time"])
  const idxType = colIdx(["type", "action", "direction", "side"])
  const idxSize = colIdx(["size", "volume", "lots", "quantity", "qty"])
  const idxItem = colIdx(["item", "symbol", "instrument", "pair"])
  const idxOpenPrice = colIdx(["open price", "price open", "entry price", "open_price"])
  const idxClosePrice = colIdx(["close price", "price close", "exit price", "close_price"])
  const idxCommission = colIdx(["commission", "commissions", "comm"])
  const idxTaxes = colIdx(["taxes", "tax"])
  const idxSwap = colIdx(["swap", "rollover"])
  const idxProfit = colIdx(["profit", "pnl", "gain", "amount"])

  // Let's handle duplicate "Price" headers (MT4 exports often list "Price" twice: once for open, once for close)
  let openPriceIndex = idxOpenPrice
  let closePriceIndex = idxClosePrice
  if (openPriceIndex === -1 || closePriceIndex === -1) {
    const priceIndices: number[] = []
    headers.forEach((h, idx) => {
      if (h.toLowerCase().trim() === "price" || h.toLowerCase().trim() === "prix") {
        priceIndices.push(idx)
      }
    })
    if (priceIndices.length >= 2) {
      openPriceIndex = priceIndices[0]
      closePriceIndex = priceIndices[1]
    } else if (priceIndices.length === 1) {
      openPriceIndex = priceIndices[0]
      closePriceIndex = priceIndices[0]
    }
  }

  if (idxItem === -1 || idxType === -1 || (idxOpenTime === -1 && idxCloseTime === -1)) {
    return {
      broker: "generic",
      trades: [],
      errors: [{ row: 0, message: `Missing required columns. Found headers: ${headers.join(", ")}` }],
      totalRows: 0,
    }
  }

  let totalRows = 0

  for (let i = headerIndex + 1; i < lines.length; i++) {
    const line = lines[i].trim()
    if (!line || line.startsWith("#")) continue

    const cols = parseRow(line)
    totalRows++

    try {
      const typeVal = cols[idxType]?.toLowerCase() ?? ""
      // Skip balance modifications, deposits, withdrawals, cancellations
      if (
        typeVal.includes("deposit") ||
        typeVal.includes("withdrawal") ||
        typeVal.includes("balance") ||
        typeVal.includes("credit") ||
        typeVal.includes("limit") ||
        typeVal.includes("stop")
      ) {
        continue
      }

      const symbol = cols[idxItem]?.trim().toUpperCase().replace(".PRO", "").replace("+", "")
      const side = typeVal.includes("buy") || typeVal.includes("long") ? "LONG" : "SHORT"

      const openTimeStr = idxOpenTime >= 0 ? cols[idxOpenTime]?.trim() : ""
      const closeTimeStr = idxCloseTime >= 0 ? cols[idxCloseTime]?.trim() : ""

      const entryAt = parseDate(openTimeStr || closeTimeStr)
      const exitAt = parseDate(closeTimeStr)

      const qty = parseNumber(cols[idxSize]) ?? 1
      const entryPrice = openPriceIndex >= 0 ? parseNumber(cols[openPriceIndex]) : undefined
      const exitPrice = closePriceIndex >= 0 ? parseNumber(cols[closePriceIndex]) : undefined

      const commission = idxCommission >= 0 ? parseNumber(cols[idxCommission]) ?? 0 : 0
      const taxes = idxTaxes >= 0 ? parseNumber(cols[idxTaxes]) ?? 0 : 0
      const swap = idxSwap >= 0 ? parseNumber(cols[idxSwap]) ?? 0 : 0
      const profit = idxProfit >= 0 ? parseNumber(cols[idxProfit]) ?? 0 : 0

      if (!symbol || !entryAt) {
        errors.push({ row: i + 1, message: `Row ${i + 1}: Missing symbol or date.` })
        continue
      }

      const fees = Math.abs(commission) + Math.abs(taxes) + Math.abs(swap)
      // MT4 profit is net (without commission/swap), so netPnl is profit + commission + taxes + swap
      const netPnl = profit + commission + taxes + swap

      trades.push({
        externalId: idxTicket >= 0 ? cols[idxTicket]?.trim() : undefined,
        symbol,
        side,
        quantity: qty,
        entryPrice,
        exitPrice,
        entryAt,
        exitAt: exitAt || undefined,
        fees,
        netPnl,
        status: exitAt ? "closed" : "open",
        instrumentType: classifySymbol(symbol),
        importSource: "csv",
      })
    } catch (err: any) {
      errors.push({ row: i + 1, message: `Row ${i + 1}: ${err.message}` })
    }
  }

  return {
    broker: "generic", // maps to generic or unknown for auto-detect mapping
    trades,
    errors,
    totalRows,
  }
}

import { prisma } from "./prisma"
import { dayKey, nextMidnightInTz } from "@/lib/dates"

type EventSeverity = "info" | "warning" | "critical"

const DEFAULT_PREFS: Record<string, boolean> = {
  breached: true,
  target_hit: true,
  alert_80pct: true,
  alert_90pct: true,
  min_days_not_met: false,
  stop_trading: true,
  goal_reached: true,
  deadline_5d: true,
  deadline_1d: true,
}

function prefEnabled(prefs: any, eventType: string) {
  const map = prefs?.eventTypes
  if (!map || typeof map !== "object") return DEFAULT_PREFS[eventType] ?? true
  if (eventType in map) return Boolean(map[eventType])
  return DEFAULT_PREFS[eventType] ?? true
}

async function logEventIfAbsent(
  challengeId: string,
  eventType: string,
  severity: EventSeverity,
  message: string,
  metadata?: object,
  enabled: boolean = true
) {
  if (!enabled) return
  const existing = await prisma.propChallengeEvent.findFirst({
    where: { challengeId, eventType },
    select: { id: true },
  })
  if (existing) return

  await prisma.propChallengeEvent.create({
    data: { challengeId, eventType, severity, message, metadata: metadata ?? undefined },
  })

  // Trigger email notification for important events
  const shouldEmail = severity === "critical" || severity === "warning" || eventType === "target_hit"
  if (shouldEmail) {
    const challengeInfo = await prisma.propChallenge.findUnique({
      where: { id: challengeId },
      select: { template: { select: { firmName: true } }, user: { select: { email: true, name: true } } }
    })

    if (challengeInfo?.user.email) {
      import("@/lib/email").then(({ sendEmail }) => {
        import("@/emails/PropAlertEmail").then(({ PropAlertEmail }) => {
          sendEmail({
            to: challengeInfo.user.email,
            subject: `TradeLink: Update on your ${challengeInfo.template.firmName} Challenge`,
            react: PropAlertEmail({
              userName: challengeInfo.user.name || "Trader",
              firmName: challengeInfo.template.firmName,
              eventType: eventType.replace(/_/g, " ").toUpperCase(),
              severity: severity as any,
              message: message,
            }),
          }).catch(console.error)
        })
      }).catch(console.error)
    }
  }
}

interface DayAccum {
  date: Date
  startBalance: number
  endBalance: number
  lowestEquity: number
  pnl: number
  count: number
}

export async function evaluateChallenge(challengeId: string) {
  const challenge = await prisma.propChallenge.findUnique({
    where: { id: challengeId },
    include: { template: true, account: true }
  })

  if (!challenge) throw new Error("Challenge not found")
  if (challenge.status === "breached" || challenge.status === "failed") {
    return challenge // Terminal state
  }

  const timezone = challenge.template.dailyResetTimezone || "UTC"

  // User notification preferences (controls which events are created)
  const user = await prisma.user.findUnique({
    where: { id: challenge.userId },
    select: { email: true, name: true, notificationPrefs: true },
  })
  const prefs = user?.notificationPrefs


  // Time limit check
  if (challenge.deadlineAt && challenge.status === 'active' && new Date() > challenge.deadlineAt) {
    await markFailed(challenge.id, 'time_limit', `Time limit reached. Challenge expired.`, prefs)
    return prisma.propChallenge.findUnique({ where: { id: challenge.id } })
  }

  // Deadline reminders (J-5 and J-1, once each)
  if (challenge.deadlineAt && challenge.status === 'active') {
    const daysRemaining = Math.ceil((challenge.deadlineAt.getTime() - Date.now()) / 86400000)
    if (daysRemaining <= 5) {
      await logEventIfAbsent(
        challenge.id,
        "deadline_5d",
        "warning",
        `Deadline approaching: ${Math.max(0, daysRemaining)} day(s) left (${challenge.deadlineAt.toISOString().slice(0, 10)}).`,
        { daysRemaining: Math.max(0, daysRemaining) },
        prefEnabled(prefs, "deadline_5d")
      )
    }
    if (daysRemaining <= 1) {
      await logEventIfAbsent(
        challenge.id,
        "deadline_1d",
        "critical",
        `Last day! Deadline is ${Math.max(0, daysRemaining) === 0 ? "today" : "tomorrow"}.`,
        { daysRemaining: Math.max(0, daysRemaining) },
        prefEnabled(prefs, "deadline_1d")
      )
    }
  }

  const trades = await prisma.trade.findMany({
    where: { accountId: challenge.accountId, status: "closed" },
    orderBy: { exitAt: 'asc' }
  })

  let currentBalance = Number(challenge.initialBalance)
  let highestBalance = Number(challenge.initialBalance)
  let highestEquity = Number(challenge.initialBalance)
  let todayStartBalance = Number(challenge.initialBalance)
  let todayResetAt = challenge.todayResetAt || new Date(challenge.startedAt)

  const profitTarget = Number(challenge.initialBalance) * (Number(challenge.profitTargetPct) / 100)

  // Per-trading-day accumulation (keys in the template's reset timezone)
  const days = new Map<string, DayAccum>()

  for (const trade of trades) {
    if (!trade.exitAt) continue
    const tradeExit = trade.exitAt

    // Check if we entered a new day (reset boundary is midnight in the template's timezone)
    if (tradeExit > todayResetAt) {
      todayStartBalance = currentBalance
      todayResetAt = nextMidnightInTz(tradeExit, timezone)
    }

    const pnl = Number(trade.netPnl || 0)
    currentBalance += pnl

    // Update highest marks for stats
    highestBalance = Math.max(highestBalance, currentBalance)
    highestEquity = Math.max(highestEquity, currentBalance)

    // Accumulate into the trading day
    const key = dayKey(tradeExit, timezone)
    const acc = days.get(key) || {
      date: tradeExit,
      startBalance: currentBalance - pnl,
      endBalance: currentBalance,
      lowestEquity: currentBalance,
      pnl: 0,
      count: 0,
    }
    acc.endBalance = currentBalance
    acc.lowestEquity = Math.min(acc.lowestEquity, currentBalance)
    acc.pnl += pnl
    acc.count += 1
    days.set(key, acc)

    // Evaluate breaches
    const maxDdReference =
      challenge.template.drawdownType === 'static_balance' ? Number(challenge.initialBalance) :
      challenge.template.drawdownType === 'trailing_balance' ? highestBalance :
      highestEquity

    const maxDdThreshold = maxDdReference * (1 - Number(challenge.maxDDPct) / 100)
    const dailyDdThreshold = todayStartBalance * (1 - Number(challenge.dailyDDPct) / 100)

    // Alert thresholds — % of max drawdown used (fire 80% then 90%, once each)
    const ddBudget = maxDdReference * (Number(challenge.maxDDPct) / 100)
    const ddUsedPct = ddBudget > 0 ? ((maxDdReference - currentBalance) / ddBudget) * 100 : 0

    if (ddUsedPct >= 90) {
      await logEventIfAbsent(
        challenge.id,
        "alert_90pct",
        "critical",
        `Drawdown alert: ${Math.round(ddUsedPct)}% of your max drawdown is used.`,
        { ddUsedPct: Math.round(ddUsedPct) },
        prefEnabled(prefs, "alert_90pct")
      )
    }
    if (ddUsedPct >= 80) {
      await logEventIfAbsent(
        challenge.id,
        "alert_80pct",
        "warning",
        `Drawdown alert: ${Math.round(ddUsedPct)}% of your max drawdown is used.`,
        { ddUsedPct: Math.round(ddUsedPct) },
        prefEnabled(prefs, "alert_80pct")
      )
    }

    // Custom alert thresholds (configurable per challenge)
    const alertConfig: any = challenge.alertConfig || {}
    if (alertConfig.enableStopTrading && Number(alertConfig.stopTradingPct) > 0 && ddUsedPct >= Number(alertConfig.stopTradingPct)) {
      await logEventIfAbsent(
        challenge.id,
        "stop_trading",
        "critical",
        `Stop-trading alert: ${Math.round(ddUsedPct)}% of max drawdown used (threshold ${alertConfig.stopTradingPct}%). Consider stopping for the day.`,
        { ddUsedPct: Math.round(ddUsedPct), threshold: Number(alertConfig.stopTradingPct) },
        prefEnabled(prefs, "stop_trading")
      )
    }
    if (alertConfig.enableProfitGoal && Number(alertConfig.profitGoalPct) > 0) {
      const profitGoal = profitTarget * (Number(alertConfig.profitGoalPct) / 100)
      const currentProfit = currentBalance - Number(challenge.initialBalance)
      if (currentProfit >= profitGoal && profitGoal > 0) {
        await logEventIfAbsent(
          challenge.id,
          "goal_reached",
          "info",
          `Profit goal reached: ${Math.round(currentProfit * 100) / 100} (${alertConfig.profitGoalPct}% of target).`,
          { currentProfit: Math.round(currentProfit * 100) / 100 },
          prefEnabled(prefs, "goal_reached")
        )
      }
    }

    if (currentBalance <= maxDdThreshold) {
      await updateLive(challenge.id, currentBalance, highestBalance, highestEquity, todayStartBalance, todayResetAt, days.size)
      await markBreached(challenge.id, 'max_dd', prefs)
      await writeDailySnapshots(challenge.id, days, Number(challenge.dailyDDPct || 0))
      return prisma.propChallenge.findUnique({ where: { id: challenge.id } })
    }

    if (currentBalance <= dailyDdThreshold) {
      await updateLive(challenge.id, currentBalance, highestBalance, highestEquity, todayStartBalance, todayResetAt, days.size)
      await markBreached(challenge.id, 'daily_dd', prefs)
      await writeDailySnapshots(challenge.id, days, Number(challenge.dailyDDPct || 0))
      return prisma.propChallenge.findUnique({ where: { id: challenge.id } })
    }
  }

  // Persist daily snapshots for the chart
  await writeDailySnapshots(challenge.id, days, Number(challenge.dailyDDPct || 0))

  // Trading-day bookkeeping for the gauges
  const tradingDays = days.size
  const minTradingDays = Number(challenge.minTradingDays || 0)
  // Check Profit Target
  const currentProfit = currentBalance - Number(challenge.initialBalance)

  if (currentProfit >= profitTarget) {
    // Funded accounts don't "pass" — they become eligible for payouts.
    if (challenge.phase === 'funded') {
      await logEventIfAbsent(
        challenge.id,
        "target_hit",
        "info",
        `Profit target of ${challenge.profitTargetPct}% reached. You are eligible for a payout.`,
        { currentProfit: Math.round(currentProfit * 100) / 100 },
        prefEnabled(prefs, "target_hit")
      )
      return updateLive(challenge.id, currentBalance, highestBalance, highestEquity, todayStartBalance, todayResetAt, tradingDays)
    }

    // Min trading days gate
    if (tradingDays < minTradingDays) {
      await logEventIfAbsent(
        challenge.id,
        "min_days_not_met",
        "info",
        `Profit target reached but min trading days (${minTradingDays}) not met — ${tradingDays} traded.`,
        { tradingDays, minTradingDays },
        prefEnabled(prefs, "min_days_not_met")
      )
      return updateLive(challenge.id, currentBalance, highestBalance, highestEquity, todayStartBalance, todayResetAt, tradingDays)
    }

    // Consistency rule gate
    const consistencyPct = Number(challenge.template.consistencyRulePct || 0)
    if (consistencyPct > 0 && currentProfit > 0) {
      let biggestDay = 0
      for (const acc of days.values()) biggestDay = Math.max(biggestDay, acc.pnl)
      const biggestPct = (biggestDay / currentProfit) * 100
      if (biggestPct > consistencyPct) {
        await updateLive(challenge.id, currentBalance, highestBalance, highestEquity, todayStartBalance, todayResetAt, tradingDays)
        await markFailed(challenge.id, 'consistency', `Consistency rule violated: largest day was ${Math.round(biggestPct)}% of total profit (max ${consistencyPct}%).`, prefs)
        return prisma.propChallenge.findUnique({ where: { id: challenge.id } })
      }
    }

    await logEventIfAbsent(
      challenge.id,
      "target_hit",
      "info",
      `Profit target of ${challenge.profitTargetPct}% reached. Prepare to pass the phase.`,
      { currentProfit: Math.round(currentProfit * 100) / 100 },
      prefEnabled(prefs, "target_hit")
    )
    await updateLive(challenge.id, currentBalance, highestBalance, highestEquity, todayStartBalance, todayResetAt, tradingDays)
    await prisma.propChallenge.update({
      where: { id: challenge.id },
      data: { status: 'passed' }
    })
    return prisma.propChallenge.findUnique({ where: { id: challenge.id } })
  }

  // Update live values if no breach
  return updateLive(challenge.id, currentBalance, highestBalance, highestEquity, todayStartBalance, todayResetAt, tradingDays)
}

async function updateLive(
  challengeId: string,
  currentBalance: number,
  highestBalance: number,
  highestEquity: number,
  todayStartBalance: number,
  todayResetAt: Date,
  tradingDays: number
) {
  const challenge = await prisma.propChallenge.findUnique({
    where: { id: challengeId },
    select: { metadata: true },
  })
  const metadata = (challenge?.metadata as any) || {}
  return prisma.propChallenge.update({
    where: { id: challengeId },
    data: {
      currentBalance,
      currentEquity: currentBalance, // MVP approximation
      highestBalance,
      highestEquity,
      todayStartBalance,
      todayResetAt,
      metadata: { ...metadata, tradingDaysCount: tradingDays }
    }
  })
}

async function markFailed(challengeId: string, reason: string, message: string, prefs?: any) {
  await prisma.propChallenge.update({
    where: { id: challengeId },
    data: {
      status: 'failed',
      breachReason: reason,
      breachedAt: new Date()
    }
  })
  await logEventIfAbsent(
    challengeId,
    "breached",
    "critical",
    message,
    { reason },
    prefEnabled(prefs, "breached")
  )
}

async function markBreached(challengeId: string, reason: string, prefs?: any) {
  await prisma.propChallenge.update({
    where: { id: challengeId },
    data: {
      status: 'breached',
      breachReason: reason,
      breachedAt: new Date()
    }
  })
  await logEventIfAbsent(
    challengeId,
    "breached",
    "critical",
    `Challenge breached: ${reason.replace('_', ' ')} limit hit.`,
    { reason },
    prefEnabled(prefs, "breached")
  )
}

async function writeDailySnapshots(challengeId: string, days: Map<string, DayAccum>, dailyDDPct: number) {
  // First, delete any existing snapshots that are not in the current evaluation
  // This handles cases where trades were deleted or filtered out.
  const evaluatedDates = Array.from(days.values()).map(acc => acc.date)

  if (evaluatedDates.length === 0) {
    await prisma.propChallengeDailySnapshot.deleteMany({
      where: { challengeId }
    })
  } else {
    await prisma.propChallengeDailySnapshot.deleteMany({
      where: {
        challengeId,
        date: { notIn: evaluatedDates }
      }
    })
  }

  for (const acc of days.values()) {
    const key = dayKey(acc.date, "UTC")
    const [y, m, d] = key.split("-").map(Number)
    const date = new Date(Date.UTC(y, m - 1, d, 0, 0, 0, 0))
    const dailyDdAllowed = acc.startBalance * (Number(dailyDDPct) / 100)
    const ddUsed = Math.max(0, acc.startBalance - acc.lowestEquity)
    const dailyDDUsedPct = dailyDdAllowed > 0 ? (ddUsed / dailyDdAllowed) * 100 : null

    await prisma.propChallengeDailySnapshot.upsert({
      where: { challengeId_date: { challengeId, date } },
      update: {
        startBalance: acc.startBalance,
        endBalance: acc.endBalance,
        lowestEquity: acc.lowestEquity,
        dailyPnl: acc.pnl,
        tradesCount: acc.count,
        dailyDDUsedPct,
      },
      create: {
        challengeId,
        date,
        startBalance: acc.startBalance,
        endBalance: acc.endBalance,
        lowestEquity: acc.lowestEquity,
        dailyPnl: acc.pnl,
        tradesCount: acc.count,
        dailyDDUsedPct,
      }
    })
  }
}
